];

import { GoogleGenAI } from "@google/genai";
import { ART_STYLES } from "../constants";

// Initialize the API client
// Note: API Key must be in process.env.API_KEY
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Generates an image using the Gemini Nano Banana model (gemini-2.5-flash-image).
 * @param prompt The user's input text.
 * @param styleId The ID of the selected style.
 * @returns A promise that resolves to the Base64 image string.
 */
export const generateImageWithNano = async (prompt: string, styleId: string): Promise<string> => {
  const selectedStyle = ART_STYLES.find(s => s.id === styleId);
  const styleModifier = selectedStyle ? selectedStyle.promptModifier : '';

  // Construct a rich prompt for better results
  const fullPrompt = `Generate a high quality image of: ${prompt}. \nStyle details: ${styleModifier}. \nEnsure high resolution and detailed textures.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            text: fullPrompt,
          },
        ],
      },
      // Note: Nano Banana (2.5 flash image) does not support advanced imageConfig like aspectRatio yet in all environments,
      // but we send the request. If parameters are ignored, the model defaults to 1:1.
    });

    // Parse the response to find the image data
    if (response.candidates && response.candidates[0].content.parts) {
        for (const part of response.candidates[0].content.parts) {
            if (part.inlineData && part.inlineData.data) {
                // Return the formatted data URL
                return `data:${part.inlineData.mimeType || 'image/png'};base64,${part.inlineData.data}`;
            }
        }
    }

    throw new Error("No image data found in the response.");

  } catch (error) {
    console.error("Gemini Generation Error:", error);
    throw error;
  }
};

import React from 'react';
import { ArtStyle } from '../types';
import { Check } from 'lucide-react';

// --- Button Component ---
interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'ghost';
  isLoading?: boolean;
  icon?: React.ReactNode;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  isLoading, 
  className = '', 
  icon,
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center gap-2 px-6 py-3 rounded-xl font-medium transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-offset-1 disabled:opacity-50 disabled:cursor-not-allowed active:scale-[0.98]";

  const variants = {
    primary: "bg-nano-900 text-white hover:bg-black focus:ring-nano-900 shadow-lg shadow-nano-900/20",
    secondary: "bg-white text-nano-900 border border-nano-200 hover:bg-nano-50 hover:border-nano-300 focus:ring-nano-400 shadow-sm",
    ghost: "bg-transparent text-nano-600 hover:bg-nano-100 hover:text-nano-900"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${className}`} 
      disabled={isLoading || props.disabled}
      {...props}
    >
      {isLoading ? (
        <>
          <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-current" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
          </svg>
          Processing...
        </>
      ) : (
        <>
          {icon && <span className="w-5 h-5">{icon}</span>}
          {children}
        </>
      )}
    </button>
  );
};

