import { GoogleGenAI } from "@google/genai";
import { ART_STYLES } from "../constants";

// Initialize the API client
// Note: API Key must be in process.env.API_KEY
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Generates an image using the Gemini Nano Banana model (gemini-2.5-flash-image).
 * @param prompt The user's input text.
 * @param styleId The ID of the selected style.
 * @param aspectRatio The aspect ratio for the generated image.
 * @returns A promise that resolves to the Base64 image string.
 */
export const generateImageWithNano = async (prompt: string, styleId: string, aspectRatio: string = "1:1"): Promise<string> => {
  const selectedStyle = ART_STYLES.find(s => s.id === styleId);
  const styleModifier = selectedStyle ? selectedStyle.promptModifier : '';

  // Construct a rich prompt for better results
  const fullPrompt = `Generate a high quality image of: ${prompt}. \nStyle details: ${styleModifier}. \nEnsure high resolution and detailed textures.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            text: fullPrompt,
          },
        ],
      },
      config: {
        imageConfig: {
            aspectRatio: aspectRatio,
        }
      }
    });

    // Parse the response to find the image data
    if (response.candidates && response.candidates[0].content.parts) {
        for (const part of response.candidates[0].content.parts) {
            if (part.inlineData && part.inlineData.data) {
                // Return the formatted data URL
                return `data:${part.inlineData.mimeType || 'image/png'};base64,${part.inlineData.data}`;
            }
        }
    }

    throw new Error("No image data found in the response.");

  } catch (error) {
    console.error("Gemini Generation Error:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { 
  Sparkles, 
  Download, 
  RefreshCw, 
  Image as ImageIcon, 
  History, 
  Zap,
  Camera,
  Maximize
} from 'lucide-react';
import { ART_STYLES, APP_NAME, MODEL_NAME_DISPLAY, ASPECT_RATIOS } from './constants';
import { ArtStyle, GeneratedImage, GenerationStatus } from './types';
import { generateImageWithNano } from './services/geminiService';
import { Button, StyleCard, Badge } from './components/UI';

const App: React.FC = () => {
  // State
  const [prompt, setPrompt] = useState<string>('');
  const [selectedStyleId, setSelectedStyleId] = useState<string>(ART_STYLES[0].id);
  const [aspectRatio, setAspectRatio] = useState<string>('1:1');
  const [status, setStatus] = useState<GenerationStatus>('idle');
  const [currentImage, setCurrentImage] = useState<GeneratedImage | null>(null);
  const [history, setHistory] = useState<GeneratedImage[]>([]);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  // Refs for scrolling
  const previewRef = useRef<HTMLDivElement>(null);

  // Helper to get full style object
  const selectedStyle = ART_STYLES.find(s => s.id === selectedStyleId) || ART_STYLES[0];

  // Logic: Handle Generation
  const handleGenerate = async () => {
    if (!prompt.trim()) return;

