import React, { useState, useRef, useEffect } from 'react';
import { Button } from './UI';
import { Check, X, Crop, Wand2, ZoomIn } from 'lucide-react';
import { IMAGE_FILTERS, ASPECT_RATIOS } from '../constants';

interface ImageEditorProps {
  imageSrc: string;
  onSave: (newImageSrc: string) => void;
  onCancel: () => void;
}

export const ImageEditor: React.FC<ImageEditorProps> = ({ imageSrc, onSave, onCancel }) => {
  const [activeTab, setActiveTab] = useState<'filter' | 'crop'>('filter');
  const [selectedFilterId, setSelectedFilterId] = useState('none');

  // Crop state
  const [zoom, setZoom] = useState(1);
  const [cropRatio, setCropRatio] = useState<string>('1:1');
  const [pan, setPan] = useState({ x: 0, y: 0 });

  // Interaction state
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  const imageRef = useRef<HTMLImageElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Get current filter string
  const currentFilter = IMAGE_FILTERS.find(f => f.id === selectedFilterId)?.filter || 'none';

  const handlePointerDown = (e: React.PointerEvent) => {
    setIsDragging(true);
    setDragStart({ x: e.clientX - pan.x, y: e.clientY - pan.y });
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (isDragging) {
      setPan({
        x: e.clientX - dragStart.x,
        y: e.clientY - dragStart.y
      });
    }
  };

  const handlePointerUp = () => {
    setIsDragging(false);
  };

  const handleSave = () => {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    const img = imageRef.current;

    if (!ctx || !img) return;

    // Determine output size based on crop ratio
    // We'll use a fixed high resolution for the output, maintaining ratio
    const outputSize = 1024;
    let width = outputSize;
    let height = outputSize;

    const [wRatio, hRatio] = cropRatio.split(':').map(Number);
    if (wRatio && hRatio) {
        if (wRatio > hRatio) {
            height = outputSize * (hRatio / wRatio);
        } else {
            width = outputSize * (wRatio / hRatio);
        }
    }

    canvas.width = width;
    canvas.height = height;

    // Apply Filter
    ctx.filter = currentFilter;

    // Draw background (black)
    ctx.fillStyle = '#000000';
    ctx.fillRect(0, 0, width, height);

    // Calculate scaling to fit the image into the canvas based on user's zoom/pan
    // This is an approximation of the DOM transform logic
    // In DOM: transform: scale(zoom) translate(pan.x, pan.y)
    // We need to map screen pixels to canvas pixels

    // Simple approach: Render exact viewport
    // Find the center of the image relative to the container center

    const container = containerRef.current;
    if (!container) return;

    const scaleFactor = width / container.clientWidth;

    ctx.save();

    // Move to center
    ctx.translate(width / 2, height / 2);
    ctx.scale(zoom, zoom);
    ctx.translate(pan.x * scaleFactor, pan.y * scaleFactor);

    // Draw image centered
    // We need to maintain aspect ratio of original image
    const imgAspect = img.naturalWidth / img.naturalHeight;

    let drawWidth, drawHeight;
    if (width / height > imgAspect) {
        // Canvas is wider than image
        drawHeight = height;
        drawWidth = height * imgAspect;
    } else {
        // Canvas is taller than image
        drawWidth = width;
        drawHeight = width / imgAspect;
    }

    // Draw centered
    ctx.drawImage(img, -drawWidth / 2, -drawHeight / 2, drawWidth, drawHeight);

    ctx.restore();

    onSave(canvas.toDataURL('image/png'));
  };

  return (
    <div className="absolute inset-0 bg-white z-50 flex flex-col h-full animate-in fade-in duration-300">
      {/* Header */}
      <div className="h-14 border-b border-nano-200 flex items-center justify-between px-4 bg-white shrink-0">
        <button 
          onClick={onCancel}
          className="p-2 text-nano-500 hover:text-nano-900 hover:bg-nano-100 rounded-lg transition-colors"
        >
          <X size={20} />
        </button>
        <span className="font-semibold text-sm">Edit Image</span>
        <button 
          onClick={handleSave}
          className="p-2 text-nano-900 hover:bg-nano-100 rounded-lg transition-colors font-medium"
        >
          <Check size={20} />
        </button>
      </div>

      {/* Main Canvas Area */}
      <div className="flex-grow bg-nano-100 overflow-hidden relative flex items-center justify-center p-8 select-none">

        {/* Viewport Frame */}
        <div 
          ref={containerRef}
          className="relative bg-black overflow-hidden shadow-2xl ring-4 ring-white/50"
          style={{
             aspectRatio: cropRatio.replace(':', '/'),
             width: '100%',
             maxWidth: '100%',
             maxHeight: '100%',
             cursor: isDragging ? 'grabbing' : 'grab',
             touchAction: 'none'
          }}
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={handlePointerUp}
          onPointerLeave={handlePointerUp}
        >
           <img 
             ref={imageRef}
             src={imageSrc} 
             alt="Editing"
             className="absolute max-w-none max-h-none origin-center pointer-events-none"
             style={{
                top: '50%',
                left: '50%',
                transform: `translate(-50%, -50%) scale(${zoom}) translate(${pan.x}px, ${pan.y}px)`,
                filter: currentFilter,
                minWidth: '100%',
                minHeight: '100%'
             }}
             draggable={false}
           />
        </div>

        <div className="absolute bottom-4 left-1/2 -translate-x-1/2 bg-black/70 text-white text-xs px-3 py-1 rounded-full backdrop-blur-sm pointer-events-none opacity-50">
           Drag to Pan • Pinch to Zoom
        </div>
      </div>

      {/* Controls */}
      <div className="bg-white border-t border-nano-200 shrink-0 pb-safe">

        {/* Tabs */}
        <div className="flex border-b border-nano-100">
           <button 
             onClick={() => setActiveTab('filter')}
             className={`flex-1 py-3 text-sm font-medium flex items-center justify-center gap-2 ${activeTab === 'filter' ? 'text-nano-900 border-b-2 border-nano-900' : 'text-nano-500'}`}
           >
             <Wand2 size={16} /> Filters
           </button>
           <button 
             onClick={() => setActiveTab('crop')}
             className={`flex-1 py-3 text-sm font-medium flex items-center justify-center gap-2 ${activeTab === 'crop' ? 'text-nano-900 border-b-2 border-nano-900' : 'text-nano-500'}`}
           >
             <Crop size={16} /> Crop
           </button>
        </div>

        {/* Tab Content */}
        <div className="h-32 p-4">

           {activeTab === 'filter' && (
             <div className="flex gap-4 overflow-x-auto pb-2 hide-scrollbar h-full items-center">
                {IMAGE_FILTERS.map((f) => (
                   <button 
                     key={f.id}
                     onClick={() => setSelectedFilterId(f.id)}
                     className="flex flex-col items-center gap-2 shrink-0 group"
                   >
                      <div className={`w-16 h-16 rounded-lg overflow-hidden border-2 transition-all ${selectedFilterId === f.id ? 'border-nano-900 ring-2 ring-nano-900/20' : 'border-transparent group-hover:border-nano-300'}`}>
                         <img 
                           src={imageSrc} 
                           alt={f.name} 
                           className="w-full h-full object-cover" 
                           style={{ filter: f.filter }}
                         />
                      </div>
                      <span className={`text-xs font-medium ${selectedFilterId === f.id ? 'text-nano-900' : 'text-nano-500'}`}>{f.name}</span>
                   </button>
                ))}
             </div>
           )}

           {activeTab === 'crop' && (
             <div className="flex flex-col gap-4 h-full justify-center">
                {/* Zoom Slider */}
                <div className="flex items-center gap-3 px-2">
                   <ZoomIn size={16} className="text-nano-500" />
                   <input 
                     type="range" 
                     min="0.5" 
                     max="3" 
                     step="0.1"
                     value={zoom}
                     onChange={(e) => setZoom(parseFloat(e.target.value))}
                     className="w-full h-1.5 bg-nano-200 rounded-lg appearance-none cursor-pointer accent-nano-900"
                   />
                </div>

                {/* Ratios */}
                <div className="flex gap-2 overflow-x-auto pb-1 hide-scrollbar">
                   <button 
                     onClick={() => { setCropRatio('1:1'); setZoom(1); setPan({x:0,y:0}); }}
                     className={`px-3 py-1.5 rounded-lg border text-xs font-medium whitespace-nowrap ${cropRatio === '1:1' ? 'bg-nano-900 text-white border-nano-900' : 'border-nano-200 text-nano-600'}`}
                   >
                     Square
                   </button>
                   {ASPECT_RATIOS.slice(1).map(r => (
                     <button 
                        key={r.id}
                        onClick={() => { setCropRatio(r.id); setZoom(1); setPan({x:0,y:0}); }}
                        className={`px-3 py-1.5 rounded-lg border text-xs font-medium whitespace-nowrap ${cropRatio === r.id ? 'bg-nano-900 text-white border-nano-900' : 'border-nano-200 text-nano-600'}`}
                     >
                        {r.label}
                     </button>
                   ))}
                </div>
             </div>
           )}

        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { 
  Sparkles, 
  Download, 
  RefreshCw, 
  Image as ImageIcon, 
  History, 
  Zap,
  Camera,
  Maximize,
  Sliders,
  ChevronDown,
  ChevronUp,
  Undo,
  Redo,
  Upload,
  X,
  Plus,
  Edit2
} from 'lucide-react';
import { ART_STYLES, APP_NAME, MODEL_NAME_DISPLAY, ASPECT_RATIOS } from './constants';
import { ArtStyle, GeneratedImage, GenerationStatus } from './types';
import { generateImageWithNano } from './services/geminiService';
import { Button, StyleCard, Badge } from './components/UI';
import { ImageEditor } from './components/ImageEditor';

const App: React.FC = () => {
  // State
  const [prompt, setPrompt] = useState<string>('');
  const [selectedStyleId, setSelectedStyleId] = useState<string>(ART_STYLES[0].id);
  const [aspectRatio, setAspectRatio] = useState<string>('1:1');

  // Advanced Settings State
  const [seed, setSeed] = useState<number | undefined>(undefined);
  const [creativity, setCreativity] = useState<number>(50); // 0-100
  const [showAdvanced, setShowAdvanced] = useState<boolean>(false);

  // Image Upload State
  const [uploadedImage, setUploadedImage] = useState<string | null>(null);

  const [status, setStatus] = useState<GenerationStatus>('idle');
  const [currentImage, setCurrentImage] = useState<GeneratedImage | null>(null);
  const [history, setHistory] = useState<GeneratedImage[]>([]);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  // Editing State
  const [isEditing, setIsEditing] = useState(false);

  // Undo/Redo State
  const [promptHistory, setPromptHistory] = useState<string[]>(['']);
  const [historyIndex, setHistoryIndex] = useState(0);
  const debounceRef = useRef<any>(null);

  // Refs
  const previewRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Helper to get full style object
  const selectedStyle = ART_STYLES.find(s => s.id === selectedStyleId) || ART_STYLES[0];

  // Logic: Handle Prompt Change with Debounced History
  const handlePromptChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newVal = e.target.value;
    setPrompt(newVal);

    // Debounce adding to history so we don't save every char
    if (debounceRef.current) clearTimeout(debounceRef.current);

    debounceRef.current = setTimeout(() => {
      setPromptHistory(prev => {
        const newHistory = prev.slice(0, historyIndex + 1);
        newHistory.push(newVal);
        return newHistory;
      });
      setHistoryIndex(prev => prev + 1);
    }, 400);
  };

  // Logic: Undo
  const handleUndo = () => {
    if (historyIndex > 0) {
      const newIndex = historyIndex - 1;
      setHistoryIndex(newIndex);
      setPrompt(promptHistory[newIndex]);
    }
  };

  // Logic: Redo
  const handleRedo = () => {
    if (historyIndex < promptHistory.length - 1) {
      const newIndex = historyIndex + 1;
      setHistoryIndex(newIndex);
      setPrompt(promptHistory[newIndex]);
    }
  };

  // Logic: File Upload
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        if (event.target?.result) {
          setUploadedImage(event.target.result as string);
        }
      };
      reader.readAsDataURL(file);
    }
    // Reset value so same file can be selected again if needed
    if (fileInputRef.current) {
        fileInputRef.current.value = '';
    }
  };

  const clearUploadedImage = () => {
    setUploadedImage(null);
  };

  // Logic: Handle Generation
  const handleGenerate = async () => {
    if (!prompt.trim() && !uploadedImage) return; 
    if (!prompt.trim()) {
        setErrorMsg("Please enter a text prompt to guide the transformation.");
        setStatus('error');
        return;
    }

    setStatus('generating');
    setErrorMsg(null);
    setCurrentImage(null);
    setIsEditing(false);

    // Scroll to preview on mobile
    if (window.innerWidth < 768) {
        previewRef.current?.scrollIntoView({ behavior: 'smooth' });
    }

    try {
      const base64Image = await generateImageWithNano(
          prompt, 
          selectedStyleId, 
          aspectRatio, 
          seed, 
          creativity, 
          uploadedImage
      );

      const newImage: GeneratedImage = {
        id: crypto.randomUUID(),
        url: base64Image,
        prompt: prompt,
        styleId: selectedStyleId,
        aspectRatio: aspectRatio,
        seed: seed,
        creativity: creativity,
        timestamp: Date.now()
      };

      setCurrentImage(newImage);
      setHistory(prev => [newImage, ...prev].slice(0, 10)); // Keep last 10
      setStatus('success');
    } catch (error) {
      console.error(error);
      setStatus('error');
      setErrorMsg("Failed to generate. Please try again.");
    }
  };

  // Logic: Handle Download
  const handleDownload = () => {
    if (!currentImage) return;
    const link = document.createElement('a');
    link.href = currentImage.url;
    link.download = `${APP_NAME.toLowerCase()}-${currentImage.id.slice(0, 8)}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Logic: Load from history
  const loadFromHistory = (img: GeneratedImage) => {
    setCurrentImage(img);
    setPrompt(img.prompt);

    // Update undo history with loaded prompt
    setPromptHistory(prev => {
       const newHistory = prev.slice(0, historyIndex + 1);
       if (newHistory[newHistory.length - 1] !== img.prompt) {
         newHistory.push(img.prompt);
       }
       return newHistory;
    });
    setHistoryIndex(prev => prev + 1);

    setSelectedStyleId(img.styleId);
    setAspectRatio(img.aspectRatio || '1:1');
    setSeed(img.seed);
    setCreativity(img.creativity ?? 50);
    setUploadedImage(null); 

    setStatus('success');
    setIsEditing(false);
    if (window.innerWidth < 768) {
        previewRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  };

  // Logic: Save Edit
  const handleSaveEdit = (newImageSrc: string) => {
     if (!currentImage) return;

     const newImage: GeneratedImage = {
        ...currentImage,
        id: crypto.randomUUID(),
        url: newImageSrc,
        timestamp: Date.now()
     };

     setCurrentImage(newImage);
     setHistory(prev => [newImage, ...prev].slice(0, 10));
     setIsEditing(false);
  };

  return (
    <div className="min-h-screen bg-nano-50 text-nano-900 selection:bg-nano-900 selection:text-white flex flex-col">

      {/* --- Header --- */}
      <header className="bg-white/80 backdrop-blur-md sticky top-0 z-50 border-b border-nano-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-nano-900 rounded-lg flex items-center justify-center text-white">
              <Camera size={18} />
            </div>
            <h1 className="text-lg font-bold tracking-tight">{APP_NAME}</h1>
            <Badge text={MODEL_NAME_DISPLAY} />
          </div>
          <div className="hidden sm:flex text-sm text-nano-500 font-medium">
             AI Photo Lab
          </div>
        </div>
      </header>

      {/* --- Main Content --- */}
      <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full flex flex-col lg:flex-row gap-8 lg:gap-12">

        {/* --- Left Column: Controls --- */}
        <div className="w-full lg:w-1/3 flex flex-col gap-8 order-2 lg:order-1">

          {/* Prompt Section */}
          <section className="space-y-4">
            <div className="flex justify-between items-end">
              <div className="space-y-1">
                <label htmlFor="prompt" className="block text-sm font-semibold text-nano-800">
                  Prompt
                </label>
                <p className="text-xs text-nano-500">Describe what you want to see in detail.</p>
              </div>
              <div className="flex items-center gap-1">
                <button 
                  onClick={handleUndo}
                  disabled={historyIndex === 0}
                  className="p-1.5 rounded-md hover:bg-nano-100 text-nano-500 disabled:opacity-30 disabled:hover:bg-transparent transition-colors"
                  title="Undo"
                >
                  <Undo size={14} />
                </button>
                <button 
                  onClick={handleRedo}
                  disabled={historyIndex >= promptHistory.length - 1}
                  className="p-1.5 rounded-md hover:bg-nano-100 text-nano-500 disabled:opacity-30 disabled:hover:bg-transparent transition-colors"
                  title="Redo"
                >
                  <Redo size={14} />
                </button>
              </div>
            </div>
            <div className="relative">
              <textarea
                id="prompt"
                value={prompt}
                onChange={handlePromptChange}
                placeholder="A futuristic house on a cliff, golden hour..."
                className="w-full p-4 rounded-xl border border-nano-200 bg-white shadow-sm text-nano-900 placeholder:text-nano-400 focus:ring-2 focus:ring-nano-900 focus:border-transparent resize-none h-32 transition-all outline-none"
              />
            </div>
          </section>

          {/* Reference Image Section */}
          <section className="space-y-4">
            <div className="space-y-1">
               <label className="block text-sm font-semibold text-nano-800">
                 Reference Image
               </label>
               <p className="text-xs text-nano-500">Upload a photo to guide the generation (optional).</p>
            </div>

            <input 
              type="file" 
              ref={fileInputRef}
              onChange={handleFileUpload}
              className="hidden" 
              accept="image/*"
            />

            {!uploadedImage ? (
              <div 
                onClick={() => fileInputRef.current?.click()}
                className="border-2 border-dashed border-nano-200 rounded-xl p-6 flex flex-col items-center justify-center text-nano-400 hover:border-nano-400 hover:text-nano-600 hover:bg-nano-50 transition-all cursor-pointer h-24"
              >
                 <div className="flex items-center gap-2 text-sm font-medium">
                   <Upload size={16} />
                   <span>Upload Image</span>
                 </div>
              </div>
            ) : (
              <div className="relative group">
                <div className="h-48 w-full bg-nano-100 rounded-xl overflow-hidden border border-nano-200">
                   <img src={uploadedImage} alt="Reference" className="w-full h-full object-cover opacity-80 group-hover:opacity-100 transition-opacity" />
                </div>
                <button 
                  onClick={clearUploadedImage}
                  className="absolute top-2 right-2 bg-white/90 backdrop-blur p-1.5 rounded-full text-nano-600 hover:text-red-500 hover:bg-white shadow-sm transition-all"
                >
                  <X size={14} />
                </button>
                <div className="absolute bottom-2 right-2 px-2 py-1 bg-black/50 backdrop-blur-sm rounded-md text-white text-[10px] font-medium pointer-events-none">
                  Reference
                </div>
              </div>
            )}
          </section>

          {/* Aspect Ratio Section */}
          <section className="space-y-4">
            <div className="space-y-1">
              <label className="block text-sm font-semibold text-nano-800">
                Dimensions
              </label>
              <p className="text-xs text-nano-500">Choose the aspect ratio.</p>
            </div>
            <div className="flex gap-2 flex-wrap">
              {ASPECT_RATIOS.map((ratio) => (
                <button
                  key={ratio.id}
                  onClick={() => setAspectRatio(ratio.id)}
                  className={`
                    flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium border transition-all
                    ${aspectRatio === ratio.id 
                      ? 'bg-nano-900 text-white border-nano-900 shadow-md' 
                      : 'bg-white text-nano-600 border-nano-200 hover:border-nano-300 hover:bg-nano-50'
                    }
                  `}
                >
                  <div className={`border-2 rounded-sm ${ratio.shapeClass} ${aspectRatio === ratio.id ? 'border-white/80' : 'border-nano-400'}`}></div>
                  <span>{ratio.label}</span>
                </button>
              ))}
            </div>
          </section>

          {/* Advanced Settings Toggle */}
          <section className="space-y-4">
             <button 
              onClick={() => setShowAdvanced(!showAdvanced)}
              className="flex items-center justify-between w-full text-sm font-semibold text-nano-800 hover:text-nano-600 transition-colors"
             >
                <div className="flex items-center gap-2">
                  <Sliders size={16} />
                  <span>Advanced Settings</span>
                </div>
                {showAdvanced ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
             </button>

             {/* Advanced Settings Content */}
             {showAdvanced && (
                <div className="bg-white rounded-xl border border-nano-200 p-4 space-y-4 animate-in slide-in-from-top-2 fade-in duration-200">
                    {/* Seed */}
                    <div className="space-y-1">
                      <div className="flex justify-between items-center">
                        <label className="text-xs font-medium text-nano-700">Seed</label>
                        <span className="text-[10px] text-nano-400">Optional</span>
                      </div>
                      <input 
                        type="number" 
                        placeholder="Random" 
                        value={seed === undefined ? '' : seed}
                        onChange={(e) => {
                          const val = e.target.value;
                          setSeed(val === '' ? undefined : parseInt(val));
                        }}
                        className="w-full p-2 text-sm rounded-lg border border-nano-200 focus:outline-none focus:ring-1 focus:ring-nano-900"
                      />
                    </div>

                    {/* Creative Boost (Temperature) */}
                    <div className="space-y-2">
                      <div className="flex justify-between items-center">
                        <label className="text-xs font-medium text-nano-700">Creative Boost</label>
                        <span className="text-[10px] font-mono text-nano-500">{creativity}%</span>
                      </div>
                      <input 
                        type="range" 
                        min="0" 
                        max="100" 
                        value={creativity}
                        onChange={(e) => setCreativity(parseInt(e.target.value))}
                        className="w-full h-1.5 bg-nano-200 rounded-lg appearance-none cursor-pointer accent-nano-900"
                      />
                      <div className="flex justify-between text-[10px] text-nano-400">
                         <span>More Predictable</span>
                         <span>More Creative</span>
                      </div>
                    </div>
                </div>
             )}
          </section>

          {/* Style Section */}
          <section className="space-y-4">
             <div className="space-y-1">
              <label className="block text-sm font-semibold text-nano-800">
                Visual Style
              </label>
              <p className="text-xs text-nano-500">Select a preset to guide the aesthetic.</p>
            </div>
            <div className="grid grid-cols-2 gap-3">
              {ART_STYLES.map((style) => (
                <StyleCard 
                  key={style.id}
                  style={style}
                  isSelected={selectedStyleId === style.id}
                  onClick={() => setSelectedStyleId(style.id)}
                />
              ))}
            </div>
          </section>

          {/* Action Area */}
          <div className="pt-4 sticky bottom-6 lg:static z-20">
            <Button 
              onClick={handleGenerate} 
              isLoading={status === 'generating'}
              disabled={!prompt.trim() && !uploadedImage}
              className="w-full"
              icon={<Zap size={18} />}
            >
              {status === 'generating' ? 'Generating...' : 'Generate Image'}
            </Button>
          </div>
        </div>

        {/* --- Right Column: Preview --- */}
        <div className="w-full lg:w-2/3 flex flex-col gap-6 order-1 lg:order-2">

          {/* Main Preview Card */}
          <div 
            ref={previewRef}
            className="w-full bg-white rounded-2xl shadow-xl shadow-nano-200/50 border border-nano-200 overflow-hidden relative flex flex-col min-h-[400px] lg:min-h-[600px] transition-all duration-500"
          >
            {/* Editor Overlay */}
            {isEditing && currentImage ? (
                <ImageEditor 
                  imageSrc={currentImage.url}
                  onSave={handleSaveEdit}
                  onCancel={() => setIsEditing(false)}
                />
            ) : (
                <>
                    {/* Toolbar */}
                    <div className="h-14 border-b border-nano-100 flex items-center justify-between px-4 bg-white/50 backdrop-blur-sm z-10">
                    <div className="flex items-center gap-2 text-xs font-medium text-nano-500">
                        <ImageIcon size={14} />
                        <span>Preview Canvas</span>
                    </div>
                    {status === 'success' && (
                        <div className="flex gap-2">
                        <button 
                            onClick={() => setIsEditing(true)}
                            className="p-2 hover:bg-nano-100 rounded-lg text-nano-600 transition-colors"
                            title="Edit"
                        >
                            <Edit2 size={18} />
                        </button>
                        <button 
                            onClick={handleGenerate}
                            className="p-2 hover:bg-nano-100 rounded-lg text-nano-600 transition-colors"
                            title="Regenerate"
                        >
                            <RefreshCw size={18} />
                        </button>
                        <Button variant="secondary" onClick={handleDownload} className="!py-1.5 !px-3 !text-xs !h-8">
                            <Download size={14} className="mr-1.5" />
                            Download
                        </Button>
                        </div>
                    )}
                    </div>

                    {/* Canvas Area */}
                    <div className="flex-grow relative bg-nano-50 flex items-center justify-center p-4">

                    {status === 'idle' && (
                        <div className="text-center max-w-sm px-6 py-12">
                        <div className="w-16 h-16 bg-white rounded-2xl shadow-sm border border-nano-200 flex items-center justify-center mx-auto mb-4">
                            <Sparkles className="text-nano-400" size={32} />
                        </div>
                        <h3 className="text-lg font-medium text-nano-900 mb-2">Ready to Create</h3>
                        <p className="text-nano-500 text-sm">
                            Enter a prompt and optionally upload an image to generate high-quality visuals with {MODEL_NAME_DISPLAY}.
                        </p>
                        </div>
                    )}

                    {status === 'generating' && (
                        <div className="w-full h-full absolute inset-0 bg-white flex flex-col items-center justify-center z-20">
                        <div className="w-full max-w-md px-8 space-y-6">
                            {/* Animated Skeleton */}
                            <div className="w-full aspect-square bg-gradient-to-tr from-nano-100 via-nano-50 to-nano-200 rounded-lg animate-pulse-slow relative overflow-hidden">
                            <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/40 to-transparent -skew-x-12 translate-x-[-150%] animate-[shimmer_2s_infinite]"></div>
                            </div>
                            <div className="space-y-2 text-center">
                            <p className="text-sm font-medium text-nano-700 animate-pulse">Designing layout...</p>
                            <p className="text-xs text-nano-400">Powered by Gemini Nano</p>
                            </div>
                        </div>
                        </div>
                    )}

                    {status === 'error' && (
                        <div className="text-center">
                        <div className="w-12 h-12 bg-red-50 rounded-full flex items-center justify-center mx-auto mb-3">
                            <Zap className="text-red-500" size={24} />
                        </div>
                        <p className="text-red-600 font-medium">{errorMsg}</p>
                        </div>
                    )}

                    {currentImage && (
                        <img 
                        src={currentImage.url} 
                        alt={currentImage.prompt}
                        className={`max-w-full max-h-[70vh] rounded-lg shadow-sm transition-opacity duration-700 ${status === 'generating' ? 'opacity-0' : 'opacity-100'}`}
                        />
                    )}
                    </div>
                </>
            )}
          </div>

          {/* History Bar */}
          {history.length > 0 && (
            <div className="space-y-2">
              <div className="flex items-center gap-2 text-sm font-semibold text-nano-800 px-1">
                <History size={16} />
                <span>Session History</span>
              </div>
              <div className="flex gap-3 overflow-x-auto pb-4 pt-1 px-1 hide-scrollbar">
                {history.map((img) => (
                  <button
                    key={img.id}
                    onClick={() => loadFromHistory(img)}
                    className={`
                      relative flex-shrink-0 w-24 h-24 rounded-lg overflow-hidden border-2 transition-all duration-200
                      ${currentImage?.id === img.id ? 'border-nano-900 ring-2 ring-nano-900/20' : 'border-transparent hover:border-nano-300 opacity-70 hover:opacity-100'}
                    `}
                  >
                    <img src={img.url} alt="thumbnail" className="w-full h-full object-cover" />
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

