                    {/* Creative Boost (Temperature) */}
                    <div className="space-y-2">
                      <div className="flex justify-between items-center">
                        <label className="text-xs font-medium text-nano-700">Creative Boost</label>
                        <span className="text-[10px] font-mono text-nano-500">{creativity}%</span>
                      </div>
                      <input 
                        type="range" 
                        min="0" 
                        max="100" 
                        value={creativity}
                        onChange={(e) => setCreativity(parseInt(e.target.value))}
                        className="w-full h-1.5 bg-nano-200 rounded-lg appearance-none cursor-pointer accent-nano-900"
                      />
                      <div className="flex justify-between text-[10px] text-nano-400">
                         <span>More Predictable</span>
                         <span>More Creative</span>
                      </div>
                    </div>
                </div>
             )}
          </section>

          {/* Style Section */}
          <section className="space-y-4">
             <div className="space-y-1">
              <label className="block text-sm font-semibold text-nano-800">
                Visual Style
              </label>
              <p className="text-xs text-nano-500">Select a preset to guide the aesthetic.</p>
            </div>
            <div className="grid grid-cols-2 gap-3">
              {ART_STYLES.map((style) => (
                <StyleCard 
                  key={style.id}
                  style={style}
                  isSelected={selectedStyleId === style.id}
                  onClick={() => setSelectedStyleId(style.id)}
                />
              ))}
            </div>
          </section>

          {/* Action Area */}
          <div className="pt-4 sticky bottom-6 lg:static z-20">
            <Button 
              onClick={handleGenerate} 
              isLoading={status === 'generating'}
              disabled={!prompt.trim() && !uploadedImage}
              className="w-full"
              icon={<Zap size={18} />}
            >
              {status === 'generating' ? 'Generating...' : 'Generate Image'}
            </Button>
          </div>
        </div>

        {/* --- Right Column: Preview --- */}
        <div className="w-full lg:w-2/3 flex flex-col gap-6 order-1 lg:order-2">

          {/* Main Preview Card */}
          <div 
            ref={previewRef}
            className="w-full bg-white rounded-2xl shadow-xl shadow-nano-200/50 border border-nano-200 overflow-hidden relative flex flex-col min-h-[400px] lg:min-h-[600px] transition-all duration-500"
          >
            {/* Editor Overlay */}
            {isEditing && currentImage ? (
                <ImageEditor 
                  imageSrc={currentImage.url}
                  onSave={handleSaveEdit}
                  onCancel={() => setIsEditing(false)}
                />
            ) : (
                <>
                    {/* Toolbar */}
                    <div className="h-14 border-b border-nano-100 flex items-center justify-between px-4 bg-white/50 backdrop-blur-sm z-10">
                    <div className="flex items-center gap-2 text-xs font-medium text-nano-500">
                        <ImageIcon size={14} />
                        <span>Preview Canvas</span>
                    </div>
                    {status === 'success' && (
                        <div className="flex gap-2">
                        <button 
                            onClick={() => setIsEditing(true)}
                            className="p-2 hover:bg-nano-100 rounded-lg text-nano-600 transition-colors"
                            title="Edit"
                        >
                            <Edit2 size={18} />
