import React, { useState, useEffect, useRef } from 'react';
import { 
  Sparkles, 
  Download, 
  RefreshCw, 
  Image as ImageIcon, 
  History, 
  Zap,
  Camera,
  Maximize,
  Sliders,
  ChevronDown,
  ChevronUp,
  Undo,
  Redo,
  Upload,
  X,
  Plus,
  Edit2,
  Dices
} from 'lucide-react';
import { ART_STYLES, APP_NAME, MODEL_NAME_DISPLAY, ASPECT_RATIOS } from './constants';
import { ArtStyle, GeneratedImage, GenerationStatus } from './types';
import { generateImageWithNano } from './services/geminiService';
import { Button, StyleCard, Badge } from './components/UI';
import { ImageEditor } from './components/ImageEditor';
import { ZoomablePreview } from './components/ZoomablePreview';

const App: React.FC = () => {
  // State
  const [prompt, setPrompt] = useState<string>('');
  const [selectedStyleId, setSelectedStyleId] = useState<string>(ART_STYLES[0].id);
  const [aspectRatio, setAspectRatio] = useState<string>('1:1');

  // Advanced Settings State
  const [seed, setSeed] = useState<number | undefined>(undefined);
  const [creativity, setCreativity] = useState<number>(50); // 0-100
  const [showAdvanced, setShowAdvanced] = useState<boolean>(false);

  // Image Upload State
  const [uploadedImage, setUploadedImage] = useState<string | null>(null);

  const [status, setStatus] = useState<GenerationStatus>('idle');
  const [currentImage, setCurrentImage] = useState<GeneratedImage | null>(null);
  const [history, setHistory] = useState<GeneratedImage[]>([]);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  // Editing State
  const [isEditing, setIsEditing] = useState(false);

  // Undo/Redo State
  const [promptHistory, setPromptHistory] = useState<string[]>(['']);
  const [historyIndex, setHistoryIndex] = useState(0);
  const debounceRef = useRef<any>(null);

  // Refs
  const previewRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Helper to get full style object
  const selectedStyle = ART_STYLES.find(s => s.id === selectedStyleId) || ART_STYLES[0];

  // Logic: Handle Prompt Change with Debounced History
  const handlePromptChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newVal = e.target.value;
    setPrompt(newVal);

    // Debounce adding to history so we don't save every char
    if (debounceRef.current) clearTimeout(debounceRef.current);

    debounceRef.current = setTimeout(() => {
      setPromptHistory(prev => {
        const newHistory = prev.slice(0, historyIndex + 1);
        newHistory.push(newVal);
        return newHistory;
      });
      setHistoryIndex(prev => prev + 1);
    }, 400);
  };

  // Logic: Undo
  const handleUndo = () => {
    if (historyIndex > 0) {
      const newIndex = historyIndex - 1;
      setHistoryIndex(newIndex);
      setPrompt(promptHistory[newIndex]);
    }
  };

  // Logic: Redo
  const handleRedo = () => {
    if (historyIndex < promptHistory.length - 1) {
      const newIndex = historyIndex + 1;
      setHistoryIndex(newIndex);
      setPrompt(promptHistory[newIndex]);
    }
  };

  // Logic: File Upload
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        if (event.target?.result) {
          setUploadedImage(event.target.result as string);
        }
      };
      reader.readAsDataURL(file);
    }
    // Reset value so same file can be selected again if needed
    if (fileInputRef.current) {
        fileInputRef.current.value = '';
    }
  };

  const clearUploadedImage = () => {
    setUploadedImage(null);
  };

  // Logic: Generate Random Seed
  const handleRandomSeed = () => {
    setSeed(Math.floor(Math.random() * 1000000000));
  };

  // Logic: Handle Generation
  const handleGenerate = async () => {
    // Basic validation: Must have either prompt OR image
    if (!prompt.trim() && !uploadedImage) {
        setErrorMsg("Please enter a text prompt or upload an image to start.");
        setStatus('error');
        return;
    }

    setStatus('generating');
    setErrorMsg(null);
    setCurrentImage(null);
    setIsEditing(false);

    // Scroll to preview on mobile
    if (window.innerWidth < 768) {
        previewRef.current?.scrollIntoView({ behavior: 'smooth' });
    }

    try {
      const base64Image = await generateImageWithNano(
          prompt, 
          selectedStyleId, 
          aspectRatio, 
          seed, 
          creativity, 
          uploadedImage
      );

      const newImage: GeneratedImage = {
        id: crypto.randomUUID(),
        url: base64Image,
        prompt: prompt || 'Image Variation', // Fallback title for history if prompt empty
        styleId: selectedStyleId,
        aspectRatio: aspectRatio,
        seed: seed,
        creativity: creativity,
        timestamp: Date.now()
      };

      setCurrentImage(newImage);
      setHistory(prev => [newImage, ...prev].slice(0, 10)); // Keep last 10
      setStatus('success');
    } catch (error) {
      console.error(error);
      setStatus('error');
      setErrorMsg("Failed to generate. Please try again.");
    }
  };

  // Logic: Handle Download
  const handleDownload = () => {
    if (!currentImage) return;
    const link = document.createElement('a');
    link.href = currentImage.url;
    link.download = `${APP_NAME.toLowerCase()}-${currentImage.id.slice(0, 8)}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Logic: Load from history
  const loadFromHistory = (img: GeneratedImage) => {
    setCurrentImage(img);
    setPrompt(img.prompt);

    // Update undo history with loaded prompt
    setPromptHistory(prev => {
       const newHistory = prev.slice(0, historyIndex + 1);
       if (newHistory[newHistory.length - 1] !== img.prompt) {
         newHistory.push(img.prompt);
       }
       return newHistory;
    });
    setHistoryIndex(prev => prev + 1);

    setSelectedStyleId(img.styleId);
    setAspectRatio(img.aspectRatio || '1:1');
    setSeed(img.seed);
    setCreativity(img.creativity ?? 50);
    setUploadedImage(null); 

    setStatus('success');
    setIsEditing(false);
    if (window.innerWidth < 768) {
        previewRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  };

  // Logic: Save Edit
  const handleSaveEdit = (newImageSrc: string) => {
     if (!currentImage) return;

     const newImage: GeneratedImage = {
        ...currentImage,
        id: crypto.randomUUID(),
        url: newImageSrc,
        timestamp: Date.now()
     };

     setCurrentImage(newImage);
     setHistory(prev => [newImage, ...prev].slice(0, 10));
     setIsEditing(false);
  };

  return (
    <div className="min-h-screen bg-nano-50 text-nano-900 selection:bg-nano-900 selection:text-white flex flex-col">

      {/* --- Header --- */}
      <header className="bg-white/80 backdrop-blur-md sticky top-0 z-50 border-b border-nano-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-nano-900 rounded-lg flex items-center justify-center text-white">
              <Camera size={18} />
            </div>
            <h1 className="text-lg font-bold tracking-tight">{APP_NAME}</h1>
            <Badge text={MODEL_NAME_DISPLAY} />
          </div>
          <div className="hidden sm:flex text-sm text-nano-500 font-medium">
             AI Photo Lab
          </div>
        </div>
      </header>

      {/* --- Main Content --- */}
      <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full flex flex-col lg:flex-row gap-8 lg:gap-12">

        {/* --- Left Column: Controls --- */}
        <div className="w-full lg:w-1/3 flex flex-col gap-8 order-2 lg:order-1">

          {/* Prompt Section */}
          <section className="space-y-4">
            <div className="flex justify-between items-end">
              <div className="space-y-1">
                <label htmlFor="prompt" className="block text-sm font-semibold text-nano-800">
                  Prompt
                </label>
                <p className="text-xs text-nano-500">Describe what you want to see in detail.</p>
              </div>
              <div className="flex items-center gap-1">
                <button 
                  onClick={handleUndo}
                  disabled={historyIndex === 0}
                  className="p-1.5 rounded-md hover:bg-nano-100 text-nano-500 disabled:opacity-30 disabled:hover:bg-transparent transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-1"
                  title="Undo"
                >
                  <Undo size={14} />
                </button>
                <button 
                  onClick={handleRedo}
                  disabled={historyIndex >= promptHistory.length - 1}
                  className="p-1.5 rounded-md hover:bg-nano-100 text-nano-500 disabled:opacity-30 disabled:hover:bg-transparent transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-1"
                  title="Redo"
                >
                  <Redo size={14} />
                </button>
              </div>
            </div>
            <div className="relative">
              <textarea
                id="prompt"
                value={prompt}
                onChange={handlePromptChange}
                placeholder="A futuristic house on a cliff, golden hour..."
                className="w-full p-4 rounded-xl border border-nano-200 bg-white shadow-sm text-nano-900 placeholder:text-nano-400 focus:outline-none focus:ring-2 focus:ring-nano-900 focus:ring-offset-1 focus:border-transparent resize-none h-32 transition-all"
              />
            </div>
          </section>

          {/* Reference Image Section */}
          <section className="space-y-4">
            <div className="space-y-1">
               <label className="block text-sm font-semibold text-nano-800">
                 Reference Image
               </label>
               <p className="text-xs text-nano-500">Upload a photo to guide the generation (optional).</p>
            </div>

            <input 
              type="file" 
              ref={fileInputRef}
              onChange={handleFileUpload}
              className="hidden" 
              accept="image/*"
            />

            {!uploadedImage ? (
              <button 
                type="button"
                onClick={() => fileInputRef.current?.click()}
                className="w-full border-2 border-dashed border-nano-200 rounded-xl p-6 flex flex-col items-center justify-center text-nano-400 hover:border-nano-400 hover:text-nano-600 hover:bg-nano-50 transition-all cursor-pointer h-24 focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-2"
              >
                 <div className="flex items-center gap-2 text-sm font-medium">
                   <Upload size={16} />
                   <span>Upload Image</span>
                 </div>
              </button>
            ) : (
              <div className="relative group">
                <div className="h-48 w-full bg-nano-100 rounded-xl overflow-hidden border border-nano-200">
                   <img src={uploadedImage} alt="Reference" className="w-full h-full object-cover opacity-80 group-hover:opacity-100 transition-opacity" />
                </div>
                <button 
                  onClick={clearUploadedImage}
                  className="absolute top-2 right-2 bg-white/90 backdrop-blur p-1.5 rounded-full text-nano-600 hover:text-red-500 hover:bg-white shadow-sm transition-all focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900"
                >
                  <X size={14} />
                </button>
                <div className="absolute bottom-2 right-2 px-2 py-1 bg-black/50 backdrop-blur-sm rounded-md text-white text-[10px] font-medium pointer-events-none">
                  Reference
                </div>
              </div>
            )}
          </section>

          {/* Aspect Ratio Section */}
          <section className="space-y-4">
            <div className="space-y-1">
              <label className="block text-sm font-semibold text-nano-800">
                Dimensions
              </label>
              <p className="text-xs text-nano-500">Choose the aspect ratio.</p>
            </div>
            <div className="flex gap-2 flex-wrap">
              {ASPECT_RATIOS.map((ratio) => (
                <button
                  key={ratio.id}
                  onClick={() => setAspectRatio(ratio.id)}
                  className={`
                    flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium border transition-all focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-2
                    ${aspectRatio === ratio.id 
                      ? 'bg-nano-900 text-white border-nano-900 shadow-md' 
                      : 'bg-white text-nano-600 border-nano-200 hover:border-nano-300 hover:bg-nano-50'
                    }
                  `}
                >
                  <div className={`border-2 rounded-sm ${ratio.shapeClass} ${aspectRatio === ratio.id ? 'border-white/80' : 'border-nano-400'}`}></div>
                  <span>{ratio.label}</span>
                </button>
              ))}
            </div>
          </section>

          {/* Advanced Settings Toggle */}
          <section className="space-y-4">
             <button 
              onClick={() => setShowAdvanced(!showAdvanced)}
