import React, { useState, useRef, useEffect } from 'react';
import { Button } from './UI';
import { Check, X, Crop, Wand2, ZoomIn } from 'lucide-react';
import { IMAGE_FILTERS, ASPECT_RATIOS } from '../constants';

interface ImageEditorProps {
  imageSrc: string;
  onSave: (newImageSrc: string) => void;
  onCancel: () => void;
}

export const ImageEditor: React.FC<ImageEditorProps> = ({ imageSrc, onSave, onCancel }) => {
  const [activeTab, setActiveTab] = useState<'filter' | 'crop'>('filter');
  const [selectedFilterId, setSelectedFilterId] = useState('none');

  // Crop state
  const [zoom, setZoom] = useState(1);
  const [cropRatio, setCropRatio] = useState<string>('1:1');
  const [pan, setPan] = useState({ x: 0, y: 0 });

  // Interaction state
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  const imageRef = useRef<HTMLImageElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Get current filter string
  const currentFilter = IMAGE_FILTERS.find(f => f.id === selectedFilterId)?.filter || 'none';

  const handlePointerDown = (e: React.PointerEvent) => {
    setIsDragging(true);
    setDragStart({ x: e.clientX - pan.x, y: e.clientY - pan.y });
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (isDragging) {
      setPan({
        x: e.clientX - dragStart.x,
        y: e.clientY - dragStart.y
      });
    }
  };

  const handlePointerUp = () => {
    setIsDragging(false);
  };

  const handleSave = () => {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    const img = imageRef.current;

    if (!ctx || !img) return;

    // Determine output size based on crop ratio
    // We'll use a fixed high resolution for the output, maintaining ratio
    const outputSize = 1024;
    let width = outputSize;
    let height = outputSize;

    const [wRatio, hRatio] = cropRatio.split(':').map(Number);
    if (wRatio && hRatio) {
        if (wRatio > hRatio) {
            height = outputSize * (hRatio / wRatio);
        } else {
            width = outputSize * (wRatio / hRatio);
        }
    }

    canvas.width = width;
    canvas.height = height;

    // Apply Filter
    ctx.filter = currentFilter;

    // Draw background (black)
    ctx.fillStyle = '#000000';
    ctx.fillRect(0, 0, width, height);

    // Calculate scaling to fit the image into the canvas based on user's zoom/pan
    // This is an approximation of the DOM transform logic
    // In DOM: transform: scale(zoom) translate(pan.x, pan.y)
    // We need to map screen pixels to canvas pixels

    // Simple approach: Render exact viewport
    // Find the center of the image relative to the container center

    const container = containerRef.current;
    if (!container) return;

    const scaleFactor = width / container.clientWidth;

    ctx.save();

    // Move to center
    ctx.translate(width / 2, height / 2);
    ctx.scale(zoom, zoom);
    ctx.translate(pan.x * scaleFactor, pan.y * scaleFactor);

    // Draw image centered
    // We need to maintain aspect ratio of original image
    const imgAspect = img.naturalWidth / img.naturalHeight;

    let drawWidth, drawHeight;
    if (width / height > imgAspect) {
        // Canvas is wider than image
        drawHeight = height;
        drawWidth = height * imgAspect;
    } else {
        // Canvas is taller than image
        drawWidth = width;
        drawHeight = width / imgAspect;
    }

    // Draw centered
    ctx.drawImage(img, -drawWidth / 2, -drawHeight / 2, drawWidth, drawHeight);

    ctx.restore();

    onSave(canvas.toDataURL('image/png'));
  };

  return (
    <div className="absolute inset-0 bg-white z-50 flex flex-col h-full animate-in fade-in duration-300">
      {/* Header */}
      <div className="h-14 border-b border-nano-200 flex items-center justify-between px-4 bg-white shrink-0">
        <button 
          onClick={onCancel}
          className="p-2 text-nano-500 hover:text-nano-900 hover:bg-nano-100 rounded-lg transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-1"
        >
          <X size={20} />
        </button>
        <span className="font-semibold text-sm">Edit Image</span>
        <button 
          onClick={handleSave}
          className="p-2 text-nano-900 hover:bg-nano-100 rounded-lg transition-colors font-medium focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-1"
        >
          <Check size={20} />
        </button>
      </div>

      {/* Main Canvas Area */}
      <div className="flex-grow bg-nano-100 overflow-hidden relative flex items-center justify-center p-8 select-none">

        {/* Viewport Frame */}
        <div 
          ref={containerRef}
          className="relative bg-black overflow-hidden shadow-2xl ring-4 ring-white/50"
          style={{
             aspectRatio: cropRatio.replace(':', '/'),
             width: '100%',
             maxWidth: '100%',
             maxHeight: '100%',
             cursor: isDragging ? 'grabbing' : 'grab',
             touchAction: 'none'
          }}
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={handlePointerUp}
          onPointerLeave={handlePointerUp}
        >
           <img 
             ref={imageRef}
             src={imageSrc} 
             alt="Editing"
             className="absolute max-w-none max-h-none origin-center pointer-events-none"
             style={{
                top: '50%',
                left: '50%',
                transform: `translate(-50%, -50%) scale(${zoom}) translate(${pan.x}px, ${pan.y}px)`,
                filter: currentFilter,
                minWidth: '100%',
                minHeight: '100%'
             }}
             draggable={false}
           />
        </div>

        <div className="absolute bottom-4 left-1/2 -translate-x-1/2 bg-black/70 text-white text-xs px-3 py-1 rounded-full backdrop-blur-sm pointer-events-none opacity-50">
           Drag to Pan • Pinch to Zoom
        </div>
      </div>

      {/* Controls */}
      <div className="bg-white border-t border-nano-200 shrink-0 pb-safe">

        {/* Tabs */}
        <div className="flex border-b border-nano-100">
           <button 
             onClick={() => setActiveTab('filter')}
             className={`flex-1 py-3 text-sm font-medium flex items-center justify-center gap-2 focus:outline-none focus-visible:bg-nano-50 ${activeTab === 'filter' ? 'text-nano-900 border-b-2 border-nano-900' : 'text-nano-500'}`}
           >
             <Wand2 size={16} /> Filters
           </button>
           <button 
             onClick={() => setActiveTab('crop')}
             className={`flex-1 py-3 text-sm font-medium flex items-center justify-center gap-2 focus:outline-none focus-visible:bg-nano-50 ${activeTab === 'crop' ? 'text-nano-900 border-b-2 border-nano-900' : 'text-nano-500'}`}
           >
             <Crop size={16} /> Crop
           </button>
        </div>

        {/* Tab Content */}
        <div className="h-32 p-4">

           {activeTab === 'filter' && (
             <div className="flex gap-4 overflow-x-auto pb-2 hide-scrollbar h-full items-center">
                {IMAGE_FILTERS.map((f) => (
                   <button 
                     key={f.id}
                     onClick={() => setSelectedFilterId(f.id)}
                     className="flex flex-col items-center gap-2 shrink-0 group focus:outline-none"
                   >
                      <div className={`w-16 h-16 rounded-lg overflow-hidden border-2 transition-all group-focus-visible:ring-2 group-focus-visible:ring-nano-900 group-focus-visible:ring-offset-2 ${selectedFilterId === f.id ? 'border-nano-900 ring-2 ring-nano-900/20' : 'border-transparent group-hover:border-nano-300'}`}>
                         <img 
                           src={imageSrc} 
                           alt={f.name} 
                           className="w-full h-full object-cover" 
                           style={{ filter: f.filter }}
                         />
                      </div>
                      <span className={`text-xs font-medium ${selectedFilterId === f.id ? 'text-nano-900' : 'text-nano-500'}`}>{f.name}</span>
                   </button>
                ))}
             </div>
           )}

           {activeTab === 'crop' && (
             <div className="flex flex-col gap-4 h-full justify-center">
                {/* Zoom Slider */}
                <div className="flex items-center gap-3 px-2">
                   <ZoomIn size={16} className="text-nano-500" />
                   <input 
                     type="range" 
                     min="0.5" 
                     max="3" 
                     step="0.1"
                     value={zoom}
                     onChange={(e) => setZoom(parseFloat(e.target.value))}
                     className="w-full h-1.5 bg-nano-200 rounded-lg appearance-none cursor-pointer accent-nano-900 focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-2"
                   />
                </div>

                {/* Ratios */}
                <div className="flex gap-2 overflow-x-auto pb-1 hide-scrollbar">
                   <button 
                     onClick={() => { setCropRatio('1:1'); setZoom(1); setPan({x:0,y:0}); }}
                     className={`px-3 py-1.5 rounded-lg border text-xs font-medium whitespace-nowrap focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-2 ${cropRatio === '1:1' ? 'bg-nano-900 text-white border-nano-900' : 'border-nano-200 text-nano-600'}`}
                   >
                     Square
                   </button>
                   {ASPECT_RATIOS.slice(1).map(r => (
                     <button 
                        key={r.id}
                        onClick={() => { setCropRatio(r.id); setZoom(1); setPan({x:0,y:0}); }}
                        className={`px-3 py-1.5 rounded-lg border text-xs font-medium whitespace-nowrap focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-2 ${cropRatio === r.id ? 'bg-nano-900 text-white border-nano-900' : 'border-nano-200 text-nano-600'}`}
                     >
                        {r.label}
                     </button>
                   ))}
                </div>
             </div>
           )}

        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { ZoomIn, ZoomOut, Maximize } from 'lucide-react';

interface ZoomablePreviewProps {
  src: string;
  alt: string;
  className?: string;
  isVisible: boolean;
}

export const ZoomablePreview: React.FC<ZoomablePreviewProps> = ({ src, alt, className, isVisible }) => {
  const [scale, setScale] = useState(1);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  const containerRef = useRef<HTMLDivElement>(null);

  // Reset state when the image source changes
  useEffect(() => {
    setScale(1);
    setPosition({ x: 0, y: 0 });
  }, [src]);

  // Non-passive wheel listener for proper scroll blocking and zoom-to-cursor
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const onWheel = (e: WheelEvent) => {
      // Allow scroll if not zoomed and not intending to zoom (no modifiers)
      // But if we are zoomed in, we likely want to intercept wheel to zoom further or ignore scroll
      if (scale === 1 && !e.ctrlKey && !e.metaKey) return;

      e.preventDefault();

      const rect = container.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      // Calculate mouse position relative to container center
      const mx = x - rect.width / 2;
      const my = y - rect.height / 2;

      const delta = e.deltaY * -0.002;
      const newScale = Math.min(Math.max(1, scale + delta), 4);

      if (newScale === 1) {
          setScale(1);
          setPosition({ x: 0, y: 0 });
          return;
      }

      // Zoom to cursor math
      // P' = M - (M - P) * (newScale / oldScale)
      // Where P is position, M is mouse relative to center
      const scaleRatio = newScale / scale;
      const newPos = {
          x: mx - (mx - position.x) * scaleRatio,
          y: my - (my - position.y) * scaleRatio
      };

      setScale(newScale);
      setPosition(newPos);
    };

    container.addEventListener('wheel', onWheel, { passive: false });
    return () => container.removeEventListener('wheel', onWheel);
  }, [scale, position]);

  // Button handlers
  const handleZoomIn = () => {
      setScale(s => Math.min(s + 0.5, 4));
  };

  const handleZoomOut = () => {
    setScale(s => {
        const next = Math.max(s - 0.5, 1);
        if (next === 1) setPosition({ x: 0, y: 0 });
        return next;
    });
  };

  const handleReset = () => {
    setScale(1);
    setPosition({ x: 0, y: 0 });
  };

  // Drag handlers
  const handlePointerDown = (e: React.PointerEvent) => {
    if (scale > 1) {
      setIsDragging(true);
      setDragStart({ x: e.clientX - position.x, y: e.clientY - position.y });
      (e.target as HTMLElement).setPointerCapture(e.pointerId);
      e.preventDefault();
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (isDragging && scale > 1) {
      setPosition({
        x: e.clientX - dragStart.x,
        y: e.clientY - dragStart.y
      });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
      setIsDragging(false);
      (e.target as HTMLElement).releasePointerCapture(e.pointerId);
  };

  return (
    <div 
        ref={containerRef}
        className={`relative w-full h-full flex items-center justify-center overflow-hidden group ${isVisible ? 'opacity-100' : 'opacity-0'} transition-opacity duration-700`}
    >
        {/* Transform Container */}
        <div
            className="relative flex items-center justify-center"
            style={{ 
                transform: `translate(${position.x}px, ${position.y}px) scale(${scale})`,
                transition: isDragging ? 'none' : 'transform 0.1s ease-out',
                cursor: scale > 1 ? (isDragging ? 'grabbing' : 'grab') : 'default',
                touchAction: 'none',
                willChange: 'transform'
            }}
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
        >
            <img
                src={src}
                alt={alt}
                draggable={false}
                className={className}
            />
        </div>

        {/* Floating Controls Overlay */}
        <div 
            className={`
                absolute bottom-6 left-1/2 -translate-x-1/2 
                flex items-center gap-2 
                bg-nano-900/90 backdrop-blur-md rounded-full px-3 py-2 
                text-white shadow-2xl border border-white/10 
                transition-all duration-300 z-10
                ${scale > 1 ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4 group-hover:opacity-100 group-hover:translate-y-0'}
            `}
        >
            <button 
                onClick={handleZoomOut} 
                className="p-1.5 hover:bg-white/20 rounded-full transition-colors active:scale-95 focus:outline-none focus-visible:ring-2 focus-visible:ring-white focus-visible:ring-offset-2 focus-visible:ring-offset-nano-900" 
                title="Zoom Out"
            >
                <ZoomOut size={16} />
            </button>
            <span className="text-xs font-medium w-12 text-center select-none font-mono tabular-nums">
                {Math.round(scale * 100)}%
