import React, { useState, useEffect, useRef } from 'react';
import { ZoomIn, ZoomOut, Maximize, Loader2 } from 'lucide-react';

interface ZoomablePreviewProps {
  src: string;
  alt: string;
  className?: string;
  isVisible: boolean;
}

export const ZoomablePreview: React.FC<ZoomablePreviewProps> = ({ src, alt, className, isVisible }) => {
  const [scale, setScale] = useState(1);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [isLoaded, setIsLoaded] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);

  // Reset state when the image source changes
  useEffect(() => {
    setScale(1);
    setPosition({ x: 0, y: 0 });
    setIsLoaded(false);
  }, [src]);

  // Non-passive wheel listener for proper scroll blocking and zoom-to-cursor
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const onWheel = (e: WheelEvent) => {
      // Allow scroll if not zoomed and not intending to zoom (no modifiers)
      // But if we are zoomed in, we likely want to intercept wheel to zoom further or ignore scroll
      if (scale === 1 && !e.ctrlKey && !e.metaKey) return;

      e.preventDefault();

      const rect = container.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      // Calculate mouse position relative to container center
      const mx = x - rect.width / 2;
      const my = y - rect.height / 2;

      const delta = e.deltaY * -0.002;
      const newScale = Math.min(Math.max(1, scale + delta), 4);

      if (newScale === 1) {
          setScale(1);
          setPosition({ x: 0, y: 0 });
          return;
      }

      // Zoom to cursor math
      // P' = M - (M - P) * (newScale / oldScale)
      // Where P is position, M is mouse relative to center
      const scaleRatio = newScale / scale;
      const newPos = {
          x: mx - (mx - position.x) * scaleRatio,
          y: my - (my - position.y) * scaleRatio
      };

      setScale(newScale);
      setPosition(newPos);
    };

    container.addEventListener('wheel', onWheel, { passive: false });
    return () => container.removeEventListener('wheel', onWheel);
  }, [scale, position]);

  // Button handlers
  const handleZoomIn = () => {
      setScale(s => Math.min(s + 0.5, 4));
  };

  const handleZoomOut = () => {
    setScale(s => {
        const next = Math.max(s - 0.5, 1);
        if (next === 1) setPosition({ x: 0, y: 0 });
        return next;
    });
  };

  const handleReset = () => {
    setScale(1);
    setPosition({ x: 0, y: 0 });
  };

  // Drag handlers
  const handlePointerDown = (e: React.PointerEvent) => {
    if (scale > 1) {
      setIsDragging(true);
      setDragStart({ x: e.clientX - position.x, y: e.clientY - position.y });
      (e.target as HTMLElement).setPointerCapture(e.pointerId);
      e.preventDefault();
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (isDragging && scale > 1) {
      setPosition({
        x: e.clientX - dragStart.x,
        y: e.clientY - dragStart.y
      });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
      setIsDragging(false);
      (e.target as HTMLElement).releasePointerCapture(e.pointerId);
  };

  return (
    <div 
        ref={containerRef}
        className={`relative w-full h-full flex items-center justify-center overflow-hidden group bg-nano-50 ${isVisible ? 'opacity-100' : 'opacity-0'} transition-opacity duration-700`}
    >
        {/* Loader */}
        {!isLoaded && (
          <div className="absolute inset-0 flex items-center justify-center z-0">
             <Loader2 className="w-8 h-8 text-nano-300 animate-spin" />
          </div>
        )}

        {/* Transform Container */}
        <div
            className="relative flex items-center justify-center"
            style={{ 
                transform: `translate(${position.x}px, ${position.y}px) scale(${scale})`,
                transition: isDragging ? 'none' : 'transform 0.1s ease-out',
                cursor: scale > 1 ? (isDragging ? 'grabbing' : 'grab') : 'default',
                touchAction: 'none',
                willChange: 'transform'
            }}
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
        >
            <img
                src={src}
                alt={alt}
                draggable={false}
                loading="lazy"
                decoding="async"
                onLoad={() => setIsLoaded(true)}
                className={`${className} transition-opacity duration-300 ${isLoaded ? 'opacity-100' : 'opacity-0'}`}
            />
        </div>

        {/* Floating Controls Overlay */}
        <div 
            className={`
                absolute bottom-6 left-1/2 -translate-x-1/2 
                flex items-center gap-2 
                bg-nano-900/90 backdrop-blur-md rounded-full px-3 py-2 
                text-white shadow-2xl border border-white/10 
                transition-all duration-300 z-10
                ${isLoaded && scale > 1 ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4 pointer-events-none'}
                ${isLoaded && 'group-hover:opacity-100 group-hover:translate-y-0 group-hover:pointer-events-auto'}
            `}
        >
            <button 
                onClick={handleZoomOut} 
                className="p-1.5 hover:bg-white/20 rounded-full transition-colors active:scale-95 focus:outline-none focus-visible:ring-2 focus-visible:ring-white focus-visible:ring-offset-2 focus-visible:ring-offset-nano-900" 
                title="Zoom Out"
            >
                <ZoomOut size={16} />
            </button>
            <span className="text-xs font-medium w-12 text-center select-none font-mono tabular-nums">
                {Math.round(scale * 100)}%
            </span>
            <button 
                onClick={handleZoomIn} 
                className="p-1.5 hover:bg-white/20 rounded-full transition-colors active:scale-95 focus:outline-none focus-visible:ring-2 focus-visible:ring-white focus-visible:ring-offset-2 focus-visible:ring-offset-nano-900" 
                title="Zoom In"
            >
                <ZoomIn size={16} />
            </button>
            <div className="w-px h-4 bg-white/20 mx-1"></div>
            <button 
                onClick={handleReset} 
                className="p-1.5 hover:bg-white/20 rounded-full transition-colors active:scale-95 focus:outline-none focus-visible:ring-2 focus-visible:ring-white focus-visible:ring-offset-2 focus-visible:ring-offset-nano-900" 
                title="Reset View"
            >
                <Maximize size={16} />
            </button>
        </div>

        {/* Hint for first-time users */}
        {isLoaded && scale === 1 && (
             <div className="absolute top-4 right-4 bg-black/60 text-white text-[10px] font-medium px-3 py-1.5 rounded-full backdrop-blur-sm pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity duration-300 shadow-sm border border-white/10">
                Pinch or Scroll to Zoom
             </div>
        )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Button } from './UI';
import { Check, X, Crop, Wand2, ZoomIn, RotateCcw, Loader2 } from 'lucide-react';
import { IMAGE_FILTERS, ASPECT_RATIOS } from '../constants';

interface ImageEditorProps {
  imageSrc: string;
  onSave: (newImageSrc: string) => void;
  onCancel: () => void;
}

export const ImageEditor: React.FC<ImageEditorProps> = ({ imageSrc, onSave, onCancel }) => {
  const [activeTab, setActiveTab] = useState<'filter' | 'crop'>('filter');
  const [selectedFilterId, setSelectedFilterId] = useState('none');
  const [imageLoaded, setImageLoaded] = useState(false);

  // Crop state
  const [zoom, setZoom] = useState(1);
  const [cropRatio, setCropRatio] = useState<string>('1:1');
  const [pan, setPan] = useState({ x: 0, y: 0 });

  // Interaction state
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  const imageRef = useRef<HTMLImageElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Get current filter string
  const currentFilter = IMAGE_FILTERS.find(f => f.id === selectedFilterId)?.filter || 'none';

  const handlePointerDown = (e: React.PointerEvent) => {
    setIsDragging(true);
    setDragStart({ x: e.clientX - pan.x, y: e.clientY - pan.y });
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (isDragging) {
      setPan({
        x: e.clientX - dragStart.x,
        y: e.clientY - dragStart.y
      });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    setIsDragging(false);
    (e.target as HTMLElement).releasePointerCapture(e.pointerId);
  };

  const handleResetTransform = () => {
    setZoom(1);
    setPan({ x: 0, y: 0 });
  };

  const handleSave = () => {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    const img = imageRef.current;

    if (!ctx || !img) return;

    // Determine output size based on crop ratio
    // We'll use a fixed high resolution for the output, maintaining ratio
    const outputSize = 1536; // High res export
    let width = outputSize;
    let height = outputSize;

    const [wRatio, hRatio] = cropRatio.split(':').map(Number);
    if (wRatio && hRatio) {
        if (wRatio > hRatio) {
            height = outputSize * (hRatio / wRatio);
        } else {
            width = outputSize * (wRatio / hRatio);
        }
    }

    canvas.width = width;
    canvas.height = height;

    // Draw background (black) - cleanly without filter
    ctx.fillStyle = '#000000';
    ctx.fillRect(0, 0, width, height);

    // Calculate scaling to fit the image into the canvas based on user's zoom/pan
    // This is an approximation of the DOM transform logic
    // In DOM: transform: scale(zoom) translate(pan.x, pan.y)
    // We need to map screen pixels to canvas pixels

    // Simple approach: Render exact viewport
    // Find the center of the image relative to the container center

    const container = containerRef.current;
    if (!container) return;

    const scaleFactor = width / container.clientWidth;

    ctx.save();

    // Apply Filter only to the image drawing
    ctx.filter = currentFilter;

    // Move to center
    ctx.translate(width / 2, height / 2);
    ctx.scale(zoom, zoom);
    ctx.translate(pan.x * scaleFactor, pan.y * scaleFactor);

    // Draw image centered
    // We need to maintain aspect ratio of original image
    const imgAspect = img.naturalWidth / img.naturalHeight;

    let drawWidth, drawHeight;
    if (width / height > imgAspect) {
        // Canvas is wider than image
        drawHeight = height;
        drawWidth = height * imgAspect;
    } else {
        // Canvas is taller than image
        drawWidth = width;
        drawHeight = width / imgAspect;
    }

    // Draw centered
    ctx.drawImage(img, -drawWidth / 2, -drawHeight / 2, drawWidth, drawHeight);

    ctx.restore();

    onSave(canvas.toDataURL('image/png', 0.95));
  };

  return (
    <div className="absolute inset-0 bg-white z-50 flex flex-col h-full animate-in fade-in duration-300">
      {/* Header */}
      <div className="h-14 border-b border-nano-200 flex items-center justify-between px-4 bg-white shrink-0">
        <button 
          onClick={onCancel}
          className="p-2 text-nano-500 hover:text-nano-900 hover:bg-nano-100 rounded-lg transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-1"
        >
          <X size={20} />
        </button>
        <span className="font-semibold text-sm">Edit Image</span>
        <button 
          onClick={handleSave}
          disabled={!imageLoaded}
          className="p-2 text-nano-900 hover:bg-nano-100 rounded-lg transition-colors font-medium focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-1 disabled:opacity-50"
        >
          <Check size={20} />
        </button>
      </div>

      {/* Main Canvas Area */}
      <div className="flex-grow bg-nano-100 overflow-hidden relative flex items-center justify-center p-8 select-none">

        {/* Loader */}
        {!imageLoaded && (
          <div className="absolute inset-0 z-10 flex items-center justify-center bg-nano-100/80 backdrop-blur-sm">
             <Loader2 className="w-8 h-8 text-nano-900 animate-spin" />
          </div>
        )}

        {/* Viewport Frame */}
        <div 
          ref={containerRef}
          className="relative bg-black overflow-hidden shadow-2xl ring-4 ring-white/50"
          style={{
             aspectRatio: cropRatio.replace(':', '/'),
             width: '100%',
             maxWidth: '100%',
             maxHeight: '100%',
             cursor: isDragging ? 'grabbing' : 'grab',
             touchAction: 'none'
          }}
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={handlePointerUp}
          onPointerLeave={handlePointerUp}
        >
           <img 
             ref={imageRef}
             src={imageSrc} 
             alt="Editing"
             loading="lazy"
             decoding="async"
             onLoad={() => setImageLoaded(true)}
             className={`absolute max-w-none max-h-none origin-center pointer-events-none transition-opacity duration-300 ${imageLoaded ? 'opacity-100' : 'opacity-0'}`}
             style={{
                top: '50%',
                left: '50%',
                transform: `translate(-50%, -50%) scale(${zoom}) translate(${pan.x}px, ${pan.y}px)`,
                filter: currentFilter,
                minWidth: '100%',
                minHeight: '100%'
             }}
             draggable={false}
           />

           {/* Rule of Thirds Grid Overlay */}
           {activeTab === 'crop' && imageLoaded && (
             <div className="absolute inset-0 pointer-events-none opacity-50">
                <div className="absolute top-1/3 left-0 right-0 h-px bg-white/50 shadow-sm"></div>
                <div className="absolute top-2/3 left-0 right-0 h-px bg-white/50 shadow-sm"></div>
                <div className="absolute left-1/3 top-0 bottom-0 w-px bg-white/50 shadow-sm"></div>
                <div className="absolute left-2/3 top-0 bottom-0 w-px bg-white/50 shadow-sm"></div>
             </div>
           )}
        </div>

        {imageLoaded && (
            <div className="absolute bottom-4 left-1/2 -translate-x-1/2 bg-black/70 text-white text-xs px-3 py-1 rounded-full backdrop-blur-sm pointer-events-none opacity-50">
            Drag to Pan • Pinch to Zoom
            </div>
        )}
      </div>

      {/* Controls */}
      <div className="bg-white border-t border-nano-200 shrink-0 pb-safe">

        {/* Tabs */}
        <div className="flex border-b border-nano-100">
           <button 
             onClick={() => setActiveTab('filter')}
             className={`flex-1 py-3 text-sm font-medium flex items-center justify-center gap-2 focus:outline-none focus-visible:bg-nano-50 ${activeTab === 'filter' ? 'text-nano-900 border-b-2 border-nano-900' : 'text-nano-500'}`}
           >
             <Wand2 size={16} /> Filters
           </button>
           <button 
             onClick={() => setActiveTab('crop')}
             className={`flex-1 py-3 text-sm font-medium flex items-center justify-center gap-2 focus:outline-none focus-visible:bg-nano-50 ${activeTab === 'crop' ? 'text-nano-900 border-b-2 border-nano-900' : 'text-nano-500'}`}
           >
             <Crop size={16} /> Crop
           </button>
        </div>

        {/* Tab Content */}
        <div className="h-32 p-4">

           {activeTab === 'filter' && (
             <div className="flex gap-4 overflow-x-auto pb-2 hide-scrollbar h-full items-center">
                {IMAGE_FILTERS.map((f) => (
                   <button 
                     key={f.id}
                     onClick={() => setSelectedFilterId(f.id)}
                     className="flex flex-col items-center gap-2 shrink-0 group focus:outline-none"
                   >
                      <div className={`w-16 h-16 rounded-lg overflow-hidden border-2 transition-all group-focus-visible:ring-2 group-focus-visible:ring-nano-900 group-focus-visible:ring-offset-2 ${selectedFilterId === f.id ? 'border-nano-900 ring-2 ring-nano-900/20' : 'border-transparent group-hover:border-nano-300'}`}>
                         <img 
                           src={imageSrc} 
                           alt={f.name} 
                           loading="lazy"
                           decoding="async"
                           className="w-full h-full object-cover" 
                           style={{ filter: f.filter }}
                         />
                      </div>
                      <span className={`text-xs font-medium ${selectedFilterId === f.id ? 'text-nano-900' : 'text-nano-500'}`}>{f.name}</span>
                   </button>
                ))}
             </div>
           )}

           {activeTab === 'crop' && (
             <div className="flex flex-col gap-4 h-full justify-center">
                {/* Zoom Slider */}
                <div className="flex items-center gap-3 px-2">
                   <ZoomIn size={16} className="text-nano-500" />
                   <input 
                     type="range" 
                     min="0.5" 
                     max="3" 
                     step="0.1"
                     value={zoom}
                     onChange={(e) => setZoom(parseFloat(e.target.value))}
                     className="w-full h-1.5 bg-nano-200 rounded-lg appearance-none cursor-pointer accent-nano-900 focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-2"
                   />
                   <button 
                     onClick={handleResetTransform}
                     className="ml-2 p-1.5 text-nano-500 hover:text-nano-900 hover:bg-nano-100 rounded-lg transition-colors"
                     title="Reset Transform"
                   >
                     <RotateCcw size={16} />
                   </button>
                </div>

                {/* Ratios */}
                <div className="flex gap-2 overflow-x-auto pb-1 hide-scrollbar">
                   <button 
                     onClick={() => { setCropRatio('1:1'); setZoom(1); setPan({x:0,y:0}); }}
                     className={`px-3 py-1.5 rounded-lg border text-xs font-medium whitespace-nowrap focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-2 ${cropRatio === '1:1' ? 'bg-nano-900 text-white border-nano-900' : 'border-nano-200 text-nano-600'}`}
                   >
                     Square
                   </button>
                   {ASPECT_RATIOS.slice(1).map(r => (
                     <button 
                        key={r.id}
                        onClick={() => { setCropRatio(r.id); setZoom(1); setPan({x:0,y:0}); }}
                        className={`px-3 py-1.5 rounded-lg border text-xs font-medium whitespace-nowrap focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-2 ${cropRatio === r.id ? 'bg-nano-900 text-white border-nano-900' : 'border-nano-200 text-nano-600'}`}
                     >
                        {r.label}
                     </button>
                   ))}
                </div>
             </div>
           )}

        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { 
  Sparkles, 
  Download, 
  RefreshCw, 
  Image as ImageIcon, 
  History, 
  Zap,
  Camera,
  Maximize,
  Sliders,
  ChevronDown,
  ChevronUp,
  Undo,
  Redo,
  Upload,
  X,
  Plus,
  Edit2,
  Dices,
  Trash2
} from 'lucide-react';
import { ART_STYLES, APP_NAME, MODEL_NAME_DISPLAY, ASPECT_RATIOS } from './constants';
import { ArtStyle, GeneratedImage, GenerationStatus } from './types';
import { generateImageWithNano } from './services/geminiService';
import { Button, StyleCard, Badge } from './components/UI';
import { ImageEditor } from './components/ImageEditor';
import { ZoomablePreview } from './components/ZoomablePreview';

const App: React.FC = () => {
  // State
  const [prompt, setPrompt] = useState<string>('');
  const [selectedStyleId, setSelectedStyleId] = useState<string>(ART_STYLES[0].id);
  const [aspectRatio, setAspectRatio] = useState<string>('1:1');

  // Advanced Settings State
  const [seed, setSeed] = useState<number | undefined>(undefined);
  const [creativity, setCreativity] = useState<number>(50); // 0-100
  const [showAdvanced, setShowAdvanced] = useState<boolean>(false);

  // Image Upload State
  const [uploadedImage, setUploadedImage] = useState<string | null>(null);

  const [status, setStatus] = useState<GenerationStatus>('idle');
  const [currentImage, setCurrentImage] = useState<GeneratedImage | null>(null);
  const [history, setHistory] = useState<GeneratedImage[]>([]);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  // Editing State
  const [isEditing, setIsEditing] = useState(false);

  // Undo/Redo State
  const [promptHistory, setPromptHistory] = useState<string[]>(['']);
  const [historyIndex, setHistoryIndex] = useState(0);
  const debounceRef = useRef<any>(null);

  // Refs
  const previewRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Helper to get full style object
  const selectedStyle = ART_STYLES.find(s => s.id === selectedStyleId) || ART_STYLES[0];

  // Logic: Handle Prompt Change with Debounced History
  const handlePromptChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newVal = e.target.value;
    setPrompt(newVal);

    // Debounce adding to history so we don't save every char
    if (debounceRef.current) clearTimeout(debounceRef.current);

    debounceRef.current = setTimeout(() => {
      setPromptHistory(prev => {
        const newHistory = prev.slice(0, historyIndex + 1);
        newHistory.push(newVal);
        return newHistory;
      });
      setHistoryIndex(prev => prev + 1);
    }, 400);
  };

  // Logic: Undo
  const handleUndo = () => {
    if (historyIndex > 0) {
      const newIndex = historyIndex - 1;
      setHistoryIndex(newIndex);
      setPrompt(promptHistory[newIndex]);
    }
  };

  // Logic: Redo
  const handleRedo = () => {
    if (historyIndex < promptHistory.length - 1) {
      const newIndex = historyIndex + 1;
      setHistoryIndex(newIndex);
      setPrompt(promptHistory[newIndex]);
    }
  };

  // Logic: File Upload
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        if (event.target?.result) {
          setUploadedImage(event.target.result as string);
        }
      };
      reader.readAsDataURL(file);
    }
    // Reset value so same file can be selected again if needed
    if (fileInputRef.current) {
        fileInputRef.current.value = '';
    }
  };

  const clearUploadedImage = () => {
    setUploadedImage(null);
  };

  // Logic: Generate Random Seed
  const handleRandomSeed = () => {
    setSeed(Math.floor(Math.random() * 1000000000));
  };

  // Logic: Handle Generation
  const handleGenerate = async () => {
    // Basic validation: Must have either prompt OR image
    if (!prompt.trim() && !uploadedImage) {
        setErrorMsg("Please enter a text prompt or upload an image to start.");
        setStatus('error');
        return;
    }

    setStatus('generating');
    setErrorMsg(null);
    setCurrentImage(null);
    setIsEditing(false);

    // Scroll to preview on mobile
    if (window.innerWidth < 768) {
        previewRef.current?.scrollIntoView({ behavior: 'smooth' });
    }

    try {
      const base64Image = await generateImageWithNano(
          prompt, 
          selectedStyleId, 
          aspectRatio, 
          seed, 
          creativity, 
          uploadedImage
      );

      const newImage: GeneratedImage = {
        id: crypto.randomUUID(),
        url: base64Image,
        prompt: prompt || 'Image Variation', // Fallback title for history if prompt empty
        styleId: selectedStyleId,
        aspectRatio: aspectRatio,
        seed: seed,
        creativity: creativity,
        timestamp: Date.now()
      };

      setCurrentImage(newImage);
      setHistory(prev => [newImage, ...prev].slice(0, 10)); // Keep last 10
      setStatus('success');
    } catch (error) {
      console.error(error);
      setStatus('error');
      setErrorMsg("Failed to generate. Please try again.");
    }
  };

  // Logic: Handle Download
  const handleDownload = () => {
    if (!currentImage) return;
    const link = document.createElement('a');
    link.href = currentImage.url;
    link.download = `${APP_NAME.toLowerCase()}-${currentImage.id.slice(0, 8)}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Logic: Load from history
  const loadFromHistory = (img: GeneratedImage) => {
    setCurrentImage(img);
    setPrompt(img.prompt);

    // Update undo history with loaded prompt
    setPromptHistory(prev => {
       const newHistory = prev.slice(0, historyIndex + 1);
       if (newHistory[newHistory.length - 1] !== img.prompt) {
         newHistory.push(img.prompt);
       }
       return newHistory;
    });
    setHistoryIndex(prev => prev + 1);

    setSelectedStyleId(img.styleId);
    setAspectRatio(img.aspectRatio || '1:1');
    setSeed(img.seed);
    setCreativity(img.creativity ?? 50);
    setUploadedImage(null); 

    setStatus('success');
    setIsEditing(false);
    if (window.innerWidth < 768) {
        previewRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  };

  // Logic: Save Edit
  const handleSaveEdit = (newImageSrc: string) => {
     if (!currentImage) return;

     const newImage: GeneratedImage = {
        ...currentImage,
        id: crypto.randomUUID(),
        url: newImageSrc,
        timestamp: Date.now()
     };

     setCurrentImage(newImage);
     setHistory(prev => [newImage, ...prev].slice(0, 10));
     setIsEditing(false);
  };

  return (
    <div className="min-h-screen bg-nano-50 text-nano-900 selection:bg-nano-900 selection:text-white flex flex-col">

      {/* --- Header --- */}
      <header className="bg-white/80 backdrop-blur-md sticky top-0 z-50 border-b border-nano-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-nano-900 rounded-lg flex items-center justify-center text-white">
              <Camera size={18} />
            </div>
            <h1 className="text-lg font-bold tracking-tight">{APP_NAME}</h1>
            <Badge text={MODEL_NAME_DISPLAY} />
          </div>
          <div className="hidden sm:flex text-sm text-nano-500 font-medium">
             AI Photo Lab
          </div>
        </div>
      </header>

      {/* --- Main Content --- */}
      <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full flex flex-col lg:flex-row gap-8 lg:gap-12">

        {/* --- Left Column: Controls --- */}
        <div className="w-full lg:w-1/3 flex flex-col gap-8 order-2 lg:order-1">

          {/* Prompt Section */}
          <section className="space-y-4">
            <div className="flex justify-between items-end">
              <div className="space-y-1">
                <label htmlFor="prompt" className="block text-sm font-semibold text-nano-800">
                  Prompt
                </label>
                <p className="text-xs text-nano-500">Describe what you want to see in detail.</p>
              </div>
              <div className="flex items-center gap-1">
                <button 
                  onClick={handleUndo}
                  disabled={historyIndex === 0}
                  className="p-1.5 rounded-md hover:bg-nano-100 text-nano-500 disabled:opacity-30 disabled:hover:bg-transparent transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-1"
                  title="Undo"
                >
                  <Undo size={14} />
                </button>
                <button 
                  onClick={handleRedo}
                  disabled={historyIndex >= promptHistory.length - 1}
                  className="p-1.5 rounded-md hover:bg-nano-100 text-nano-500 disabled:opacity-30 disabled:hover:bg-transparent transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-1"
                  title="Redo"
                >
                  <Redo size={14} />
                </button>
              </div>
            </div>
            <div className="relative">
              <textarea
                id="prompt"
                value={prompt}
                onChange={handlePromptChange}
                placeholder="A futuristic house on a cliff, golden hour..."
                className="w-full p-4 rounded-xl border border-nano-200 bg-white shadow-sm text-nano-900 placeholder:text-nano-400 focus:outline-none focus:ring-2 focus:ring-nano-900 focus:ring-offset-1 focus:border-transparent resize-none h-32 transition-all"
              />
            </div>
          </section>

          {/* Reference Image Section */}
          <section className="space-y-4">
            <div className="space-y-1">
               <label className="block text-sm font-semibold text-nano-800">
                 Reference Image
               </label>
               <p className="text-xs text-nano-500">Upload a photo to guide the generation (optional).</p>
            </div>

            <input 
              type="file" 
              ref={fileInputRef}
              onChange={handleFileUpload}
              className="hidden" 
              accept="image/*"
            />

            {!uploadedImage ? (
              <button 
                type="button"
                onClick={() => fileInputRef.current?.click()}
                className="w-full border-2 border-dashed border-nano-200 rounded-xl p-6 flex flex-col items-center justify-center text-nano-400 hover:border-nano-400 hover:text-nano-600 hover:bg-nano-50 transition-all cursor-pointer h-24 focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-2"
              >
                 <div className="flex items-center gap-2 text-sm font-medium">
                   <Upload size={16} />
                   <span>Upload Image</span>
                 </div>
              </button>
            ) : (
              <div className="flex flex-col gap-2">
                <div className="relative group">
                    <div className="h-48 w-full bg-nano-100 rounded-xl overflow-hidden border border-nano-200">
                    <img src={uploadedImage} alt="Reference" className="w-full h-full object-cover opacity-80 group-hover:opacity-100 transition-opacity" />
                    </div>
                    <button 
                    onClick={clearUploadedImage}
                    className="absolute top-2 right-2 bg-white/90 backdrop-blur p-1.5 rounded-full text-nano-600 hover:text-red-500 hover:bg-white shadow-sm transition-all focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900"
                    title="Remove image"
                    >
                    <X size={14} />
                    </button>
                    <div className="absolute bottom-2 right-2 px-2 py-1 bg-black/50 backdrop-blur-sm rounded-md text-white text-[10px] font-medium pointer-events-none">
                    Reference
                    </div>
                </div>
                <button
                    onClick={clearUploadedImage}
                    className="self-end text-xs text-nano-500 hover:text-red-600 font-medium flex items-center gap-1.5 transition-colors px-1 py-0.5 rounded-md focus:outline-none focus-visible:ring-2 focus-visible:ring-red-500"
                >
                    <Trash2 size={12} />
                    Remove Image
                </button>
              </div>
            )}
          </section>

          {/* Aspect Ratio Section */}
          <section className="space-y-4">
            <div className="space-y-1">
              <label className="block text-sm font-semibold text-nano-800">
                Dimensions
              </label>
              <p className="text-xs text-nano-500">Choose the aspect ratio.</p>
            </div>
            <div className="flex gap-2 flex-wrap">
              {ASPECT_RATIOS.map((ratio) => (
                <button
                  key={ratio.id}
                  onClick={() => setAspectRatio(ratio.id)}
                  className={`
                    flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium border transition-all focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-2
                    ${aspectRatio === ratio.id 
                      ? 'bg-nano-900 text-white border-nano-900 shadow-md' 
                      : 'bg-white text-nano-600 border-nano-200 hover:border-nano-300 hover:bg-nano-50'
                    }
                  `}
                >
                  <div className={`border-2 rounded-sm ${ratio.shapeClass} ${aspectRatio === ratio.id ? 'border-white/80' : 'border-nano-400'}`}></div>
                  <span>{ratio.label}</span>
                </button>
              ))}
            </div>
          </section>

          {/* Advanced Settings Toggle */}
          <section className="space-y-4">
             <button 
              onClick={() => setShowAdvanced(!showAdvanced)}
              className="flex items-center justify-between w-full text-sm font-semibold text-nano-800 hover:text-nano-600 transition-colors p-1 -ml-1 rounded-lg focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900"
             >
                <div className="flex items-center gap-2">
                  <Sliders size={16} />
                  <span>Advanced Settings</span>
                </div>
                {showAdvanced ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
             </button>

             {/* Advanced Settings Content */}
             {showAdvanced && (
                <div className="bg-white rounded-xl border border-nano-200 p-4 space-y-4 animate-in slide-in-from-top-2 fade-in duration-200">
                    {/* Seed */}
