                      <div className="flex justify-between items-center">
                        <label className="text-xs font-medium text-nano-700">Seed</label>
                        <span className="text-[10px] text-nano-400">Optional</span>
                      </div>
                      <div className="flex gap-2">
                        <input 
                          type="number" 
                          placeholder="Random" 
                          value={seed === undefined ? '' : seed}
                          onChange={(e) => {
                            const val = e.target.value;
                            setSeed(val === '' ? undefined : parseInt(val));
                          }}
                          className="w-full p-2 text-sm rounded-lg border border-nano-200 focus:outline-none focus:ring-2 focus:ring-nano-900 focus:ring-offset-1 transition-shadow"
                        />
                        <button 
                          onClick={handleRandomSeed}
                          className="p-2 bg-nano-100 text-nano-600 rounded-lg hover:bg-nano-200 transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-1"
                          title="Randomize Seed"
                        >
                          <Dices size={18} />
                        </button>
                      </div>
                    </div>

                    {/* Creative Boost (Temperature & TopP) */}
                    <div className="space-y-2">
                      <div className="flex justify-between items-center">
                        <label className="text-xs font-medium text-nano-700">Creativity Boost</label>
                        <span className="text-[10px] font-mono text-nano-500 bg-nano-100 px-1.5 py-0.5 rounded">{creativity}</span>
                      </div>
                      <input 
                        type="range" 
                        min="0" 
                        max="100" 
                        value={creativity}
                        onChange={(e) => setCreativity(parseInt(e.target.value))}
                        className="w-full h-1.5 bg-nano-200 rounded-lg appearance-none cursor-pointer accent-nano-900 focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-4"
                      />
                      <div className="flex justify-between text-[10px] text-nano-400 font-medium">
                         <span>Strict</span>
                         <span>Balanced</span>
                         <span>Wild</span>
                      </div>
                    </div>
                </div>
             )}
          </section>

          {/* Style Section */}
          <section className="space-y-4">
             <div className="space-y-1">
              <label className="block text-sm font-semibold text-nano-800">
                Visual Style
              </label>
              <p className="text-xs text-nano-500">Select a preset to guide the aesthetic.</p>
            </div>
            <div className="grid grid-cols-2 gap-3">
              {ART_STYLES.map((style) => (
                <StyleCard 
                  key={style.id}
                  style={style}
                  isSelected={selectedStyleId === style.id}
                  onClick={() => setSelectedStyleId(style.id)}
                />
              ))}
            </div>
          </section>

          {/* Action Area */}
          <div className="pt-4 sticky bottom-6 lg:static z-20">
            <Button 
              onClick={handleGenerate} 
              isLoading={status === 'generating'}
              disabled={!prompt.trim() && !uploadedImage}
              className="w-full"
              icon={<Zap size={18} />}
            >
              {status === 'generating' ? 'Generating...' : 'Generate Image'}
            </Button>
          </div>
        </div>

