        <div className="w-full lg:w-2/3 flex flex-col gap-6 order-1 lg:order-2">

          {/* Main Preview Card */}
          <div 
            ref={previewRef}
            className="w-full bg-white rounded-2xl shadow-xl shadow-nano-200/50 border border-nano-200 overflow-hidden relative flex flex-col min-h-[400px] lg:min-h-[600px] transition-all duration-500"
          >
            {/* Editor Overlay */}
            {isEditing && currentImage ? (
                <ImageEditor 
                  imageSrc={currentImage.url}
                  onSave={handleSaveEdit}
                  onCancel={() => setIsEditing(false)}
                />
            ) : (
                <>
                    {/* Toolbar */}
                    <div className="h-14 border-b border-nano-100 flex items-center justify-between px-4 bg-white/50 backdrop-blur-sm z-10">
                    <div className="flex items-center gap-2 text-xs font-medium text-nano-500">
                        <ImageIcon size={14} />
                        <span>Preview Canvas</span>
                    </div>
                    {status === 'success' && (
                        <div className="flex gap-2">
                        <button 
                            onClick={() => setIsEditing(true)}
                            className="p-2 hover:bg-nano-100 rounded-lg text-nano-600 transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-1"
                            title="Edit"
                        >
                            <Edit2 size={18} />
                        </button>
                        <button 
                            onClick={handleGenerate}
                            className="p-2 hover:bg-nano-100 rounded-lg text-nano-600 transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-1"
                            title="Regenerate"
                        >
                            <RefreshCw size={18} />
                        </button>
                        <Button variant="secondary" onClick={handleDownload} className="!py-1.5 !px-3 !text-xs !h-8">
                            <Download size={14} className="mr-1.5" />
                            Download
                        </Button>
                        </div>
                    )}
                    </div>

                    {/* Canvas Area */}
                    <div className="flex-grow relative bg-nano-50 flex items-center justify-center p-4">

                    {status === 'idle' && (
                        <div className="text-center max-w-sm px-6 py-12">
                        <div className="w-16 h-16 bg-white rounded-2xl shadow-sm border border-nano-200 flex items-center justify-center mx-auto mb-4">
                            <Sparkles className="text-nano-400" size={32} />
                        </div>
                        <h3 className="text-lg font-medium text-nano-900 mb-2">Ready to Create</h3>
                        <p className="text-nano-500 text-sm">
                            Enter a prompt and optionally upload an image to generate high-quality visuals with {MODEL_NAME_DISPLAY}.
                        </p>
                        </div>
                    )}

                    {status === 'generating' && (
                        <div className="w-full h-full absolute inset-0 bg-white flex flex-col items-center justify-center z-20">
                        <div className="w-full max-w-md px-8 space-y-6">
                            {/* Animated Skeleton */}
                            <div className="w-full aspect-square bg-gradient-to-tr from-nano-100 via-nano-50 to-nano-200 rounded-lg animate-pulse-slow relative overflow-hidden">
                            <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/40 to-transparent -skew-x-12 translate-x-[-150%] animate-[shimmer_2s_infinite]"></div>
                            </div>
                            <div className="space-y-2 text-center">
                            <p className="text-sm font-medium text-nano-700 animate-pulse">Designing layout...</p>
                            <p className="text-xs text-nano-400">Powered by Gemini Nano</p>
                            </div>
                        </div>
                        </div>
                    )}

                    {status === 'error' && (
                        <div className="text-center">
                        <div className="w-12 h-12 bg-red-50 rounded-full flex items-center justify-center mx-auto mb-3">
                            <Zap className="text-red-500" size={24} />
                        </div>
                        <p className="text-red-600 font-medium">{errorMsg}</p>
                        </div>
                    )}

                    {currentImage && (
                        <ZoomablePreview 
                            src={currentImage.url} 
                            alt={currentImage.prompt}
                            className="max-w-full max-h-[70vh] rounded-lg shadow-sm"
                            isVisible={status !== 'generating'}
                        />
                    )}
                    </div>
                </>
            )}
          </div>

          {/* History Bar */}
          {history.length > 0 && (
            <div className="space-y-2">
              <div className="flex items-center gap-2 text-sm font-semibold text-nano-800 px-1">
                <History size={16} />
                <span>Session History</span>
              </div>
              <div className="flex gap-3 overflow-x-auto pb-4 pt-1 px-1 hide-scrollbar">
                {history.map((img) => (
                  <button
                    key={img.id}
                    onClick={() => loadFromHistory(img)}
                    className={`
                      relative flex-shrink-0 w-24 h-24 rounded-lg overflow-hidden border-2 transition-all duration-200 focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-2
                      ${currentImage?.id === img.id ? 'border-nano-900 ring-2 ring-nano-900/20' : 'border-transparent hover:border-nano-300 opacity-70 hover:opacity-100'}
                    `}
                  >
                    <img src={img.url} alt="thumbnail" className="w-full h-full object-cover" />
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

