  const fileInputRef = useRef<HTMLInputElement>(null);

  // Helper to get full style object
  const selectedStyle = ART_STYLES.find(s => s.id === selectedStyleId) || ART_STYLES[0];

  // Logic: Handle Prompt Change with Debounced History
  const handlePromptChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newVal = e.target.value;
    setPrompt(newVal);

    // Debounce adding to history so we don't save every char
    if (debounceRef.current) clearTimeout(debounceRef.current);

    debounceRef.current = setTimeout(() => {
      setPromptHistory(prev => {
        const newHistory = prev.slice(0, historyIndex + 1);
        newHistory.push(newVal);
        return newHistory;
      });
      setHistoryIndex(prev => prev + 1);
    }, 400);
  };

  // Logic: Undo
  const handleUndo = () => {
    if (historyIndex > 0) {
      const newIndex = historyIndex - 1;
      setHistoryIndex(newIndex);
      setPrompt(promptHistory[newIndex]);
    }
  };

  // Logic: Redo
  const handleRedo = () => {
    if (historyIndex < promptHistory.length - 1) {
      const newIndex = historyIndex + 1;
      setHistoryIndex(newIndex);
      setPrompt(promptHistory[newIndex]);
    }
  };

  // Logic: File Upload
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = async (event) => {
        if (event.target?.result) {
          const base64 = event.target.result as string;
          setUploadedImage(base64);

          // Auto-detect style from image
          setIsDetectingStyle(true);
          try {
            const detectedStyleId = await detectImageStyle(base64);
            if (detectedStyleId) {
                // Clean up string just in case
                const cleanId = detectedStyleId.trim();
                const matchedStyle = ART_STYLES.find(s => cleanId.includes(s.id));
                if (matchedStyle) {
                    setSelectedStyleId(matchedStyle.id);
                }
            }
          } catch (err) {
            console.warn("Style detection failed silent", err);
          } finally {
            setIsDetectingStyle(false);
          }
        }
      };
      reader.readAsDataURL(file);
    }
    // Reset value so same file can be selected again if needed
    if (fileInputRef.current) {
        fileInputRef.current.value = '';
    }
  };

  const clearUploadedImage = () => {
    setUploadedImage(null);
  };

  // Logic: Generate Random Seed
  const handleRandomSeed = () => {
    setSeed(Math.floor(Math.random() * 1000000000));
  };

  // Logic: Handle Generation
  const handleGenerate = async () => {
    // Basic validation: Must have either prompt OR image
    if (!prompt.trim() && !uploadedImage) {
        setErrorMsg("Please enter a text prompt or upload an image to start.");
        setStatus('error');
        return;
    }

    setStatus('generating');
    setErrorMsg(null);
    setCurrentImage(null);
    setIsEditing(false);

    // Scroll to preview on mobile
    if (window.innerWidth < 768) {
        previewRef.current?.scrollIntoView({ behavior: 'smooth' });
    }

    try {
      const base64Image = await generateImageWithNano(
          prompt, 
          selectedStyleId, 
          aspectRatio, 
          seed, 
          creativity, 
          uploadedImage
      );

      const newImage: GeneratedImage = {
        id: crypto.randomUUID(),
        url: base64Image,
        prompt: prompt || 'Image Variation', // Fallback title for history if prompt empty
        styleId: selectedStyleId,
        aspectRatio: aspectRatio,
        seed: seed,
        creativity: creativity,
        referenceImage: uploadedImage, // Save the reference used
        timestamp: Date.now()
      };

      setCurrentImage(newImage);
      setHistory(prev => [newImage, ...prev].slice(0, 10)); // Keep last 10
      setStatus('success');
    } catch (error) {
      console.error(error);
      setStatus('error');
      setErrorMsg("Failed to generate. Please try again.");
    }
  };

  // Logic: Handle Download
  const handleDownload = () => {
    if (!currentImage) return;
    const link = document.createElement('a');
    link.href = currentImage.url;
    link.download = `${APP_NAME.toLowerCase()}-${currentImage.id.slice(0, 8)}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Logic: Load from history
  const loadFromHistory = (img: GeneratedImage) => {
    setCurrentImage(img);
    setPrompt(img.prompt);

    // Update undo history with loaded prompt
    setPromptHistory(prev => {
       const newHistory = prev.slice(0, historyIndex + 1);
       if (newHistory[newHistory.length - 1] !== img.prompt) {
         newHistory.push(img.prompt);
       }
       return newHistory;
    });
    setHistoryIndex(prev => prev + 1);

    setSelectedStyleId(img.styleId);
    setAspectRatio(img.aspectRatio || '1:1');
    setSeed(img.seed);
    setCreativity(img.creativity ?? 50);
    setUploadedImage(img.referenceImage || null); // Restore reference image

    setStatus('success');
    setIsEditing(false);
    if (window.innerWidth < 768) {
        previewRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  };

  // Logic: Save Edit
  const handleSaveEdit = (newImageSrc: string) => {
     if (!currentImage) return;

     const newImage: GeneratedImage = {
        ...currentImage,
        id: crypto.randomUUID(),
        url: newImageSrc,
        timestamp: Date.now()
     };

     setCurrentImage(newImage);
     setHistory(prev => [newImage, ...prev].slice(0, 10));
     setIsEditing(false);
  };

  return (
    <div className="min-h-screen bg-nano-50 text-nano-900 selection:bg-nano-900 selection:text-white flex flex-col">

      {/* --- Header --- */}
      <header className="bg-white/80 backdrop-blur-md sticky top-0 z-50 border-b border-nano-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-nano-900 rounded-lg flex items-center justify-center text-white">
              <Camera size={18} />
            </div>
            <h1 className="text-lg font-bold tracking-tight">{APP_NAME}</h1>
            <Badge text={MODEL_NAME_DISPLAY} />
          </div>
          <div className="hidden sm:flex text-sm text-nano-500 font-medium">
             AI Photo Lab
          </div>
        </div>
      </header>

      {/* --- Main Content --- */}
      <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full flex flex-col lg:flex-row gap-8 lg:gap-12">

        {/* --- Left Column: Controls --- */}
        <div className="w-full lg:w-1/3 flex flex-col gap-8 order-2 lg:order-1">

          {/* Prompt Section */}
          <section className="space-y-4">
            <div className="flex justify-between items-end">
              <div className="space-y-1">
                <label htmlFor="prompt" className="block text-sm font-semibold text-nano-800">
                  Prompt
                </label>
                <p className="text-xs text-nano-500">Describe what you want to see in detail.</p>
              </div>
              <div className="flex items-center gap-1">
                <button 
                  onClick={handleUndo}
                  disabled={historyIndex === 0}
                  className="p-1.5 rounded-md hover:bg-nano-100 text-nano-500 disabled:opacity-30 disabled:hover:bg-transparent transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-1"
                  title="Undo"
                >
                  <Undo size={14} />
                </button>
                <button 
                  onClick={handleRedo}
                  disabled={historyIndex >= promptHistory.length - 1}
                  className="p-1.5 rounded-md hover:bg-nano-100 text-nano-500 disabled:opacity-30 disabled:hover:bg-transparent transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-1"
                  title="Redo"
                >
                  <Redo size={14} />
                </button>
              </div>
            </div>
            <div className="relative">
              <textarea
                id="prompt"
                value={prompt}
                onChange={handlePromptChange}
                placeholder="A futuristic house on a cliff, golden hour..."
                className="w-full p-4 rounded-xl border border-nano-200 bg-white shadow-sm text-nano-900 placeholder:text-nano-400 focus:outline-none focus:ring-2 focus:ring-nano-900 focus:ring-offset-1 focus:border-transparent resize-none h-32 transition-all"
              />
            </div>
          </section>

          {/* Reference Image Section */}
          <section className="space-y-4">
            <div className="space-y-1">
               <label className="block text-sm font-semibold text-nano-800">
                 Reference Image
               </label>
               <p className="text-xs text-nano-500">Upload a photo to guide the generation (optional).</p>
            </div>

            <input 
              type="file" 
              ref={fileInputRef}
              onChange={handleFileUpload}
              className="hidden" 
              accept="image/*"
            />

            {!uploadedImage ? (
              <button 
                type="button"
                onClick={() => fileInputRef.current?.click()}
                className="w-full border-2 border-dashed border-nano-200 rounded-xl p-6 flex flex-col items-center justify-center text-nano-400 hover:border-nano-400 hover:text-nano-600 hover:bg-nano-50 transition-all cursor-pointer h-24 focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-2"
              >
                 <div className="flex items-center gap-2 text-sm font-medium">
                   <Upload size={16} />
                   <span>Upload Image</span>
                 </div>
              </button>
            ) : (
              <div className="flex flex-col gap-2">
                <div className="relative group">
                    <div className="h-48 w-full bg-nano-100 rounded-xl overflow-hidden border border-nano-200">
                    <img src={uploadedImage} alt="Reference" className="w-full h-full object-cover opacity-80 group-hover:opacity-100 transition-opacity" />
                    </div>
                    <button 
                    onClick={clearUploadedImage}
                    className="absolute top-2 right-2 bg-white/90 backdrop-blur p-1.5 rounded-full text-nano-600 hover:text-red-500 hover:bg-white shadow-sm transition-all focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900"
                    title="Remove image"
                    >
                    <X size={14} />
                    </button>
                    {isDetectingStyle && (
                        <div className="absolute inset-0 bg-black/10 backdrop-blur-[1px] flex items-center justify-center">
                            <div className="bg-white/90 backdrop-blur rounded-full px-3 py-1.5 flex items-center gap-2 text-xs font-medium text-nano-700 shadow-sm">
                                <Wand2 size={12} className="animate-spin-slow text-purple-500" />
                                <span>Analyzing Style...</span>
                            </div>
                        </div>
                    )}
                    <div className="absolute bottom-2 right-2 px-2 py-1 bg-black/50 backdrop-blur-sm rounded-md text-white text-[10px] font-medium pointer-events-none">
                    Reference
                    </div>
                </div>
                <button
                    onClick={clearUploadedImage}
                    className="self-end text-xs text-nano-500 hover:text-red-600 font-medium flex items-center gap-1.5 transition-colors px-1 py-0.5 rounded-md focus:outline-none focus-visible:ring-2 focus-visible:ring-red-500"
                >
                    <Trash2 size={12} />
                    Remove Image
                </button>
              </div>
            )}
          </section>

          {/* Aspect Ratio Section */}
          <section className="space-y-4">
            <div className="space-y-1">
              <label className="block text-sm font-semibold text-nano-800">
                Dimensions
              </label>
              <p className="text-xs text-nano-500">Choose the aspect ratio.</p>
            </div>
            <div className="flex gap-2 flex-wrap">
              {ASPECT_RATIOS.map((ratio) => (
                <button
                  key={ratio.id}
                  onClick={() => setAspectRatio(ratio.id)}
                  className={`
                    flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium border transition-all focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-2
                    ${aspectRatio === ratio.id 
                      ? 'bg-nano-900 text-white border-nano-900 shadow-md transform scale-105' 
                      : 'bg-white text-nano-600 border-nano-200 hover:border-nano-300 hover:bg-nano-50'
                    }
                  `}
                >
                  <div className={`
                    border-2 rounded-sm ${ratio.shapeClass} 
                    ${aspectRatio === ratio.id ? 'bg-white border-white' : 'border-nano-400'}
                  `}></div>
                  <span>{ratio.label}</span>
                </button>
              ))}
            </div>
          </section>

          {/* Advanced Settings Toggle */}
          <section className="space-y-4">
             <div className="flex items-center justify-between">
                <button 
                  onClick={() => setShowAdvanced(!showAdvanced)}
                  className="flex items-center gap-2 text-sm font-semibold text-nano-800 hover:text-nano-600 transition-colors p-1 -ml-1 rounded-lg focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900"
                >
                    <div className="flex items-center gap-2">
                      <Sliders size={16} />
                      <span>Advanced Settings</span>
                    </div>
                    {showAdvanced ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
                </button>
                {showAdvanced && (seed !== undefined || creativity !== 50) && (
                  <button 
                    onClick={() => { setSeed(undefined); setCreativity(50); }}
                    className="text-[10px] text-nano-400 hover:text-red-500 font-medium transition-colors px-2 py-1"
                  >
                    Reset Defaults
                  </button>
                )}
             </div>

             {/* Advanced Settings Content */}
             {showAdvanced && (
                <div className="bg-white rounded-xl border border-nano-200 p-4 space-y-4 animate-in slide-in-from-top-2 fade-in duration-200">
                    {/* Seed */}
                    <div className="space-y-1">
                      <div className="flex justify-between items-center">
                        <label className="text-xs font-medium text-nano-700">Seed</label>
                        <span className="text-[10px] text-nano-400">Optional</span>
                      </div>
                      <div className="flex gap-2">
                        <input 
                          type="number" 
                          placeholder="Random" 
                          value={seed === undefined ? '' : seed}
                          onChange={(e) => {
                            const val = e.target.value;
                            setSeed(val === '' ? undefined : parseInt(val));
                          }}
                          className="w-full p-2 text-sm rounded-lg border border-nano-200 focus:outline-none focus:ring-2 focus:ring-nano-900 focus:ring-offset-1 transition-shadow placeholder:text-nano-300"
                        />
                        <button 
                          onClick={handleRandomSeed}
                          className="p-2 bg-nano-100 text-nano-600 rounded-lg hover:bg-nano-200 transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-1"
                          title="Randomize Seed"
                        >
                          <Dices size={18} />
                        </button>
                      </div>
                    </div>

                    {/* Creative Boost (Temperature & TopP) */}
                    <div className="space-y-2">
                      <div className="flex justify-between items-center">
                        <label className="text-xs font-medium text-nano-700">Creativity Boost</label>
                        <span className="text-[10px] font-mono text-nano-500 bg-nano-100 px-1.5 py-0.5 rounded">{creativity}</span>
                      </div>
                      <input 
                        type="range" 
                        min="0" 
                        max="100" 
                        value={creativity}
                        onChange={(e) => setCreativity(parseInt(e.target.value))}
                        className="w-full h-1.5 bg-nano-200 rounded-lg appearance-none cursor-pointer accent-nano-900 focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-4"
                      />
                      <div className="flex justify-between text-[10px] text-nano-400 font-medium select-none">
                         <button onClick={() => setCreativity(0)} className="hover:text-nano-800 transition-colors focus:outline-none">Strict</button>
                         <button onClick={() => setCreativity(50)} className="hover:text-nano-800 transition-colors focus:outline-none">Balanced</button>
                         <button onClick={() => setCreativity(100)} className="hover:text-nano-800 transition-colors focus:outline-none">Wild</button>
                      </div>
                    </div>
                </div>
             )}
          </section>

          {/* Style Section */}
          <section className="space-y-4">
             <div className="space-y-1">
              <label className="block text-sm font-semibold text-nano-800">
                Visual Style
              </label>
              <p className="text-xs text-nano-500">Select a preset to guide the aesthetic.</p>
            </div>
            <div className="grid grid-cols-2 gap-3">
              {ART_STYLES.map((style) => (
                <StyleCard 
                  key={style.id}
                  style={style}
                  isSelected={selectedStyleId === style.id}
                  onClick={() => setSelectedStyleId(style.id)}
                />
              ))}
            </div>
          </section>

          {/* Action Area */}
          <div className="pt-4 sticky bottom-6 lg:static z-20">
            <Button 
              onClick={handleGenerate} 
              isLoading={status === 'generating'}
              disabled={!prompt.trim() && !uploadedImage}
              className="w-full"
              icon={<Zap size={18} />}
            >
              {status === 'generating' ? 'Generating...' : 'Generate Image'}
            </Button>
          </div>
        </div>

        {/* --- Right Column: Preview --- */}
        <div className="w-full lg:w-2/3 flex flex-col gap-6 order-1 lg:order-2">

          {/* Main Preview Card */}
          <div 
            ref={previewRef}
            className="w-full bg-white rounded-2xl shadow-xl shadow-nano-200/50 border border-nano-200 overflow-hidden relative flex flex-col min-h-[400px] lg:min-h-[600px] transition-all duration-500"
          >
            {/* Editor Overlay */}
            {isEditing && currentImage ? (
                <ImageEditor 
                  imageSrc={currentImage.url}
                  onSave={handleSaveEdit}
                  onCancel={() => setIsEditing(false)}
                />
            ) : (
                <>
                    {/* Toolbar */}
                    <div className="h-14 border-b border-nano-100 flex items-center justify-between px-4 bg-white/50 backdrop-blur-sm z-10">
                    <div className="flex items-center gap-2 text-xs font-medium text-nano-500">
                        <ImageIcon size={14} />
                        <span>Preview Canvas</span>
                    </div>
                    {status === 'success' && (
                        <div className="flex gap-2">
                        <button 
                            onClick={() => setIsEditing(true)}
                            className="p-2 hover:bg-nano-100 rounded-lg text-nano-600 transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-1"
                            title="Edit"
                        >
                            <Edit2 size={18} />
                        </button>
                        <button 
                            onClick={handleGenerate}
                            className="p-2 hover:bg-nano-100 rounded-lg text-nano-600 transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-1"
                            title="Regenerate"
                        >
                            <RefreshCw size={18} />
                        </button>
                        <Button variant="secondary" onClick={handleDownload} className="!py-1.5 !px-3 !text-xs !h-8">
                            <Download size={14} className="mr-1.5" />
                            Download
                        </Button>
                        </div>
                    )}
                    </div>

                    {/* Canvas Area */}
                    <div className="flex-grow relative bg-nano-50 flex items-center justify-center p-4">

                    {status === 'idle' && (
                        <div className="text-center max-w-sm px-6 py-12">
                        <div className="w-16 h-16 bg-white rounded-2xl shadow-sm border border-nano-200 flex items-center justify-center mx-auto mb-4">
                            <Sparkles className="text-nano-400" size={32} />
                        </div>
                        <h3 className="text-lg font-medium text-nano-900 mb-2">Ready to Create</h3>
                        <p className="text-nano-500 text-sm">
                            Enter a prompt and optionally upload an image to generate high-quality visuals with {MODEL_NAME_DISPLAY}.
                        </p>
                        </div>
                    )}

                    {status === 'generating' && (
                        <div className="w-full h-full absolute inset-0 bg-white flex flex-col items-center justify-center z-20">
                        <div className="w-full max-w-md px-8 space-y-6">
                            {/* Animated Skeleton */}
                            <div className="w-full aspect-square bg-gradient-to-tr from-nano-100 via-nano-50 to-nano-200 rounded-lg animate-pulse-slow relative overflow-hidden">
                            <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/40 to-transparent -skew-x-12 translate-x-[-150%] animate-[shimmer_2s_infinite]"></div>
                            </div>
                            <div className="space-y-2 text-center">
                            <p className="text-sm font-medium text-nano-700 animate-pulse">Designing layout...</p>
                            <p className="text-xs text-nano-400">Powered by Gemini Nano</p>
                            </div>
                        </div>
                        </div>
                    )}

                    {status === 'error' && (
                        <div className="text-center">
                        <div className="w-12 h-12 bg-red-50 rounded-full flex items-center justify-center mx-auto mb-3">
                            <Zap className="text-red-500" size={24} />
                        </div>
                        <p className="text-red-600 font-medium">{errorMsg}</p>
                        </div>
                    )}

                    {currentImage && (
                        <ZoomablePreview 
                            src={currentImage.url} 
                            alt={currentImage.prompt}
                            className="max-w-full max-h-[70vh] rounded-lg shadow-sm"
                            isVisible={status !== 'generating'}
                        />
                    )}
                    </div>
                </>
            )}
          </div>

          {/* History Bar */}
          {history.length > 0 && (
            <div className="space-y-2">
              <div className="flex items-center gap-2 text-sm font-semibold text-nano-800 px-1">
                <History size={16} />
                <span>Session History</span>
              </div>
              <div className="flex gap-3 overflow-x-auto pb-4 pt-1 px-1 hide-scrollbar">
                {history.map((img) => (
                  <button
                    key={img.id}
                    onClick={() => loadFromHistory(img)}
                    className={`
                      relative flex-shrink-0 w-24 h-24 rounded-lg overflow-hidden border-2 transition-all duration-200 focus:outline-none focus-visible:ring-2 focus-visible:ring-nano-900 focus-visible:ring-offset-2
                      ${currentImage?.id === img.id ? 'border-nano-900 ring-2 ring-nano-900/20' : 'border-transparent hover:border-nano-300 opacity-70 hover:opacity-100'}
                    `}
                  >
                    <img src={img.url} alt="thumbnail" className="w-full h-full object-cover" />
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

import { ArtStyle } from './types';

export const APP_NAME = "NanoFrame";
export const MODEL_NAME_DISPLAY = "Nano Banana";

export const ASPECT_RATIOS = [
  { id: '1:1', label: 'Square', shapeClass: 'w-4 h-4' },
  { id: '16:9', label: 'Wide', shapeClass: 'w-6 h-3.5' },
  { id: '9:16', label: 'Tall', shapeClass: 'w-3.5 h-6' },
  { id: '4:3', label: 'Standard', shapeClass: 'w-5 h-4' },
  { id: '3:4', label: 'Portrait', shapeClass: 'w-4 h-5' },
];

export const ART_STYLES: ArtStyle[] = [
  {
