                         <img 
                           src={imageSrc} 
                           alt={f.name} 
                           loading="lazy"
                           decoding="async"
                           className="w-full h-full object-cover" 
                           style={{ filter: f.filter }}
                         />
                      </div>
                      <span className={`text-xs font-medium transition-colors ${selectedFilterId === f.id || hoveredFilterId === f.id ? 'text-nano-900' : 'text-nano-500'}`}>{f.name}</span>
                   </button>
                ))}
             </div>
           )}

           {activeTab === 'crop' && (
             <div className="flex flex-col gap-4 h-full justify-center">
                {/* Zoom Slider */}
                <div className="flex items-center gap-3 px-2">
                   <ZoomIn size={16} className="text-nano-500" />
                   <input 
                     type="range" 
                     min="0.5" 
                     max="3" 
                     step="0.1"
