  const [lastSavedPresetId, setLastSavedPresetId] = useState<string | null>(null);

  // Image Upload State
  const [uploadedImage, setUploadedImage] = useState<string | null>(null);
  const [isDetectingStyle, setIsDetectingStyle] = useState(false);

  const [status, setStatus] = useState<GenerationStatus>('idle');
  const [currentImage, setCurrentImage] = useState<GeneratedImage | null>(null);
  const [history, setHistory] = useState<GeneratedImage[]>([]);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  // Editing State
  const [isEditing, setIsEditing] = useState(false);

  // Undo/Redo State
  const [promptHistory, setPromptHistory] = useState<string[]>(['']);
  const [historyIndex, setHistoryIndex] = useState(0);
  const debounceRef = useRef<any>(null);

  // Refs
  const previewRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Load Presets on Mount
  useEffect(() => {
    const savedPresets = localStorage.getItem('nanoframe_presets');
    if (savedPresets) {
      try {
        setPresets(JSON.parse(savedPresets));
      } catch (e) {
        console.error("Failed to parse presets", e);
      }
    }
  }, []);

  // Save Presets on Change
  useEffect(() => {
    localStorage.setItem('nanoframe_presets', JSON.stringify(presets));
  }, [presets]);

  // Logic: Handle Prompt Change with Debounced History
  const handlePromptChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newVal = e.target.value;
    setPrompt(newVal);

    if (debounceRef.current) clearTimeout(debounceRef.current);

    debounceRef.current = setTimeout(() => {
      setPromptHistory(prev => {
        const newHistory = prev.slice(0, historyIndex + 1);
        newHistory.push(newVal);
        return newHistory;
      });
      setHistoryIndex(prev => prev + 1);
    }, 400);
  };

  // Logic: Undo/Redo
  const handleUndo = () => {
    if (historyIndex > 0) {
      const newIndex = historyIndex - 1;
      setHistoryIndex(newIndex);
      setPrompt(promptHistory[newIndex]);
    }
  };

  const handleRedo = () => {
    if (historyIndex < promptHistory.length - 1) {
      const newIndex = historyIndex + 1;
      setHistoryIndex(newIndex);
      setPrompt(promptHistory[newIndex]);
    }
  };

  // Logic: File Upload & Style Detection
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = async (event) => {
        if (event.target?.result) {
          const base64 = event.target.result as string;
          setUploadedImage(base64);
          setIsDetectingStyle(true);
          try {
            const detectedStyleId = await detectImageStyle(base64);
            if (detectedStyleId) {
                const cleanId = detectedStyleId.trim();
                const matchedStyle = ART_STYLES.find(s => cleanId.includes(s.id));
                if (matchedStyle) {
                    setSelectedStyleId(matchedStyle.id);
                }
            }
          } catch (err) {
            console.warn("Style detection failed", err);
          } finally {
            setIsDetectingStyle(false);
          }
        }
      };
      reader.readAsDataURL(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const clearUploadedImage = () => setUploadedImage(null);

  // Logic: Presets
  const handleSavePreset = (customName?: string) => {
    const nameToUse = (customName || newPresetName).trim() || 
                      (prompt ? prompt.slice(0, 20) + '...' : 'Untitled Preset');

    const preset: GenerationPreset = {
      id: crypto.randomUUID(),
      name: nameToUse,
      prompt,
      styleId: selectedStyleId,
      aspectRatio,
      seed,
      creativity,
      referenceImage: uploadedImage,
      timestamp: Date.now()
    };

    setPresets(prev => [preset, ...prev]);
    setNewPresetName('');
    setIsSavingPreset(false);
    setLastSavedPresetId(preset.id);
    setShowPresets(true);

    // Clear the "saved" checkmark after 3 seconds
    setTimeout(() => setLastSavedPresetId(null), 3000);
  };

  const loadPreset = (preset: GenerationPreset) => {
    setPrompt(preset.prompt);
    setSelectedStyleId(preset.styleId);
    setAspectRatio(preset.aspectRatio);
    setSeed(preset.seed);
    setCreativity(preset.creativity);
    setUploadedImage(preset.referenceImage || null);

    // Add to prompt history
    setPromptHistory(prev => [...prev.slice(0, historyIndex + 1), preset.prompt]);
    setHistoryIndex(prev => prev + 1);

    // Smooth scroll to top on mobile
    if (window.innerWidth < 1024) {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const deletePreset = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    setPresets(prev => prev.filter(p => p.id !== id));
  };

  // Logic: Generation
  const handleGenerate = async () => {
    if (!prompt.trim() && !uploadedImage) {
        setErrorMsg("Please enter a text prompt or upload an image to start.");
        setStatus('error');
        return;
    }

    setStatus('generating');
    setErrorMsg(null);
    setCurrentImage(null);
    setIsEditing(false);

    if (window.innerWidth < 768) previewRef.current?.scrollIntoView({ behavior: 'smooth' });

    try {
      const base64Image = await generateImageWithNano(
          prompt, 
          selectedStyleId, 
          aspectRatio, 
          seed, 
          creativity, 
          uploadedImage
      );

      const newImage: GeneratedImage = {
        id: crypto.randomUUID(),
        url: base64Image,
        prompt: prompt || 'Image Variation',
        styleId: selectedStyleId,
        aspectRatio: aspectRatio,
        seed: seed,
        creativity: creativity,
        referenceImage: uploadedImage,
        timestamp: Date.now()
      };

      setCurrentImage(newImage);
      setHistory(prev => [newImage, ...prev].slice(0, 10));
      setStatus('success');
    } catch (error) {
      console.error(error);
      setStatus('error');
      setErrorMsg("Failed to generate. Please try again.");
    }
  };

  const handleDownload = () => {
    if (!currentImage) return;
    const link = document.createElement('a');
    link.href = currentImage.url;
    link.download = `${APP_NAME.toLowerCase()}-${currentImage.id.slice(0, 8)}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const loadFromHistory = (img: GeneratedImage) => {
    setCurrentImage(img);
    setPrompt(img.prompt);
    setPromptHistory(prev => [...prev.slice(0, historyIndex + 1), img.prompt]);
    setHistoryIndex(prev => prev + 1);
    setSelectedStyleId(img.styleId);
    setAspectRatio(img.aspectRatio || '1:1');
    setSeed(img.seed);
    setCreativity(img.creativity ?? 50);
    setUploadedImage(img.referenceImage || null);
    setStatus('success');
    setIsEditing(false);
    if (window.innerWidth < 768) previewRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleSaveEdit = (newImageSrc: string) => {
     if (!currentImage) return;
     const newImage: GeneratedImage = {
        ...currentImage,
        id: crypto.randomUUID(),
        url: newImageSrc,
        timestamp: Date.now()
     };
     setCurrentImage(newImage);
     setHistory(prev => [newImage, ...prev].slice(0, 10));
     setIsEditing(false);
  };

  return (
    <div className="min-h-screen bg-nano-50 text-nano-900 selection:bg-nano-900 selection:text-white flex flex-col">

      <header className="bg-white/80 backdrop-blur-md sticky top-0 z-50 border-b border-nano-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-nano-900 rounded-lg flex items-center justify-center text-white">
              <Camera size={18} />
            </div>
            <h1 className="text-lg font-bold tracking-tight">{APP_NAME}</h1>
            <Badge text={MODEL_NAME_DISPLAY} />
          </div>
          <div className="hidden sm:flex text-sm text-nano-500 font-medium">AI Photo Lab</div>
        </div>
      </header>

      <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full flex flex-col lg:flex-row gap-8 lg:gap-12">

        {/* Left Column: Controls */}
        <div className="w-full lg:w-1/3 flex flex-col gap-8 order-2 lg:order-1 pb-24 lg:pb-0">

          {/* Presets Section */}
          <section className="space-y-4">
            <div className="flex items-center justify-between">
              <button 
                onClick={() => setShowPresets(!showPresets)}
                className="flex items-center gap-2 text-sm font-semibold text-nano-800 hover:text-nano-600 transition-colors p-1 -ml-1 rounded-lg focus:outline-none"
              >
                <div className="flex items-center gap-2">
                  <Bookmark size={16} className={presets.length > 0 ? "text-nano-900 fill-nano-900" : "text-nano-400"} />
                  <span>My Presets</span>
                  {presets.length > 0 && (
                    <span className="bg-nano-100 text-nano-600 text-[10px] px-1.5 py-0.5 rounded-full font-bold">
                      {presets.length}
                    </span>
                  )}
                </div>
                {showPresets ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
              </button>

              {!isSavingPreset ? (
                <button 
                  onClick={() => setIsSavingPreset(true)}
                  className="text-xs font-medium text-nano-500 hover:text-nano-900 flex items-center gap-1.5 transition-colors"
                >
                  <Plus size={14} />
                  New Preset
                </button>
              ) : (
                <button 
                  onClick={() => setIsSavingPreset(false)}
                  className="text-xs font-medium text-red-500 hover:text-red-700 transition-colors"
                >
                  Cancel
                </button>
              )}
            </div>

            {isSavingPreset && (
              <div className="bg-white rounded-xl border border-nano-200 p-3 shadow-sm space-y-3 animate-in slide-in-from-top-2 fade-in duration-200">
                <input 
                  autoFocus
                  type="text"
                  placeholder="Preset name (Optional)"
                  value={newPresetName}
                  onChange={(e) => setNewPresetName(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleSavePreset()}
                  className="w-full p-2 text-sm rounded-lg border border-nano-200 focus:outline-none focus:ring-2 focus:ring-nano-900"
                />
                <Button 
                  onClick={() => handleSavePreset()}
                  className="w-full !py-2 !text-xs"
                  icon={<Save size={14} />}
                >
                  Save Current Settings
                </Button>
              </div>
            )}

            {showPresets && (
              <div className="grid grid-cols-1 gap-2 max-h-64 overflow-y-auto pr-1 hide-scrollbar">
                {presets.length === 0 ? (
                  <p className="text-xs text-nano-400 text-center py-6 bg-nano-100/50 rounded-xl border border-dashed border-nano-200">
                    Your saved workspace presets will appear here.
                  </p>
                ) : (
                  presets.map((p) => (
                    <button
                      key={p.id}
                      onClick={() => loadPreset(p)}
                      className={`group relative flex items-center justify-between p-3 rounded-xl bg-white border transition-all text-left focus:outline-none shadow-sm ${lastSavedPresetId === p.id ? 'border-green-500 bg-green-50/30' : 'border-nano-200 hover:border-nano-900'}`}
                    >
                      <div className="flex flex-col gap-1 min-w-0 pr-4">
                        <div className="flex items-center gap-2">
                           <span className="text-sm font-semibold text-nano-900 truncate">{p.name}</span>
                           {lastSavedPresetId === p.id && <CheckCircle2 size={12} className="text-green-500" />}
                        </div>
                        <div className="flex items-center gap-2 text-[10px] text-nano-500">
                          <span className={`px-1.5 py-0.5 rounded border ${ART_STYLES.find(s => s.id === p.styleId)?.gradient.includes('white') ? 'bg-nano-800 text-white' : 'bg-nano-100 text-nano-700'}`}>
                            {ART_STYLES.find(s => s.id === p.styleId)?.name || 'Default'}
                          </span>
                          <span className="flex items-center gap-1"><Maximize size={8}/> {p.aspectRatio}</span>
                          <span className="flex items-center gap-1"><Clock size={8}/> {new Date(p.timestamp).toLocaleDateString()}</span>
                        </div>
                      </div>
                      <div 
                        onClick={(e) => deletePreset(p.id, e)}
                        className="p-1.5 rounded-lg text-nano-300 hover:text-red-500 hover:bg-red-50 opacity-0 group-hover:opacity-100 transition-all shrink-0"
                      >
                        <Trash2 size={14} />
                      </div>
                    </button>
                  ))
                )}
              </div>
            )}
          </section>

          {/* Prompt Section */}
          <section className="space-y-4">
            <div className="flex justify-between items-end">
              <div className="space-y-1">
                <label htmlFor="prompt" className="block text-sm font-semibold text-nano-800">Prompt</label>
                <p className="text-xs text-nano-500">Describe your vision.</p>
              </div>
              <div className="flex items-center gap-1">
                <button onClick={handleUndo} disabled={historyIndex === 0} className="p-1.5 rounded-md hover:bg-nano-100 text-nano-500 disabled:opacity-30 transition-colors"><Undo size={14} /></button>
                <button onClick={handleRedo} disabled={historyIndex >= promptHistory.length - 1} className="p-1.5 rounded-md hover:bg-nano-100 text-nano-500 disabled:opacity-30 transition-colors"><Redo size={14} /></button>
              </div>
            </div>
            <textarea
              id="prompt"
              value={prompt}
              onChange={handlePromptChange}
              placeholder="A futuristic house on a cliff, golden hour..."
              className="w-full p-4 rounded-xl border border-nano-200 bg-white shadow-sm text-nano-900 placeholder:text-nano-400 focus:outline-none focus:ring-2 focus:ring-nano-900 h-32 transition-all resize-none"
            />
          </section>

          {/* Reference Image Section */}
          <section className="space-y-4">
            <div className="space-y-1">
               <label className="block text-sm font-semibold text-nano-800">Reference Image</label>
               <p className="text-xs text-nano-500">Guide the model with visual context.</p>
            </div>
            <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" accept="image/*" />
            {!uploadedImage ? (
              <button onClick={() => fileInputRef.current?.click()} className="w-full border-2 border-dashed border-nano-200 rounded-xl p-6 flex flex-col items-center justify-center text-nano-400 hover:border-nano-400 hover:text-nano-600 hover:bg-nano-50 transition-all h-24">
                 <div className="flex items-center gap-2 text-sm font-medium"><Upload size={16} /><span>Upload Context</span></div>
              </button>
            ) : (
              <div className="flex flex-col gap-2">
                <div className="relative group">
                    <div className="h-48 w-full bg-nano-100 rounded-xl overflow-hidden border border-nano-200">
                      <img src={uploadedImage} alt="Reference" className="w-full h-full object-cover opacity-80 group-hover:opacity-100" />
                    </div>
                    <button onClick={clearUploadedImage} className="absolute top-2 right-2 bg-white/90 backdrop-blur p-1.5 rounded-full text-nano-600 hover:text-red-500 shadow-sm transition-all"><X size={14} /></button>
                    {isDetectingStyle && (
                        <div className="absolute inset-0 bg-black/10 backdrop-blur-[1px] flex items-center justify-center">
                            <div className="bg-white/90 backdrop-blur rounded-full px-3 py-1.5 flex items-center gap-2 text-xs font-medium shadow-sm">
                                <Wand2 size={12} className="animate-spin text-purple-500" /><span>Analyzing Style...</span>
                            </div>
                        </div>
                    )}
                </div>
              </div>
            )}
          </section>

          {/* Dimensions Section */}
          <section className="space-y-4">
            <div className="space-y-1">
              <label className="block text-sm font-semibold text-nano-800">Aspect Ratio</label>
            </div>
            <div className="flex gap-2 flex-wrap">
              {ASPECT_RATIOS.map((ratio) => (
                <button
                  key={ratio.id}
                  onClick={() => setAspectRatio(ratio.id)}
                  className={`flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium border transition-all ${aspectRatio === ratio.id ? 'bg-nano-900 text-white border-nano-900 shadow-md scale-105' : 'bg-white text-nano-600 border-nano-200 hover:border-nano-300'}`}
                >
                  <div className={`border-2 rounded-sm ${ratio.shapeClass} ${aspectRatio === ratio.id ? 'bg-white border-white' : 'border-nano-400'}`}></div>
                  <span>{ratio.label}</span>
                </button>
              ))}
            </div>
          </section>

          {/* Advanced Section */}
          <section className="space-y-4">
             <button onClick={() => setShowAdvanced(!showAdvanced)} className="flex items-center gap-2 text-sm font-semibold text-nano-800 hover:text-nano-600 transition-colors p-1 -ml-1 rounded-lg">
                <Sliders size={16} /><span>Advanced Control</span>{showAdvanced ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
             </button>
             {showAdvanced && (
                <div className="bg-white rounded-xl border border-nano-200 p-4 space-y-4 animate-in slide-in-from-top-2 fade-in">
                    <div className="space-y-1">
                      <div className="flex justify-between items-center"><label className="text-xs font-medium">Seed</label><span className="text-[10px] text-nano-400">Optional</span></div>
                      <div className="flex gap-2">
                        <input type="number" placeholder="Random" value={seed === undefined ? '' : seed} onChange={(e) => setSeed(e.target.value === '' ? undefined : parseInt(e.target.value))} className="w-full p-2 text-sm rounded-lg border border-nano-200" />
                        <button onClick={() => setSeed(Math.floor(Math.random() * 1000000000))} className="p-2 bg-nano-100 rounded-lg"><Dices size={18} /></button>
                      </div>
                    </div>
                    <div className="space-y-2">
                      <div className="flex justify-between items-center"><label className="text-xs font-medium">Creativity Weight</label><span className="text-[10px] bg-nano-100 px-1.5 py-0.5 rounded">{creativity}</span></div>
                      <input type="range" min="0" max="100" value={creativity} onChange={(e) => setCreativity(parseInt(e.target.value))} className="w-full h-1.5 bg-nano-200 rounded-lg appearance-none cursor-pointer accent-nano-900" />
                    </div>
                </div>
             )}
          </section>

          {/* Style Section */}
          <section className="space-y-4">
            <label className="block text-sm font-semibold text-nano-800">Curation Style</label>
            <div className="grid grid-cols-2 gap-3">
              {ART_STYLES.map((style) => (
                <StyleCard key={style.id} style={style} isSelected={selectedStyleId === style.id} onClick={() => setSelectedStyleId(style.id)} />
              ))}
            </div>
          </section>

          <div className="pt-4 sticky bottom-6 lg:static z-20">
            <Button onClick={handleGenerate} isLoading={status === 'generating'} disabled={!prompt.trim() && !uploadedImage} className="w-full" icon={<Zap size={18} />}>
              {status === 'generating' ? 'Generating Art...' : 'Launch Generation'}
            </Button>
          </div>
        </div>

        {/* Right Column: Preview */}
        <div className="w-full lg:w-2/3 flex flex-col gap-6 order-1 lg:order-2">
          <div ref={previewRef} className="w-full bg-white rounded-2xl shadow-xl border border-nano-200 overflow-hidden relative flex flex-col min-h-[400px] lg:min-h-[600px]">
            {isEditing && currentImage ? (
                <ImageEditor imageSrc={currentImage.url} onSave={handleSaveEdit} onCancel={() => setIsEditing(false)} />
            ) : (
                <>
                    <div className="h-14 border-b border-nano-100 flex items-center justify-between px-4 bg-white/50 backdrop-blur-sm z-10">
                    <div className="flex items-center gap-2 text-xs font-medium text-nano-500"><ImageIcon size={14} /><span>Master Canvas</span></div>
                    {status === 'success' && (
                        <div className="flex gap-2">
                          <button 
                            onClick={() => handleSavePreset()} 
                            className="flex items-center gap-1.5 px-3 py-1.5 hover:bg-nano-100 rounded-lg text-nano-600 text-xs font-medium transition-colors"
                            title="Save these settings as a preset"
                          >
                            <Bookmark size={14} /> <span>Save Preset</span>
                          </button>
                          <div className="w-px h-6 bg-nano-200 mx-1"></div>
                          <button onClick={() => setIsEditing(true)} className="p-2 hover:bg-nano-100 rounded-lg text-nano-600" title="Edit Image"><Edit2 size={18} /></button>
                          <button onClick={handleGenerate} className="p-2 hover:bg-nano-100 rounded-lg text-nano-600" title="Regenerate"><RefreshCw size={18} /></button>
                          <Button variant="secondary" onClick={handleDownload} className="!py-1.5 !px-3 !text-xs !h-8"><Download size={14} className="mr-1.5" />Download</Button>
                        </div>
                    )}
                    </div>

                    <div className="flex-grow relative bg-nano-50 flex items-center justify-center p-4">
                    {status === 'idle' && (
                        <div className="text-center max-w-sm px-6 py-12">
                        <div className="w-16 h-16 bg-white rounded-2xl shadow-sm border border-nano-200 flex items-center justify-center mx-auto mb-4"><Sparkles className="text-nano-400" size={32} /></div>
                        <h3 className="text-lg font-medium mb-2">Studio Empty</h3>
                        <p className="text-nano-500 text-sm">Configure your settings and launch a generation to see the {MODEL_NAME_DISPLAY} model in action.</p>
                        </div>
                    )}
                    {status === 'generating' && (
                        <div className="w-full h-full absolute inset-0 bg-white flex flex-col items-center justify-center z-20">
                          <div className="w-full max-w-md px-8 space-y-6">
                            <div className="w-full aspect-square bg-gradient-to-tr from-nano-100 to-nano-200 rounded-lg animate-pulse-slow"></div>
                            <div className="space-y-2 text-center">
                              <p className="text-sm font-medium animate-pulse">Rendering complex textures...</p>
                            </div>
                          </div>
                        </div>
                    )}
                    {currentImage && (
                        <ZoomablePreview src={currentImage.url} alt={currentImage.prompt} className="max-w-full max-h-[70vh] rounded-lg shadow-sm" isVisible={status !== 'generating'} />
                    )}
                    </div>
                </>
            )}
          </div>

          {history.length > 0 && (
            <div className="space-y-2">
              <div className="flex items-center gap-2 text-sm font-semibold text-nano-800 px-1"><History size={16} /><span>Recent Gallery</span></div>
              <div className="flex gap-3 overflow-x-auto pb-4 pt-1 px-1 hide-scrollbar">
                {history.map((img) => (
                  <button key={img.id} onClick={() => loadFromHistory(img)} className={`relative flex-shrink-0 w-24 h-24 rounded-xl overflow-hidden border-2 transition-all ${currentImage?.id === img.id ? 'border-nano-900 ring-2 ring-nano-900/20' : 'border-transparent opacity-70 hover:opacity-100'}`}>
                    <img src={img.url} alt="thumbnail" className="w-full h-full object-cover" />
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Button } from './UI';
import { 
  Check, 
  X, 
  Crop, 
  Wand2, 
  ZoomIn, 
  RotateCcw, 
  Loader2, 
  Sliders, 
  Sun, 
  Contrast, 
  Lock, 
  Unlock 
} from 'lucide-react';
import { IMAGE_FILTERS, ASPECT_RATIOS } from '../constants';

interface ImageEditorProps {
  imageSrc: string;
  onSave: (newImageSrc: string) => void;
  onCancel: () => void;
}

export const ImageEditor: React.FC<ImageEditorProps> = ({ imageSrc, onSave, onCancel }) => {
  const [activeTab, setActiveTab] = useState<'filter' | 'adjust' | 'crop'>('filter');
  const [selectedFilterId, setSelectedFilterId] = useState('none');
  const [hoveredFilterId, setHoveredFilterId] = useState<string | null>(null);
  const [imageLoaded, setImageLoaded] = useState(false);

  // Adjustment state
  const [brightness, setBrightness] = useState(100); // 0 to 200
  const [contrast, setContrast] = useState(100);   // 0 to 200

  // Crop state
  const [zoom, setZoom] = useState(1);
  const [cropRatio, setCropRatio] = useState<string>('1:1');
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [isRatioLocked, setIsRatioLocked] = useState(true);

  // Interaction state
  const [isDragging, setIsDragging] = useState(false);
  const [isResetting, setIsResetting] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  const imageRef = useRef<HTMLImageElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Helper to calculate minimum zoom required to fill container
  const getMinZoom = useCallback(() => {
    if (!imageRef.current || !containerRef.current) return 1;
    const img = imageRef.current;
    const container = containerRef.current;

    const containerAspect = container.clientWidth / container.clientHeight;
    const imgAspect = img.naturalWidth / img.naturalHeight;

    if (imgAspect > containerAspect) {
      // Image is wider than container, height must match
      return 1; // Since object-fit or our layout ensures height matches if wider
    } else {
      // Image is taller than container, width must match
      return containerAspect / imgAspect;
    }
  }, []);

  // Constrain pan to prevent black bars
  const constrainPan = useCallback((currentPan: { x: number; y: number }, currentZoom: number) => {
    if (!isRatioLocked || !imageRef.current || !containerRef.current) return currentPan;

    const img = imageRef.current;
    const container = containerRef.current;

    const imgAspect = img.naturalWidth / img.naturalHeight;
    const containerAspect = container.clientWidth / container.clientHeight;

    // Dimensions of image as displayed in container at scale 1 (before our zoom)
    let displayWidth, displayHeight;
    if (imgAspect > containerAspect) {
      displayHeight = container.clientHeight;
      displayWidth = container.clientHeight * imgAspect;
    } else {
      displayWidth = container.clientWidth;
      displayHeight = container.clientWidth / imgAspect;
    }

    // Dimensions after our zoom
    const scaledWidth = displayWidth * currentZoom;
    const scaledHeight = displayHeight * currentZoom;

    // Max allowed pan in pixels (distance from center)
    const maxX = Math.max(0, (scaledWidth - container.clientWidth) / 2) / currentZoom;
    const maxY = Math.max(0, (scaledHeight - container.clientHeight) / 2) / currentZoom;

    return {
      x: Math.min(Math.max(currentPan.x, -maxX), maxX),
      y: Math.min(Math.max(currentPan.y, -maxY), maxY)
    };
  }, [isRatioLocked]);

  // Effect to enforce constraints when lock is enabled or ratio changes
  useEffect(() => {
    if (isRatioLocked && imageLoaded) {
      const minZoom = getMinZoom();
      if (zoom < minZoom) {
        setZoom(minZoom);
      }
      setPan(prev => constrainPan(prev, Math.max(zoom, minZoom)));
    }
  }, [isRatioLocked, cropRatio, imageLoaded, zoom, constrainPan, getMinZoom]);

  // Get current filter string based on hover or selection
  const effectiveFilterId = hoveredFilterId || selectedFilterId;
  const baseFilter = IMAGE_FILTERS.find(f => f.id === effectiveFilterId)?.filter || 'none';

  // Combine preset filter with manual adjustments
  const currentFilter = `${baseFilter === 'none' ? '' : baseFilter} brightness(${brightness}%) contrast(${contrast}%)`;

  const handlePointerDown = (e: React.PointerEvent) => {
    if (isResetting) return;
    setIsDragging(true);
    setDragStart({ x: e.clientX - pan.x * zoom, y: e.clientY - pan.y * zoom });
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (isDragging) {
      const newPan = {
        x: (e.clientX - dragStart.x) / zoom,
        y: (e.clientY - dragStart.y) / zoom
      };
      setPan(constrainPan(newPan, zoom));
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    setIsDragging(false);
    (e.target as HTMLElement).releasePointerCapture(e.pointerId);
  };

  const handleResetTransform = () => {
    if (isResetting) return;
    setIsResetting(true);
    const minZ = isRatioLocked ? getMinZoom() : 1;
    setZoom(minZ);
    setPan({ x: 0, y: 0 });

    setTimeout(() => {
      setIsResetting(false);
    }, 500);
  };

  const handleResetAdjustments = () => {
    setBrightness(100);
    setContrast(100);
    setSelectedFilterId('none');
  };

  const handleSave = () => {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    const img = imageRef.current;

    if (!ctx || !img) return;

    const outputSize = 1536; 
    let width = outputSize;
    let height = outputSize;

    const [wRatio, hRatio] = cropRatio.split(':').map(Number);
    if (wRatio && hRatio) {
        if (wRatio > hRatio) {
            height = outputSize * (hRatio / wRatio);
        } else {
            width = outputSize * (wRatio / hRatio);
        }
    }

    canvas.width = width;
    canvas.height = height;
    ctx.fillStyle = '#000000';
    ctx.fillRect(0, 0, width, height);

    const container = containerRef.current;
    if (!container) return;

    const scaleFactor = width / container.clientWidth;

    ctx.save();
    const saveBaseFilter = IMAGE_FILTERS.find(f => f.id === selectedFilterId)?.filter || 'none';
    ctx.filter = `${saveBaseFilter === 'none' ? '' : saveBaseFilter} brightness(${brightness}%) contrast(${contrast}%)`;

    ctx.translate(width / 2, height / 2);
    ctx.scale(zoom, zoom);
    ctx.translate(pan.x * scaleFactor, pan.y * scaleFactor);

    const imgAspect = img.naturalWidth / img.naturalHeight;
    const containerAspect = container.clientWidth / container.clientHeight;

    let drawWidth, drawHeight;
    if (imgAspect > containerAspect) {
        drawHeight = height / zoom;
        drawWidth = drawHeight * imgAspect;
    } else {
        drawWidth = width / zoom;
        drawHeight = drawWidth / imgAspect;
    }

    ctx.drawImage(img, -drawWidth / 2, -drawHeight / 2, drawWidth, drawHeight);
    ctx.restore();

    onSave(canvas.toDataURL('image/png', 0.95));
  };

  return (
    <div className="absolute inset-0 bg-white z-50 flex flex-col h-full animate-in fade-in duration-300">
      {/* Header */}
      <div className="h-14 border-b border-nano-200 flex items-center justify-between px-4 bg-white shrink-0">
        <button 
          onClick={onCancel}
          className="p-2 text-nano-500 hover:text-nano-900 hover:bg-nano-100 rounded-lg transition-colors focus:outline-none"
        >
          <X size={20} />
        </button>
        <span className="font-semibold text-sm">Edit Image</span>
        <button 
          onClick={handleSave}
          disabled={!imageLoaded}
          className="p-2 text-nano-900 hover:bg-nano-100 rounded-lg transition-colors font-medium disabled:opacity-50"
        >
          <Check size={20} />
        </button>
      </div>

      {/* Main Canvas Area */}
      <div className="flex-grow bg-nano-100 overflow-hidden relative flex items-center justify-center p-8 select-none">
        {!imageLoaded && (
          <div className="absolute inset-0 z-10 flex items-center justify-center bg-nano-100/80 backdrop-blur-sm">
             <Loader2 className="w-8 h-8 text-nano-900 animate-spin" />
          </div>
        )}

        <div 
          ref={containerRef}
          className="relative bg-black overflow-hidden shadow-2xl ring-4 ring-white/50"
          style={{
             aspectRatio: cropRatio.replace(':', '/'),
             width: '100%',
             maxWidth: '100%',
             maxHeight: '100%',
             cursor: isDragging ? 'grabbing' : 'grab',
             touchAction: 'none'
          }}
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={handlePointerUp}
          onPointerLeave={handlePointerUp}
        >
           <img 
             ref={imageRef}
             src={imageSrc} 
             alt="Editing"
             loading="lazy"
             decoding="async"
             onLoad={() => setImageLoaded(true)}
             className={`absolute max-w-none max-h-none origin-center pointer-events-none transition-opacity duration-300 ${imageLoaded ? 'opacity-100' : 'opacity-0'}`}
             style={{
                top: '50%',
                left: '50%',
                transform: `translate(-50%, -50%) scale(${zoom}) translate(${pan.x}px, ${pan.y}px)`,
                filter: currentFilter,
                minWidth: '100%',
                minHeight: '100%',
                transition: isResetting 
                  ? 'transform 0.5s cubic-bezier(0.16, 1, 0.3, 1)' 
                  : (isDragging ? 'none' : 'transform 0.1s ease-out')
             }}
             draggable={false}
           />

           {activeTab === 'crop' && imageLoaded && (
             <div className="absolute inset-0 pointer-events-none opacity-50">
                <div className="absolute top-1/3 left-0 right-0 h-px bg-white/50 shadow-sm"></div>
                <div className="absolute top-2/3 left-0 right-0 h-px bg-white/50 shadow-sm"></div>
                <div className="absolute left-1/3 top-0 bottom-0 w-px bg-white/50 shadow-sm"></div>
                <div className="absolute left-2/3 top-0 bottom-0 w-px bg-white/50 shadow-sm"></div>
             </div>
           )}
        </div>

        {imageLoaded && (
            <div className="absolute bottom-4 left-1/2 -translate-x-1/2 bg-black/70 text-white text-[10px] px-3 py-1 rounded-full backdrop-blur-sm pointer-events-none opacity-50">
            Drag to Pan • Pinch to Zoom
            </div>
        )}
      </div>

      {/* Controls */}
      <div className="bg-white border-t border-nano-200 shrink-0 pb-safe">
        {/* Tabs */}
        <div className="flex border-b border-nano-100">
           <button 
             onClick={() => setActiveTab('filter')}
             className={`flex-1 py-3 text-sm font-medium flex items-center justify-center gap-2 focus:outline-none ${activeTab === 'filter' ? 'text-nano-900 border-b-2 border-nano-900' : 'text-nano-500'}`}
           >
             <Wand2 size={16} /> Filters
           </button>
           <button 
             onClick={() => setActiveTab('adjust')}
             className={`flex-1 py-3 text-sm font-medium flex items-center justify-center gap-2 focus:outline-none ${activeTab === 'adjust' ? 'text-nano-900 border-b-2 border-nano-900' : 'text-nano-500'}`}
           >
             <Sliders size={16} /> Adjust
           </button>
           <button 
             onClick={() => setActiveTab('crop')}
             className={`flex-1 py-3 text-sm font-medium flex items-center justify-center gap-2 focus:outline-none ${activeTab === 'crop' ? 'text-nano-900 border-b-2 border-nano-900' : 'text-nano-500'}`}
           >
             <Crop size={16} /> Crop
           </button>
        </div>

        {/* Tab Content */}
        <div className="h-32 p-4">
           {activeTab === 'filter' && (
             <div className="flex gap-4 overflow-x-auto pb-2 hide-scrollbar h-full items-center">
                {IMAGE_FILTERS.map((f) => (
                   <button 
                     key={f.id}
                     onClick={() => setSelectedFilterId(f.id)}
                     onMouseEnter={() => setHoveredFilterId(f.id)}
                     onMouseLeave={() => setHoveredFilterId(null)}
                     className="flex flex-col items-center gap-2 shrink-0 group focus:outline-none"
                   >
                      <div className={`w-14 h-14 rounded-lg overflow-hidden border-2 transition-all ${selectedFilterId === f.id ? 'border-nano-900 ring-2 ring-nano-900/20' : 'border-transparent group-hover:border-nano-300'}`}>
                         <img 
                           src={imageSrc} 
                           alt={f.name} 
                           loading="lazy"
                           decoding="async"
                           className="w-full h-full object-cover" 
                           style={{ filter: f.filter }}
                         />
                      </div>
                      <span className={`text-[10px] font-medium transition-colors ${selectedFilterId === f.id || hoveredFilterId === f.id ? 'text-nano-900' : 'text-nano-500'}`}>{f.name}</span>
                   </button>
                ))}
             </div>
           )}

           {activeTab === 'adjust' && (
             <div className="flex flex-col gap-3 h-full justify-center">
                <div className="flex items-center gap-4 px-2">
                   <div className="flex items-center gap-2 w-24 shrink-0">
                      <Sun size={14} className="text-nano-500" />
                      <span className="text-xs font-medium text-nano-700">Brightness</span>
                   </div>
                   <input 
                     type="range" 
                     min="0" 
                     max="200" 
                     step="1"
                     value={brightness}
                     onChange={(e) => setBrightness(parseInt(e.target.value))}
                     className="w-full h-1.5 bg-nano-200 rounded-lg appearance-none cursor-pointer accent-nano-900"
                   />
                   <span className="text-[10px] font-mono w-8 text-right text-nano-500">{brightness}%</span>
                </div>
                <div className="flex items-center gap-4 px-2">
                   <div className="flex items-center gap-2 w-24 shrink-0">
                      <Contrast size={14} className="text-nano-500" />
                      <span className="text-xs font-medium text-nano-700">Contrast</span>
                   </div>
                   <input 
                     type="range" 
                     min="0" 
                     max="200" 
                     step="1"
                     value={contrast}
                     onChange={(e) => setContrast(parseInt(e.target.value))}
                     className="w-full h-1.5 bg-nano-200 rounded-lg appearance-none cursor-pointer accent-nano-900"
                   />
                   <span className="text-[10px] font-mono w-8 text-right text-nano-500">{contrast}%</span>
                </div>
                <button 
                  onClick={handleResetAdjustments}
                  className="text-[10px] text-nano-400 hover:text-nano-900 self-end px-2"
                >
                  Reset Adjustments
                </button>
             </div>
           )}

           {activeTab === 'crop' && (
             <div className="flex flex-col gap-3 h-full justify-center">
                <div className="flex items-center gap-3 px-2">
                   <ZoomIn size={16} className="text-nano-500" />
                   <input 
                     type="range" 
                     min={isRatioLocked ? getMinZoom() : 0.5} 
                     max="4" 
                     step="0.01"
                     value={zoom}
                     onChange={(e) => {
                       const val = parseFloat(e.target.value);
                       setZoom(val);
                       setPan(prev => constrainPan(prev, val));
                     }}
                     className="w-full h-1.5 bg-nano-200 rounded-lg appearance-none cursor-pointer accent-nano-900"
                   />
                   <div className="flex gap-1 ml-2">
                     <button 
                       onClick={() => setIsRatioLocked(!isRatioLocked)}
                       className={`p-1.5 rounded-lg transition-colors active:scale-90 ${isRatioLocked ? 'bg-nano-900 text-white' : 'text-nano-500 hover:bg-nano-100'}`}
                       title={isRatioLocked ? "Unlock Aspect Ratio" : "Lock Aspect Ratio (Fill Container)"}
                     >
                       {isRatioLocked ? <Lock size={16} /> : <Unlock size={16} />}
                     </button>
                     <button 
                       onClick={handleResetTransform}
                       className="p-1.5 text-nano-500 hover:text-nano-900 hover:bg-nano-100 rounded-lg transition-colors active:scale-90"
                       title="Reset Transform"
                     >
                       <RotateCcw size={16} />
                     </button>
                   </div>
                </div>

                <div className="flex gap-2 overflow-x-auto pb-1 hide-scrollbar">
                   <button 
                     onClick={() => { setCropRatio('1:1'); }}
                     className={`px-3 py-1.5 rounded-lg border text-[10px] font-medium whitespace-nowrap ${cropRatio === '1:1' ? 'bg-nano-900 text-white border-nano-900' : 'border-nano-200 text-nano-600'}`}
                   >
                     Square
                   </button>
                   {ASPECT_RATIOS.slice(1).map(r => (
                     <button 
                        key={r.id}
                        onClick={() => { setCropRatio(r.id); }}
                        className={`px-3 py-1.5 rounded-lg border text-[10px] font-medium whitespace-nowrap ${cropRatio === r.id ? 'bg-nano-900 text-white border-nano-900' : 'border-nano-200 text-nano-600'}`}
                     >
                        {r.label}
                     </button>
                   ))}
                </div>
             </div>
           )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { 
  Sparkles, 
  Download, 
  RefreshCw, 
  Image as ImageIcon, 
  History, 
  Zap,
  Camera,
  Maximize,
  Sliders,
  ChevronDown,
  ChevronUp,
  Undo,
  Redo,
  Upload,
  X,
  Plus,
  Edit2,
  Dices,
  Trash2,
  Wand2,
  Bookmark,
  Save,
  Clock,
  CheckCircle2
} from 'lucide-react';
import { ART_STYLES, APP_NAME, MODEL_NAME_DISPLAY, ASPECT_RATIOS } from './constants';
import { ArtStyle, GeneratedImage, GenerationStatus, GenerationPreset } from './types';
import { generateImageWithNano, detectImageStyle } from './services/geminiService';
import { Button, StyleCard, Badge } from './components/UI';
import { ImageEditor } from './components/ImageEditor';
import { ZoomablePreview } from './components/ZoomablePreview';

const App: React.FC = () => {
  // --- Basic Generation State ---
  const [prompt, setPrompt] = useState<string>('');
  const [selectedStyleId, setSelectedStyleId] = useState<string>(ART_STYLES[0].id);
  const [aspectRatio, setAspectRatio] = useState<string>('1:1');

  // --- Advanced Parameters State ---
  const [seed, setSeed] = useState<number | undefined>(undefined);
  const [creativity, setCreativity] = useState<number>(50); // 0-100
  const [showAdvanced, setShowAdvanced] = useState<boolean>(false);

  // --- Presets State & Logic ---
  const [presets, setPresets] = useState<GenerationPreset[]>([]);
  const [isSavingPreset, setIsSavingPreset] = useState(false);
  const [newPresetName, setNewPresetName] = useState('');
  const [showPresets, setShowPresets] = useState(false);
  const [lastSavedPresetId, setLastSavedPresetId] = useState<string | null>(null);

  // --- Reference Image State ---
  const [uploadedImage, setUploadedImage] = useState<string | null>(null);
  const [isDetectingStyle, setIsDetectingStyle] = useState(false);

  // --- Generation & Gallery State ---
  const [status, setStatus] = useState<GenerationStatus>('idle');
  const [currentImage, setCurrentImage] = useState<GeneratedImage | null>(null);
  const [history, setHistory] = useState<GeneratedImage[]>([]);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  // --- UI/Editor State ---
  const [isEditing, setIsEditing] = useState(false);

  // --- Prompt History (Undo/Redo) ---
  const [promptHistory, setPromptHistory] = useState<string[]>(['']);
  const [historyIndex, setHistoryIndex] = useState(0);
  const debounceRef = useRef<any>(null);

  // --- Refs ---
  const previewRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const presetNameInputRef = useRef<HTMLInputElement>(null);

  // --- Effects ---
  // Load presets from LocalStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('nanoframe_presets_v2');
    if (saved) {
      try {
        setPresets(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse presets", e);
      }
    }
  }, []);

  // Persist presets to LocalStorage whenever they change
  useEffect(() => {
    localStorage.setItem('nanoframe_presets_v2', JSON.stringify(presets));
  }, [presets]);

  // --- Handlers ---

  const handlePromptChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newVal = e.target.value;
    setPrompt(newVal);

    if (debounceRef.current) clearTimeout(debounceRef.current);

    debounceRef.current = setTimeout(() => {
      setPromptHistory(prev => {
        const newHistory = prev.slice(0, historyIndex + 1);
        newHistory.push(newVal);
        return newHistory;
      });
      setHistoryIndex(prev => prev + 1);
    }, 400);
  };

  const handleUndo = () => {
    if (historyIndex > 0) {
      const newIndex = historyIndex - 1;
      setHistoryIndex(newIndex);
      setPrompt(promptHistory[newIndex]);
    }
  };

  const handleRedo = () => {
    if (historyIndex < promptHistory.length - 1) {
      const newIndex = historyIndex + 1;
      setHistoryIndex(newIndex);
      setPrompt(promptHistory[newIndex]);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = async (event) => {
        if (event.target?.result) {
          const base64 = event.target.result as string;
          setUploadedImage(base64);
          setIsDetectingStyle(true);
          try {
            const detectedStyleId = await detectImageStyle(base64);
            if (detectedStyleId) {
                const cleanId = detectedStyleId.trim();
                const matchedStyle = ART_STYLES.find(s => cleanId.includes(s.id));
                if (matchedStyle) setSelectedStyleId(matchedStyle.id);
            }
          } catch (err) {
            console.warn("Style detection failed", err);
          } finally {
            setIsDetectingStyle(false);
          }
        }
      };
      reader.readAsDataURL(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const clearUploadedImage = () => setUploadedImage(null);

  // --- Preset Actions ---

  const handleSavePreset = (e?: React.FormEvent) => {
    if (e) e.preventDefault();

    const nameToUse = newPresetName.trim() || 
                      (prompt ? prompt.slice(0, 24) + '...' : 'Untitled Preset');

    const preset: GenerationPreset = {
      id: crypto.randomUUID(),
      name: nameToUse,
      prompt,
      styleId: selectedStyleId,
      aspectRatio,
      seed,
      creativity,
      referenceImage: uploadedImage,
      timestamp: Date.now()
    };

    setPresets(prev => [preset, ...prev]);
    setNewPresetName('');
    setIsSavingPreset(false);
    setLastSavedPresetId(preset.id);
    setShowPresets(true);

    // Clear feedback state after delay
    setTimeout(() => setLastSavedPresetId(null), 3000);
  };

  const loadPreset = (preset: GenerationPreset) => {
    setPrompt(preset.prompt);
    setSelectedStyleId(preset.styleId);
    setAspectRatio(preset.aspectRatio);
    setSeed(preset.seed);
    setCreativity(preset.creativity);
    setUploadedImage(preset.referenceImage || null);

    // Update history for Undo/Redo
    setPromptHistory(prev => [...prev.slice(0, historyIndex + 1), preset.prompt]);
    setHistoryIndex(prev => prev + 1);

    // Smooth transition
    if (window.innerWidth < 1024) {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const deletePreset = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    setPresets(prev => prev.filter(p => p.id !== id));
  };

  const startSavingPreset = () => {
    setIsSavingPreset(true);
    setShowPresets(true);
    // Focus the input in the next tick
    setTimeout(() => presetNameInputRef.current?.focus(), 100);
    // Scroll to the sidebar on mobile
    if (window.innerWidth < 1024) {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  // --- Generation Logic ---

  const handleGenerate = async () => {
    if (!prompt.trim() && !uploadedImage) {
        setErrorMsg("Please enter a text prompt or upload an image to start.");
        setStatus('error');
        return;
    }

    setStatus('generating');
    setErrorMsg(null);
    setCurrentImage(null);
    setIsEditing(false);

    if (window.innerWidth < 768) previewRef.current?.scrollIntoView({ behavior: 'smooth' });

    try {
      const base64Image = await generateImageWithNano(
          prompt, 
          selectedStyleId, 
          aspectRatio, 
          seed, 
          creativity, 
          uploadedImage
      );

      const newImage: GeneratedImage = {
        id: crypto.randomUUID(),
        url: base64Image,
        prompt: prompt || 'Image Variation',
        styleId: selectedStyleId,
        aspectRatio: aspectRatio,
        seed: seed,
        creativity: creativity,
        referenceImage: uploadedImage,
        timestamp: Date.now()
      };

      setCurrentImage(newImage);
      setHistory(prev => [newImage, ...prev].slice(0, 10));
      setStatus('success');
    } catch (error) {
      console.error(error);
      setStatus('error');
      setErrorMsg("Failed to generate. Please try again.");
    }
  };

  const handleDownload = () => {
    if (!currentImage) return;
    const link = document.createElement('a');
    link.href = currentImage.url;
    link.download = `${APP_NAME.toLowerCase()}-${currentImage.id.slice(0, 8)}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const loadFromHistory = (img: GeneratedImage) => {
    setCurrentImage(img);
    setPrompt(img.prompt);
    setPromptHistory(prev => [...prev.slice(0, historyIndex + 1), img.prompt]);
    setHistoryIndex(prev => prev + 1);
    setSelectedStyleId(img.styleId);
    setAspectRatio(img.aspectRatio || '1:1');
    setSeed(img.seed);
    setCreativity(img.creativity ?? 50);
    setUploadedImage(img.referenceImage || null);
    setStatus('success');
    setIsEditing(false);
    if (window.innerWidth < 768) previewRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleSaveEdit = (newImageSrc: string) => {
     if (!currentImage) return;
     const newImage: GeneratedImage = {
        ...currentImage,
        id: crypto.randomUUID(),
        url: newImageSrc,
        timestamp: Date.now()
     };
     setCurrentImage(newImage);
     setHistory(prev => [newImage, ...prev].slice(0, 10));
     setIsEditing(false);
  };

  return (
    <div className="min-h-screen bg-nano-50 text-nano-900 selection:bg-nano-900 selection:text-white flex flex-col">

