            )}
          </div>

          {/* Recent History Gallery */}
          {history.length > 0 && (
            <div className="space-y-4">
              <div className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-widest text-nano-400 px-1"><History size={16} /><span>Recent Lab Results</span></div>
              <div className="flex gap-4 overflow-x-auto pb-6 pt-1 px-1 hide-scrollbar">
                {history.map((img) => (
                  <button 
