            {isEditing && currentImage ? (
                <ImageEditor imageSrc={currentImage.url} onSave={handleSaveEdit} onCancel={() => setIsEditing(false)} />
            ) : (
                <>
                    <div className="h-14 border-b border-nano-100 flex items-center justify-between px-4 bg-white/70 backdrop-blur-md z-10 shrink-0">
                      <div className="flex items-center gap-2 text-xs font-bold uppercase tracking-widest text-nano-400">
                        <ImageIcon size={14} /><span>Master Canvas</span>
                      </div>

                      {status === 'success' && currentImage && (
                        <div className="flex gap-2 items-center">
