                          <button onClick={handleGenerate} className="p-2 hover:bg-nano-100 rounded-lg text-nano-600" title="Re-roll"><RefreshCw size={18} /></button>
                          <Button variant="secondary" onClick={handleDownload} className="!py-1.5 !px-3 !text-[10px] !h-8 !font-bold !uppercase !tracking-wider"><Download size={14} className="mr-1.5" />Export</Button>
                        </div>
                      )}
                    </div>

                    <div className="flex-grow relative bg-nano-50 flex items-center justify-center p-4">
                      {status === 'idle' && (
                          <div className="text-center max-w-sm px-6 py-12">
                            <div className="w-20 h-20 bg-white rounded-3xl shadow-sm border border-nano-100 flex items-center justify-center mx-auto mb-6 transform rotate-3"><Sparkles className="text-nano-200" size={40} /></div>
                            <h3 className="text-xl font-bold mb-2">Welcome to NanoFrame</h3>
                            <p className="text-nano-400 text-sm leading-relaxed">Enter a prompt on the left to begin your journey. Every generation is powered by the {MODEL_NAME_DISPLAY} engine.</p>
                          </div>
                      )}

                      {status === 'generating' && (
                          <div className="w-full h-full absolute inset-0 bg-white/90 backdrop-blur-sm flex flex-col items-center justify-center z-20">
                            <div className="w-full max-w-md px-8 space-y-8">
                              <div className="w-full aspect-square bg-gradient-to-tr from-nano-100 via-nano-50 to-nano-200 rounded-2xl animate-pulse shadow-inner border border-white"></div>
                              <div className="space-y-3 text-center">
                                <p className="text-sm font-bold tracking-widest uppercase text-nano-600 animate-pulse">Computing Modalities...</p>
                                <div className="h-1 w-32 bg-nano-200 rounded-full mx-auto overflow-hidden">
                                  <div className="h-full bg-nano-900 w-1/2 animate-[shimmer_2s_infinite]"></div>
                                </div>
                              </div>
                            </div>
                          </div>
                      )}

                      {currentImage && (
                          <ZoomablePreview src={currentImage.url} alt={currentImage.prompt} className="max-w-full max-h-[75vh] rounded-xl shadow-2xl" isVisible={status !== 'generating'} />
                      )}
                    </div>
                </>
            )}
          </div>

          {/* Recent History Gallery */}
          {history.length > 0 && (
            <div className="space-y-4">
              <div className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-widest text-nano-400 px-1"><History size={16} /><span>Recent Lab Results</span></div>
              <div className="flex gap-4 overflow-x-auto pb-6 pt-1 px-1 hide-scrollbar">
                {history.map((img) => (
                  <button 
                    key={img.id} 
                    onClick={() => loadFromHistory(img)} 
                    className={`relative flex-shrink-0 w-24 h-24 rounded-2xl overflow-hidden border-2 transition-all shadow-sm ${currentImage?.id === img.id ? 'border-nano-900 ring-4 ring-nano-900/10 scale-105' : 'border-transparent opacity-60 hover:opacity-100 hover:scale-105'}`}
                  >
                    <img src={img.url} alt="thumb" className="w-full h-full object-cover" loading="lazy" />
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </main>

      {/* CSS For custom animations */}
      <style dangerouslySetInnerHTML={{ __html: `
        @keyframes shimmer {
          0% { transform: translateX(-100%); }
          100% { transform: translateX(200%); }
        }
      `}} />
    </div>
  );
};

export default App;

