                        <div className="flex items-center gap-2 overflow-hidden">
                          <span className="text-[9px] font-bold uppercase tracking-wider text-nano-300 shrink-0">
                            {ART_STYLES.find(s => s.id === p.styleId)?.name || 'Custom'}
                          </span>
                          <span className="text-[9px] text-nano-400 truncate">{p.prompt}</span>
                        </div>
                      </div>

                      <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-all shrink-0">
                        <button 
                          onClick={(e) => startRenaming(p, e)}
                          className="p-1.5 rounded-md text-nano-400 hover:text-white hover:bg-white/10 transition-all"
                        >
                          <Edit2 size={12} />
                        </button>
                        <button 
                          onClick={(e) => deletePreset(p.id, e)}
                          className="p-1.5 rounded-md text-nano-400 hover:text-red-400 hover:bg-white/10 transition-all"
                        >
                          <Trash2 size={12} />
                        </button>
                      </div>
                    </div>
                  ))
                )}
              </div>
            )}
          </section>

          {/* --- PROMPT INPUT --- */}
          <section className="space-y-4">
            <div className="flex justify-between items-end">
              <div className="space-y-1">
                <label htmlFor="prompt" className="block text-sm font-bold text-nano-700">Visual Blueprint</label>
                <p className="text-[11px] text-nano-300">Describe the subject and environment</p>
              </div>
              <div className="flex items-center gap-0.5 bg-nano-100 rounded-lg border border-white/5 p-0.5 shadow-sm">
                <button onClick={handleUndo} disabled={historyIndex === 0} className="p-1.5 rounded hover:bg-white/10 text-nano-300 disabled:opacity-20 transition-all"><Undo size={14} /></button>
                <button onClick={handleRedo} disabled={historyIndex >= promptHistory.length - 1} className="p-1.5 rounded hover:bg-white/10 text-nano-300 disabled:opacity-20 transition-all"><Redo size={14} /></button>
              </div>
            </div>
            <textarea
              id="prompt"
              value={prompt}
              onChange={handlePromptChange}
              placeholder="e.g. A hyper-realistic macro shot of a morning dew drop on a lavender petal..."
              className="w-full p-4 rounded-2xl border border-white/10 bg-nano-100 shadow-inner text-white placeholder:text-nano-400 focus:outline-none focus:ring-2 focus:ring-nano-900 h-32 transition-all resize-none text-sm leading-relaxed"
            />
          </section>

          {/* --- REFERENCE IMAGE --- */}
          <section className="space-y-4">
            <div className="space-y-1">
               <label className="block text-sm font-bold text-nano-700">Compositional Reference</label>
               <p className="text-[11px] text-nano-300">Guide the AI with structural context</p>
            </div>
            <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" accept="image/*" />
            {!uploadedImage ? (
              <button onClick={() => fileInputRef.current?.click()} className="w-full border-2 border-dashed border-white/10 rounded-2xl p-8 flex flex-col items-center justify-center text-nano-300 hover:border-white/30 hover:text-white hover:bg-white/5 transition-all group">
                 <div className="w-12 h-12 rounded-full bg-white/5 flex items-center justify-center mb-3 group-hover:scale-110 transition-transform">
                   <Upload size={20} />
                 </div>
                 <span className="text-xs font-bold uppercase tracking-wider">Load Reference</span>
              </button>
            ) : (
              <div className="relative group overflow-hidden rounded-2xl border border-white/10 shadow-2xl">
                  <div className="aspect-video w-full bg-black/40">
                    <img src={uploadedImage} alt="Reference" className="w-full h-full object-cover opacity-60 group-hover:opacity-100 transition-opacity" />
                  </div>
                  <div className="absolute inset-0 bg-gradient-to-t from-black/80 to-transparent opacity-0 group-hover:opacity-100 transition-opacity flex items-end p-3">
                    <button onClick={clearUploadedImage} className="w-full py-2 bg-white/10 hover:bg-white/20 backdrop-blur text-white text-[10px] font-bold uppercase tracking-widest rounded-lg transition-all flex items-center justify-center gap-2">
                       <X size={12} /> Remove Reference
                    </button>
                  </div>
                  {isDetectingStyle && (
                      <div className="absolute inset-0 bg-nano-50/80 backdrop-blur-sm flex items-center justify-center">
                          <div className="bg-nano-100 border border-white/10 rounded-full px-4 py-2 flex items-center gap-3 text-[10px] font-bold shadow-2xl text-white">
                              <Loader2 size={14} className="animate-spin text-white" />
                              <span className="uppercase tracking-widest">Parsing Style...</span>
                          </div>
                      </div>
                  )}
              </div>
            )}
          </section>

          {/* --- DIMENSIONS --- */}
          <section className="space-y-4">
            <label className="block text-sm font-bold text-nano-700">Canvas Dimensions</label>
            <div className="grid grid-cols-3 gap-2">
              {ASPECT_RATIOS.map((ratio) => (
                <button
                  key={ratio.id}
                  onClick={() => setAspectRatio(ratio.id)}
                  className={`flex flex-col items-center justify-center gap-2 p-3 rounded-xl border transition-all ${aspectRatio === ratio.id ? 'bg-white text-nano-50 border-white shadow-[0_0_20px_rgba(255,255,255,0.2)]' : 'bg-nano-100 text-nano-300 border-white/5 hover:border-white/20'}`}
                >
                  <div className={`border-2 rounded-sm ${ratio.shapeClass} ${aspectRatio === ratio.id ? 'bg-nano-50 border-nano-50' : 'border-nano-300'}`}></div>
                  <span className="text-[10px] font-bold uppercase tracking-tighter">{ratio.label}</span>
                </button>
              ))}
            </div>
          </section>

          {/* --- ADVANCED ENGINE PARAMS --- */}
          <section className="space-y-4">
             <button onClick={() => setShowAdvanced(!showAdvanced)} className="flex items-center justify-between w-full text-sm font-bold text-nano-800 hover:text-white transition-colors p-1 rounded-lg">
                <div className="flex items-center gap-2"><Sliders size={16} /><span>Advanced Parameters</span></div>
                {showAdvanced ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
             </button>
             {showAdvanced && (
                <div className="bg-nano-100 rounded-2xl border border-white/10 p-5 space-y-6 animate-in slide-in-from-top-2 duration-300 shadow-2xl">
                    <div className="space-y-3">
                      <div className="flex justify-between items-center">
                        <label className="text-[10px] font-bold uppercase tracking-widest text-nano-300">Entropy Seed</label>
                        <span className="text-[9px] font-mono text-nano-400">AUTO-GEN</span>
                      </div>
                      <div className="flex gap-2">
                        <input 
                          type="number" 
                          placeholder="Random" 
                          value={seed === undefined ? '' : seed} 
                          onChange={(e) => setSeed(e.target.value === '' ? undefined : parseInt(e.target.value))} 
                          className="w-full p-2 text-sm rounded-xl border border-white/5 bg-nano-50 text-white focus:ring-1 focus:ring-white/20 focus:outline-none transition-all" 
                        />
                        <button onClick={() => setSeed(Math.floor(Math.random() * 1000000000))} className="p-2.5 bg-white text-nano-50 hover:bg-nano-700 hover:text-white rounded-xl transition-all active:scale-90" title="Randomize"><Dices size={18} /></button>
                      </div>
                    </div>
                    <div className="space-y-4">
                      <div className="flex justify-between items-center">
                        <label className="text-[10px] font-bold uppercase tracking-widest text-nano-300">Diffusion Temperature</label>
                        <span className="text-[10px] bg-white text-nano-50 px-2 py-0.5 rounded-full font-bold tabular-nums">{creativity}%</span>
                      </div>
                      <input 
                        type="range" 
                        min="0" 
                        max="100" 
                        value={creativity} 
                        onChange={(e) => setCreativity(parseInt(e.target.value))} 
                        className="w-full h-1.5 bg-nano-50 rounded-full appearance-none cursor-pointer accent-white" 
                      />
                      <div className="flex justify-between text-[8px] text-nano-400 font-bold tracking-widest px-1">
                        <span>LITERAL</span>
                        <span>ABSTRACT</span>
                      </div>
                    </div>
                </div>
             )}
          </section>

          {/* --- STYLE PRESETS --- */}
          <section className="space-y-4">
            <label className="block text-sm font-bold text-nano-700">Visual Aesthetic</label>
            <div className="grid grid-cols-2 gap-3">
              {ART_STYLES.map((style) => (
                <StyleCard key={style.id} style={style} isSelected={selectedStyleId === style.id} onClick={() => setSelectedStyleId(style.id)} />
              ))}
            </div>
          </section>

          {/* --- LAUNCH ACTION --- */}
          <div className="pt-4 sticky bottom-8 lg:static z-20">
            <Button onClick={handleGenerate} isLoading={status === 'generating'} disabled={!prompt.trim() && !uploadedImage} className="w-full !rounded-2xl !h-14 shadow-[0_10px_40px_rgba(0,0,0,0.5)] hover:scale-[1.02]" icon={<Zap size={20} className="fill-nano-50" />}>
              {status === 'generating' ? 'Synthesizing...' : 'Launch Generation'}
            </Button>
            {errorMsg && <p className="text-red-400 text-[11px] text-center mt-3 font-bold uppercase tracking-tight animate-pulse">{errorMsg}</p>}
          </div>
        </div>

        {/* Right Column: Creative Results */}
        <div className="w-full lg:w-2/3 flex flex-col gap-6 order-1 lg:order-2">

          <div ref={previewRef} className="w-full bg-nano-100 rounded-3xl shadow-2xl border border-white/10 overflow-hidden relative flex flex-col min-h-[500px] lg:min-h-[700px]">

            {isEditing && currentImage ? (
                <ImageEditor imageSrc={currentImage.url} onSave={handleSaveEdit} onCancel={() => setIsEditing(false)} />
            ) : (
                <>
                    <div className="h-16 border-b border-white/5 flex items-center justify-between px-6 bg-nano-100/80 backdrop-blur-md z-10 shrink-0">
                      <div className="flex items-center gap-3">
                        <div className="w-2 h-2 bg-white rounded-full animate-pulse shadow-[0_0_8px_white]"></div>
                        <span className="text-xs font-bold uppercase tracking-widest text-white">Output Stream</span>
                      </div>

                      {status === 'success' && currentImage && (
                        <div className="flex gap-2 items-center">
                          <button 
                            onClick={startSavingPreset} 
                            className="flex items-center gap-2 px-4 py-2 hover:bg-white/5 rounded-xl text-nano-300 text-[11px] font-bold uppercase tracking-widest transition-all"
                            title="Store this configuration"
                          >
                            <Bookmark size={14} /> <span className="hidden sm:inline">Save Preset</span>
                          </button>
                          <div className="w-px h-6 bg-white/10 mx-1"></div>
                          <button onClick={() => setIsEditing(true)} className="p-2.5 hover:bg-white/5 rounded-xl text-nano-300 transition-all" title="Retouch Toolset"><Edit2 size={20} /></button>
                          <button onClick={handleGenerate} className="p-2.5 hover:bg-white/5 rounded-xl text-nano-300 transition-all" title="Re-simulate"><RefreshCw size={20} /></button>
                          <Button variant="secondary" onClick={handleDownload} className="!py-2 !px-5 !text-[11px] !h-10 !rounded-xl !font-bold !uppercase !tracking-widest !bg-white !text-nano-50"><Download size={16} className="mr-2" />Export</Button>
                        </div>
                      )}
                    </div>

                    <div className="flex-grow relative bg-nano-50 flex items-center justify-center p-6">
                      {status === 'idle' && (
                          <div className="text-center max-w-sm px-8">
                            <div className="w-24 h-24 bg-nano-100 rounded-[2.5rem] shadow-2xl border border-white/5 flex items-center justify-center mx-auto mb-8 transform rotate-6 hover:rotate-0 transition-transform duration-700">
                              <Sparkles className="text-white/20" size={48} />
                            </div>
                            <h3 className="text-2xl font-bold text-white mb-3 tracking-tight">Studio Laboratory</h3>
                            <p className="text-nano-400 text-sm leading-relaxed mb-8">Define your parameters in the sidebar to initiate image synthesis. All results are high-fidelity captures from the {MODEL_NAME_DISPLAY} core.</p>
                            <div className="flex flex-wrap justify-center gap-2">
                               <button onClick={() => setPrompt("A futuristic garden with floating crystal spheres")} className="text-[10px] font-bold uppercase tracking-widest bg-nano-100 border border-white/5 px-3 py-1.5 rounded-full text-nano-400 hover:text-white transition-colors">Garden</button>
                               <button onClick={() => setPrompt("Minimalist brutalist architecture against a sunset sky")} className="text-[10px] font-bold uppercase tracking-widest bg-nano-100 border border-white/5 px-3 py-1.5 rounded-full text-nano-400 hover:text-white transition-colors">Architecture</button>
                            </div>
                          </div>
                      )}

                      {status === 'generating' && (
                          <div className="w-full h-full absolute inset-0 bg-nano-50 flex flex-col items-center justify-center z-20">
                            <div className="w-full max-w-md px-12 space-y-12">
                              <div className="relative w-full aspect-square bg-gradient-to-br from-nano-100 via-nano-50 to-nano-200 rounded-3xl overflow-hidden shadow-2xl border border-white/5">
                                <div className="absolute inset-0 bg-gradient-to-tr from-white/5 to-transparent animate-pulse"></div>
                                <div className="absolute top-1/2 left-0 right-0 h-[2px] bg-white/20 -translate-y-1/2 animate-[scan_3s_linear_infinite]"></div>
                              </div>
                              <div className="space-y-4 text-center">
                                <div className="flex items-center justify-center gap-2">
                                  <Sparkles size={16} className="text-white animate-spin" />
                                  <p className="text-xs font-bold tracking-[0.3em] uppercase text-white">Synthesizing Pixels</p>
                                </div>
                                <div className="h-1 w-48 bg-white/5 rounded-full mx-auto overflow-hidden">
                                  <div className="h-full bg-white w-full -translate-x-full animate-[progress_2s_ease-in-out_infinite]"></div>
                                </div>
                              </div>
                            </div>
                          </div>
                      )}

                      {currentImage && (
                          <ZoomablePreview src={currentImage.url} alt={currentImage.prompt} className="max-w-full max-h-[80vh] rounded-2xl shadow-2xl" isVisible={status !== 'generating'} />
                      )}
                    </div>
                </>
            )}
          </div>

          {/* Persistent History Stream */}
          {history.length > 0 && (
            <div className="space-y-5">
              <div className="flex items-center justify-between px-1">
                <div className="flex items-center gap-3 text-[10px] font-bold uppercase tracking-[0.2em] text-nano-400">
                  <History size={16} /><span>Lab Sequence</span>
                </div>
                <span className="text-[9px] font-bold text-nano-500 uppercase">Limit: 10 Instances</span>
              </div>
              <div className="flex gap-5 overflow-x-auto pb-6 pt-2 px-1 hide-scrollbar">
                {history.map((img) => (
                  <button 
                    key={img.id} 
                    onClick={() => loadFromHistory(img)} 
                    className={`relative flex-shrink-0 w-28 h-28 rounded-2xl overflow-hidden border-2 transition-all shadow-xl group ${currentImage?.id === img.id ? 'border-white ring-4 ring-white/10 scale-105 z-10' : 'border-transparent opacity-40 hover:opacity-100 hover:scale-105'}`}
                  >
                    <img src={img.url} alt="Sequence" className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" loading="lazy" />
                    <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity"></div>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </main>

      {/* Engine Animations */}
      <style dangerouslySetInnerHTML={{ __html: `
        @keyframes progress {
          0% { transform: translateX(-100%); }
          50% { transform: translateX(0); }
          100% { transform: translateX(100%); }
        }
        @keyframes scan {
          0% { transform: translateY(-300px); }
          100% { transform: translateY(300px); }
        }
      `}} />
    </div>
  );
};

