import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Button } from './UI';
import { 
  Check, 
  X, 
  Crop, 
  Wand2, 
  ZoomIn, 
  RotateCcw, 
  Loader2, 
  Sliders, 
  Sun, 
  Contrast, 
  Lock, 
  Unlock,
  Palette,
  Droplets
} from 'lucide-react';
import { IMAGE_FILTERS, ASPECT_RATIOS } from '../constants';

interface ImageEditorProps {
  imageSrc: string;
  onSave: (newImageSrc: string) => void;
  onCancel: () => void;
}

export const ImageEditor: React.FC<ImageEditorProps> = ({ imageSrc, onSave, onCancel }) => {
  const [activeTab, setActiveTab] = useState<'filter' | 'adjust' | 'crop'>('filter');
  const [selectedFilterId, setSelectedFilterId] = useState('none');
  const [hoveredFilterId, setHoveredFilterId] = useState<string | null>(null);
  const [imageLoaded, setImageLoaded] = useState(false);

  // Adjustment state
  const [brightness, setBrightness] = useState(100); 
  const [contrast, setContrast] = useState(100);   
  const [saturation, setSaturation] = useState(100); 
  const [hueRotate, setHueRotate] = useState(0);    

  // Crop state
  const [zoom, setZoom] = useState(1);
  const [cropRatio, setCropRatio] = useState<string>('1:1');
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [isRatioLocked, setIsRatioLocked] = useState(true);

  // Interaction state
  const [isDragging, setIsDragging] = useState(false);
  const [isResetting, setIsResetting] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  const imageRef = useRef<HTMLImageElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const getMinZoom = useCallback(() => {
    if (!imageRef.current || !containerRef.current) return 1;
    const img = imageRef.current;
    const container = containerRef.current;

    const containerAspect = container.clientWidth / container.clientHeight;
    const imgAspect = img.naturalWidth / img.naturalHeight;

    if (imgAspect > containerAspect) {
      return 1; 
    } else {
      return containerAspect / imgAspect;
    }
  }, []);

  const constrainPan = useCallback((currentPan: { x: number; y: number }, currentZoom: number) => {
    if (isResetting || !isRatioLocked || !imageRef.current || !containerRef.current) return currentPan;

    const img = imageRef.current;
    const container = containerRef.current;

    const imgAspect = img.naturalWidth / img.naturalHeight;
    const containerAspect = container.clientWidth / container.clientHeight;

    let displayWidth, displayHeight;
    if (imgAspect > containerAspect) {
      displayHeight = container.clientHeight;
      displayWidth = container.clientHeight * imgAspect;
    } else {
      displayWidth = container.clientWidth;
      displayHeight = container.clientWidth / imgAspect;
    }

    const scaledWidth = displayWidth * currentZoom;
    const scaledHeight = displayHeight * currentZoom;

    const maxX = Math.max(0, (scaledWidth - container.clientWidth) / 2) / currentZoom;
    const maxY = Math.max(0, (scaledHeight - container.clientHeight) / 2) / currentZoom;

    return {
      x: Math.min(Math.max(currentPan.x, -maxX), maxX),
      y: Math.min(Math.max(currentPan.y, -maxY), maxY)
    };
  }, [isRatioLocked, isResetting]);

  useEffect(() => {
    if (isRatioLocked && imageLoaded && !isResetting) {
      const minZoom = getMinZoom();
      if (zoom < minZoom) {
        setZoom(minZoom);
      }
      setPan(prev => constrainPan(prev, Math.max(zoom, minZoom)));
    }
  }, [isRatioLocked, cropRatio, imageLoaded, zoom, constrainPan, getMinZoom, isResetting]);

  const effectiveFilterId = hoveredFilterId || selectedFilterId;
  const baseFilter = IMAGE_FILTERS.find(f => f.id === effectiveFilterId)?.filter || 'none';
  const currentFilter = `${baseFilter === 'none' ? '' : baseFilter} brightness(${brightness}%) contrast(${contrast}%) saturate(${saturation}%) hue-rotate(${hueRotate}deg)`;

  const handlePointerDown = (e: React.PointerEvent) => {
    if (isResetting) return;
    setIsDragging(true);
    setDragStart({ x: e.clientX - pan.x * zoom, y: e.clientY - pan.y * zoom });
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (isDragging) {
      const newPan = {
        x: (e.clientX - dragStart.x) / zoom,
        y: (e.clientY - dragStart.y) / zoom
      };
      setPan(constrainPan(newPan, zoom));
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    setIsDragging(false);
    (e.target as HTMLElement).releasePointerCapture(e.pointerId);
  };

  const handleResetTransform = () => {
    if (isResetting) return;
    setIsResetting(true);
    const targetZoom = isRatioLocked ? getMinZoom() : 1;
    setZoom(targetZoom);
    setPan({ x: 0, y: 0 });
    setTimeout(() => setIsResetting(false), 600);
  };

  const handleResetAdjustments = () => {
    setBrightness(100);
    setContrast(100);
    setSaturation(100);
    setHueRotate(0);
    setSelectedFilterId('none');
  };

  const handleSave = () => {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    const img = imageRef.current;

    if (!ctx || !img) return;

    const outputSize = 1536; 
    let width = outputSize;
    let height = outputSize;

    const [wRatio, hRatio] = cropRatio.split(':').map(Number);
    if (wRatio && hRatio) {
        if (wRatio > hRatio) {
            height = outputSize * (hRatio / wRatio);
        } else {
            width = outputSize * (wRatio / hRatio);
        }
    }

    canvas.width = width;
    canvas.height = height;
    ctx.fillStyle = '#000000';
    ctx.fillRect(0, 0, width, height);

    const container = containerRef.current;
    if (!container) return;

    const scaleFactor = width / container.clientWidth;

    ctx.save();
    const saveBaseFilter = IMAGE_FILTERS.find(f => f.id === selectedFilterId)?.filter || 'none';
    ctx.filter = `${saveBaseFilter === 'none' ? '' : saveBaseFilter} brightness(${brightness}%) contrast(${contrast}%) saturate(${saturation}%) hue-rotate(${hueRotate}deg)`;

    ctx.translate(width / 2, height / 2);
    ctx.scale(zoom, zoom);
    ctx.translate(pan.x * scaleFactor, pan.y * scaleFactor);

    const imgAspect = img.naturalWidth / img.naturalHeight;
    const containerAspect = container.clientWidth / container.clientHeight;

    let drawWidth, drawHeight;
    if (imgAspect > containerAspect) {
        drawHeight = height / zoom;
        drawWidth = drawHeight * imgAspect;
    } else {
        drawWidth = width / zoom;
        drawHeight = drawWidth / imgAspect;
    }

    ctx.drawImage(img, -drawWidth / 2, -drawHeight / 2, drawWidth, drawHeight);
    ctx.restore();

    onSave(canvas.toDataURL('image/png', 0.95));
  };

  return (
    <div className="absolute inset-0 bg-nano-50 z-50 flex flex-col h-full animate-in fade-in duration-300">
      <div className="h-14 border-b border-white/10 flex items-center justify-between px-4 bg-nano-100 shrink-0">
        <button onClick={onCancel} className="p-2 text-nano-400 hover:text-white hover:bg-white/5 rounded-lg transition-colors focus:outline-none">
          <X size={20} />
        </button>
        <span className="font-bold text-xs uppercase tracking-widest text-white">Retouch Station</span>
        <button onClick={handleSave} disabled={!imageLoaded} className="p-2 text-white hover:bg-white/10 rounded-lg transition-colors font-medium disabled:opacity-50">
          <Check size={20} />
        </button>
      </div>

      <div className="flex-grow bg-black/40 overflow-hidden relative flex items-center justify-center p-8 select-none">
        {!imageLoaded && (
          <div className="absolute inset-0 z-10 flex items-center justify-center bg-nano-50/80 backdrop-blur-sm">
             <Loader2 className="w-8 h-8 text-white animate-spin" />
          </div>
        )}

        <div 
          ref={containerRef}
          className="relative bg-black overflow-hidden shadow-2xl ring-1 ring-white/20"
          style={{
             aspectRatio: cropRatio.replace(':', '/'),
             width: '100%',
             maxWidth: '100%',
             maxHeight: '100%',
             cursor: isDragging ? 'grabbing' : 'grab',
             touchAction: 'none'
          }}
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={handlePointerUp}
          onPointerLeave={handlePointerUp}
        >
           <img 
             ref={imageRef}
             src={imageSrc} 
             alt="Editing"
             loading="lazy"
             decoding="async"
             onLoad={() => setImageLoaded(true)}
             className={`absolute max-w-none max-h-none origin-center pointer-events-none transition-opacity duration-300 ${imageLoaded ? 'opacity-100' : 'opacity-0'}`}
             style={{
                top: '50%',
                left: '50%',
                transform: `translate(-50%, -50%) scale(${zoom}) translate(${pan.x}px, ${pan.y}px)`,
                filter: currentFilter,
                minWidth: '100%',
                minHeight: '100%',
                transition: isResetting 
                  ? 'transform 0.6s cubic-bezier(0.25, 1, 0.5, 1), filter 0.3s ease' 
                  : (isDragging ? 'none' : 'transform 0.1s ease-out, filter 0.2s ease')
             }}
             draggable={false}
           />
        </div>
      </div>

      <div className="bg-nano-100 border-t border-white/10 shrink-0 pb-safe">
        <div className="flex border-b border-white/5">
           <button onClick={() => setActiveTab('filter')} className={`flex-1 py-3 text-[10px] uppercase font-bold tracking-widest flex items-center justify-center gap-2 focus:outline-none transition-all ${activeTab === 'filter' ? 'text-white border-b-2 border-white bg-white/5' : 'text-nano-400'}`}>
             <Wand2 size={14} /> Filters
           </button>
           <button onClick={() => setActiveTab('adjust')} className={`flex-1 py-3 text-[10px] uppercase font-bold tracking-widest flex items-center justify-center gap-2 focus:outline-none transition-all ${activeTab === 'adjust' ? 'text-white border-b-2 border-white bg-white/5' : 'text-nano-400'}`}>
             <Sliders size={14} /> Adjust
           </button>
           <button onClick={() => setActiveTab('crop')} className={`flex-1 py-3 text-[10px] uppercase font-bold tracking-widest flex items-center justify-center gap-2 focus:outline-none transition-all ${activeTab === 'crop' ? 'text-white border-b-2 border-white bg-white/5' : 'text-nano-400'}`}>
             <Crop size={14} /> Crop
           </button>
        </div>

        <div className="h-44 p-4 overflow-y-auto hide-scrollbar">
           {activeTab === 'filter' && (
             <div className="flex gap-4 overflow-x-auto pb-2 hide-scrollbar h-full items-center">
                {IMAGE_FILTERS.map((f) => (
                   <button 
                     key={f.id}
                     onClick={() => setSelectedFilterId(f.id)}
                     onMouseEnter={() => setHoveredFilterId(f.id)}
                     onMouseLeave={() => setHoveredFilterId(null)}
                     className="flex flex-col items-center gap-2 shrink-0 group focus:outline-none"
                   >
                      <div className={`w-14 h-14 rounded-lg overflow-hidden border-2 transition-all ${selectedFilterId === f.id ? 'border-white ring-2 ring-white/20' : 'border-transparent group-hover:border-white/20'}`}>
                         <img src={imageSrc} alt={f.name} className="w-full h-full object-cover" style={{ filter: f.filter }} />
                      </div>
                      <span className={`text-[9px] font-bold uppercase tracking-wider transition-colors ${selectedFilterId === f.id || hoveredFilterId === f.id ? 'text-white' : 'text-nano-400'}`}>{f.name}</span>
                   </button>
                ))}
             </div>
           )}

           {activeTab === 'adjust' && (
             <div className="flex flex-col gap-2 h-full justify-center max-w-lg mx-auto">
                <div className="flex items-center gap-4 px-2">
                   <div className="flex items-center gap-2 w-28 shrink-0">
                      <Sun size={12} className="text-nano-400" />
                      <span className="text-[10px] font-bold uppercase tracking-widest text-nano-300">Brightness</span>
                   </div>
                   <input type="range" min="0" max="200" step="1" value={brightness} onChange={(e) => setBrightness(parseInt(e.target.value))} className="w-full h-1 bg-nano-50 rounded-full appearance-none cursor-pointer accent-white" />
                   <span className="text-[10px] font-mono w-10 text-right text-nano-400">{brightness}%</span>
                </div>
                <div className="flex items-center gap-4 px-2">
                   <div className="flex items-center gap-2 w-28 shrink-0">
                      <Contrast size={12} className="text-nano-400" />
                      <span className="text-[10px] font-bold uppercase tracking-widest text-nano-300">Contrast</span>
                   </div>
                   <input type="range" min="0" max="200" step="1" value={contrast} onChange={(e) => setContrast(parseInt(e.target.value))} className="w-full h-1 bg-nano-50 rounded-full appearance-none cursor-pointer accent-white" />
                   <span className="text-[10px] font-mono w-10 text-right text-nano-400">{contrast}%</span>
                </div>
                <div className="flex items-center gap-4 px-2">
                   <div className="flex items-center gap-2 w-28 shrink-0">
                      <Droplets size={12} className="text-nano-400" />
                      <span className="text-[10px] font-bold uppercase tracking-widest text-nano-300">Saturation</span>
                   </div>
                   <input type="range" min="0" max="200" step="1" value={saturation} onChange={(e) => setSaturation(parseInt(e.target.value))} className="w-full h-1 bg-nano-50 rounded-full appearance-none cursor-pointer accent-white" />
                   <span className="text-[10px] font-mono w-10 text-right text-nano-400">{saturation}%</span>
                </div>
                <button onClick={handleResetAdjustments} className="text-[9px] font-bold uppercase tracking-[0.2em] text-nano-500 hover:text-white self-end px-2 mt-2 transition-colors">Reset Adjustments</button>
             </div>
           )}

           {activeTab === 'crop' && (
             <div className="flex flex-col gap-3 h-full justify-center max-w-lg mx-auto">
                <div className="flex items-center gap-3 px-2">
                   <ZoomIn size={14} className="text-nano-400" />
                   <input 
                     type="range" 
                     min={isRatioLocked ? getMinZoom() : 0.5} 
                     max="4" 
                     step="0.01"
                     value={zoom}
                     onChange={(e) => {
                       const val = parseFloat(e.target.value);
                       setZoom(val);
                       setPan(prev => constrainPan(prev, val));
                     }}
                     className="w-full h-1 bg-nano-50 rounded-full appearance-none cursor-pointer accent-white"
                   />
                   <div className="flex gap-2 ml-2">
                     <button onClick={() => setIsRatioLocked(!isRatioLocked)} className={`p-2 rounded-lg transition-all active:scale-90 ${isRatioLocked ? 'bg-white text-nano-50' : 'text-nano-400 hover:bg-white/5'}`} title={isRatioLocked ? "Unlock Aspect Ratio" : "Lock Aspect Ratio"}>
                       {isRatioLocked ? <Lock size={14} /> : <Unlock size={14} />}
                     </button>
                     <button onClick={handleResetTransform} className="p-2 text-nano-400 hover:text-white hover:bg-white/5 rounded-lg transition-all active:scale-90">
                       <RotateCcw size={14} />
                     </button>
                   </div>
                </div>

                <div className="flex gap-2 overflow-x-auto pb-1 hide-scrollbar justify-center">
                   {['1:1', '16:9', '9:16', '4:3', '3:4'].map(r => (
                     <button key={r} onClick={() => { setCropRatio(r); }} className={`px-4 py-1.5 rounded-lg border text-[9px] font-bold uppercase tracking-widest whitespace-nowrap transition-all ${cropRatio === r ? 'bg-white text-nano-50 border-white' : 'border-white/10 text-nano-400 hover:border-white/30'}`}>
                        {r === '1:1' ? 'Square' : r}
                     </button>
                   ))}
                </div>
             </div>
           )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { 
  Sparkles, 
  Download, 
  RefreshCw, 
  Image as ImageIcon, 
  History, 
  Zap,
  Camera,
  Maximize,
  Sliders,
  ChevronDown,
  ChevronUp,
  Undo,
  Redo,
  Upload,
  X,
  Plus,
  Edit2,
  Dices,
  Trash2,
  Wand2,
  Bookmark,
  Save,
  Clock,
  CheckCircle2,
  Eraser,
  Search,
  Loader2
} from 'lucide-react';
import { ART_STYLES, APP_NAME, MODEL_NAME_DISPLAY, ASPECT_RATIOS } from './constants';
import { ArtStyle, GeneratedImage, GenerationStatus, GenerationPreset } from './types';
import { generateImageWithNano, detectImageStyle } from './services/geminiService';
import { Button, StyleCard, Badge } from './components/UI';
import { ImageEditor } from './components/ImageEditor';
import { ZoomablePreview } from './components/ZoomablePreview';

const App: React.FC = () => {
  // --- Basic Generation State ---
  const [prompt, setPrompt] = useState<string>('');
  const [selectedStyleId, setSelectedStyleId] = useState<string>(ART_STYLES[0].id);
  const [aspectRatio, setAspectRatio] = useState<string>('1:1');

  // --- Advanced Parameters State ---
  const [seed, setSeed] = useState<number | undefined>(undefined);
  const [creativity, setCreativity] = useState<number>(50); // 0-100
  const [showAdvanced, setShowAdvanced] = useState<boolean>(false);

  // --- Presets State ---
  const [presets, setPresets] = useState<GenerationPreset[]>([]);
  const [isSavingPreset, setIsSavingPreset] = useState(false);
  const [newPresetName, setNewPresetName] = useState('');
  const [showPresets, setShowPresets] = useState(true);
  const [lastSavedPresetId, setLastSavedPresetId] = useState<string | null>(null);
  const [editingPresetId, setEditingPresetId] = useState<string | null>(null);
  const [editNameValue, setEditNameValue] = useState('');
  const [presetSearch, setPresetSearch] = useState('');

  // --- Reference Image State ---
  const [uploadedImage, setUploadedImage] = useState<string | null>(null);
  const [isDetectingStyle, setIsDetectingStyle] = useState(false);

  // --- Generation & Gallery State ---
  const [status, setStatus] = useState<GenerationStatus>('idle');
  const [currentImage, setCurrentImage] = useState<GeneratedImage | null>(null);
  const [history, setHistory] = useState<GeneratedImage[]>([]);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  // --- UI/Editor State ---
  const [isEditing, setIsEditing] = useState(false);

  // --- Prompt History (Undo/Redo) ---
  const [promptHistory, setPromptHistory] = useState<string[]>(['']);
  const [historyIndex, setHistoryIndex] = useState(0);
  const debounceRef = useRef<any>(null);

  // --- Refs ---
  const previewRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const presetNameInputRef = useRef<HTMLInputElement>(null);

  // --- Persistence ---
  useEffect(() => {
    const saved = localStorage.getItem('nanoframe_presets_v4');
    if (saved) {
      try {
        setPresets(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse presets", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('nanoframe_presets_v4', JSON.stringify(presets));
  }, [presets]);

  // --- Handlers ---

  const handlePromptChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newVal = e.target.value;
    setPrompt(newVal);

    if (debounceRef.current) clearTimeout(debounceRef.current);

    debounceRef.current = setTimeout(() => {
      setPromptHistory(prev => {
        const newHistory = prev.slice(0, historyIndex + 1);
        newHistory.push(newVal);
        return newHistory;
      });
      setHistoryIndex(prev => prev + 1);
    }, 400);
  };

  const handleUndo = () => {
    if (historyIndex > 0) {
      const newIndex = historyIndex - 1;
      setHistoryIndex(newIndex);
      setPrompt(promptHistory[newIndex]);
    }
  };

  const handleRedo = () => {
    if (historyIndex < promptHistory.length - 1) {
      const newIndex = historyIndex + 1;
      setHistoryIndex(newIndex);
      setPrompt(promptHistory[newIndex]);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = async (event) => {
        if (event.target?.result) {
          const base64 = event.target.result as string;
          setUploadedImage(base64);
          setIsDetectingStyle(true);
          try {
            const detectedStyleId = await detectImageStyle(base64);
            if (detectedStyleId) {
                const cleanId = detectedStyleId.trim();
                const matchedStyle = ART_STYLES.find(s => cleanId.includes(s.id));
                if (matchedStyle) setSelectedStyleId(matchedStyle.id);
            }
          } catch (err) {
            console.warn("Style detection failed", err);
          } finally {
            setIsDetectingStyle(false);
          }
        }
      };
      reader.readAsDataURL(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const clearUploadedImage = () => setUploadedImage(null);

  const resetWorkspace = () => {
    if (confirm("Reset current laboratory settings? This will clear your prompt and image.")) {
      setPrompt('');
      setSelectedStyleId(ART_STYLES[0].id);
      setAspectRatio('1:1');
      setSeed(undefined);
      setCreativity(50);
      setUploadedImage(null);
      setPromptHistory(['']);
      setHistoryIndex(0);
      setStatus('idle');
      setCurrentImage(null);
    }
  };

  // --- Preset Actions ---

  const handleSavePreset = (e?: React.FormEvent) => {
    if (e) e.preventDefault();

    const nameToUse = newPresetName.trim() || 
                      (prompt ? (prompt.length > 20 ? prompt.slice(0, 20) + '...' : prompt) : 'New Configuration');

    const preset: GenerationPreset = {
      id: crypto.randomUUID(),
      name: nameToUse,
      prompt,
      styleId: selectedStyleId,
      aspectRatio,
      seed,
      creativity,
      referenceImage: uploadedImage,
      timestamp: Date.now()
    };

    setPresets(prev => [preset, ...prev]);
    setNewPresetName('');
    setIsSavingPreset(false);
    setLastSavedPresetId(preset.id);
    setShowPresets(true);

    setTimeout(() => setLastSavedPresetId(null), 3000);
  };

  const loadPreset = (preset: GenerationPreset) => {
    if (editingPresetId) return; 

    setPrompt(preset.prompt);
    setSelectedStyleId(preset.styleId);
    setAspectRatio(preset.aspectRatio);
    setSeed(preset.seed);
    setCreativity(preset.creativity);
    setUploadedImage(preset.referenceImage || null);

    setPromptHistory(prev => [...prev.slice(0, historyIndex + 1), preset.prompt]);
    setHistoryIndex(prev => prev + 1);

    if (window.innerWidth < 1024) {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const deletePreset = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm("Delete this configuration permanently?")) {
      setPresets(prev => prev.filter(p => p.id !== id));
    }
  };

  const startSavingPreset = () => {
    setIsSavingPreset(true);
    setShowPresets(true);
    setTimeout(() => presetNameInputRef.current?.focus(), 100);
    if (window.innerWidth < 1024) {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const startRenaming = (preset: GenerationPreset, e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingPresetId(preset.id);
    setEditNameValue(preset.name);
  };

  const handleRenameSubmit = (id: string) => {
    setPresets(prev => prev.map(p => p.id === id ? { ...p, name: editNameValue.trim() || p.name } : p));
    setEditingPresetId(null);
  };

  // --- Generation Logic ---

  const handleGenerate = async () => {
    if (!prompt.trim() && !uploadedImage) {
        setErrorMsg("Please enter a text prompt or upload an image to start.");
        setStatus('error');
        return;
    }

    setStatus('generating');
    setErrorMsg(null);
    setCurrentImage(null);
    setIsEditing(false);

    if (window.innerWidth < 768) previewRef.current?.scrollIntoView({ behavior: 'smooth' });

    try {
      const base64Image = await generateImageWithNano(
          prompt, 
          selectedStyleId, 
          aspectRatio, 
          seed, 
          creativity, 
          uploadedImage
      );

      const newImage: GeneratedImage = {
        id: crypto.randomUUID(),
        url: base64Image,
        prompt: prompt || 'Image Variation',
        styleId: selectedStyleId,
        aspectRatio: aspectRatio,
        seed: seed,
        creativity: creativity,
        referenceImage: uploadedImage,
        timestamp: Date.now()
      };

      setCurrentImage(newImage);
      setHistory(prev => [newImage, ...prev].slice(0, 10));
      setStatus('success');
    } catch (error) {
      console.error(error);
      setStatus('error');
      setErrorMsg("Failed to generate. Please try again.");
    }
  };

  const handleDownload = () => {
    if (!currentImage) return;
    const link = document.createElement('a');
    link.href = currentImage.url;
    link.download = `${APP_NAME.toLowerCase()}-${currentImage.id.slice(0, 8)}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const loadFromHistory = (img: GeneratedImage) => {
    setCurrentImage(img);
    setPrompt(img.prompt);
    setPromptHistory(prev => [...prev.slice(0, historyIndex + 1), img.prompt]);
    setHistoryIndex(prev => prev + 1);
    setSelectedStyleId(img.styleId);
    setAspectRatio(img.aspectRatio || '1:1');
    setSeed(img.seed);
    setCreativity(img.creativity ?? 50);
    setUploadedImage(img.referenceImage || null);
    setStatus('success');
    setIsEditing(false);
    if (window.innerWidth < 768) previewRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleSaveEdit = (newImageSrc: string) => {
     if (!currentImage) return;
     const newImage: GeneratedImage = {
        ...currentImage,
        id: crypto.randomUUID(),
        url: newImageSrc,
        timestamp: Date.now()
     };
     setCurrentImage(newImage);
     setHistory(prev => [newImage, ...prev].slice(0, 10));
     setIsEditing(false);
  };

  const filteredPresets = presets.filter(p => 
    p.name.toLowerCase().includes(presetSearch.toLowerCase()) ||
    p.prompt.toLowerCase().includes(presetSearch.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-nano-50 text-white selection:bg-white selection:text-nano-50 flex flex-col">

      <header className="bg-nano-100/80 backdrop-blur-md sticky top-0 z-50 border-b border-white/10">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-white rounded-lg flex items-center justify-center text-nano-50">
              <Camera size={18} />
            </div>
            <h1 className="text-lg font-bold tracking-tight text-white">{APP_NAME}</h1>
            <Badge text={MODEL_NAME_DISPLAY} />
          </div>
          <div className="flex items-center gap-4">
             <button onClick={resetWorkspace} className="text-xs text-nano-400 hover:text-red-400 flex items-center gap-1 transition-colors">
               <Eraser size={14} /> Reset Lab
             </button>
             <div className="hidden sm:block w-px h-6 bg-white/10"></div>
             <div className="hidden sm:flex text-sm text-nano-400 font-medium">Pro AI Suite</div>
          </div>
        </div>
      </header>

      <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full flex flex-col lg:flex-row gap-8 lg:gap-12">

        {/* Left Column: Laboratory Controls */}
        <div className="w-full lg:w-1/3 flex flex-col gap-8 order-2 lg:order-1 pb-24 lg:pb-0">

          {/* --- MY PRESETS DRAWER --- */}
          <section className="bg-nano-100 rounded-2xl border border-white/10 overflow-hidden shadow-2xl">
            <div className="p-4 border-b border-white/5 flex items-center justify-between">
              <button 
                onClick={() => setShowPresets(!showPresets)}
                className="flex items-center gap-2 text-sm font-bold text-white focus:outline-none"
              >
                <Bookmark size={16} className={presets.length > 0 ? "text-white fill-white" : "text-nano-500"} />
                <span>My Presets</span>
                {presets.length > 0 && (
                  <span className="bg-white text-nano-50 text-[10px] px-1.5 py-0.5 rounded-full font-bold">
                    {presets.length}
                  </span>
                )}
                {showPresets ? <ChevronUp size={14} className="text-nano-400" /> : <ChevronDown size={14} className="text-nano-400" />}
              </button>

              {!isSavingPreset && (
                <button 
                  onClick={startSavingPreset}
                  className="p-1.5 rounded-lg text-nano-400 hover:text-white hover:bg-white/10 transition-all"
                  title="Capture current setup"
                >
                  <Plus size={18} />
                </button>
              )}
            </div>

            {isSavingPreset && (
              <div className="p-4 bg-nano-50/30 border-b border-white/5 animate-in slide-in-from-top-2 duration-300">
                <form onSubmit={handleSavePreset} className="space-y-3">
                  <div className="flex gap-2">
                    <input 
                      ref={presetNameInputRef}
                      type="text"
                      placeholder="Name your setup..."
                      value={newPresetName}
                      onChange={(e) => setNewPresetName(e.target.value)}
                      className="flex-grow p-2 text-sm rounded-lg border border-white/10 bg-nano-50 text-white placeholder:text-nano-500 focus:outline-none focus:ring-2 focus:ring-white transition-all"
                    />
                    <button 
                      type="button"
                      onClick={() => setIsSavingPreset(false)}
                      className="p-2 text-nano-400 hover:text-red-400"
                    >
                      <X size={18} />
                    </button>
                  </div>
                  <Button 
                    type="submit"
                    className="w-full !py-2 !text-xs !rounded-lg"
                    icon={<Save size={14} />}
                  >
                    Save Laboratory State
                  </Button>
                </form>
              </div>
            )}

            {showPresets && (
              <div className="p-2 space-y-2 max-h-[400px] overflow-y-auto hide-scrollbar">
                {presets.length > 3 && (
                  <div className="relative px-2 py-1">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-nano-400" size={12} />
                    <input 
                      type="text" 
                      placeholder="Search presets..." 
                      value={presetSearch}
                      onChange={(e) => setPresetSearch(e.target.value)}
                      className="w-full pl-8 pr-4 py-1.5 text-[11px] rounded-lg border border-white/5 bg-nano-50 text-white focus:outline-none focus:ring-1 focus:ring-white/20"
                    />
                  </div>
                )}

                {presets.length === 0 ? (
                  <div className="py-12 text-center px-4">
                    <div className="w-12 h-12 bg-nano-50 rounded-full flex items-center justify-center mx-auto mb-3">
                      <Bookmark size={20} className="text-nano-500" />
                    </div>
                    <p className="text-xs text-nano-400">Save your favorite laboratory<br/>configurations here.</p>
                  </div>
                ) : filteredPresets.length === 0 ? (
                  <div className="py-8 text-center text-xs text-nano-400">No matching presets.</div>
                ) : (
                  filteredPresets.map((p) => (
                    <div
                      key={p.id}
                      onClick={() => loadPreset(p)}
                      className={`group relative flex items-center justify-between p-3 rounded-xl border transition-all text-left cursor-pointer ${lastSavedPresetId === p.id ? 'border-emerald-500 bg-emerald-500/10' : 'border-transparent hover:bg-white/5 bg-nano-50/40'}`}
                    >
                      <div className="flex flex-col gap-1 min-w-0 flex-grow pr-2">
                        {editingPresetId === p.id ? (
                          <div className="flex items-center gap-1" onClick={e => e.stopPropagation()}>
                            <input 
                              autoFocus
                              value={editNameValue}
                              onChange={e => setEditNameValue(e.target.value)}
                              onKeyDown={e => e.key === 'Enter' && handleRenameSubmit(p.id)}
                              onBlur={() => handleRenameSubmit(p.id)}
                              className="w-full text-xs font-bold p-0 border-none bg-transparent focus:ring-0 text-white"
                            />
                          </div>
                        ) : (
                          <div className="flex items-center gap-2">
                            <span className="text-xs font-bold text-white truncate">{p.name}</span>
                            {lastSavedPresetId === p.id && <CheckCircle2 size={12} className="text-emerald-400 shrink-0 animate-bounce" />}
                          </div>
                        )}
                        <div className="flex items-center gap-2 overflow-hidden">
                          <span className="text-[9px] font-bold uppercase tracking-wider text-nano-400 shrink-0">
                            {ART_STYLES.find(s => s.id === p.styleId)?.name || 'Custom'}
                          </span>
                          <span className="text-[9px] text-nano-300 truncate">{p.prompt}</span>
                        </div>
                      </div>

                      <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-all shrink-0">
                        <button 
                          onClick={(e) => startRenaming(p, e)}
                          className="p-1.5 rounded-md text-nano-400 hover:text-white hover:bg-white/10 transition-all"
                        >
                          <Edit2 size={12} />
                        </button>
                        <button 
                          onClick={(e) => deletePreset(p.id, e)}
                          className="p-1.5 rounded-md text-nano-400 hover:text-red-400 hover:bg-white/10 transition-all"
                        >
                          <Trash2 size={12} />
                        </button>
                      </div>
                    </div>
                  ))
                )}
              </div>
            )}
          </section>

          {/* --- PROMPT INPUT --- */}
          <section className="space-y-4">
            <div className="flex justify-between items-end">
              <div className="space-y-1">
                <label htmlFor="prompt" className="block text-sm font-bold text-white">Visual Blueprint</label>
                <p className="text-[11px] text-nano-400">Describe the subject and environment</p>
              </div>
              <div className="flex items-center gap-0.5 bg-nano-100 rounded-lg border border-white/5 p-0.5 shadow-sm">
                <button onClick={handleUndo} disabled={historyIndex === 0} className="p-1.5 rounded hover:bg-white/10 text-nano-300 disabled:opacity-20 transition-all"><Undo size={14} /></button>
                <button onClick={handleRedo} disabled={historyIndex >= promptHistory.length - 1} className="p-1.5 rounded hover:bg-white/10 text-nano-300 disabled:opacity-20 transition-all"><Redo size={14} /></button>
              </div>
            </div>
            <textarea
              id="prompt"
              value={prompt}
              onChange={handlePromptChange}
              placeholder="e.g. A hyper-realistic macro shot of a morning dew drop on a lavender petal..."
              className="w-full p-4 rounded-2xl border border-white/10 bg-nano-100 shadow-inner text-white placeholder:text-nano-500 focus:outline-none focus:ring-2 focus:ring-white h-32 transition-all resize-none text-sm leading-relaxed"
            />
          </section>

          {/* --- REFERENCE IMAGE --- */}
          <section className="space-y-4">
            <div className="space-y-1">
               <label className="block text-sm font-bold text-white">Compositional Reference</label>
               <p className="text-[11px] text-nano-400">Guide the AI with structural context</p>
            </div>
            <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" accept="image/*" />
            {!uploadedImage ? (
              <button onClick={() => fileInputRef.current?.click()} className="w-full border-2 border-dashed border-white/10 rounded-2xl p-8 flex flex-col items-center justify-center text-nano-400 hover:border-white/30 hover:text-white hover:bg-white/5 transition-all group">
                 <div className="w-12 h-12 rounded-full bg-white/5 flex items-center justify-center mb-3 group-hover:scale-110 transition-transform">
                   <Upload size={20} />
                 </div>
                 <span className="text-xs font-bold uppercase tracking-wider">Load Reference</span>
              </button>
            ) : (
              <div className="relative group overflow-hidden rounded-2xl border border-white/10 shadow-2xl">
                  <div className="aspect-video w-full bg-black/40">
                    <img src={uploadedImage} alt="Reference" className="w-full h-full object-cover opacity-60 group-hover:opacity-100 transition-opacity" />
                  </div>
                  <div className="absolute inset-0 bg-gradient-to-t from-black/80 to-transparent opacity-0 group-hover:opacity-100 transition-opacity flex items-end p-3">
                    <button onClick={clearUploadedImage} className="w-full py-2 bg-white/10 hover:bg-white/20 backdrop-blur text-white text-[10px] font-bold uppercase tracking-widest rounded-lg transition-all flex items-center justify-center gap-2">
                       <X size={12} /> Remove Reference
                    </button>
                  </div>
                  {isDetectingStyle && (
                      <div className="absolute inset-0 bg-nano-50/80 backdrop-blur-sm flex items-center justify-center">
                          <div className="bg-nano-100 border border-white/10 rounded-full px-4 py-2 flex items-center gap-3 text-[10px] font-bold shadow-2xl text-white">
                              <Loader2 size={14} className="animate-spin text-white" />
                              <span className="uppercase tracking-widest">Parsing Style...</span>
                          </div>
                      </div>
                  )}
              </div>
            )}
          </section>

          {/* --- DIMENSIONS --- */}
          <section className="space-y-4">
            <label className="block text-sm font-bold text-white">Canvas Dimensions</label>
            <div className="grid grid-cols-3 gap-2">
              {ASPECT_RATIOS.map((ratio) => (
                <button
                  key={ratio.id}
                  onClick={() => setAspectRatio(ratio.id)}
                  className={`flex flex-col items-center justify-center gap-2 p-3 rounded-xl border transition-all ${aspectRatio === ratio.id ? 'bg-white text-nano-50 border-white shadow-[0_0_20px_rgba(255,255,255,0.3)]' : 'bg-nano-100 text-nano-400 border-white/5 hover:border-white/20'}`}
                >
                  <div className={`border-2 rounded-sm ${ratio.shapeClass} ${aspectRatio === ratio.id ? 'bg-nano-50 border-nano-50' : 'border-nano-500'}`}></div>
                  <span className="text-[10px] font-bold uppercase tracking-tighter">{ratio.label}</span>
                </button>
              ))}
            </div>
          </section>

          {/* --- ADVANCED ENGINE PARAMS --- */}
          <section className="space-y-4">
             <button onClick={() => setShowAdvanced(!showAdvanced)} className="flex items-center justify-between w-full text-sm font-bold text-white hover:text-nano-300 transition-colors p-1 rounded-lg">
                <div className="flex items-center gap-2"><Sliders size={16} /><span>Advanced Parameters</span></div>
                {showAdvanced ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
             </button>
             {showAdvanced && (
                <div className="bg-nano-100 rounded-2xl border border-white/10 p-5 space-y-6 animate-in slide-in-from-top-2 duration-300 shadow-2xl">
                    <div className="space-y-3">
                      <div className="flex justify-between items-center">
                        <label className="text-[10px] font-bold uppercase tracking-widest text-nano-400">Entropy Seed</label>
                        <span className="text-[9px] font-mono text-nano-500">AUTO-GEN</span>
                      </div>
                      <div className="flex gap-2">
                        <input 
                          type="number" 
                          placeholder="Random" 
                          value={seed === undefined ? '' : seed} 
                          onChange={(e) => setSeed(e.target.value === '' ? undefined : parseInt(e.target.value))} 
                          className="w-full p-2 text-sm rounded-xl border border-white/5 bg-nano-50 text-white focus:ring-1 focus:ring-white focus:outline-none transition-all" 
                        />
                        <button onClick={() => setSeed(Math.floor(Math.random() * 1000000000))} className="p-2.5 bg-white text-nano-50 hover:bg-nano-200 rounded-xl transition-all active:scale-90" title="Randomize"><Dices size={18} /></button>
                      </div>
                    </div>
                    <div className="space-y-4">
                      <div className="flex justify-between items-center">
                        <label className="text-[10px] font-bold uppercase tracking-widest text-nano-400">Diffusion Temperature</label>
                        <span className="text-[10px] bg-white text-nano-50 px-2 py-0.5 rounded-full font-bold tabular-nums">{creativity}%</span>
                      </div>
                      <input 
                        type="range" 
                        min="0" 
                        max="100" 
                        value={creativity} 
                        onChange={(e) => setCreativity(parseInt(e.target.value))} 
                        className="w-full h-1.5 bg-nano-50 rounded-full appearance-none cursor-pointer accent-white" 
                      />
                      <div className="flex justify-between text-[8px] text-nano-500 font-bold tracking-widest px-1">
                        <span>LITERAL</span>
                        <span>ABSTRACT</span>
                      </div>
                    </div>
                </div>
             )}
          </section>

          {/* --- STYLE PRESETS --- */}
          <section className="space-y-4">
            <label className="block text-sm font-bold text-white">Visual Aesthetic</label>
            <div className="grid grid-cols-2 gap-3">
              {ART_STYLES.map((style) => (
                <StyleCard key={style.id} style={style} isSelected={selectedStyleId === style.id} onClick={() => setSelectedStyleId(style.id)} />
              ))}
            </div>
          </section>

          {/* --- LAUNCH ACTION --- */}
          <div className="pt-4 sticky bottom-8 lg:static z-20">
            <Button onClick={handleGenerate} isLoading={status === 'generating'} disabled={!prompt.trim() && !uploadedImage} className="w-full !rounded-2xl !h-14 shadow-[0_10px_40px_rgba(0,0,0,0.5)] hover:scale-[1.02]" icon={<Zap size={20} className="fill-nano-50" />}>
              {status === 'generating' ? 'Synthesizing...' : 'Launch Generation'}
            </Button>
            {errorMsg && <p className="text-red-400 text-[11px] text-center mt-3 font-bold uppercase tracking-tight animate-pulse">{errorMsg}</p>}
          </div>
        </div>

        {/* Right Column: Creative Results */}
        <div className="w-full lg:w-2/3 flex flex-col gap-6 order-1 lg:order-2">

          <div ref={previewRef} className="w-full bg-nano-100 rounded-3xl shadow-2xl border border-white/10 overflow-hidden relative flex flex-col min-h-[500px] lg:min-h-[700px]">

            {isEditing && currentImage ? (
                <ImageEditor imageSrc={currentImage.url} onSave={handleSaveEdit} onCancel={() => setIsEditing(false)} />
            ) : (
                <>
                    <div className="h-16 border-b border-white/5 flex items-center justify-between px-6 bg-nano-100/80 backdrop-blur-md z-10 shrink-0">
                      <div className="flex items-center gap-3">
                        <div className="w-2 h-2 bg-white rounded-full animate-pulse shadow-[0_0_8px_white]"></div>
                        <span className="text-xs font-bold uppercase tracking-widest text-white">Output Stream</span>
                      </div>

                      {status === 'success' && currentImage && (
                        <div className="flex gap-2 items-center">
                          <button 
                            onClick={startSavingPreset} 
                            className="flex items-center gap-2 px-4 py-2 hover:bg-white/5 rounded-xl text-nano-400 text-[11px] font-bold uppercase tracking-widest transition-all"
                            title="Store this configuration"
                          >
                            <Bookmark size={14} /> <span className="hidden sm:inline text-white">Save Preset</span>
                          </button>
                          <div className="w-px h-6 bg-white/10 mx-1"></div>
                          <button onClick={() => setIsEditing(true)} className="p-2.5 hover:bg-white/5 rounded-xl text-white transition-all" title="Retouch Toolset"><Edit2 size={20} /></button>
                          <button onClick={handleGenerate} className="p-2.5 hover:bg-white/5 rounded-xl text-white transition-all" title="Re-simulate"><RefreshCw size={20} /></button>
                          <Button variant="secondary" onClick={handleDownload} className="!py-2 !px-5 !text-[11px] !h-10 !rounded-xl !font-bold !uppercase !tracking-widest !bg-white !text-nano-50"><Download size={16} className="mr-2" />Export</Button>
                        </div>
                      )}
                    </div>

                    <div className="flex-grow relative bg-nano-50 flex items-center justify-center p-6">
                      {status === 'idle' && (
                          <div className="text-center max-w-sm px-8">
                            <div className="w-24 h-24 bg-nano-100 rounded-[2.5rem] shadow-2xl border border-white/5 flex items-center justify-center mx-auto mb-8 transform rotate-6 hover:rotate-0 transition-transform duration-700">
                              <Sparkles className="text-white/20" size={48} />
                            </div>
                            <h3 className="text-2xl font-bold text-white mb-3 tracking-tight">Studio Laboratory</h3>
                            <p className="text-nano-400 text-sm leading-relaxed mb-8">Define your parameters in the sidebar to initiate image synthesis. All results are high-fidelity captures from the {MODEL_NAME_DISPLAY} core.</p>
                            <div className="flex flex-wrap justify-center gap-2">
                               <button onClick={() => setPrompt("A futuristic garden with floating crystal spheres")} className="text-[10px] font-bold uppercase tracking-widest bg-nano-100 border border-white/5 px-3 py-1.5 rounded-full text-nano-400 hover:text-white transition-colors">Garden</button>
                               <button onClick={() => setPrompt("Minimalist brutalist architecture against a sunset sky")} className="text-[10px] font-bold uppercase tracking-widest bg-nano-100 border border-white/5 px-3 py-1.5 rounded-full text-nano-400 hover:text-white transition-colors">Architecture</button>
                            </div>
                          </div>
                      )}

                      {status === 'generating' && (
                          <div className="w-full h-full absolute inset-0 bg-nano-50 flex flex-col items-center justify-center z-20">
                            <div className="w-full max-w-md px-12 space-y-12">
                              <div className="relative w-full aspect-square bg-gradient-to-br from-nano-100 via-nano-50 to-nano-200 rounded-3xl overflow-hidden shadow-2xl border border-white/5">
                                <div className="absolute inset-0 bg-gradient-to-tr from-white/5 to-transparent animate-pulse"></div>
                                <div className="absolute top-1/2 left-0 right-0 h-[2px] bg-white/20 -translate-y-1/2 animate-[scan_3s_linear_infinite]"></div>
                              </div>
                              <div className="space-y-4 text-center">
                                <div className="flex items-center justify-center gap-2">
                                  <Sparkles size={16} className="text-white animate-spin" />
                                  <p className="text-xs font-bold tracking-[0.3em] uppercase text-white">Synthesizing Pixels</p>
                                </div>
                                <div className="h-1 w-48 bg-white/5 rounded-full mx-auto overflow-hidden">
                                  <div className="h-full bg-white w-full -translate-x-full animate-[progress_2s_ease-in-out_infinite]"></div>
                                </div>
                              </div>
                            </div>
                          </div>
                      )}

                      {currentImage && (
                          <ZoomablePreview src={currentImage.url} alt={currentImage.prompt} className="max-w-full max-h-[80vh] rounded-2xl shadow-2xl" isVisible={status !== 'generating'} />
                      )}
                    </div>
                </>
            )}
          </div>

          {/* Persistent History Stream */}
          {history.length > 0 && (
            <div className="space-y-5">
              <div className="flex items-center justify-between px-1">
                <div className="flex items-center gap-3 text-[10px] font-bold uppercase tracking-[0.2em] text-nano-400">
                  <History size={16} /><span>Lab Sequence</span>
                </div>
                <span className="text-[9px] font-bold text-nano-500 uppercase">Limit: 10 Instances</span>
              </div>
              <div className="flex gap-5 overflow-x-auto pb-6 pt-2 px-1 hide-scrollbar">
                {history.map((img) => (
                  <button 
                    key={img.id} 
                    onClick={() => loadFromHistory(img)} 
                    className={`relative flex-shrink-0 w-28 h-28 rounded-2xl overflow-hidden border-2 transition-all shadow-xl group ${currentImage?.id === img.id ? 'border-white ring-4 ring-white/10 scale-105 z-10' : 'border-transparent opacity-40 hover:opacity-100 hover:scale-105'}`}
                  >
                    <img src={img.url} alt="Sequence" className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" loading="lazy" />
                    <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity"></div>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </main>

      {/* Engine Animations */}
      <style dangerouslySetInnerHTML={{ __html: `
        @keyframes progress {
          0% { transform: translateX(-100%); }
          50% { transform: translateX(0); }
          100% { transform: translateX(100%); }
        }
        @keyframes scan {
          0% { transform: translateY(-300px); }
          100% { transform: translateY(300px); }
        }
      `}} />
    </div>
  );
};

