);

import React, { useState, useEffect, useRef } from 'react';
import { 
  Sparkles, 
  Download, 
  RefreshCw, 
  Image as ImageIcon, 
  History, 
  Zap,
  Camera,
  Maximize,
  Sliders,
  ChevronDown,
  ChevronUp,
  Undo,
  Redo,
  Upload,
  X,
  Plus,
  Edit2,
  Dices,
  Trash2,
  Wand2,
  Bookmark,
  Save,
  Clock,
  CheckCircle2,
  Eraser,
  Search,
  Loader2
} from 'lucide-react';
import { ART_STYLES, APP_NAME, MODEL_NAME_DISPLAY, ASPECT_RATIOS } from './constants';
import { ArtStyle, GeneratedImage, GenerationStatus, GenerationPreset } from './types';
import { generateImageWithNano, detectImageStyle } from './services/geminiService';
import { Button, StyleCard, Badge } from './components/UI';
import { ImageEditor } from './components/ImageEditor';
import { ZoomablePreview } from './components/ZoomablePreview';

const App: React.FC = () => {
  // --- Basic Generation State ---
  const [prompt, setPrompt] = useState<string>('');
  const [selectedStyleId, setSelectedStyleId] = useState<string>(ART_STYLES[0].id);
  const [aspectRatio, setAspectRatio] = useState<string>('1:1');

  // --- Advanced Parameters State ---
  const [seed, setSeed] = useState<number | undefined>(undefined);
  const [creativity, setCreativity] = useState<number>(50); // 0-100
  const [showAdvanced, setShowAdvanced] = useState<boolean>(false);

  // --- Presets State ---
  const [presets, setPresets] = useState<GenerationPreset[]>([]);
  const [isSavingPreset, setIsSavingPreset] = useState(false);
  const [newPresetName, setNewPresetName] = useState('');
  const [showPresets, setShowPresets] = useState(true);
  const [lastSavedPresetId, setLastSavedPresetId] = useState<string | null>(null);
  const [editingPresetId, setEditingPresetId] = useState<string | null>(null);
  const [editNameValue, setEditNameValue] = useState('');
  const [presetSearch, setPresetSearch] = useState('');

  // --- Reference Image State ---
  const [uploadedImage, setUploadedImage] = useState<string | null>(null);
  const [isDetectingStyle, setIsDetectingStyle] = useState(false);

  // --- Generation & Gallery State ---
  const [status, setStatus] = useState<GenerationStatus>('idle');
  const [currentImage, setCurrentImage] = useState<GeneratedImage | null>(null);
  const [history, setHistory] = useState<GeneratedImage[]>([]);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  // --- UI/Editor State ---
  const [isEditing, setIsEditing] = useState(false);

  // --- Prompt History (Undo/Redo) ---
  const [promptHistory, setPromptHistory] = useState<string[]>(['']);
  const [historyIndex, setHistoryIndex] = useState(0);
  const debounceRef = useRef<any>(null);

  // --- Refs ---
  const previewRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const presetNameInputRef = useRef<HTMLInputElement>(null);

  // --- Persistence ---
  useEffect(() => {
    const saved = localStorage.getItem('nanoframe_presets_v4');
    if (saved) {
      try {
        setPresets(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse presets", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('nanoframe_presets_v4', JSON.stringify(presets));
  }, [presets]);

  // --- Handlers ---

  const handlePromptChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newVal = e.target.value;
    setPrompt(newVal);

    if (debounceRef.current) clearTimeout(debounceRef.current);

    debounceRef.current = setTimeout(() => {
      setPromptHistory(prev => {
        const newHistory = prev.slice(0, historyIndex + 1);
        newHistory.push(newVal);
        return newHistory;
      });
      setHistoryIndex(prev => prev + 1);
    }, 400);
  };

  const handleUndo = () => {
    if (historyIndex > 0) {
      const newIndex = historyIndex - 1;
      setHistoryIndex(newIndex);
      setPrompt(promptHistory[newIndex]);
    }
  };

  const handleRedo = () => {
    if (historyIndex < promptHistory.length - 1) {
      const newIndex = historyIndex + 1;
      setHistoryIndex(newIndex);
      setPrompt(promptHistory[newIndex]);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = async (event) => {
        if (event.target?.result) {
          const base64 = event.target.result as string;
          setUploadedImage(base64);
          setIsDetectingStyle(true);
          try {
            const detectedStyleId = await detectImageStyle(base64);
            if (detectedStyleId) {
                const cleanId = detectedStyleId.trim();
                const matchedStyle = ART_STYLES.find(s => cleanId.includes(s.id));
                if (matchedStyle) setSelectedStyleId(matchedStyle.id);
            }
          } catch (err) {
            console.warn("Style detection failed", err);
          } finally {
            setIsDetectingStyle(false);
          }
        }
      };
      reader.readAsDataURL(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const clearUploadedImage = () => setUploadedImage(null);

  const resetWorkspace = () => {
    if (confirm("Reset current laboratory settings? This will clear your prompt and image.")) {
      setPrompt('');
      setSelectedStyleId(ART_STYLES[0].id);
      setAspectRatio('1:1');
      setSeed(undefined);
      setCreativity(50);
      setUploadedImage(null);
      setPromptHistory(['']);
      setHistoryIndex(0);
      setStatus('idle');
      setCurrentImage(null);
    }
  };

  const handleQuickStart = (p: string, style?: string) => {
    setPrompt(p);
    if (style) setSelectedStyleId(style);
    // Inmediatamente generamos para que el usuario vea que la sidebar y el motor funcionan
    setTimeout(() => {
        handleGenerate();
    }, 100);
  };

  const handleGenerate = async () => {
    const currentPrompt = prompt.trim();
    if (!currentPrompt && !uploadedImage) {
        setErrorMsg("Please enter a text prompt or upload an image to start.");
        setStatus('error');
        return;
    }

    setStatus('generating');
    setErrorMsg(null);
    setCurrentImage(null);
    setIsEditing(false);

    if (window.innerWidth < 768) previewRef.current?.scrollIntoView({ behavior: 'smooth' });

    try {
      const base64Image = await generateImageWithNano(
          currentPrompt, 
          selectedStyleId, 
          aspectRatio, 
          seed, 
          creativity, 
          uploadedImage
      );

      const newImage: GeneratedImage = {
        id: crypto.randomUUID(),
        url: base64Image,
        prompt: currentPrompt || 'Image Variation',
        styleId: selectedStyleId,
        aspectRatio: aspectRatio,
        seed: seed,
        creativity: creativity,
        referenceImage: uploadedImage,
        timestamp: Date.now()
      };

      setCurrentImage(newImage);
      setHistory(prev => [newImage, ...prev].slice(0, 10));
      setStatus('success');
    } catch (error) {
      console.error(error);
      setStatus('error');
      setErrorMsg("Failed to generate. Please try again.");
    }
  };

  // --- UI Logic ---
  const handleDownload = () => {
    if (!currentImage) return;
    const link = document.createElement('a');
    link.href = currentImage.url;
    link.download = `${APP_NAME.toLowerCase()}-${currentImage.id.slice(0, 8)}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const loadFromHistory = (img: GeneratedImage) => {
    setCurrentImage(img);
    setPrompt(img.prompt);
    setPromptHistory(prev => [...prev.slice(0, historyIndex + 1), img.prompt]);
    setHistoryIndex(prev => prev + 1);
    setSelectedStyleId(img.styleId);
    setAspectRatio(img.aspectRatio || '1:1');
    setSeed(img.seed);
    setCreativity(img.creativity ?? 50);
    setUploadedImage(img.referenceImage || null);
    setStatus('success');
    setIsEditing(false);
    if (window.innerWidth < 768) previewRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleSaveEdit = (newImageSrc: string) => {
     if (!currentImage) return;
     const newImage: GeneratedImage = {
        ...currentImage,
        id: crypto.randomUUID(),
        url: newImageSrc,
        timestamp: Date.now()
     };
     setCurrentImage(newImage);
     setHistory(prev => [newImage, ...prev].slice(0, 10));
     setIsEditing(false);
  };

  const filteredPresets = presets.filter(p => 
    p.name.toLowerCase().includes(presetSearch.toLowerCase()) ||
    p.prompt.toLowerCase().includes(presetSearch.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-nano-50 text-white selection:bg-white selection:text-nano-50 flex flex-col font-sans">

      <header className="bg-nano-100/80 backdrop-blur-xl sticky top-0 z-50 border-b border-white/10 shadow-lg">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 bg-white rounded-xl flex items-center justify-center text-nano-50 shadow-xl shadow-white/5">
              <Camera size={20} />
            </div>
            <h1 className="text-xl font-extrabold tracking-tight text-white">{APP_NAME}</h1>
            <Badge text={MODEL_NAME_DISPLAY} />
          </div>
          <div className="flex items-center gap-6">
             <button onClick={resetWorkspace} className="text-xs font-bold text-white/50 hover:text-red-400 flex items-center gap-1.5 transition-all">
               <Eraser size={14} /> Clear Engine
             </button>
             <div className="hidden sm:block w-px h-6 bg-white/10"></div>
             <div className="hidden sm:flex text-sm text-white/40 font-bold uppercase tracking-[0.2em]">Studio PRO</div>
          </div>
        </div>
      </header>

      <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full flex flex-col lg:flex-row gap-8 lg:gap-12">

        {/* Left Column: Laboratory Controls */}
        <aside className="w-full lg:w-1/3 flex flex-col gap-8 order-2 lg:order-1">

          {/* --- MY PRESETS DRAWER --- */}
          <section className="bg-nano-100 rounded-3xl border border-white/10 overflow-hidden shadow-2xl">
            <div className="p-5 border-b border-white/5 flex items-center justify-between bg-white/5">
              <button 
                onClick={() => setShowPresets(!showPresets)}
                className="flex items-center gap-2.5 text-sm font-black text-white focus:outline-none"
              >
                <Bookmark size={18} className={presets.length > 0 ? "text-white fill-white" : "text-white/20"} />
                <span className="uppercase tracking-widest">Library</span>
                {presets.length > 0 && (
                  <span className="bg-white text-nano-50 text-[10px] px-2 py-0.5 rounded-full font-black">
                    {presets.length}
                  </span>
                )}
                {showPresets ? <ChevronUp size={14} className="text-white/40" /> : <ChevronDown size={14} className="text-white/40" />}
              </button>

              {!isSavingPreset && (
                <button 
                  onClick={() => setIsSavingPreset(true)}
                  className="p-2 rounded-xl text-white/40 hover:text-white hover:bg-white/10 transition-all shadow-inner"
                  title="Save current configuration"
                >
                  <Plus size={20} />
                </button>
              )}
            </div>

            {isSavingPreset && (
              <div className="p-5 bg-nano-50/50 border-b border-white/5 animate-in slide-in-from-top-2">
                <form onSubmit={(e) => { e.preventDefault(); handleSavePreset(); }} className="space-y-4">
                  <input 
                    autoFocus
                    type="text"
                    placeholder="Configuration Name..."
                    value={newPresetName}
                    onChange={(e) => setNewPresetName(e.target.value)}
                    className="w-full p-3 text-sm rounded-xl border border-white/10 bg-nano-100 text-white placeholder:text-white/20 focus:outline-none focus:ring-2 focus:ring-white transition-all"
                  />
                  <div className="flex gap-2">
                    <Button type="submit" className="flex-grow !py-2 !text-[10px]" icon={<Save size={14} />}>Store State</Button>
                    <button onClick={() => setIsSavingPreset(false)} className="px-4 py-2 text-white/40 hover:text-white text-[10px] font-bold uppercase">Cancel</button>
                  </div>
                </form>
              </div>
            )}

            {showPresets && (
              <div className="p-3 space-y-3 max-h-[350px] overflow-y-auto hide-scrollbar">
                {presets.length === 0 ? (
                  <div className="py-12 text-center">
                    <p className="text-[11px] font-bold text-white/20 uppercase tracking-[0.2em]">No saved presets yet</p>
                  </div>
                ) : (
                  presets.map((p) => (
                    <div
                      key={p.id}
                      onClick={() => loadPreset(p)}
                      className={`group flex items-center justify-between p-3.5 rounded-2xl border transition-all cursor-pointer ${lastSavedPresetId === p.id ? 'border-emerald-500 bg-emerald-500/10' : 'border-white/5 hover:bg-white/5 bg-white/2'}`}
                    >
                      <div className="min-w-0 pr-3">
                        <p className="text-xs font-black text-white truncate">{p.name}</p>
                        <p className="text-[9px] font-bold text-white/40 uppercase tracking-widest mt-1">
                          {ART_STYLES.find(s => s.id === p.styleId)?.name || 'Custom'}
                        </p>
                      </div>
                      <button onClick={(e) => deletePreset(p.id, e)} className="opacity-0 group-hover:opacity-100 p-2 text-white/20 hover:text-red-400 transition-all">
                        <Trash2 size={14} />
                      </button>
                    </div>
                  ))
                )}
              </div>
            )}
          </section>

          {/* --- PROMPT INPUT --- */}
          <section className="space-y-4">
            <div className="flex justify-between items-end">
              <div className="space-y-1">
                <label className="block text-xs font-black text-white uppercase tracking-[0.2em]">1. Visual Prompt</label>
                <p className="text-[10px] text-white/40 font-bold">Describe your desired masterpiece</p>
              </div>
              <div className="flex gap-1">
                <button onClick={handleUndo} disabled={historyIndex === 0} className="p-2 text-white/30 hover:text-white disabled:opacity-10 transition-all"><Undo size={14} /></button>
                <button onClick={handleRedo} disabled={historyIndex >= promptHistory.length - 1} className="p-2 text-white/30 hover:text-white disabled:opacity-10 transition-all"><Redo size={14} /></button>
              </div>
            </div>
            <textarea
              id="prompt"
              value={prompt}
              onChange={handlePromptChange}
              placeholder="A futuristic cyber-city with neon reflections..."
              className="w-full p-5 rounded-3xl border border-white/10 bg-nano-100 shadow-inner text-white placeholder:text-white/20 focus:outline-none focus:ring-2 focus:ring-white h-40 transition-all resize-none text-sm font-medium leading-relaxed"
            />
          </section>

          {/* --- STYLE PRESETS --- */}
          <section className="space-y-4">
            <label className="block text-xs font-black text-white uppercase tracking-[0.2em]">2. Visual Aesthetic</label>
            <div className="grid grid-cols-2 gap-3">
              {ART_STYLES.map((style) => (
                <StyleCard key={style.id} style={style} isSelected={selectedStyleId === style.id} onClick={() => setSelectedStyleId(style.id)} />
              ))}
            </div>
          </section>

          {/* --- DIMENSIONS & ADVANCED --- */}
          <section className="space-y-6">
            <div className="space-y-4">
              <label className="block text-xs font-black text-white uppercase tracking-[0.2em]">3. Canvas Size</label>
              <div className="grid grid-cols-5 gap-2">
                {ASPECT_RATIOS.map((ratio) => (
                  <button
                    key={ratio.id}
                    onClick={() => setAspectRatio(ratio.id)}
                    className={`flex flex-col items-center justify-center p-2.5 rounded-2xl border transition-all ${aspectRatio === ratio.id ? 'bg-white text-nano-50 border-white shadow-xl shadow-white/5' : 'bg-nano-100 text-white/40 border-white/5 hover:border-white/20'}`}
                  >
                    <div className={`border-2 rounded-sm mb-1.5 ${ratio.shapeClass} ${aspectRatio === ratio.id ? 'border-nano-50 bg-nano-50' : 'border-white/20'}`}></div>
                    <span className="text-[9px] font-black">{ratio.id}</span>
                  </button>
                ))}
              </div>
            </div>

            <div className="pt-2">
                <button onClick={() => setShowAdvanced(!showAdvanced)} className="flex items-center justify-between w-full p-4 rounded-2xl bg-white/5 border border-white/10 hover:bg-white/10 transition-all">
                    <div className="flex items-center gap-3"><Sliders size={16} className="text-white" /><span className="text-[10px] font-black uppercase tracking-widest text-white">Engine parameters</span></div>
                    {showAdvanced ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
                </button>

                {showAdvanced && (
                    <div className="mt-4 p-5 bg-nano-100 rounded-3xl border border-white/10 space-y-8 animate-in slide-in-from-top-4">
                        <div className="space-y-3">
                            <div className="flex justify-between">
                                <label className="text-[10px] font-black uppercase text-white/50">Diffusion Seed</label>
                                <span className="text-[9px] font-mono text-white/30">NANO_V2</span>
                            </div>
                            <div className="flex gap-2">
                                <input 
                                    type="number" 
                                    placeholder="Randomized" 
                                    value={seed === undefined ? '' : seed} 
                                    onChange={(e) => setSeed(e.target.value === '' ? undefined : parseInt(e.target.value))} 
                                    className="flex-grow p-3 text-sm rounded-xl border border-white/10 bg-nano-50 text-white focus:ring-2 focus:ring-white focus:outline-none"
                                />
                                <button onClick={() => setSeed(Math.floor(Math.random() * 9999999))} className="p-3 bg-white text-nano-50 rounded-xl hover:bg-white/80 active:scale-95 transition-all"><Dices size={20} /></button>
                            </div>
                        </div>
                        <div className="space-y-4">
                            <div className="flex justify-between items-center">
                                <label className="text-[10px] font-black uppercase text-white/50">Model Temperature</label>
                                <span className="bg-white text-nano-50 px-2 py-0.5 rounded-full text-[10px] font-black">{creativity}%</span>
                            </div>
                            <input 
                                type="range" min="0" max="100" value={creativity} 
                                onChange={(e) => setCreativity(parseInt(e.target.value))} 
                                className="w-full h-1.5 bg-white/10 rounded-full appearance-none accent-white cursor-pointer"
                            />
                        </div>
                    </div>
                )}
            </div>
          </section>

          <div className="pt-4 sticky bottom-8 z-30">
            <Button onClick={handleGenerate} isLoading={status === 'generating'} className="w-full !rounded-3xl !h-16 shadow-2xl shadow-black/40 hover:scale-[1.02] border-t border-white/20" icon={<Zap size={22} className="fill-nano-50" />}>
               {status === 'generating' ? 'PRODUCING MASTERPIECE' : 'START GENERATION'}
            </Button>
            {errorMsg && <p className="text-red-400 text-[10px] font-black text-center mt-3 uppercase tracking-widest animate-pulse">{errorMsg}</p>}
          </div>
        </aside>

        {/* Right Column: Creative Results */}
        <section className="w-full lg:w-2/3 flex flex-col gap-6 order-1 lg:order-2">

          <div ref={previewRef} className="w-full bg-nano-100 rounded-[2.5rem] shadow-2xl border border-white/10 overflow-hidden relative flex flex-col min-h-[500px] lg:min-h-[750px] shadow-white/5">

            {isEditing && currentImage ? (
                <ImageEditor imageSrc={currentImage.url} onSave={handleSaveEdit} onCancel={() => setIsEditing(false)} />
            ) : (
                <>
                    <header className="h-20 border-b border-white/5 flex items-center justify-between px-8 bg-nano-100/40 backdrop-blur-md z-10 shrink-0">
                      <div className="flex items-center gap-3">
                        <div className="w-2.5 h-2.5 bg-emerald-400 rounded-full animate-pulse shadow-[0_0_12px_#34d399]"></div>
                        <span className="text-[11px] font-black uppercase tracking-[0.3em] text-white">Capture Stream</span>
                      </div>

                      {status === 'success' && currentImage && (
                        <div className="flex gap-2 items-center">
                          <button onClick={() => setIsEditing(true)} className="p-3 hover:bg-white/10 rounded-2xl text-white transition-all" title="Retouch"><Edit2 size={20} /></button>
                          <button onClick={handleGenerate} className="p-3 hover:bg-white/10 rounded-2xl text-white transition-all" title="Regenerate"><RefreshCw size={20} /></button>
                          <div className="w-px h-8 bg-white/10 mx-2"></div>
                          <Button variant="secondary" onClick={handleDownload} className="!py-2.5 !px-6 !text-[10px] !rounded-2xl !bg-white !text-nano-50"><Download size={18} className="mr-2" />EXPORT</Button>
                        </div>
                      )}
                    </header>

                    <div className="flex-grow relative bg-nano-50 flex items-center justify-center p-8">
                      {status === 'idle' && (
                          <div className="text-center max-w-lg px-8">
                            <div className="w-28 h-28 bg-white/5 rounded-[3rem] border border-white/10 flex items-center justify-center mx-auto mb-10 transform -rotate-3 hover:rotate-0 transition-all duration-1000">
                              <Sparkles className="text-white/40" size={56} />
                            </div>
                            <h3 className="text-3xl font-black text-white mb-4 tracking-tighter">AI Studio Active</h3>
                            <p className="text-white/40 text-sm font-medium leading-relaxed mb-10">Select a style and enter a prompt in the sidebar to begin synthesis. The engine is ready to process your vision.</p>

                            <div className="space-y-3">
                                <p className="text-[9px] font-black uppercase tracking-[0.4em] text-white/20 mb-4">Quick laboratory starters</p>
                                <div className="flex flex-wrap justify-center gap-3">
                                   <button onClick={() => handleQuickStart("A lush cyberpunk botanical garden under a neon dome", "moody-cinematic")} className="group flex items-center gap-3 px-5 py-3 rounded-2xl bg-white/5 border border-white/10 text-white/70 hover:text-white hover:bg-white/10 transition-all">
                                      <Zap size={14} className="group-hover:text-emerald-400" />
                                      <span className="text-[10px] font-black uppercase tracking-widest">Neon Garden</span>
                                   </button>
                                   <button onClick={() => handleQuickStart("Hyper-detailed architectural macro of a glass skyscraper", "daytime-exterior")} className="group flex items-center gap-3 px-5 py-3 rounded-2xl bg-white/5 border border-white/10 text-white/70 hover:text-white hover:bg-white/10 transition-all">
                                      <Maximize size={14} className="group-hover:text-sky-400" />
                                      <span className="text-[10px] font-black uppercase tracking-widest">Crystal Tower</span>
                                   </button>
                                   <button onClick={() => handleQuickStart("A close up of a coffee bean splashing in milk, studio lighting", "minimal-studio")} className="group flex items-center gap-3 px-5 py-3 rounded-2xl bg-white/5 border border-white/10 text-white/70 hover:text-white hover:bg-white/10 transition-all">
                                      <Sun size={14} className="group-hover:text-amber-400" />
                                      <span className="text-[10px] font-black uppercase tracking-widest">Coffee splash</span>
                                   </button>
                                </div>
                            </div>
                          </div>
                      )}

                      {status === 'generating' && (
                          <div className="w-full h-full absolute inset-0 bg-nano-50 flex flex-col items-center justify-center z-20">
                            <div className="w-full max-w-sm px-12 space-y-12">
                              <div className="relative w-full aspect-square bg-gradient-to-br from-nano-100 to-nano-50 rounded-[4rem] overflow-hidden shadow-2xl border border-white/10">
                                <div className="absolute inset-0 bg-gradient-to-tr from-white/10 to-transparent animate-pulse-slow"></div>
                                <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-transparent via-white to-transparent -translate-y-full animate-[scan_2s_ease-in-out_infinite]"></div>
                              </div>
                              <div className="text-center space-y-4">
                                <p className="text-[11px] font-black tracking-[0.4em] uppercase text-white animate-pulse">Computing Light Rays</p>
                                <div className="h-1.5 w-32 bg-white/5 rounded-full mx-auto overflow-hidden">
                                  <div className="h-full bg-white w-full -translate-x-full animate-[progress_1.5s_infinite]"></div>
                                </div>
                              </div>
                            </div>
                          </div>
                      )}

                      {currentImage && (
                          <ZoomablePreview src={currentImage.url} alt={currentImage.prompt} className="max-w-full max-h-[85vh] rounded-3xl shadow-2xl" isVisible={status !== 'generating'} />
                      )}
                    </div>
                </>
            )}
          </div>

          {/* History Stream */}
          {history.length > 0 && (
            <section className="space-y-5 px-2">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3 text-[10px] font-black uppercase tracking-[0.3em] text-white/30">
                  <History size={16} /><span>Lab Sequence</span>
                </div>
                <span className="text-[9px] font-black text-white/20 uppercase tracking-widest">{history.length} / 10 saved</span>
              </div>
              <div className="flex gap-5 overflow-x-auto pb-6 pt-2 hide-scrollbar">
                {history.map((img) => (
                  <button 
                    key={img.id} 
                    onClick={() => loadFromHistory(img)} 
                    className={`relative flex-shrink-0 w-32 h-32 rounded-[2rem] overflow-hidden border-2 transition-all shadow-xl group ${currentImage?.id === img.id ? 'border-white ring-4 ring-white/10 scale-105 z-10' : 'border-transparent opacity-40 hover:opacity-100 hover:scale-105'}`}
                  >
                    <img src={img.url} alt="Sequence" className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" loading="lazy" />
                  </button>
                ))}
              </div>
            </section>
          )}
        </section>
      </main>

      <style dangerouslySetInnerHTML={{ __html: `
        @keyframes progress {
          0% { transform: translateX(-100%); }
          100% { transform: translateX(100%); }
        }
        @keyframes scan {
          0% { transform: translateY(0); }
          100% { transform: translateY(500px); }
        }
      `}} />
    </div>
  );
};

export default App;

import React from 'react';
import { ArtStyle } from '../types';
import { Check } from 'lucide-react';

// --- Button Component ---
interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'ghost';
  isLoading?: boolean;
  icon?: React.ReactNode;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  isLoading, 
  className = '', 
  icon,
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center gap-2 px-6 py-3 rounded-2xl font-black transition-all duration-200 focus:outline-none focus-visible:ring-2 focus-visible:ring-white disabled:opacity-50 disabled:cursor-not-allowed active:scale-[0.98]";

  const variants = {
    primary: "bg-white text-nano-50 hover:bg-nano-900 hover:text-white shadow-xl shadow-white/5 uppercase tracking-[0.2em] text-[11px]",
    secondary: "bg-nano-100 text-white border border-white/10 hover:bg-white/5 hover:border-white/20 shadow-sm uppercase tracking-widest text-[10px]",
    ghost: "bg-transparent text-white/50 hover:bg-white/5 hover:text-white"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${className}`} 
      disabled={isLoading || props.disabled}
      {...props}
    >
      {isLoading ? (
        <div className="flex items-center gap-3">
          <Loader2 className="animate-spin h-4 w-4" />
          <span className="tracking-widest">PROCESSING</span>
        </div>
      ) : (
        <>
          {icon && <span className="w-5 h-5">{icon}</span>}
          {children}
        </>
      )}
    </button>
  );
};

const Loader2 = ({ className }: { className?: string }) => (
  <svg className={className} xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
  </svg>
);

