        focus:outline-none ring-offset-nano-50
        bg-gradient-to-br ${style.gradient}
        ${isSelected ? 'ring-2 ring-white ring-offset-2 scale-[1.03] shadow-2xl z-10' : 'hover:scale-[1.02] opacity-80 hover:opacity-100 border border-white/5'}
      `}
    >
      <div className={`absolute inset-0 transition-opacity ${isDark ? 'bg-white/5' : 'bg-black/5'} opacity-0 group-hover:opacity-100`}></div>

      <div className="relative z-10">
        <h3 className={`font-black text-[11px] uppercase tracking-[0.2em] ${isDark ? 'text-white' : 'text-black'}`}>
          {style.name}
        </h3>
        <p className={`text-[9px] mt-1.5 font-bold leading-tight ${isDark ? 'text-white/70' : 'text-black/80'}`}>
          {style.description}
