import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Button } from './UI';
import { 
  Check, 
  X, 
  Crop, 
  Wand2, 
  ZoomIn, 
  RotateCcw, 
  Loader2, 
  Sliders, 
  Sun, 
  Contrast, 
  Lock, 
  Unlock,
  Palette,
  Droplets,
  Eye,
  Sparkles,
  Zap
} from 'lucide-react';
import { IMAGE_FILTERS, ASPECT_RATIOS } from '../constants';
import { generateImageWithNano } from '../services/geminiService';

interface ImageEditorProps {
  imageSrc: string;
  prompt: string;
  styleId: string;
  initialCreativity: number;
  onSave: (newImageSrc: string) => void;
  onCancel: () => void;
}

export const ImageEditor: React.FC<ImageEditorProps> = ({ 
  imageSrc: initialImageSrc, 
  prompt, 
  styleId, 
  initialCreativity, 
  onSave, 
  onCancel 
}) => {
  const [activeTab, setActiveTab] = useState<'filter' | 'adjust' | 'crop'>('filter');
  const [selectedFilterId, setSelectedFilterId] = useState('none');
  const [hoveredFilterId, setHoveredFilterId] = useState<string | null>(null);
  const [imageLoaded, setImageLoaded] = useState(false);
  const [currentImageSrc, setCurrentImageSrc] = useState(initialImageSrc);
  const [isRefining, setIsRefining] = useState(false);

  // Adjustment state
  const [brightness, setBrightness] = useState(100); 
  const [contrast, setContrast] = useState(100);   
  const [saturation, setSaturation] = useState(100); 
  const [hueRotate, setHueRotate] = useState(0);    
  const [creativity, setCreativity] = useState(initialCreativity);

  // Crop state
  const [zoom, setZoom] = useState(1);
  const [cropRatio, setCropRatio] = useState<string>('1:1');
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [isRatioLocked, setIsRatioLocked] = useState(true);

  // Interaction state
  const [isDragging, setIsDragging] = useState(false);
  const [isResetting, setIsResetting] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  const imageRef = useRef<HTMLImageElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const getMinZoom = useCallback(() => {
    if (!imageRef.current || !containerRef.current) return 1;
    const img = imageRef.current;
    const container = containerRef.current;

    const containerAspect = container.clientWidth / container.clientHeight;
    const imgAspect = img.naturalWidth / img.naturalHeight;

    if (imgAspect > containerAspect) {
      return 1; 
    } else {
      return containerAspect / imgAspect;
    }
  }, []);

  const constrainPan = useCallback((currentPan: { x: number; y: number }, currentZoom: number) => {
    if (isResetting || !isRatioLocked || !imageRef.current || !containerRef.current) return currentPan;

    const img = imageRef.current;
    const container = containerRef.current;

    const imgAspect = img.naturalWidth / img.naturalHeight;
    const containerAspect = container.clientWidth / container.clientHeight;

    let displayWidth, displayHeight;
    if (imgAspect > containerAspect) {
      displayHeight = container.clientHeight;
      displayWidth = container.clientHeight * imgAspect;
    } else {
      displayWidth = container.clientWidth;
      displayHeight = container.clientWidth / imgAspect;
    }

    const scaledWidth = displayWidth * currentZoom;
    const scaledHeight = displayHeight * currentZoom;

    const maxX = Math.max(0, (scaledWidth - container.clientWidth) / 2) / currentZoom;
    const maxY = Math.max(0, (scaledHeight - container.clientHeight) / 2) / currentZoom;

    return {
      x: Math.min(Math.max(currentPan.x, -maxX), maxX),
      y: Math.min(Math.max(currentPan.y, -maxY), maxY)
    };
  }, [isRatioLocked, isResetting]);

  useEffect(() => {
    if (isRatioLocked && imageLoaded && !isResetting) {
      const minZoom = getMinZoom();
      if (zoom < minZoom) {
        setZoom(minZoom);
      }
      setPan(prev => constrainPan(prev, Math.max(zoom, minZoom)));
    }
  }, [isRatioLocked, cropRatio, imageLoaded, zoom, constrainPan, getMinZoom, isResetting]);

  // Logic for real-time preview
  const effectiveFilterId = hoveredFilterId || selectedFilterId;
  const activeFilterObject = IMAGE_FILTERS.find(f => f.id === effectiveFilterId);
  const baseFilter = activeFilterObject?.filter || 'none';
  const currentFilter = `${baseFilter === 'none' ? '' : baseFilter} brightness(${brightness}%) contrast(${contrast}%) saturate(${saturation}%) hue-rotate(${hueRotate}deg)`;

  const handlePointerDown = (e: React.PointerEvent) => {
    if (isResetting) return;
    setIsDragging(true);
    setDragStart({ x: e.clientX - pan.x * zoom, y: e.clientY - pan.y * zoom });
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (isDragging) {
      const newPan = {
        x: (e.clientX - dragStart.x) / zoom,
        y: (e.clientY - dragStart.y) / zoom
      };
      setPan(constrainPan(newPan, zoom));
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    setIsDragging(false);
    (e.target as HTMLElement).releasePointerCapture(e.pointerId);
  };

  const handleResetTransform = () => {
    if (isResetting) return;
    setIsResetting(true);
    const targetZoom = isRatioLocked ? getMinZoom() : 1;
    setZoom(targetZoom);
    setPan({ x: 0, y: 0 });
    setTimeout(() => setIsResetting(false), 600);
  };

  const handleResetAdjustments = () => {
    setBrightness(100);
    setContrast(100);
    setSaturation(100);
    setHueRotate(0);
    setCreativity(initialCreativity);
    setSelectedFilterId('none');
  };

  const getCanvasData = () => {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    const img = imageRef.current;

    if (!ctx || !img) return null;

    const outputSize = 1024; // Standard reference size
    let width = outputSize;
    let height = outputSize;

    const [wRatio, hRatio] = cropRatio.split(':').map(Number);
    if (wRatio && hRatio) {
        if (wRatio > hRatio) {
            height = outputSize * (hRatio / wRatio);
        } else {
            width = outputSize * (wRatio / hRatio);
        }
    }

    canvas.width = width;
    canvas.height = height;
    ctx.fillStyle = '#000000';
    ctx.fillRect(0, 0, width, height);

    const container = containerRef.current;
    if (!container) return null;

    const scaleFactor = width / container.clientWidth;

    ctx.save();
    const saveBaseFilter = IMAGE_FILTERS.find(f => f.id === selectedFilterId)?.filter || 'none';
    ctx.filter = `${saveBaseFilter === 'none' ? '' : saveBaseFilter} brightness(${brightness}%) contrast(${contrast}%) saturate(${saturation}%) hue-rotate(${hueRotate}deg)`;

    ctx.translate(width / 2, height / 2);
    ctx.scale(zoom, zoom);
    ctx.translate(pan.x * scaleFactor, pan.y * scaleFactor);

    const imgAspect = img.naturalWidth / img.naturalHeight;
    const containerAspect = container.clientWidth / container.clientHeight;

    let drawWidth, drawHeight;
    if (imgAspect > containerAspect) {
        drawHeight = height / zoom;
        drawWidth = drawHeight * imgAspect;
    } else {
        drawWidth = width / zoom;
        drawHeight = drawWidth / imgAspect;
    }

    ctx.drawImage(img, -drawWidth / 2, -drawHeight / 2, drawWidth, drawHeight);
    ctx.restore();

    return canvas.toDataURL('image/png', 0.95);
  };

  const handleSave = () => {
    const dataUrl = getCanvasData();
    if (dataUrl) onSave(dataUrl);
  };

  const handleAIRefine = async () => {
    const referenceData = getCanvasData();
    if (!referenceData) return;

    setIsRefining(true);
    setImageLoaded(false);

    try {
      const newImage = await generateImageWithNano(
        prompt,
        styleId,
        cropRatio,
        undefined, // random seed
        creativity,
        referenceData
      );
      setCurrentImageSrc(newImage);
      // Reset canvas filters to "none" because the new image already has the look
      handleResetAdjustments();
      handleResetTransform();
    } catch (error) {
      console.error("AI Refine failed:", error);
      setImageLoaded(true);
    } finally {
      setIsRefining(false);
    }
  };

  return (
    <div className="absolute inset-0 bg-nano-50 z-50 flex flex-col h-full animate-in fade-in duration-300">
      <div className="h-14 border-b border-white/10 flex items-center justify-between px-4 bg-nano-100 shrink-0">
        <button onClick={onCancel} className="p-2 text-nano-400 hover:text-white hover:bg-white/5 rounded-lg transition-colors focus:outline-none">
          <X size={20} />
        </button>
        <span className="font-bold text-xs uppercase tracking-widest text-white">Retouch Station</span>
        <button onClick={handleSave} disabled={!imageLoaded || isRefining} className="p-2 text-white hover:bg-white/10 rounded-lg transition-colors font-medium disabled:opacity-50">
          <Check size={20} />
        </button>
      </div>

      <div className="flex-grow bg-black/40 overflow-hidden relative flex items-center justify-center p-8 select-none">
        {/* Preview Indicator */}
        {hoveredFilterId && (
          <div className="absolute top-12 left-1/2 -translate-x-1/2 z-20 flex items-center gap-2 px-4 py-2 bg-white text-nano-50 rounded-full shadow-2xl animate-in slide-in-from-top-4">
            <Eye size={12} className="animate-pulse" />
            <span className="text-[10px] font-black uppercase tracking-widest">Previewing: {activeFilterObject?.name}</span>
          </div>
        )}

        {(!imageLoaded || isRefining) && (
          <div className="absolute inset-0 z-30 flex flex-col items-center justify-center bg-nano-50/80 backdrop-blur-sm">
             <Loader2 className="w-8 h-8 text-white animate-spin mb-4" />
             {isRefining && <span className="text-[10px] font-black uppercase tracking-[0.3em] text-white animate-pulse">AI Re-imagining...</span>}
          </div>
        )}

        <div 
          ref={containerRef}
          className="relative bg-black overflow-hidden shadow-2xl ring-1 ring-white/20"
          style={{
             aspectRatio: cropRatio.replace(':', '/'),
             width: '100%',
             maxWidth: '100%',
             maxHeight: '100%',
             cursor: isDragging ? 'grabbing' : 'grab',
             touchAction: 'none'
          }}
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={handlePointerUp}
          onPointerLeave={handlePointerUp}
        >
           <img 
             ref={imageRef}
             src={currentImageSrc} 
             alt="Editing"
             loading="lazy"
             decoding="async"
             onLoad={() => setImageLoaded(true)}
             className={`absolute max-w-none max-h-none origin-center pointer-events-none transition-opacity duration-300 ${imageLoaded ? 'opacity-100' : 'opacity-0'}`}
             style={{
                top: '50%',
                left: '50%',
                transform: `translate(-50%, -50%) scale(${zoom}) translate(${pan.x}px, ${pan.y}px)`,
                filter: currentFilter,
                minWidth: '100%',
                minHeight: '100%',
                transition: isResetting 
                  ? 'transform 0.6s cubic-bezier(0.25, 1, 0.5, 1), filter 0.3s ease' 
                  : (isDragging ? 'none' : 'transform 0.1s ease-out, filter 0.25s ease-out')
             }}
             draggable={false}
           />
        </div>
      </div>

      <div className="bg-nano-100 border-t border-white/10 shrink-0 pb-safe">
        <div className="flex border-b border-white/5">
           <button onClick={() => setActiveTab('filter')} className={`flex-1 py-3 text-[10px] uppercase font-bold tracking-widest flex items-center justify-center gap-2 focus:outline-none transition-all ${activeTab === 'filter' ? 'text-white border-b-2 border-white bg-white/5' : 'text-nano-400'}`}>
             <Wand2 size={14} /> Filters
           </button>
           <button onClick={() => setActiveTab('adjust')} className={`flex-1 py-3 text-[10px] uppercase font-bold tracking-widest flex items-center justify-center gap-2 focus:outline-none transition-all ${activeTab === 'adjust' ? 'text-white border-b-2 border-white bg-white/5' : 'text-nano-400'}`}>
             <Sliders size={14} /> Adjust
           </button>
           <button onClick={() => setActiveTab('crop')} className={`flex-1 py-3 text-[10px] uppercase font-bold tracking-widest flex items-center justify-center gap-2 focus:outline-none transition-all ${activeTab === 'crop' ? 'text-white border-b-2 border-white bg-white/5' : 'text-nano-400'}`}>
             <Crop size={14} /> Crop
           </button>
        </div>

        <div className="h-52 p-4 overflow-y-auto hide-scrollbar">
           {activeTab === 'filter' && (
             <div className="flex gap-4 overflow-x-auto pb-2 hide-scrollbar h-full items-center">
                {IMAGE_FILTERS.map((f) => (
                   <button 
                     key={f.id}
                     onClick={() => setSelectedFilterId(f.id)}
                     onMouseEnter={() => setHoveredFilterId(f.id)}
                     onMouseLeave={() => setHoveredFilterId(null)}
                     className="flex flex-col items-center gap-2 shrink-0 group focus:outline-none"
                   >
                      <div className={`w-14 h-14 rounded-lg overflow-hidden border-2 transition-all ${selectedFilterId === f.id ? 'border-white ring-2 ring-white/20' : 'border-transparent group-hover:border-white/20 group-hover:scale-105'}`}>
                         <img src={currentImageSrc} alt={f.name} className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110" style={{ filter: f.filter }} />
                      </div>
                      <span className={`text-[9px] font-black uppercase tracking-wider transition-colors ${selectedFilterId === f.id || hoveredFilterId === f.id ? 'text-white' : 'text-nano-300'}`}>{f.name}</span>
                   </button>
                ))}
             </div>
           )}

           {activeTab === 'adjust' && (
             <div className="flex flex-col gap-2 h-full justify-center max-w-lg mx-auto">
                <div className="flex items-center gap-4 px-2">
                   <div className="flex items-center gap-2 w-28 shrink-0">
                      <Sun size={12} className="text-white" />
                      <span className="text-[10px] font-black uppercase tracking-widest text-white">Brightness</span>
                   </div>
                   <input type="range" min="0" max="200" step="1" value={brightness} onChange={(e) => setBrightness(parseInt(e.target.value))} className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-white" />
                   <span className="text-[10px] font-mono w-10 text-right text-nano-300">{brightness}%</span>
                </div>
                <div className="flex items-center gap-4 px-2">
                   <div className="flex items-center gap-2 w-28 shrink-0">
                      <Contrast size={12} className="text-white" />
                      <span className="text-[10px] font-black uppercase tracking-widest text-white">Contrast</span>
                   </div>
                   <input type="range" min="0" max="200" step="1" value={contrast} onChange={(e) => setContrast(parseInt(e.target.value))} className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-white" />
                   <span className="text-[10px] font-mono w-10 text-right text-nano-300">{contrast}%</span>
                </div>

                {/* Creativity Slider */}
                <div className="flex items-center gap-4 px-2 group">
                   <div className="flex items-center gap-2 w-28 shrink-0">
                      <Sparkles size={12} className="text-emerald-400 group-hover:animate-pulse" />
                      <span className="text-[10px] font-black uppercase tracking-widest text-emerald-400">Creativity</span>
                   </div>
                   <input type="range" min="0" max="100" step="1" value={creativity} onChange={(e) => setCreativity(parseInt(e.target.value))} className="w-full h-1 bg-emerald-500/20 rounded-full appearance-none cursor-pointer accent-emerald-400" />
                   <span className="text-[10px] font-mono w-10 text-right text-emerald-400">{creativity}%</span>
                </div>

                <div className="flex justify-between items-center mt-2 px-2">
                   <button onClick={handleResetAdjustments} className="text-[9px] font-black uppercase tracking-[0.2em] text-white/50 hover:text-white transition-colors">Reset</button>
                   <button 
                     onClick={handleAIRefine} 
                     disabled={isRefining}
                     className="flex items-center gap-2 px-4 py-2 bg-emerald-500 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-emerald-400 transition-all active:scale-95 disabled:opacity-50"
                   >
                      <Zap size={14} className="fill-white" />
                      AI Refine
                   </button>
                </div>
             </div>
           )}

           {activeTab === 'crop' && (
             <div className="flex flex-col gap-3 h-full justify-center max-w-lg mx-auto">
                <div className="flex items-center gap-3 px-2">
                   <ZoomIn size={14} className="text-white" />
                   <input 
                     type="range" 
                     min={isRatioLocked ? getMinZoom() : 0.5} 
                     max="4" 
                     step="0.01"
                     value={zoom}
                     onChange={(e) => {
                       const val = parseFloat(e.target.value);
                       setZoom(val);
                       setPan(prev => constrainPan(prev, val));
                     }}
                     className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-white"
                   />
                   <div className="flex gap-2 ml-2">
                     <button onClick={() => setIsRatioLocked(!isRatioLocked)} className={`p-2 rounded-lg transition-all active:scale-90 ${isRatioLocked ? 'bg-white text-nano-50' : 'text-white hover:bg-white/5'}`} title={isRatioLocked ? "Unlock Aspect Ratio" : "Lock Aspect Ratio"}>
                       {isRatioLocked ? <Lock size={14} /> : <Unlock size={14} />}
                     </button>
                     <button onClick={handleResetTransform} className="p-2 text-white hover:bg-white/5 rounded-lg transition-all active:scale-90">
                       <RotateCcw size={14} />
                     </button>
                   </div>
                </div>

                <div className="flex gap-2 overflow-x-auto pb-1 hide-scrollbar justify-center">
                   {['1:1', '16:9', '9:16', '4:3', '3:4'].map(r => (
                     <button key={r} onClick={() => { setCropRatio(r); }} className={`px-4 py-1.5 rounded-lg border text-[9px] font-black uppercase tracking-widest whitespace-nowrap transition-all ${cropRatio === r ? 'bg-white text-nano-50 border-white' : 'border-white/10 text-white hover:border-white/30'}`}>
                        {r === '1:1' ? 'Square' : r}
                     </button>
                   ))}
                </div>
             </div>
           )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { 
  Sparkles, 
  Download, 
  RefreshCw, 
  Image as ImageIcon, 
  History, 
  Zap,
  Camera,
  Maximize,
  Sliders,
  ChevronDown,
  ChevronUp,
  Undo,
  Redo,
  Upload,
  X,
  Plus,
  Edit2,
  Dices,
  Trash2,
  Wand2,
  Bookmark,
  Save,
  Clock,
  CheckCircle2,
  Eraser,
  Search,
  Loader2,
  Sun,
  Cloud,
  BookOpen,
  User,
  Trees,
  Home,
  Building2,
  Coffee,
  Shapes,
  Bug,
  Waves,
  Check
} from 'lucide-react';
import { ART_STYLES, APP_NAME, MODEL_NAME_DISPLAY, ASPECT_RATIOS } from './constants';
import { ArtStyle, GeneratedImage, GenerationStatus, GenerationPreset } from './types';
import { generateImageWithNano, detectImageStyle } from './services/geminiService';
import { Button, StyleCard, Badge } from './components/UI';
import { ImageEditor } from './components/ImageEditor';
import { ZoomablePreview } from './components/ZoomablePreview';

const App: React.FC = () => {
  // --- Basic Generation State ---
  const [prompt, setPrompt] = useState<string>('');
  const [selectedStyleId, setSelectedStyleId] = useState<string>(ART_STYLES[0].id);
  const [aspectRatio, setAspectRatio] = useState<string>('1:1');

  // --- Advanced Parameters State ---
  const [seed, setSeed] = useState<number | undefined>(undefined);
  const [creativity, setCreativity] = useState<number>(50); // 0-100
  const [showAdvanced, setShowAdvanced] = useState<boolean>(false);

  // --- Presets State ---
  const [presets, setPresets] = useState<GenerationPreset[]>([]);
  const [isSavingPreset, setIsSavingPreset] = useState(false);
  const [newPresetName, setNewPresetName] = useState('');
  const [showPresets, setShowPresets] = useState(true);
  const [lastSavedPresetId, setLastSavedPresetId] = useState<string | null>(null);
  const [editingPresetId, setEditingPresetId] = useState<string | null>(null);
  const [editNameValue, setEditNameValue] = useState('');
  const [presetSearch, setPresetSearch] = useState('');

  // --- Reference Image State ---
  const [uploadedImage, setUploadedImage] = useState<string | null>(null);
  const [isDetectingStyle, setIsDetectingStyle] = useState(false);

  // --- Generation & Gallery State ---
  const [status, setStatus] = useState<GenerationStatus>('idle');
  const [currentImage, setCurrentImage] = useState<GeneratedImage | null>(null);
  const [history, setHistory] = useState<GeneratedImage[]>([]);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  // --- UI/Editor State ---
  const [isEditing, setIsEditing] = useState(false);

  // --- Prompt History (Undo/Redo) ---
  const [promptHistory, setPromptHistory] = useState<string[]>(['']);
  const [historyIndex, setHistoryIndex] = useState(0);
  const debounceRef = useRef<any>(null);

  // --- Refs ---
  const previewRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- Persistence ---
  useEffect(() => {
    const saved = localStorage.getItem('nanoframe_presets_v4');
    if (saved) {
      try {
        setPresets(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse presets", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('nanoframe_presets_v4', JSON.stringify(presets));
  }, [presets]);

  // --- Handlers ---

  const handlePromptChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newVal = e.target.value;
    setPrompt(newVal);

    if (debounceRef.current) clearTimeout(debounceRef.current);

    debounceRef.current = setTimeout(() => {
      setPromptHistory(prev => {
        const newHistory = prev.slice(0, historyIndex + 1);
        newHistory.push(newVal);
        return newHistory;
      });
      setHistoryIndex(prev => prev + 1);
    }, 400);
  };

  const handleUndo = () => {
    if (historyIndex > 0) {
      const newIndex = historyIndex - 1;
      setHistoryIndex(newIndex);
      setPrompt(promptHistory[newIndex]);
    }
  };

  const handleRedo = () => {
    if (historyIndex < promptHistory.length - 1) {
      const newIndex = historyIndex + 1;
      setHistoryIndex(newIndex);
      setPrompt(promptHistory[newIndex]);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = async (event) => {
        if (event.target?.result) {
          const base64 = event.target.result as string;
          setUploadedImage(base64);
          setIsDetectingStyle(true);
          try {
            const detectedStyleId = await detectImageStyle(base64);
            if (detectedStyleId) {
                const cleanId = detectedStyleId.trim();
                const matchedStyle = ART_STYLES.find(s => cleanId.includes(s.id));
                if (matchedStyle) setSelectedStyleId(matchedStyle.id);
            }
          } catch (err) {
            console.warn("Style detection failed", err);
          } finally {
            setIsDetectingStyle(false);
          }
        }
      };
      reader.readAsDataURL(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const clearUploadedImage = () => setUploadedImage(null);

  const handleSavePreset = () => {
    if (!newPresetName.trim()) return;

    const newPreset: GenerationPreset = {
      id: crypto.randomUUID(),
      name: newPresetName,
      prompt: prompt,
      styleId: selectedStyleId,
      aspectRatio: aspectRatio,
      seed: seed,
      creativity: creativity,
      timestamp: Date.now(),
      referenceImage: uploadedImage
    };

    setPresets(prev => [newPreset, ...prev]);
    setLastSavedPresetId(newPreset.id);
    setNewPresetName('');
    setIsSavingPreset(false);

    // Clear last saved selection highlight after a delay
    setTimeout(() => setLastSavedPresetId(null), 2000);
  };

  const handleUpdatePresetName = (id: string) => {
    if (!editNameValue.trim()) {
      setEditingPresetId(null);
      return;
    }
    setPresets(prev => prev.map(p => p.id === id ? { ...p, name: editNameValue } : p));
    setEditingPresetId(null);
  };

  const loadPreset = (p: GenerationPreset) => {
    setPrompt(p.prompt);
    setSelectedStyleId(p.styleId);
    setAspectRatio(p.aspectRatio);
    setSeed(p.seed);
    setCreativity(p.creativity);
    setUploadedImage(p.referenceImage || null);
    setLastSavedPresetId(p.id);

    setPromptHistory(prev => {
      const newHistory = prev.slice(0, historyIndex + 1);
      newHistory.push(p.prompt);
      return newHistory;
    });
    setHistoryIndex(prev => prev + 1);

    // Visual confirmation
    setTimeout(() => setLastSavedPresetId(null), 1500);
  };

  const deletePreset = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm("Delete this preset from your library?")) {
      setPresets(prev => prev.filter(p => p.id !== id));
      if (lastSavedPresetId === id) setLastSavedPresetId(null);
    }
  };

  const resetWorkspace = () => {
    if (confirm("Reset current laboratory settings? This will clear your prompt and image.")) {
      setPrompt('');
      setSelectedStyleId(ART_STYLES[0].id);
      setAspectRatio('1:1');
      setSeed(undefined);
      setCreativity(50);
      setUploadedImage(null);
      setPromptHistory(['']);
      setHistoryIndex(0);
      setStatus('idle');
      setCurrentImage(null);
    }
  };

  const handleQuickStart = (p: string, style?: string) => {
    setPrompt(p);
    if (style) setSelectedStyleId(style);
    setTimeout(() => {
        handleGenerate();
    }, 100);
  };

  const handleGenerate = async () => {
    const currentPrompt = prompt.trim();
    if (!currentPrompt && !uploadedImage) {
        setErrorMsg("Please enter a text prompt or upload an image to start.");
        setStatus('error');
        return;
    }

    setStatus('generating');
    setErrorMsg(null);
    setCurrentImage(null);
    setIsEditing(false);

    if (window.innerWidth < 768) previewRef.current?.scrollIntoView({ behavior: 'smooth' });

    try {
      const base64Image = await generateImageWithNano(
          currentPrompt, 
          selectedStyleId, 
          aspectRatio, 
          seed, 
          creativity, 
          uploadedImage
      );

      const newImage: GeneratedImage = {
        id: crypto.randomUUID(),
        url: base64Image,
        prompt: currentPrompt || 'Image Variation',
        styleId: selectedStyleId,
        aspectRatio: aspectRatio,
        seed: seed,
        creativity: creativity,
        referenceImage: uploadedImage,
        timestamp: Date.now()
      };

      setCurrentImage(newImage);
      setHistory(prev => [newImage, ...prev].slice(0, 10));
      setStatus('success');
    } catch (error) {
      console.error(error);
      setStatus('error');
      setErrorMsg("Failed to generate. Please try again.");
    }
  };

  const handleDownload = () => {
    if (!currentImage) return;
    const link = document.createElement('a');
    link.href = currentImage.url;
    link.download = `${APP_NAME.toLowerCase()}-${currentImage.id.slice(0, 8)}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const loadFromHistory = (img: GeneratedImage) => {
    setCurrentImage(img);
    setPrompt(img.prompt);
    setPromptHistory(prev => [...prev.slice(0, historyIndex + 1), img.prompt]);
    setHistoryIndex(prev => prev + 1);
    setSelectedStyleId(img.styleId);
    setAspectRatio(img.aspectRatio || '1:1');
    setSeed(img.seed);
    setCreativity(img.creativity ?? 50);
    setUploadedImage(img.referenceImage || null);
    setStatus('success');
    setIsEditing(false);
    if (window.innerWidth < 768) previewRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleSaveEdit = (newImageSrc: string) => {
     if (!currentImage) return;
     const newImage: GeneratedImage = {
        ...currentImage,
        id: crypto.randomUUID(),
        url: newImageSrc,
        timestamp: Date.now()
     };
     setCurrentImage(newImage);
     setHistory(prev => [newImage, ...prev].slice(0, 10));
     setIsEditing(false);
  };

  const filteredPresets = presets.filter(p => 
    p.name.toLowerCase().includes(presetSearch.toLowerCase()) ||
    p.prompt.toLowerCase().includes(presetSearch.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-nano-50 text-white selection:bg-white selection:text-nano-50 flex flex-col font-sans">

      <header className="bg-nano-100/80 backdrop-blur-xl sticky top-0 z-50 border-b border-white/10 shadow-lg">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 bg-white rounded-xl flex items-center justify-center text-nano-50 shadow-xl shadow-white/5">
              <Camera size={20} />
            </div>
            <h1 className="text-xl font-extrabold tracking-tight text-white">{APP_NAME}</h1>
