  Sparkles, 
  Download, 
  RefreshCw, 
  Image as ImageIcon, 
  History, 
  Zap,
  Camera,
  Maximize,
  Sliders,
  ChevronDown,
  ChevronUp,
  Undo,
  Redo,
  Upload,
  X,
  Plus,
  Edit2,
  Dices,
  Trash2,
  Wand2,
  Bookmark,
  Save,
  Clock,
  CheckCircle2,
  Eraser,
  Search,
  Loader2,
  Sun,
  Cloud,
  BookOpen,
  User,
  Trees,
  Home,
  Building2,
  Coffee,
  Shapes,
  Bug,
