                                   <button onClick={() => handleQuickStart("Hyper-detailed architectural macro of a glass skyscraper", "daytime-exterior")} className="group flex items-center gap-3 px-4 py-3 rounded-2xl bg-white/5 border border-white/10 text-white/70 hover:text-white hover:bg-white/10 transition-all text-left">
                                      <Building2 size={14} className="group-hover:text-sky-400 shrink-0" />
                                      <span className="text-[9px] font-black uppercase tracking-widest truncate">Crystal Tower</span>
                                   </button>
                                   <button onClick={() => handleQuickStart("A close up of a coffee bean splashing in milk, studio lighting", "minimal-studio")} className="group flex items-center gap-3 px-4 py-3 rounded-2xl bg-white/5 border border-white/10 text-white/70 hover:text-white hover:bg-white/10 transition-all text-left">
                                      <Coffee size={14} className="group-hover:text-amber-400 shrink-0" />
                                      <span className="text-[9px] font-black uppercase tracking-widest truncate">Coffee splash</span>
