                                   <button onClick={() => handleQuickStart("Rainy cyberpunk street at night with glowing signs and puddles", "night-exterior")} className="group flex items-center gap-3 px-4 py-3 rounded-2xl bg-white/5 border border-white/10 text-white/70 hover:text-white hover:bg-white/10 transition-all text-left">
                                      <Cloud size={14} className="group-hover:text-blue-400 shrink-0" />
                                      <span className="text-[9px] font-black uppercase tracking-widest truncate">Midnight Rain</span>
