import React from 'react';
import { ArtStyle } from '../types';
import { Check, Sparkles } from 'lucide-react';

// --- Button Component ---
interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'ghost';
  isLoading?: boolean;
  icon?: React.ReactNode;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  isLoading, 
  className = '', 
  icon,
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center gap-2 px-6 py-3 rounded-2xl font-black transition-all duration-200 focus:outline-none focus-visible:ring-2 focus-visible:ring-white disabled:opacity-50 disabled:cursor-not-allowed active:scale-[0.98]";

  const variants = {
    primary: "bg-white text-nano-50 hover:bg-nano-900 hover:text-white shadow-xl shadow-white/5 uppercase tracking-[0.2em] text-[11px]",
    secondary: "bg-nano-100 text-white border border-white/10 hover:bg-white/5 hover:border-white/20 shadow-sm uppercase tracking-widest text-[10px]",
    ghost: "bg-transparent text-white/50 hover:bg-white/5 hover:text-white"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${className}`} 
      disabled={isLoading || props.disabled}
      {...props}
    >
      {isLoading ? (
        <div className="flex items-center gap-3">
          <Loader2 className="animate-spin h-4 w-4" />
          <span className="tracking-widest">PROCESSING</span>
        </div>
      ) : (
        <>
          {icon && <span className="w-5 h-5">{icon}</span>}
          {children}
        </>
      )}
    </button>
  );
};

const Loader2 = ({ className }: { className?: string }) => (
  <svg className={className} xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
  </svg>
);

// --- Style Card Component ---
interface StyleCardProps {
  style: ArtStyle;
  isSelected: boolean;
  isAutoSelected?: boolean;
  onClick: () => void;
}

export const StyleCard: React.FC<StyleCardProps> = ({ style, isSelected, isAutoSelected, onClick }) => {
  const isDark = style.id.includes('night') || style.id.includes('moody');

  return (
    <button 
      type="button"
      onClick={onClick}
      className={`
        text-left w-full relative overflow-hidden cursor-pointer group rounded-2xl p-4 h-32 flex flex-col justify-end transition-all duration-500
        focus:outline-none ring-offset-nano-50
        bg-gradient-to-br ${style.gradient}
        ${isSelected ? 'ring-2 ring-white ring-offset-2 scale-[1.03] shadow-2xl z-10' : 'hover:scale-[1.02] opacity-80 hover:opacity-100 border border-white/5'}
        ${isAutoSelected ? 'ring-4 ring-emerald-400 ring-offset-4' : ''}
      `}
    >
      <div className={`absolute inset-0 transition-opacity ${isDark ? 'bg-white/5' : 'bg-black/5'} opacity-0 group-hover:opacity-100`}></div>

      {/* Auto-selection highlight effect */}
      {isAutoSelected && (
        <div className="absolute inset-0 bg-emerald-400/20 z-0 animate-pulse"></div>
      )}

      <div className="relative z-10">
        <h3 className={`font-black text-[11px] uppercase tracking-[0.2em] flex items-center gap-2 ${isDark ? 'text-white' : 'text-black'}`}>
          {style.name}
          {isAutoSelected && <Sparkles size={12} className="text-emerald-400 fill-emerald-400 animate-bounce" />}
        </h3>
        <p className={`text-[9px] mt-1.5 font-bold leading-tight ${isDark ? 'text-white/70' : 'text-black/80'}`}>
          {style.description}
        </p>
      </div>

      {isSelected && (
        <div className={`absolute top-3 right-3 rounded-full p-1.5 border backdrop-blur-md shadow-xl ${isDark ? 'bg-white/20 border-white/30' : 'bg-black/10 border-black/20'} ${isAutoSelected ? 'scale-125 bg-emerald-500 border-emerald-400' : ''}`}>
           <Check size={14} className={isDark || isAutoSelected ? 'text-white' : 'text-black'} strokeWidth={3} />
        </div>
      )}
    </button>
  );
};

