import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Button } from './UI';
import { 
  Check, 
  X, 
  Crop, 
  Wand2, 
  ZoomIn, 
  RotateCcw, 
  Loader2, 
  Sliders, 
  Sun, 
  Contrast, 
  Lock, 
  Unlock,
  Palette,
  Droplets,
  Eye,
  Sparkles,
  Zap,
  Undo,
  Redo
} from 'lucide-react';
import { IMAGE_FILTERS, ASPECT_RATIOS } from '../constants';
import { generateImageWithNano } from '../services/geminiService';

interface ImageEditorProps {
  imageSrc: string;
  prompt: string;
  styleId: string;
  initialCreativity: number;
  onSave: (newImageSrc: string) => void;
  onCancel: () => void;
}

// Define the shape of our history state
type EditorState = {
  imageSrc: string;
  filterId: string;
  adjustments: {
    brightness: number;
    contrast: number;
    saturation: number;
    hueRotate: number;
    creativity: number;
  };
  transform: {
    zoom: number;
    cropRatio: string;
    pan: { x: number; y: number };
    isRatioLocked: boolean;
  };
};

export const ImageEditor: React.FC<ImageEditorProps> = ({ 
  imageSrc: initialImageSrc, 
  prompt, 
  styleId, 
  initialCreativity, 
  onSave, 
  onCancel 
}) => {
  const [activeTab, setActiveTab] = useState<'filter' | 'adjust' | 'crop'>('filter');
  const [selectedFilterId, setSelectedFilterId] = useState('none');
  const [hoveredFilterId, setHoveredFilterId] = useState<string | null>(null);
  const [imageLoaded, setImageLoaded] = useState(false);
  const [currentImageSrc, setCurrentImageSrc] = useState(initialImageSrc);
  const [isRefining, setIsRefining] = useState(false);

  // Adjustment state
  const [brightness, setBrightness] = useState(100); 
  const [contrast, setContrast] = useState(100);   
  const [saturation, setSaturation] = useState(100); 
  const [hueRotate, setHueRotate] = useState(0);    
  const [creativity, setCreativity] = useState(initialCreativity);

  // Crop state
  const [zoom, setZoom] = useState(1);
  const [cropRatio, setCropRatio] = useState<string>('1:1');
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [isRatioLocked, setIsRatioLocked] = useState(true);

  // Interaction state
  const [isDragging, setIsDragging] = useState(false);
  const [isResetting, setIsResetting] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  // History state
  const [history, setHistory] = useState<EditorState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  const imageRef = useRef<HTMLImageElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // --- History Helpers ---

  // Construct the current state object from active variables
  const getCurrentState = useCallback((overrides: Partial<EditorState> = {}): EditorState => ({
    imageSrc: currentImageSrc,
    filterId: selectedFilterId,
    adjustments: { brightness, contrast, saturation, hueRotate, creativity },
    transform: { zoom, cropRatio, pan, isRatioLocked },
    ...overrides
  }), [currentImageSrc, selectedFilterId, brightness, contrast, saturation, hueRotate, creativity, zoom, cropRatio, pan, isRatioLocked]);

  // Initialize history on mount
  useEffect(() => {
    if (history.length === 0) {
      const initialState = getCurrentState();
      setHistory([initialState]);
      setHistoryIndex(0);
    }
  }, []); // Run once on mount

  const pushToHistory = (newState: EditorState) => {
    // Avoid duplicates if the state hasn't effectively changed
    if (historyIndex >= 0) {
      const currentState = history[historyIndex];
      if (JSON.stringify(currentState) === JSON.stringify(newState)) return;
    }

    const newHistory = history.slice(0, historyIndex + 1);
    newHistory.push(newState);
    setHistory(newHistory);
    setHistoryIndex(newHistory.length - 1);
  };

  const handleUndo = () => {
    if (historyIndex > 0) {
      const newIndex = historyIndex - 1;
      setHistoryIndex(newIndex);
      restoreState(history[newIndex]);
    }
  };

  const handleRedo = () => {
    if (historyIndex < history.length - 1) {
      const newIndex = historyIndex + 1;
      setHistoryIndex(newIndex);
      restoreState(history[newIndex]);
    }
  };

  const restoreState = (state: EditorState) => {
    setCurrentImageSrc(state.imageSrc);
    setSelectedFilterId(state.filterId);
    setBrightness(state.adjustments.brightness);
    setContrast(state.adjustments.contrast);
    setSaturation(state.adjustments.saturation);
    setHueRotate(state.adjustments.hueRotate);
    setCreativity(state.adjustments.creativity);
    setZoom(state.transform.zoom);
    setCropRatio(state.transform.cropRatio);
    setPan(state.transform.pan);
    setIsRatioLocked(state.transform.isRatioLocked);
  };

  // --- Logic ---

  const getMinZoom = useCallback(() => {
    if (!imageRef.current || !containerRef.current) return 1;
    const img = imageRef.current;
    const container = containerRef.current;

    const containerAspect = container.clientWidth / container.clientHeight;
    const imgAspect = img.naturalWidth / img.naturalHeight;

    if (imgAspect > containerAspect) {
      return 1; 
    } else {
      return containerAspect / imgAspect;
    }
  }, []);

  const constrainPan = useCallback((currentPan: { x: number; y: number }, currentZoom: number) => {
    if (isResetting || !isRatioLocked || !imageRef.current || !containerRef.current) return currentPan;

    const img = imageRef.current;
    const container = containerRef.current;

    const imgAspect = img.naturalWidth / img.naturalHeight;
    const containerAspect = container.clientWidth / container.clientHeight;

    let displayWidth, displayHeight;
    if (imgAspect > containerAspect) {
      displayHeight = container.clientHeight;
      displayWidth = container.clientHeight * imgAspect;
    } else {
      displayWidth = container.clientWidth;
      displayHeight = container.clientWidth / imgAspect;
    }

    const scaledWidth = displayWidth * currentZoom;
    const scaledHeight = displayHeight * currentZoom;

    const maxX = Math.max(0, (scaledWidth - container.clientWidth) / 2) / currentZoom;
    const maxY = Math.max(0, (scaledHeight - container.clientHeight) / 2) / currentZoom;

    return {
      x: Math.min(Math.max(currentPan.x, -maxX), maxX),
      y: Math.min(Math.max(currentPan.y, -maxY), maxY)
    };
  }, [isRatioLocked, isResetting]);

  useEffect(() => {
    if (isRatioLocked && imageLoaded && !isResetting) {
      const minZoom = getMinZoom();
      if (zoom < minZoom) {
        setZoom(minZoom);
      }
      setPan(prev => constrainPan(prev, Math.max(zoom, minZoom)));
    }
  }, [isRatioLocked, cropRatio, imageLoaded, zoom, constrainPan, getMinZoom, isResetting]);

  // Logic for real-time preview
  const effectiveFilterId = hoveredFilterId || selectedFilterId;
  const activeFilterObject = IMAGE_FILTERS.find(f => f.id === effectiveFilterId);
  const baseFilter = activeFilterObject?.filter || 'none';
  const currentFilter = `${baseFilter === 'none' ? '' : baseFilter} brightness(${brightness}%) contrast(${contrast}%) saturate(${saturation}%) hue-rotate(${hueRotate}deg)`;

  const handlePointerDown = (e: React.PointerEvent) => {
    if (isResetting) return;
    setIsDragging(true);
    setDragStart({ x: e.clientX - pan.x * zoom, y: e.clientY - pan.y * zoom });
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (isDragging) {
      const newPan = {
        x: (e.clientX - dragStart.x) / zoom,
        y: (e.clientY - dragStart.y) / zoom
      };
      setPan(constrainPan(newPan, zoom));
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (isDragging) {
      // Save history on drag end
      pushToHistory(getCurrentState());
    }
    setIsDragging(false);
    (e.target as HTMLElement).releasePointerCapture(e.pointerId);
  };

  const handleResetTransform = () => {
    if (isResetting) return;
    setIsResetting(true);
    const targetZoom = isRatioLocked ? getMinZoom() : 1;
    const targetPan = { x: 0, y: 0 };
    setZoom(targetZoom);
    setPan(targetPan);

    // Save history with the reset values
    pushToHistory({
        ...getCurrentState(),
        transform: {
            zoom: targetZoom,
            pan: targetPan,
            cropRatio,
            isRatioLocked
        }
    });

    setTimeout(() => setIsResetting(false), 600);
  };

  const handleResetAdjustments = () => {
    setBrightness(100);
    setContrast(100);
    setSaturation(100);
    setHueRotate(0);
    setCreativity(initialCreativity);
    setSelectedFilterId('none');

    // Save history
    pushToHistory({
        ...getCurrentState(),
        filterId: 'none',
        adjustments: { brightness: 100, contrast: 100, saturation: 100, hueRotate: 0, creativity: initialCreativity }
    });
  };

  const getCanvasData = () => {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    const img = imageRef.current;

    if (!ctx || !img) return null;

    const outputSize = 1024; // Standard reference size
    let width = outputSize;
    let height = outputSize;

    const [wRatio, hRatio] = cropRatio.split(':').map(Number);
    if (wRatio && hRatio) {
        if (wRatio > hRatio) {
            height = outputSize * (hRatio / wRatio);
        } else {
            width = outputSize * (wRatio / hRatio);
        }
    }

    canvas.width = width;
    canvas.height = height;
    ctx.fillStyle = '#000000';
    ctx.fillRect(0, 0, width, height);

    const container = containerRef.current;
    if (!container) return null;

    const scaleFactor = width / container.clientWidth;

    ctx.save();
    const saveBaseFilter = IMAGE_FILTERS.find(f => f.id === selectedFilterId)?.filter || 'none';
    ctx.filter = `${saveBaseFilter === 'none' ? '' : saveBaseFilter} brightness(${brightness}%) contrast(${contrast}%) saturate(${saturation}%) hue-rotate(${hueRotate}deg)`;

    ctx.translate(width / 2, height / 2);
    ctx.scale(zoom, zoom);
    ctx.translate(pan.x * scaleFactor, pan.y * scaleFactor);

    const imgAspect = img.naturalWidth / img.naturalHeight;
    const containerAspect = container.clientWidth / container.clientHeight;

    let drawWidth, drawHeight;
    if (imgAspect > containerAspect) {
        drawHeight = height / zoom;
        drawWidth = drawHeight * imgAspect;
    } else {
        drawWidth = width / zoom;
        drawHeight = drawWidth / imgAspect;
    }

    ctx.drawImage(img, -drawWidth / 2, -drawHeight / 2, drawWidth, drawHeight);
    ctx.restore();

    return canvas.toDataURL('image/png', 0.95);
  };

  const handleSave = () => {
    const dataUrl = getCanvasData();
    if (dataUrl) onSave(dataUrl);
  };

  const handleAIRefine = async () => {
    const referenceData = getCanvasData();
    if (!referenceData) return;

    setIsRefining(true);
    setImageLoaded(false);

    try {
      const newImage = await generateImageWithNano(
        prompt,
        styleId,
        cropRatio,
        undefined, // random seed
        creativity,
        referenceData
      );
      setCurrentImageSrc(newImage);
      // Reset canvas filters to "none" because the new image already has the look
      // And manually save the history for this major event

      setBrightness(100);
      setContrast(100);
      setSaturation(100);
      setHueRotate(0);
      setCreativity(initialCreativity);
      setSelectedFilterId('none');
      setZoom(isRatioLocked ? getMinZoom() : 1);
      setPan({ x: 0, y: 0 });

      // Add to history with new image and reset values
      const newState: EditorState = {
         imageSrc: newImage,
         filterId: 'none',
         adjustments: { brightness: 100, contrast: 100, saturation: 100, hueRotate: 0, creativity: initialCreativity },
         transform: { 
             zoom: isRatioLocked ? getMinZoom() : 1, 
             cropRatio, 
             pan: { x: 0, y: 0 }, 
             isRatioLocked 
         }
      };

      // We push manually because we want to bundle all changes
      setHistory(prev => {
         const newHistory = prev.slice(0, historyIndex + 1);
         return [...newHistory, newState];
      });
      setHistoryIndex(prev => prev + 1);

    } catch (error) {
      console.error("AI Refine failed:", error);
      setImageLoaded(true);
    } finally {
      setIsRefining(false);
    }
  };

  // Wrapper for filter change
  const handleFilterSelect = (id: string) => {
    setSelectedFilterId(id);
    pushToHistory({ ...getCurrentState(), filterId: id });
  };

  // Wrapper for crop ratio
  const handleRatioSelect = (ratio: string) => {
    setCropRatio(ratio);
    pushToHistory({ ...getCurrentState(), transform: { ...getCurrentState().transform, cropRatio: ratio } });
  };

  // Wrapper for lock toggle
  const handleLockToggle = () => {
    const newLock = !isRatioLocked;
    setIsRatioLocked(newLock);
    pushToHistory({ ...getCurrentState(), transform: { ...getCurrentState().transform, isRatioLocked: newLock } });
  };

  return (
    <div className="fixed inset-0 z-[100] bg-nano-50/90 backdrop-blur-md flex flex-col h-full animate-in fade-in duration-300">
      <div className="h-14 border-b border-white/10 flex items-center justify-between px-4 bg-nano-100 shrink-0 shadow-xl">
        <div className="flex items-center gap-2">
            <button onClick={onCancel} className="p-2 text-nano-400 hover:text-white hover:bg-white/5 rounded-lg transition-colors focus:outline-none">
            <X size={20} />
            </button>
            <div className="h-6 w-px bg-white/10 mx-2 hidden sm:block"></div>
            <button onClick={handleUndo} disabled={historyIndex <= 0} className="p-2 text-nano-400 hover:text-white hover:bg-white/5 rounded-lg transition-colors focus:outline-none disabled:opacity-30 disabled:hover:bg-transparent">
               <Undo size={18} />
            </button>
            <button onClick={handleRedo} disabled={historyIndex >= history.length - 1} className="p-2 text-nano-400 hover:text-white hover:bg-white/5 rounded-lg transition-colors focus:outline-none disabled:opacity-30 disabled:hover:bg-transparent">
               <Redo size={18} />
            </button>
        </div>

        <span className="font-bold text-xs uppercase tracking-widest text-white hidden sm:block">Retouch Station</span>

        <div className="flex items-center gap-2">
            <button 
                onClick={handleAIRefine} 
                disabled={!imageLoaded || isRefining} 
                className="flex items-center gap-2 px-3 py-1.5 text-emerald-400 hover:text-white hover:bg-white/10 rounded-lg transition-colors font-bold text-[10px] uppercase tracking-widest disabled:opacity-50"
                title="Generate new variation based on current view"
            >
                <Zap size={16} className={isRefining ? "animate-pulse" : ""} />
                <span className="hidden sm:block">Refine</span>
            </button>
            <div className="h-6 w-px bg-white/10 mx-1"></div>
            <button onClick={handleSave} disabled={!imageLoaded || isRefining} className="p-2 text-white hover:bg-white/10 rounded-lg transition-colors font-medium disabled:opacity-50">
                <Check size={20} />
            </button>
        </div>
      </div>

      <div className="flex-grow overflow-hidden relative flex items-center justify-center p-8 select-none">
        {/* Preview Indicator */}
        {hoveredFilterId && (
          <div className="absolute top-12 left-1/2 -translate-x-1/2 z-20 flex items-center gap-2 px-4 py-2 bg-white text-nano-50 rounded-full shadow-2xl animate-in slide-in-from-top-4">
            <Eye size={12} className="animate-pulse" />
            <span className="text-[10px] font-black uppercase tracking-widest">Previewing: {activeFilterObject?.name}</span>
          </div>
        )}

        {(!imageLoaded || isRefining) && (
          <div className="absolute inset-0 z-30 flex flex-col items-center justify-center bg-nano-50/80 backdrop-blur-sm">
             <Loader2 className="w-8 h-8 text-white animate-spin mb-4" />
             {isRefining && <span className="text-[10px] font-black uppercase tracking-[0.3em] text-white animate-pulse">AI Re-imagining...</span>}
          </div>
        )}

        <div 
          ref={containerRef}
          className="relative bg-black overflow-hidden shadow-2xl ring-1 ring-white/20"
          style={{
             aspectRatio: cropRatio.replace(':', '/'),
             width: '100%',
             maxWidth: '100%',
             maxHeight: '100%',
             cursor: isDragging ? 'grabbing' : 'grab',
             touchAction: 'none'
          }}
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={handlePointerUp}
          onPointerLeave={handlePointerUp}
        >
           <img 
             ref={imageRef}
             src={currentImageSrc} 
             alt="Editing"
             loading="lazy"
             decoding="async"
             onLoad={() => setImageLoaded(true)}
             className={`absolute max-w-none max-h-none origin-center pointer-events-none transition-opacity duration-300 ${imageLoaded ? 'opacity-100' : 'opacity-0'}`}
             style={{
                top: '50%',
                left: '50%',
                transform: `translate(-50%, -50%) scale(${zoom}) translate(${pan.x}px, ${pan.y}px)`,
                filter: currentFilter,
                minWidth: '100%',
                minHeight: '100%',
                transition: isResetting 
                  ? 'transform 0.6s cubic-bezier(0.25, 1, 0.5, 1), filter 0.3s ease' 
                  : (isDragging ? 'none' : 'transform 0.1s ease-out, filter 0.25s ease-out')
             }}
             draggable={false}
           />
        </div>
      </div>

      <div className="bg-nano-100 border-t border-white/10 shrink-0 pb-safe shadow-[0_-10px_40px_rgba(0,0,0,0.5)]">
        <div className="flex border-b border-white/5">
           <button onClick={() => setActiveTab('filter')} className={`flex-1 py-3 text-[10px] uppercase font-bold tracking-widest flex items-center justify-center gap-2 focus:outline-none transition-all ${activeTab === 'filter' ? 'text-white border-b-2 border-white bg-white/5' : 'text-nano-400'}`}>
             <Wand2 size={14} /> Filters
           </button>
           <button onClick={() => setActiveTab('adjust')} className={`flex-1 py-3 text-[10px] uppercase font-bold tracking-widest flex items-center justify-center gap-2 focus:outline-none transition-all ${activeTab === 'adjust' ? 'text-white border-b-2 border-white bg-white/5' : 'text-nano-400'}`}>
             <Sliders size={14} /> Adjust
           </button>
           <button onClick={() => setActiveTab('crop')} className={`flex-1 py-3 text-[10px] uppercase font-bold tracking-widest flex items-center justify-center gap-2 focus:outline-none transition-all ${activeTab === 'crop' ? 'text-white border-b-2 border-white bg-white/5' : 'text-nano-400'}`}>
             <Crop size={14} /> Crop
           </button>
        </div>

        <div className="h-52 p-4 overflow-y-auto hide-scrollbar">
           {activeTab === 'filter' && (
             <div className="flex gap-4 overflow-x-auto pb-2 hide-scrollbar h-full items-center">
                {IMAGE_FILTERS.map((f) => (
                   <button 
                     key={f.id}
                     onClick={() => handleFilterSelect(f.id)}
                     onMouseEnter={() => setHoveredFilterId(f.id)}
                     onMouseLeave={() => setHoveredFilterId(null)}
                     className="flex flex-col items-center gap-2 shrink-0 group focus:outline-none"
                   >
                      <div className={`w-14 h-14 rounded-lg overflow-hidden border-2 transition-all ${selectedFilterId === f.id ? 'border-white ring-2 ring-white/20' : 'border-transparent group-hover:border-white/20 group-hover:scale-105'}`}>
                         <img src={currentImageSrc} alt={f.name} className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110" style={{ filter: f.filter }} />
                      </div>
                      <span className={`text-[9px] font-black uppercase tracking-wider transition-colors ${selectedFilterId === f.id || hoveredFilterId === f.id ? 'text-white' : 'text-nano-300'}`}>{f.name}</span>
                   </button>
                ))}
             </div>
           )}

           {activeTab === 'adjust' && (
             <div className="flex flex-col gap-2 h-full justify-center max-w-lg mx-auto">
                <div className="flex items-center gap-4 px-2">
                   <div className="flex items-center gap-2 w-28 shrink-0">
                      <Sun size={12} className="text-white" />
                      <span className="text-[10px] font-black uppercase tracking-widest text-white">Brightness</span>
                   </div>
                   <input 
                     type="range" min="0" max="200" step="1" 
                     value={brightness} 
                     onChange={(e) => setBrightness(parseInt(e.target.value))} 
                     onPointerUp={() => pushToHistory(getCurrentState())}
                     className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-white" 
                   />
                   <span className="text-[10px] font-mono w-10 text-right text-nano-300">{brightness}%</span>
                </div>
                <div className="flex items-center gap-4 px-2">
                   <div className="flex items-center gap-2 w-28 shrink-0">
                      <Contrast size={12} className="text-white" />
                      <span className="text-[10px] font-black uppercase tracking-widest text-white">Contrast</span>
                   </div>
                   <input 
                     type="range" min="0" max="200" step="1" 
                     value={contrast} 
                     onChange={(e) => setContrast(parseInt(e.target.value))} 
                     onPointerUp={() => pushToHistory(getCurrentState())}
                     className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-white" 
                   />
                   <span className="text-[10px] font-mono w-10 text-right text-nano-300">{contrast}%</span>
                </div>

                {/* Creativity Slider */}
                <div className="flex items-center gap-4 px-2 group">
                   <div className="flex items-center gap-2 w-28 shrink-0">
                      <Sparkles size={12} className="text-emerald-400 group-hover:animate-pulse" />
                      <span className="text-[10px] font-black uppercase tracking-widest text-emerald-400">Creativity</span>
                   </div>
                   <input 
                     type="range" min="0" max="100" step="1" 
                     value={creativity} 
                     onChange={(e) => setCreativity(parseInt(e.target.value))} 
                     onPointerUp={() => pushToHistory(getCurrentState())}
                     className="w-full h-1 bg-emerald-500/20 rounded-full appearance-none cursor-pointer accent-emerald-400" 
                   />
                   <span className="text-[10px] font-mono w-10 text-right text-emerald-400">{creativity}%</span>
                </div>

                <div className="flex justify-between items-center mt-2 px-2">
                   <button onClick={handleResetAdjustments} className="text-[9px] font-black uppercase tracking-[0.2em] text-white/50 hover:text-white transition-colors">Reset</button>
                   {/* Removed duplicate AI Refine button from here as it's now in the header */}
                </div>
             </div>
           )}

           {activeTab === 'crop' && (
             <div className="flex flex-col gap-3 h-full justify-center max-w-lg mx-auto">
                <div className="flex items-center gap-3 px-2">
                   <ZoomIn size={14} className="text-white" />
                   <input 
                     type="range" 
                     min={isRatioLocked ? getMinZoom() : 0.5} 
                     max="4" 
                     step="0.01"
                     value={zoom}
                     onChange={(e) => {
                       const val = parseFloat(e.target.value);
                       setZoom(val);
                       setPan(prev => constrainPan(prev, val));
                     }}
                     onPointerUp={() => pushToHistory(getCurrentState())}
                     className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-white"
                   />
                   <div className="flex gap-2 ml-2">
                     <button onClick={handleLockToggle} className={`p-2 rounded-lg transition-all active:scale-90 ${isRatioLocked ? 'bg-white text-nano-50' : 'text-white hover:bg-white/5'}`} title={isRatioLocked ? "Unlock Aspect Ratio" : "Lock Aspect Ratio"}>
                       {isRatioLocked ? <Lock size={14} /> : <Unlock size={14} />}
                     </button>
                     <button onClick={handleResetTransform} className="p-2 text-white hover:bg-white/5 rounded-lg transition-all active:scale-90">
                       <RotateCcw size={14} />
                     </button>
                   </div>
                </div>

                <div className="flex gap-2 overflow-x-auto pb-1 hide-scrollbar justify-center">
                   {['1:1', '16:9', '9:16', '4:3', '3:4'].map(r => (
                     <button key={r} onClick={() => handleRatioSelect(r)} className={`px-4 py-1.5 rounded-lg border text-[9px] font-black uppercase tracking-widest whitespace-nowrap transition-all ${cropRatio === r ? 'bg-white text-nano-50 border-white' : 'border-white/10 text-white hover:border-white/30'}`}>
                        {r === '1:1' ? 'Square' : r}
                     </button>
                   ))}
                </div>
             </div>
           )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Button } from './UI';
import { 
  Check, 
  X, 
  Crop, 
  Wand2, 
  ZoomIn, 
  RotateCcw, 
  Loader2, 
  Sliders, 
  Sun, 
  Contrast, 
  Lock, 
  Unlock,
  Palette,
  Droplets,
  Eye,
  Sparkles,
  Zap,
  Undo,
  Redo
} from 'lucide-react';
import { IMAGE_FILTERS, ASPECT_RATIOS } from '../constants';
import { generateImageWithNano } from '../services/geminiService';

interface ImageEditorProps {
  imageSrc: string;
  prompt: string;
  styleId: string;
  initialCreativity: number;
  onSave: (newImageSrc: string) => void;
  onCancel: () => void;
}

// Define the shape of our history state
type EditorState = {
  imageSrc: string;
  filterId: string;
  adjustments: {
    brightness: number;
    contrast: number;
    saturation: number;
    hueRotate: number;
    creativity: number;
  };
  transform: {
    zoom: number;
    cropRatio: string;
    pan: { x: number; y: number };
    isRatioLocked: boolean;
  };
};

export const ImageEditor: React.FC<ImageEditorProps> = ({ 
  imageSrc: initialImageSrc, 
  prompt, 
  styleId, 
  initialCreativity, 
  onSave, 
  onCancel 
}) => {
  const [activeTab, setActiveTab] = useState<'filter' | 'adjust' | 'crop'>('filter');
  const [selectedFilterId, setSelectedFilterId] = useState('grayscale');
  const [hoveredFilterId, setHoveredFilterId] = useState<string | null>(null);
  const [imageLoaded, setImageLoaded] = useState(false);
  const [currentImageSrc, setCurrentImageSrc] = useState(initialImageSrc);
  const [isRefining, setIsRefining] = useState(false);

  // Adjustment state
  const [brightness, setBrightness] = useState(100); 
  const [contrast, setContrast] = useState(100);   
  const [saturation, setSaturation] = useState(100); 
  const [hueRotate, setHueRotate] = useState(0);    
  const [creativity, setCreativity] = useState(initialCreativity);

  // Crop state
  const [zoom, setZoom] = useState(1);
  const [cropRatio, setCropRatio] = useState<string>('1:1');
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [isRatioLocked, setIsRatioLocked] = useState(true);

  // Interaction state
  const [isDragging, setIsDragging] = useState(false);
  const [isResetting, setIsResetting] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  // History state
  const [history, setHistory] = useState<EditorState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  const imageRef = useRef<HTMLImageElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // --- History Helpers ---

  // Construct the current state object from active variables
  const getCurrentState = useCallback((overrides: Partial<EditorState> = {}): EditorState => ({
    imageSrc: currentImageSrc,
    filterId: selectedFilterId,
    adjustments: { brightness, contrast, saturation, hueRotate, creativity },
    transform: { zoom, cropRatio, pan, isRatioLocked },
    ...overrides
  }), [currentImageSrc, selectedFilterId, brightness, contrast, saturation, hueRotate, creativity, zoom, cropRatio, pan, isRatioLocked]);

  // Initialize history on mount
  useEffect(() => {
    if (history.length === 0) {
      const initialState = getCurrentState();
      setHistory([initialState]);
      setHistoryIndex(0);
    }
  }, []); // Run once on mount

  const pushToHistory = (newState: EditorState) => {
    // Avoid duplicates if the state hasn't effectively changed
    if (historyIndex >= 0) {
      const currentState = history[historyIndex];
      if (JSON.stringify(currentState) === JSON.stringify(newState)) return;
    }

    const newHistory = history.slice(0, historyIndex + 1);
    newHistory.push(newState);
    setHistory(newHistory);
    setHistoryIndex(newHistory.length - 1);
  };

  const handleUndo = () => {
    if (historyIndex > 0) {
      const newIndex = historyIndex - 1;
      setHistoryIndex(newIndex);
      restoreState(history[newIndex]);
    }
  };

  const handleRedo = () => {
    if (historyIndex < history.length - 1) {
      const newIndex = historyIndex + 1;
      setHistoryIndex(newIndex);
      restoreState(history[newIndex]);
    }
  };

  const restoreState = (state: EditorState) => {
    setCurrentImageSrc(state.imageSrc);
    setSelectedFilterId(state.filterId);
    setBrightness(state.adjustments.brightness);
    setContrast(state.adjustments.contrast);
    setSaturation(state.adjustments.saturation);
    setHueRotate(state.adjustments.hueRotate);
    setCreativity(state.adjustments.creativity);
    setZoom(state.transform.zoom);
    setCropRatio(state.transform.cropRatio);
    setPan(state.transform.pan);
    setIsRatioLocked(state.transform.isRatioLocked);
  };

  // --- Logic ---

  const getMinZoom = useCallback(() => {
    if (!imageRef.current || !containerRef.current) return 1;
    const img = imageRef.current;
    const container = containerRef.current;

    const containerAspect = container.clientWidth / container.clientHeight;
    const imgAspect = img.naturalWidth / img.naturalHeight;

    if (imgAspect > containerAspect) {
      return 1; 
    } else {
      return containerAspect / imgAspect;
    }
  }, []);

  const constrainPan = useCallback((currentPan: { x: number; y: number }, currentZoom: number) => {
    if (isResetting || !isRatioLocked || !imageRef.current || !containerRef.current) return currentPan;

    const img = imageRef.current;
    const container = containerRef.current;

    const imgAspect = img.naturalWidth / img.naturalHeight;
    const containerAspect = container.clientWidth / container.clientHeight;

    let displayWidth, displayHeight;
    if (imgAspect > containerAspect) {
      displayHeight = container.clientHeight;
      displayWidth = container.clientHeight * imgAspect;
    } else {
      displayWidth = container.clientWidth;
      displayHeight = container.clientWidth / imgAspect;
    }

    const scaledWidth = displayWidth * currentZoom;
    const scaledHeight = displayHeight * currentZoom;

    const maxX = Math.max(0, (scaledWidth - container.clientWidth) / 2) / currentZoom;
    const maxY = Math.max(0, (scaledHeight - container.clientHeight) / 2) / currentZoom;

    return {
      x: Math.min(Math.max(currentPan.x, -maxX), maxX),
      y: Math.min(Math.max(currentPan.y, -maxY), maxY)
    };
  }, [isRatioLocked, isResetting]);

  useEffect(() => {
    if (isRatioLocked && imageLoaded && !isResetting) {
      const minZoom = getMinZoom();
      if (zoom < minZoom) {
        setZoom(minZoom);
      }
      setPan(prev => constrainPan(prev, Math.max(zoom, minZoom)));
    }
  }, [isRatioLocked, cropRatio, imageLoaded, zoom, constrainPan, getMinZoom, isResetting]);

  // Logic for real-time preview
  const effectiveFilterId = hoveredFilterId || selectedFilterId;
  const activeFilterObject = IMAGE_FILTERS.find(f => f.id === effectiveFilterId);
  const baseFilter = activeFilterObject?.filter || 'none';
  const currentFilter = `${baseFilter === 'none' ? '' : baseFilter} brightness(${brightness}%) contrast(${contrast}%) saturate(${saturation}%) hue-rotate(${hueRotate}deg)`;

  const handlePointerDown = (e: React.PointerEvent) => {
    if (isResetting) return;
    setIsDragging(true);
    setDragStart({ x: e.clientX - pan.x * zoom, y: e.clientY - pan.y * zoom });
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (isDragging) {
      const newPan = {
        x: (e.clientX - dragStart.x) / zoom,
        y: (e.clientY - dragStart.y) / zoom
      };
      setPan(constrainPan(newPan, zoom));
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (isDragging) {
      // Save history on drag end
      pushToHistory(getCurrentState());
    }
    setIsDragging(false);
    (e.target as HTMLElement).releasePointerCapture(e.pointerId);
  };

  const handleResetTransform = () => {
    if (isResetting) return;
    setIsResetting(true);
    const targetZoom = isRatioLocked ? getMinZoom() : 1;
    const targetPan = { x: 0, y: 0 };
    setZoom(targetZoom);
    setPan(targetPan);

    // Save history with the reset values
    pushToHistory({
        ...getCurrentState(),
        transform: {
            zoom: targetZoom,
            pan: targetPan,
            cropRatio,
            isRatioLocked
        }
    });

    setTimeout(() => setIsResetting(false), 600);
  };

  const handleResetAdjustments = () => {
    setBrightness(100);
    setContrast(100);
    setSaturation(100);
    setHueRotate(0);
    setCreativity(initialCreativity);
    setSelectedFilterId('none');

    // Save history
    pushToHistory({
        ...getCurrentState(),
        filterId: 'none',
        adjustments: { brightness: 100, contrast: 100, saturation: 100, hueRotate: 0, creativity: initialCreativity }
    });
  };

  const getCanvasData = () => {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    const img = imageRef.current;

    if (!ctx || !img) return null;

    const outputSize = 1024; // Standard reference size
    let width = outputSize;
    let height = outputSize;

    const [wRatio, hRatio] = cropRatio.split(':').map(Number);
    if (wRatio && hRatio) {
        if (wRatio > hRatio) {
            height = outputSize * (hRatio / wRatio);
        } else {
            width = outputSize * (wRatio / hRatio);
        }
    }

    canvas.width = width;
    canvas.height = height;
    ctx.fillStyle = '#000000';
    ctx.fillRect(0, 0, width, height);

    const container = containerRef.current;
    if (!container) return null;

    const scaleFactor = width / container.clientWidth;

    ctx.save();
    const saveBaseFilter = IMAGE_FILTERS.find(f => f.id === selectedFilterId)?.filter || 'none';
    ctx.filter = `${saveBaseFilter === 'none' ? '' : saveBaseFilter} brightness(${brightness}%) contrast(${contrast}%) saturate(${saturation}%) hue-rotate(${hueRotate}deg)`;

    ctx.translate(width / 2, height / 2);
    ctx.scale(zoom, zoom);
    ctx.translate(pan.x * scaleFactor, pan.y * scaleFactor);

    const imgAspect = img.naturalWidth / img.naturalHeight;
    const containerAspect = container.clientWidth / container.clientHeight;

    let drawWidth, drawHeight;
    if (imgAspect > containerAspect) {
        drawHeight = height / zoom;
        drawWidth = drawHeight * imgAspect;
    } else {
        drawWidth = width / zoom;
        drawHeight = drawWidth / imgAspect;
    }

    ctx.drawImage(img, -drawWidth / 2, -drawHeight / 2, drawWidth, drawHeight);
    ctx.restore();

    return canvas.toDataURL('image/png', 0.95);
  };

  const handleSave = () => {
    const dataUrl = getCanvasData();
    if (dataUrl) onSave(dataUrl);
  };

  const handleAIRefine = async () => {
    const referenceData = getCanvasData();
    if (!referenceData) return;

    setIsRefining(true);
    setImageLoaded(false);

    try {
      const newImage = await generateImageWithNano(
        prompt,
        styleId,
        cropRatio,
        undefined, // random seed
        creativity,
        referenceData
      );
      setCurrentImageSrc(newImage);
      // Reset canvas filters to "none" because the new image already has the look
      // And manually save the history for this major event

      setBrightness(100);
      setContrast(100);
      setSaturation(100);
      setHueRotate(0);
      setCreativity(initialCreativity);
      setSelectedFilterId('none');
      setZoom(isRatioLocked ? getMinZoom() : 1);
      setPan({ x: 0, y: 0 });

      // Add to history with new image and reset values
      const newState: EditorState = {
         imageSrc: newImage,
         filterId: 'none',
         adjustments: { brightness: 100, contrast: 100, saturation: 100, hueRotate: 0, creativity: initialCreativity },
         transform: { 
             zoom: isRatioLocked ? getMinZoom() : 1, 
             cropRatio, 
             pan: { x: 0, y: 0 }, 
             isRatioLocked 
         }
      };

      // We push manually because we want to bundle all changes
      setHistory(prev => {
         const newHistory = prev.slice(0, historyIndex + 1);
         return [...newHistory, newState];
      });
      setHistoryIndex(prev => prev + 1);

    } catch (error) {
      console.error("AI Refine failed:", error);
      setImageLoaded(true);
    } finally {
      setIsRefining(false);
    }
  };

  // Wrapper for filter change
  const handleFilterSelect = (id: string) => {
    setSelectedFilterId(id);
    pushToHistory({ ...getCurrentState(), filterId: id });
  };

  // Wrapper for crop ratio
  const handleRatioSelect = (ratio: string) => {
    setCropRatio(ratio);
    pushToHistory({ ...getCurrentState(), transform: { ...getCurrentState().transform, cropRatio: ratio } });
  };

  // Wrapper for lock toggle
  const handleLockToggle = () => {
    const newLock = !isRatioLocked;
    setIsRatioLocked(newLock);
    pushToHistory({ ...getCurrentState(), transform: { ...getCurrentState().transform, isRatioLocked: newLock } });
  };

  return (
    <div className="fixed inset-0 z-[100] bg-nano-50/90 backdrop-blur-md flex flex-col h-full animate-in fade-in duration-300">
      <div className="h-14 border-b border-white/10 flex items-center justify-between px-4 bg-nano-100 shrink-0 shadow-xl">
        <div className="flex items-center gap-2">
            <button onClick={onCancel} className="p-2 text-nano-400 hover:text-white hover:bg-white/5 rounded-lg transition-colors focus:outline-none">
            <X size={20} />
            </button>
            <div className="h-6 w-px bg-white/10 mx-2 hidden sm:block"></div>
            <button onClick={handleUndo} disabled={historyIndex <= 0} className="p-2 text-nano-400 hover:text-white hover:bg-white/5 rounded-lg transition-colors focus:outline-none disabled:opacity-30 disabled:hover:bg-transparent">
               <Undo size={18} />
            </button>
            <button onClick={handleRedo} disabled={historyIndex >= history.length - 1} className="p-2 text-nano-400 hover:text-white hover:bg-white/5 rounded-lg transition-colors focus:outline-none disabled:opacity-30 disabled:hover:bg-transparent">
               <Redo size={18} />
            </button>
        </div>

        <span className="font-bold text-xs uppercase tracking-widest text-white hidden sm:block">Retouch Station</span>

        <div className="flex items-center gap-2">
            <button 
                onClick={handleAIRefine} 
                disabled={!imageLoaded || isRefining} 
                className="flex items-center gap-2 px-3 py-1.5 text-emerald-400 hover:text-white hover:bg-white/10 rounded-lg transition-colors font-bold text-[10px] uppercase tracking-widest disabled:opacity-50"
                title="Generate new variation based on current view"
            >
                <Zap size={16} className={isRefining ? "animate-pulse" : ""} />
                <span className="hidden sm:block">Refine</span>
            </button>
            <div className="h-6 w-px bg-white/10 mx-1"></div>
            <button onClick={handleSave} disabled={!imageLoaded || isRefining} className="p-2 text-white hover:bg-white/10 rounded-lg transition-colors font-medium disabled:opacity-50">
                <Check size={20} />
            </button>
        </div>
      </div>

      <div className="flex-grow overflow-hidden relative flex items-center justify-center p-8 select-none">
        {/* Preview Indicator */}
        {hoveredFilterId && (
          <div className="absolute top-12 left-1/2 -translate-x-1/2 z-20 flex items-center gap-2 px-4 py-2 bg-white text-nano-50 rounded-full shadow-2xl animate-in slide-in-from-top-4">
            <Eye size={12} className="animate-pulse" />
            <span className="text-[10px] font-black uppercase tracking-widest">Previewing: {activeFilterObject?.name}</span>
          </div>
        )}

        {(!imageLoaded || isRefining) && (
          <div className="absolute inset-0 z-30 flex flex-col items-center justify-center bg-nano-50/80 backdrop-blur-sm">
             <Loader2 className="w-8 h-8 text-white animate-spin mb-4" />
             {isRefining && <span className="text-[10px] font-black uppercase tracking-[0.3em] text-white animate-pulse">AI Re-imagining...</span>}
          </div>
        )}

        <div 
          ref={containerRef}
          className="relative bg-black overflow-hidden shadow-2xl ring-1 ring-white/20"
          style={{
             aspectRatio: cropRatio.replace(':', '/'),
             width: '100%',
             maxWidth: '100%',
             maxHeight: '100%',
             cursor: isDragging ? 'grabbing' : 'grab',
             touchAction: 'none'
          }}
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={handlePointerUp}
          onPointerLeave={handlePointerUp}
        >
           <img 
             ref={imageRef}
             src={currentImageSrc} 
             alt="Editing"
             loading="lazy"
             decoding="async"
             onLoad={() => setImageLoaded(true)}
             className={`absolute max-w-none max-h-none origin-center pointer-events-none transition-opacity duration-300 ${imageLoaded ? 'opacity-100' : 'opacity-0'}`}
             style={{
                top: '50%',
                left: '50%',
                transform: `translate(-50%, -50%) scale(${zoom}) translate(${pan.x}px, ${pan.y}px)`,
                filter: currentFilter,
                minWidth: '100%',
                minHeight: '100%',
                transition: isResetting 
                  ? 'transform 0.6s cubic-bezier(0.25, 1, 0.5, 1), filter 0.3s ease' 
                  : (isDragging ? 'none' : 'transform 0.1s ease-out, filter 0.25s ease-out')
             }}
             draggable={false}
           />
        </div>
      </div>

      <div className="bg-nano-100 border-t border-white/10 shrink-0 pb-safe shadow-[0_-10px_40px_rgba(0,0,0,0.5)]">
        <div className="flex border-b border-white/5">
           <button onClick={() => setActiveTab('filter')} className={`flex-1 py-3 text-[10px] uppercase font-bold tracking-widest flex items-center justify-center gap-2 focus:outline-none transition-all ${activeTab === 'filter' ? 'text-white border-b-2 border-white bg-white/5' : 'text-nano-400'}`}>
             <Wand2 size={14} /> Filters
           </button>
           <button onClick={() => setActiveTab('adjust')} className={`flex-1 py-3 text-[10px] uppercase font-bold tracking-widest flex items-center justify-center gap-2 focus:outline-none transition-all ${activeTab === 'adjust' ? 'text-white border-b-2 border-white bg-white/5' : 'text-nano-400'}`}>
             <Sliders size={14} /> Adjust
           </button>
           <button onClick={() => setActiveTab('crop')} className={`flex-1 py-3 text-[10px] uppercase font-bold tracking-widest flex items-center justify-center gap-2 focus:outline-none transition-all ${activeTab === 'crop' ? 'text-white border-b-2 border-white bg-white/5' : 'text-nano-400'}`}>
             <Crop size={14} /> Crop
           </button>
        </div>

        <div className="h-52 p-4 overflow-y-auto hide-scrollbar">
           {activeTab === 'filter' && (
             <div className="flex gap-4 overflow-x-auto pb-2 hide-scrollbar h-full items-center">
                {IMAGE_FILTERS.map((f) => (
                   <button 
                     key={f.id}
                     onClick={() => handleFilterSelect(f.id)}
                     onMouseEnter={() => setHoveredFilterId(f.id)}
                     onMouseLeave={() => setHoveredFilterId(null)}
                     className="flex flex-col items-center gap-2 shrink-0 group focus:outline-none"
                   >
                      <div className={`w-14 h-14 rounded-lg overflow-hidden border-2 transition-all ${selectedFilterId === f.id ? 'border-white ring-2 ring-white/20' : 'border-transparent group-hover:border-white/20 group-hover:scale-105'}`}>
                         <img src={currentImageSrc} alt={f.name} className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110" style={{ filter: f.filter }} />
                      </div>
                      <span className={`text-[9px] font-black uppercase tracking-wider transition-colors ${selectedFilterId === f.id || hoveredFilterId === f.id ? 'text-white' : 'text-nano-300'}`}>{f.name}</span>
                   </button>
                ))}
             </div>
           )}

           {activeTab === 'adjust' && (
             <div className="flex flex-col gap-2 h-full justify-center max-w-lg mx-auto">
                <div className="flex items-center gap-4 px-2">
                   <div className="flex items-center gap-2 w-28 shrink-0">
                      <Sun size={12} className="text-white" />
                      <span className="text-[10px] font-black uppercase tracking-widest text-white">Brightness</span>
                   </div>
                   <input 
                     type="range" min="0" max="200" step="1" 
                     value={brightness} 
                     onChange={(e) => setBrightness(parseInt(e.target.value))} 
                     onPointerUp={() => pushToHistory(getCurrentState())}
                     className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-white" 
                   />
                   <span className="text-[10px] font-mono w-10 text-right text-nano-300">{brightness}%</span>
                </div>
                <div className="flex items-center gap-4 px-2">
                   <div className="flex items-center gap-2 w-28 shrink-0">
                      <Contrast size={12} className="text-white" />
                      <span className="text-[10px] font-black uppercase tracking-widest text-white">Contrast</span>
                   </div>
                   <input 
                     type="range" min="0" max="200" step="1" 
                     value={contrast} 
                     onChange={(e) => setContrast(parseInt(e.target.value))} 
                     onPointerUp={() => pushToHistory(getCurrentState())}
                     className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-white" 
                   />
                   <span className="text-[10px] font-mono w-10 text-right text-nano-300">{contrast}%</span>
                </div>

                {/* Creativity Slider */}
                <div className="flex items-center gap-4 px-2 group">
                   <div className="flex items-center gap-2 w-28 shrink-0">
                      <Sparkles size={12} className="text-emerald-400 group-hover:animate-pulse" />
                      <span className="text-[10px] font-black uppercase tracking-widest text-emerald-400">Creativity</span>
                   </div>
                   <input 
                     type="range" min="0" max="100" step="1" 
                     value={creativity} 
                     onChange={(e) => setCreativity(parseInt(e.target.value))} 
                     onPointerUp={() => pushToHistory(getCurrentState())}
                     className="w-full h-1 bg-emerald-500/20 rounded-full appearance-none cursor-pointer accent-emerald-400" 
                   />
                   <span className="text-[10px] font-mono w-10 text-right text-emerald-400">{creativity}%</span>
                </div>

                <div className="flex justify-between items-center mt-2 px-2">
                   <button onClick={handleResetAdjustments} className="text-[9px] font-black uppercase tracking-[0.2em] text-white/50 hover:text-white transition-colors">Reset</button>
                   {/* Removed duplicate AI Refine button from here as it's now in the header */}
                </div>
             </div>
           )}

           {activeTab === 'crop' && (
             <div className="flex flex-col gap-3 h-full justify-center max-w-lg mx-auto">
                <div className="flex items-center gap-3 px-2">
                   <ZoomIn size={14} className="text-white" />
                   <input 
                     type="range" 
                     min={isRatioLocked ? getMinZoom() : 0.5} 
                     max="4" 
                     step="0.01"
                     value={zoom}
                     onChange={(e) => {
                       const val = parseFloat(e.target.value);
                       setZoom(val);
                       setPan(prev => constrainPan(prev, val));
                     }}
                     onPointerUp={() => pushToHistory(getCurrentState())}
                     className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-white"
                   />
                   <div className="flex gap-2 ml-2">
                     <button onClick={handleLockToggle} className={`p-2 rounded-lg transition-all active:scale-90 ${isRatioLocked ? 'bg-white text-nano-50' : 'text-white hover:bg-white/5'}`} title={isRatioLocked ? "Unlock Aspect Ratio" : "Lock Aspect Ratio"}>
                       {isRatioLocked ? <Lock size={14} /> : <Unlock size={14} />}
                     </button>
                     <button onClick={handleResetTransform} className="p-2 text-white hover:bg-white/5 rounded-lg transition-all active:scale-90">
                       <RotateCcw size={14} />
                     </button>
                   </div>
                </div>

                <div className="flex gap-2 overflow-x-auto pb-1 hide-scrollbar justify-center">
                   {['1:1', '16:9', '9:16', '4:3', '3:4'].map(r => (
                     <button key={r} onClick={() => handleRatioSelect(r)} className={`px-4 py-1.5 rounded-lg border text-[9px] font-black uppercase tracking-widest whitespace-nowrap transition-all ${cropRatio === r ? 'bg-white text-nano-50 border-white' : 'border-white/10 text-white hover:border-white/30'}`}>
                        {r === '1:1' ? 'Square' : r}
                     </button>
                   ))}
                </div>
             </div>
           )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Button } from './UI';
import { 
  Check, 
  X, 
  Crop, 
  Wand2, 
  ZoomIn, 
  RotateCcw, 
  Loader2, 
  Sliders, 
  Sun, 
  Contrast, 
  Lock, 
  Unlock,
  Palette,
  Droplets,
  Eye,
  Sparkles,
  Zap,
  Undo,
  Redo
} from 'lucide-react';
import { IMAGE_FILTERS, ASPECT_RATIOS } from '../constants';
import { generateImageWithNano } from '../services/geminiService';

interface ImageEditorProps {
  imageSrc: string;
  prompt: string;
  styleId: string;
  initialCreativity: number;
  onSave: (newImageSrc: string) => void;
  onCancel: () => void;
}

// Define the shape of our history state
type EditorState = {
  imageSrc: string;
  filterId: string;
  adjustments: {
    brightness: number;
    contrast: number;
    saturation: number;
    hueRotate: number;
    creativity: number;
  };
  transform: {
    zoom: number;
    cropRatio: string;
    pan: { x: number; y: number };
    isRatioLocked: boolean;
  };
};

export const ImageEditor: React.FC<ImageEditorProps> = ({ 
  imageSrc: initialImageSrc, 
  prompt, 
  styleId, 
  initialCreativity, 
  onSave, 
  onCancel 
}) => {
  const [activeTab, setActiveTab] = useState<'filter' | 'adjust' | 'crop'>('filter');
  const [selectedFilterId, setSelectedFilterId] = useState('grayscale');
  const [hoveredFilterId, setHoveredFilterId] = useState<string | null>(null);
  const [imageLoaded, setImageLoaded] = useState(false);
  const [currentImageSrc, setCurrentImageSrc] = useState(initialImageSrc);
  const [isRefining, setIsRefining] = useState(false);

  // Adjustment state
  const [brightness, setBrightness] = useState(100); 
  const [contrast, setContrast] = useState(100);   
  const [saturation, setSaturation] = useState(100); 
  const [hueRotate, setHueRotate] = useState(0);    
  const [creativity, setCreativity] = useState(initialCreativity);

  // Crop state
  const [zoom, setZoom] = useState(1);
  const [cropRatio, setCropRatio] = useState<string>('1:1');
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [isRatioLocked, setIsRatioLocked] = useState(true);

  // Interaction state
  const [isDragging, setIsDragging] = useState(false);
  const [isResetting, setIsResetting] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  // History state
  const [history, setHistory] = useState<EditorState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  const imageRef = useRef<HTMLImageElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // --- History Helpers ---

  // Construct the current state object from active variables
  const getCurrentState = useCallback((overrides: Partial<EditorState> = {}): EditorState => ({
    imageSrc: currentImageSrc,
    filterId: selectedFilterId,
    adjustments: { brightness, contrast, saturation, hueRotate, creativity },
    transform: { zoom, cropRatio, pan, isRatioLocked },
    ...overrides
  }), [currentImageSrc, selectedFilterId, brightness, contrast, saturation, hueRotate, creativity, zoom, cropRatio, pan, isRatioLocked]);

  // Initialize history on mount
  useEffect(() => {
    if (history.length === 0) {
      const initialState = getCurrentState();
      setHistory([initialState]);
      setHistoryIndex(0);
    }
  }, []); // Run once on mount

  const pushToHistory = (newState: EditorState) => {
    // Avoid duplicates if the state hasn't effectively changed
    if (historyIndex >= 0) {
      const currentState = history[historyIndex];
      if (JSON.stringify(currentState) === JSON.stringify(newState)) return;
    }

    const newHistory = history.slice(0, historyIndex + 1);
    newHistory.push(newState);
    setHistory(newHistory);
    setHistoryIndex(newHistory.length - 1);
  };

  const handleUndo = () => {
    if (historyIndex > 0) {
      const newIndex = historyIndex - 1;
      setHistoryIndex(newIndex);
      restoreState(history[newIndex]);
    }
  };

  const handleRedo = () => {
    if (historyIndex < history.length - 1) {
      const newIndex = historyIndex + 1;
      setHistoryIndex(newIndex);
      restoreState(history[newIndex]);
    }
  };

  const restoreState = (state: EditorState) => {
    setCurrentImageSrc(state.imageSrc);
    setSelectedFilterId(state.filterId);
    setBrightness(state.adjustments.brightness);
    setContrast(state.adjustments.contrast);
    setSaturation(state.adjustments.saturation);
    setHueRotate(state.adjustments.hueRotate);
    setCreativity(state.adjustments.creativity);
    setZoom(state.transform.zoom);
    setCropRatio(state.transform.cropRatio);
    setPan(state.transform.pan);
    setIsRatioLocked(state.transform.isRatioLocked);
  };

  // --- Logic ---

  const getMinZoom = useCallback(() => {
    if (!imageRef.current || !containerRef.current) return 1;
    const img = imageRef.current;
    const container = containerRef.current;

    const containerAspect = container.clientWidth / container.clientHeight;
    const imgAspect = img.naturalWidth / img.naturalHeight;

    if (imgAspect > containerAspect) {
      return 1; 
    } else {
      return containerAspect / imgAspect;
    }
  }, []);

  const constrainPan = useCallback((currentPan: { x: number; y: number }, currentZoom: number) => {
    if (isResetting || !isRatioLocked || !imageRef.current || !containerRef.current) return currentPan;

    const img = imageRef.current;
    const container = containerRef.current;

    const imgAspect = img.naturalWidth / img.naturalHeight;
    const containerAspect = container.clientWidth / container.clientHeight;

    let displayWidth, displayHeight;
    if (imgAspect > containerAspect) {
      displayHeight = container.clientHeight;
      displayWidth = container.clientHeight * imgAspect;
    } else {
      displayWidth = container.clientWidth;
      displayHeight = container.clientWidth / imgAspect;
    }

    const scaledWidth = displayWidth * currentZoom;
    const scaledHeight = displayHeight * currentZoom;

    const maxX = Math.max(0, (scaledWidth - container.clientWidth) / 2) / currentZoom;
    const maxY = Math.max(0, (scaledHeight - container.clientHeight) / 2) / currentZoom;

    return {
      x: Math.min(Math.max(currentPan.x, -maxX), maxX),
      y: Math.min(Math.max(currentPan.y, -maxY), maxY)
    };
  }, [isRatioLocked, isResetting]);

  useEffect(() => {
    if (isRatioLocked && imageLoaded && !isResetting) {
      const minZoom = getMinZoom();
      if (zoom < minZoom) {
        setZoom(minZoom);
      }
      setPan(prev => constrainPan(prev, Math.max(zoom, minZoom)));
    }
  }, [isRatioLocked, cropRatio, imageLoaded, zoom, constrainPan, getMinZoom, isResetting]);

  // Logic for real-time preview
  const effectiveFilterId = hoveredFilterId || selectedFilterId;
  const activeFilterObject = IMAGE_FILTERS.find(f => f.id === effectiveFilterId);
  const baseFilter = activeFilterObject?.filter || 'none';
  const currentFilter = `${baseFilter === 'none' ? '' : baseFilter} brightness(${brightness}%) contrast(${contrast}%) saturate(${saturation}%) hue-rotate(${hueRotate}deg)`;

  const handlePointerDown = (e: React.PointerEvent) => {
    if (isResetting) return;
    setIsDragging(true);
    setDragStart({ x: e.clientX - pan.x * zoom, y: e.clientY - pan.y * zoom });
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (isDragging) {
      const newPan = {
        x: (e.clientX - dragStart.x) / zoom,
        y: (e.clientY - dragStart.y) / zoom
      };
      setPan(constrainPan(newPan, zoom));
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (isDragging) {
      // Save history on drag end
      pushToHistory(getCurrentState());
    }
    setIsDragging(false);
    (e.target as HTMLElement).releasePointerCapture(e.pointerId);
  };

  const handleResetTransform = () => {
    if (isResetting) return;
    setIsResetting(true);
    const targetZoom = isRatioLocked ? getMinZoom() : 1;
    const targetPan = { x: 0, y: 0 };
    setZoom(targetZoom);
    setPan(targetPan);

    // Save history with the reset values
    pushToHistory({
        ...getCurrentState(),
        transform: {
            zoom: targetZoom,
            pan: targetPan,
            cropRatio,
            isRatioLocked
        }
    });

    setTimeout(() => setIsResetting(false), 600);
  };

  const handleResetAdjustments = () => {
    setBrightness(100);
    setContrast(100);
    setSaturation(100);
    setHueRotate(0);
    setCreativity(initialCreativity);
    setSelectedFilterId('none');

    // Save history
    pushToHistory({
        ...getCurrentState(),
        filterId: 'none',
        adjustments: { brightness: 100, contrast: 100, saturation: 100, hueRotate: 0, creativity: initialCreativity }
    });
  };

  const getCanvasData = () => {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    const img = imageRef.current;

    if (!ctx || !img) return null;

    const outputSize = 1024; // Standard reference size
    let width = outputSize;
    let height = outputSize;

    const [wRatio, hRatio] = cropRatio.split(':').map(Number);
    if (wRatio && hRatio) {
        if (wRatio > hRatio) {
            height = outputSize * (hRatio / wRatio);
        } else {
            width = outputSize * (wRatio / hRatio);
        }
    }

    canvas.width = width;
    canvas.height = height;
    ctx.fillStyle = '#000000';
    ctx.fillRect(0, 0, width, height);

    const container = containerRef.current;
    if (!container) return null;

    const scaleFactor = width / container.clientWidth;

    ctx.save();
    const saveBaseFilter = IMAGE_FILTERS.find(f => f.id === selectedFilterId)?.filter || 'none';
    ctx.filter = `${saveBaseFilter === 'none' ? '' : saveBaseFilter} brightness(${brightness}%) contrast(${contrast}%) saturate(${saturation}%) hue-rotate(${hueRotate}deg)`;

    ctx.translate(width / 2, height / 2);
    ctx.scale(zoom, zoom);
    ctx.translate(pan.x * scaleFactor, pan.y * scaleFactor);

    const imgAspect = img.naturalWidth / img.naturalHeight;
    const containerAspect = container.clientWidth / container.clientHeight;

    let drawWidth, drawHeight;
    if (imgAspect > containerAspect) {
        drawHeight = height / zoom;
        drawWidth = drawHeight * imgAspect;
    } else {
        drawWidth = width / zoom;
        drawHeight = drawWidth / imgAspect;
    }

    ctx.drawImage(img, -drawWidth / 2, -drawHeight / 2, drawWidth, drawHeight);
    ctx.restore();

    return canvas.toDataURL('image/png', 0.95);
  };

  const handleSave = () => {
    const dataUrl = getCanvasData();
    if (dataUrl) onSave(dataUrl);
  };

  const handleAIRefine = async () => {
    const referenceData = getCanvasData();
    if (!referenceData) return;

    setIsRefining(true);
    setImageLoaded(false);

    try {
      const newImage = await generateImageWithNano(
        prompt,
        styleId,
        cropRatio,
        undefined, // random seed
        creativity,
        referenceData
      );
      setCurrentImageSrc(newImage);
      // Reset canvas filters to "none" because the new image already has the look
      // And manually save the history for this major event

      setBrightness(100);
      setContrast(100);
      setSaturation(100);
      setHueRotate(0);
      setCreativity(initialCreativity);
      setSelectedFilterId('none');
      setZoom(isRatioLocked ? getMinZoom() : 1);
      setPan({ x: 0, y: 0 });

