import { GoogleGenAI } from "@google/genai";
import { ART_STYLES, LIGHT_SOURCES, LIGHT_DIRECTIONS } from "../constants";

// Initialize the API client
// Note: API Key must be in process.env.API_KEY
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Generates an image using the Gemini Nano Banana model (gemini-2.5-flash-image).
 * @param prompt The user's input text.
 * @param styleId The ID of the selected style.
 * @param aspectRatio The aspect ratio for the generated image.
 * @param seed Optional random seed for deterministic results.
 * @param creativity Optional creativity level (0-100).
 * @param referenceImage Optional Base64 string of an input image.
 * @param lightSourceId Optional ID for light source type.
 * @param lightDirectionId Optional ID for lighting scheme.
 * @returns A promise that resolves to the Base64 image string.
 */
export const generateImageWithNano = async (
  prompt: string, 
  styleId: string, 
  aspectRatio: string = "1:1",
  seed?: number,
  creativity: number = 50,
  referenceImage?: string | null,
  lightSourceId: string = 'auto',
  lightDirectionId: string = 'auto'
): Promise<string> => {
  const selectedStyle = ART_STYLES.find(s => s.id === styleId);
  const styleModifier = selectedStyle ? selectedStyle.promptModifier : '';

  // Resolve lighting modifiers
  const sourceModifier = LIGHT_SOURCES.find(l => l.id === lightSourceId)?.promptModifier || '';
  const directionModifier = LIGHT_DIRECTIONS.find(l => l.id === lightDirectionId)?.promptModifier || '';

  const lightingPrompt = [sourceModifier, directionModifier].filter(Boolean).join(', ');

  // Construct a rich prompt for better results
  // If prompt is empty but image exists, we guide the model to use the image as base
  let fullPrompt = '';

  let baseRequest = prompt && prompt.trim() ? `Generate a high quality image of: ${prompt}.` : `Generate a high quality image.`;
  if (!prompt && referenceImage) {
    baseRequest = `Generate a high quality image based on the provided reference image.`;
  }

  fullPrompt = `${baseRequest} \nStyle details: ${styleModifier}.`;

  if (lightingPrompt) {
    fullPrompt += ` \nLighting Setup: ${lightingPrompt}.`;
  }

  fullPrompt += ` \nEnsure high resolution and detailed textures.`;

  // Smart Creativity Mapping
  // Map 0-100 to effective model parameters
  // Temperature: 0.2 (Strict) to 1.8 (Wild)
  const temperature = 0.2 + (creativity / 100) * 1.6;

  // TopP: 0.8 (Focused) to 1.0 (Diverse)
  const topP = 0.8 + (creativity / 100) * 0.2;

  try {
    const config: any = {
      imageConfig: {
          aspectRatio: aspectRatio,
      },
      temperature: temperature,
      topP: topP
    };

    if (seed !== undefined && !isNaN(seed)) {
      config.seed = seed;
    }

    // Prepare content parts
    const parts: any[] = [];

    // If there is a reference image, add it to the parts
    if (referenceImage) {
      // Expecting format: "data:image/png;base64,..."
      const match = referenceImage.match(/^data:(image\/[a-z]+);base64,(.+)$/);
      if (match) {
        const mimeType = match[1];
        const data = match[2];
        parts.push({
          inlineData: {
            mimeType: mimeType,
            data: data
          }
        });
      }
    }

    // Add text prompt
    parts.push({ text: fullPrompt });

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: parts,
      },
      config: config
    });

    // Parse the response to find the image data
    if (response.candidates && response.candidates[0].content.parts) {
        for (const part of response.candidates[0].content.parts) {
            if (part.inlineData && part.inlineData.data) {
                // Return the formatted data URL
                return `data:${part.inlineData.mimeType || 'image/png'};base64,${part.inlineData.data}`;
            }
        }
    }

    throw new Error("No image data found in the response.");

  } catch (error) {
    console.error("Gemini Generation Error:", error);
    throw error;
  }
};

/**
 * Analyzes an uploaded image to determine the best matching art style.
 * Uses gemini-3-flash-preview for multimodal analysis.
 */
export const detectImageStyle = async (imageBase64: string): Promise<string | null> => {
  try {
    // 1. Prepare parts
    const match = imageBase64.match(/^data:(image\/[a-z]+);base64,(.+)$/);
    if (!match) return null;

    const mimeType = match[1];
    const data = match[2];

    const styleList = ART_STYLES.map(s => `ID: "${s.id}" - Name: ${s.name} (${s.description})`).join('\n');
    const prompt = `Analyze the visual style of this image. Match it to one of the following styles:\n${styleList}\n\nReturn ONLY the ID of the best matching style. Example: "warm-interior"`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { mimeType, data } },
          { text: prompt }
        ]
      }
    });

    const text = response.text?.trim().replace(/['"]/g, '');
    return text || null;
  } catch (error) {
    console.warn("Style detection failed:", error);
    return null;
  }
};

