                                {isEditing && currentImage ? <ImageEditor imageSrc={currentImage.url} prompt={prompt} styleId={selectedStyleId} initialCreativity={creativity} onSave={handleSaveEdit} onCancel={() => setIsEditing(false)} /> : (
                                    <>
                                        <header className="h-20 border-b border-white/5 flex items-center justify-between px-8 bg-nano-100/40 backdrop-blur-md z-10 shrink-0">
                                            <div className="flex items-center gap-3"><div className="w-2.5 h-2.5 bg-emerald-400 rounded-full animate-pulse shadow-[0_0_12px_#34d399]"></div><span className="text-[11px] font-black uppercase tracking-[0.3em] text-white">Stream de Captura</span></div>
                                            {status === 'success' && currentImage && <div className="flex gap-2 items-center"><button onClick={() => setIsEditing(true)} className="p-3 hover:bg-white/10 rounded-2xl text-white transition-all" title="Retouch"><Edit2 size={20} /></button><button onClick={handleGenerate} className="p-3 hover:bg-white/10 rounded-2xl text-white transition-all" title="Regenerate"><RefreshCw size={20} /></button><div className="w-px h-8 bg-white/10 mx-2"></div><Button variant="secondary" onClick={handleDownload} className="!py-2.5 !px-6 !text-[10px] !rounded-2xl !bg-white !text-nano-50"><Download size={18} className="mr-2" />EXPORTAR</Button></div>}
