                                            {status === 'idle' && (
                                                <div className="text-center max-w-2xl px-8">
                                                    <div className="w-28 h-28 bg-white/5 rounded-[3rem] border border-white/10 flex items-center justify-center mx-auto mb-10 transform -rotate-3 hover:rotate-0 transition-all duration-1000"><Sparkles className="text-white/40" size={56} /></div>
                                                    <h3 className="text-3xl font-black text-white mb-4 tracking-tighter">AI Studio Activo</h3>
                                                    <p className="text-white/40 text-sm font-medium leading-relaxed mb-10">Selecciona un estilo e ingresa un prompt para comenzar. El motor está listo.</p>
                                                    <div className="space-y-3"><p className="text-[9px] font-black uppercase tracking-[0.4em] text-white/20 mb-6">Explora Laboratorio</p>
                                                        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
                                                            <button onClick={() => handleQuickStart("Jardín botánico cyberpunk bajo cúpula de neón", "moody-cinematic")} className="group flex items-center gap-3 px-4 py-3 rounded-2xl bg-white/5 border border-white/10 text-white/70 hover:text-white hover:bg-white/10 transition-all text-left"><Zap size={14} className="group-hover:text-emerald-400 shrink-0" /><span className="text-[9px] font-black uppercase tracking-widest truncate">Jardín Neón</span></button>
                                                            <button onClick={() => handleQuickStart("Macro de rascacielos de cristal", "daytime-exterior")} className="group flex items-center gap-3 px-4 py-3 rounded-2xl bg-white/5 border border-white/10 text-white/70 hover:text-white hover:bg-white/10 transition-all text-left"><Building2 size={14} className="group-hover:text-sky-400 shrink-0" /><span className="text-[9px] font-black uppercase tracking-widest truncate">Torre Cristal</span></button>
                                                            <button onClick={() => handleQuickStart("Primer plano de grano de café en leche", "minimal-studio")} className="group flex items-center gap-3 px-4 py-3 rounded-2xl bg-white/5 border border-white/10 text-white/70 hover:text-white hover:bg-white/10 transition-all text-left"><Coffee size={14} className="group-hover:text-amber-400 shrink-0" /><span className="text-[9px] font-black uppercase tracking-widest truncate">Splash Café</span></button>
                                                            <button onClick={() => handleQuickStart("Retrato editorial alta costura con terciopelo", "natural-portrait")} className="group flex items-center gap-3 px-4 py-3 rounded-2xl bg-white/5 border border-white/10 text-white/70 hover:text-white hover:bg-white/10 transition-all text-left"><User size={14} className="group-hover:text-rose-400 shrink-0" /><span className="text-[9px] font-black uppercase tracking-widest truncate">Retrato Moda</span></button>
                                                        </div>
                                                    </div>
                                                </div>
                                            )}
                                            {currentImage && <ZoomablePreview src={currentImage.url} alt={currentImage.prompt} className="max-w-full max-h-[85vh] rounded-3xl shadow-2xl" isVisible={status !== 'generating'} />}
                                        </div>
                                    </>
                                )}
                            </div>
                            {history.length > 0 && (
                                <section className="space-y-5 px-2">
                                    <div className="flex items-center justify-between"><div className="flex items-center gap-3 text-[10px] font-black uppercase tracking-[0.3em] text-white/30"><History size={16} /><span>Secuencia Lab</span></div><span className="text-[9px] font-black text-white/20 uppercase tracking-widest">{history.length} / 10</span></div>
                                    <div className="flex gap-5 overflow-x-auto pb-6 pt-2 hide-scrollbar">{history.map((img) => <button key={img.id} onClick={() => { setCurrentImage(img); setPrompt(img.prompt); setSelectedStyleId(img.styleId); setIsEditing(false); }} className={`relative flex-shrink-0 w-32 h-32 rounded-[2rem] overflow-hidden border-2 transition-all shadow-xl group ${currentImage?.id === img.id ? 'border-white ring-4 ring-white/10 scale-105 z-10' : 'border-transparent opacity-40 hover:opacity-100 hover:scale-105'}`}><img src={img.url} alt="Seq" className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" loading="lazy" /></button>)}</div>
                                </section>
                            )}
                        </section>
                    </main>
                </div>
            );
        };

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<App />);
    </script>
</body>
