                                      <Shapes size={14} className="group-hover:text-zinc-400 shrink-0" />
                                      <span className="text-[9px] font-black uppercase tracking-widest truncate">Brutalist Concrete</span>
                                   </button>
                                   <button onClick={() => handleQuickStart("Extreme macro photography of a colorful butterfly wing", "minimal-studio")} className="group flex items-center gap-3 px-4 py-3 rounded-2xl bg-white/5 border border-white/10 text-white/70 hover:text-white hover:bg-white/10 transition-all text-left">
                                      <Bug size={14} className="group-hover:text-purple-400 shrink-0" />
                                      <span className="text-[9px] font-black uppercase tracking-widest truncate">Macro Universe</span>
                                   </button>
                                   <button onClick={() => handleQuickStart("Deep underwater scene with bioluminescent jellyfish in the abyss", "moody-cinematic")} className="group flex items-center gap-3 px-4 py-3 rounded-2xl bg-white/5 border border-white/10 text-white/70 hover:text-white hover:bg-white/10 transition-all text-left">
                                      <Waves size={14} className="group-hover:text-cyan-400 shrink-0" />
                                      <span className="text-[9px] font-black uppercase tracking-widest truncate">Oceanic Void</span>
                                   </button>
                                </div>
                            </div>
                          </div>
                      )}

                      {currentImage && (
                          <ZoomablePreview src={currentImage.url} alt={currentImage.prompt} className="max-w-full max-h-[85vh] rounded-3xl shadow-2xl" isVisible={status !== 'generating'} />
                      )}
                    </div>
                </>
            )}
          </div>

          {/* History Stream */}
          {history.length > 0 && (
            <section className="space-y-5 px-2">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3 text-[10px] font-black uppercase tracking-[0.3em] text-white/30">
                  <History size={16} /><span>Lab Sequence</span>
                </div>
                <span className="text-[9px] font-black text-white/20 uppercase tracking-widest">{history.length} / 10 saved</span>
              </div>
              <div className="flex gap-5 overflow-x-auto pb-6 pt-2 hide-scrollbar">
                {history.map((img) => (
                  <button 
                    key={img.id} 
                    onClick={() => loadFromHistory(img)} 
                    className={`relative flex-shrink-0 w-32 h-32 rounded-[2rem] overflow-hidden border-2 transition-all shadow-xl group ${currentImage?.id === img.id ? 'border-white ring-4 ring-white/10 scale-105 z-10' : 'border-transparent opacity-40 hover:opacity-100 hover:scale-105'}`}
                  >
                    <img src={img.url} alt="Sequence" className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" loading="lazy" />
                  </button>
                ))}
              </div>
            </section>
          )}
        </section>
      </main>

      <style dangerouslySetInnerHTML={{ __html: `
        @keyframes progress {
          0% { transform: translateX(-100%); }
          100% { transform: translateX(100%); }
        }
        @keyframes scan {
          0% { transform: translateY(0); }
          100% { transform: translateY(500px); }
        }
      `}} />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { 
  Sparkles, 
  Download, 
  RefreshCw, 
  Image as ImageIcon, 
  History, 
  Zap,
  Camera,
  Maximize,
  Sliders,
  ChevronDown,
  ChevronUp,
  Undo,
  Redo,
  Upload,
  X,
  Plus,
  Edit2,
  Dices,
  Trash2,
  Wand2,
  Bookmark,
  Save,
  Clock,
  CheckCircle2,
  Eraser,
  Search,
  Loader2,
  Sun,
  Cloud,
  BookOpen,
  User,
  Trees,
  Home,
  Building2,
  Coffee,
  Shapes,
  Bug,
  Waves,
  Check,
  Lightbulb,
  Copy
} from 'lucide-react';
import { ART_STYLES, APP_NAME, MODEL_NAME_DISPLAY, ASPECT_RATIOS, LIGHT_SOURCES, LIGHT_DIRECTIONS } from './constants';
import { ArtStyle, GeneratedImage, GenerationStatus, GenerationPreset } from './types';
import { generateImageWithNano, detectImageStyle } from './services/geminiService';
import { Button, StyleCard, Badge } from './components/UI';
import { ImageEditor } from './components/ImageEditor';
import { ZoomablePreview } from './components/ZoomablePreview';

const App: React.FC = () => {
  // --- Basic Generation State ---
  const [prompt, setPrompt] = useState<string>('');
  const [selectedStyleId, setSelectedStyleId] = useState<string>(ART_STYLES[0].id);
  const [aspectRatio, setAspectRatio] = useState<string>('1:1');

  // --- Lighting State ---
  const [lightSourceId, setLightSourceId] = useState<string>('auto');
  const [lightDirectionId, setLightDirectionId] = useState<string>('auto');

  // --- Advanced Parameters State ---
  const [seed, setSeed] = useState<number | undefined>(undefined);
  const [creativity, setCreativity] = useState<number>(50); // 0-100
  const [showAdvanced, setShowAdvanced] = useState<boolean>(false);

  // --- Presets State ---
  const [presets, setPresets] = useState<GenerationPreset[]>([]);
  const [isSavingPreset, setIsSavingPreset] = useState(false);
  const [newPresetName, setNewPresetName] = useState('');
  const [showPresets, setShowPresets] = useState(true);
  const [lastLoadedPresetId, setLastLoadedPresetId] = useState<string | null>(null);
  const [editingPresetId, setEditingPresetId] = useState<string | null>(null);
  const [editNameValue, setEditNameValue] = useState('');
  const [presetSearch, setPresetSearch] = useState('');

  // --- Reference Image State ---
  const [uploadedImage, setUploadedImage] = useState<string | null>(null);
  const [isDetectingStyle, setIsDetectingStyle] = useState(false);
  const [lastAutoSelectedStyleId, setLastAutoSelectedStyleId] = useState<string | null>(null);

  // --- Generation & Gallery State ---
  const [status, setStatus] = useState<GenerationStatus>('idle');
  const [currentImage, setCurrentImage] = useState<GeneratedImage | null>(null);
  const [history, setHistory] = useState<GeneratedImage[]>([]);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  // --- UI/Editor State ---
  const [isEditing, setIsEditing] = useState(false);

  // --- Prompt History (Undo/Redo) ---
  const [promptHistory, setPromptHistory] = useState<string[]>(['']);
  const [historyIndex, setHistoryIndex] = useState(0);
  const debounceRef = useRef<any>(null);

  // --- Refs ---
  const previewRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- Persistence ---
  useEffect(() => {
    const saved = localStorage.getItem('nanoframe_presets_v5');
    if (saved) {
      try {
        setPresets(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse presets", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('nanoframe_presets_v5', JSON.stringify(presets));
  }, [presets]);

  // --- Handlers ---

  const handlePromptChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newVal = e.target.value;
    setPrompt(newVal);

    if (debounceRef.current) clearTimeout(debounceRef.current);

    debounceRef.current = setTimeout(() => {
      setPromptHistory(prev => {
        const newHistory = prev.slice(0, historyIndex + 1);
        newHistory.push(newVal);
        return newHistory;
      });
      setHistoryIndex(prev => prev + 1);
    }, 400);
  };

  const handleUndo = () => {
    if (historyIndex > 0) {
      const newIndex = historyIndex - 1;
      setHistoryIndex(newIndex);
      setPrompt(promptHistory[newIndex]);
    }
  };

  const handleRedo = () => {
    if (historyIndex < promptHistory.length - 1) {
      const newIndex = historyIndex + 1;
      setHistoryIndex(newIndex);
      setPrompt(promptHistory[newIndex]);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = async (event) => {
        if (event.target?.result) {
          const base64 = event.target.result as string;
          setUploadedImage(base64);
          setIsDetectingStyle(true);
          try {
            const detectedStyleId = await detectImageStyle(base64);
            if (detectedStyleId) {
                const cleanId = detectedStyleId.trim();
                const matchedStyle = ART_STYLES.find(s => cleanId.includes(s.id));
                if (matchedStyle) {
                    setSelectedStyleId(matchedStyle.id);
                    setLastAutoSelectedStyleId(matchedStyle.id);
                    setTimeout(() => setLastAutoSelectedStyleId(null), 3000);
                }
            }
          } catch (err) {
            console.warn("Style detection failed", err);
          } finally {
            setIsDetectingStyle(false);
          }
        }
      };
      reader.readAsDataURL(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const clearUploadedImage = () => setUploadedImage(null);

  const handleSavePreset = () => {
    if (!newPresetName.trim()) return;

    const newPreset: GenerationPreset = {
      id: crypto.randomUUID(),
      name: newPresetName.trim(),
      prompt: prompt,
      styleId: selectedStyleId,
      aspectRatio: aspectRatio,
      seed: seed,
      creativity: creativity,
      timestamp: Date.now(),
      referenceImage: uploadedImage,
      lightSourceId: lightSourceId,
      lightDirectionId: lightDirectionId
    };

    setPresets(prev => [newPreset, ...prev]);
    setLastLoadedPresetId(newPreset.id);
    setNewPresetName('');
    setIsSavingPreset(false);

    // Clear last saved selection highlight after a delay
    setTimeout(() => setLastLoadedPresetId(null), 2000);
  };

  const handleUpdatePresetName = (id: string) => {
    if (!editNameValue.trim()) {
      setEditingPresetId(null);
      return;
    }
    setPresets(prev => prev.map(p => p.id === id ? { ...p, name: editNameValue.trim() } : p));
    setEditingPresetId(null);
  };

  const loadPreset = (p: GenerationPreset) => {
    setPrompt(p.prompt);
    setSelectedStyleId(p.styleId);
    setAspectRatio(p.aspectRatio);
    setSeed(p.seed);
    setCreativity(p.creativity);
    setUploadedImage(p.referenceImage || null);
    setLightSourceId(p.lightSourceId || 'auto');
    setLightDirectionId(p.lightDirectionId || 'auto');
    setLastLoadedPresetId(p.id);

    setPromptHistory(prev => {
      const newHistory = prev.slice(0, historyIndex + 1);
      newHistory.push(p.prompt);
      return newHistory;
    });
    setHistoryIndex(prev => prev + 1);

    // Visual confirmation
    setTimeout(() => setLastLoadedPresetId(null), 1500);
  };

  const deletePreset = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm("Delete this preset from your library?")) {
      setPresets(prev => prev.filter(p => p.id !== id));
      if (lastLoadedPresetId === id) setLastLoadedPresetId(null);
    }
  };

  const resetWorkspace = () => {
    if (confirm("Reset current laboratory settings? This will clear your prompt and image.")) {
      setPrompt('');
      setSelectedStyleId(ART_STYLES[0].id);
      setAspectRatio('1:1');
      setSeed(undefined);
      setCreativity(50);
      setUploadedImage(null);
      setLightSourceId('auto');
      setLightDirectionId('auto');
      setPromptHistory(['']);
      setHistoryIndex(0);
      setStatus('idle');
      setCurrentImage(null);
    }
  };

  const handleQuickStart = (p: string, style?: string) => {
    setPrompt(p);
    if (style) setSelectedStyleId(style);
    setTimeout(() => {
        handleGenerate();
    }, 100);
  };

  const handleGenerate = async () => {
    const currentPrompt = prompt.trim();
    if (!currentPrompt && !uploadedImage) {
        setErrorMsg("Please enter a text prompt or upload an image to start.");
        setStatus('error');
        return;
    }

    setStatus('generating');
    setErrorMsg(null);
    setCurrentImage(null);
    setIsEditing(false);

    if (window.innerWidth < 768) previewRef.current?.scrollIntoView({ behavior: 'smooth' });

    try {
      const base64Image = await generateImageWithNano(
          currentPrompt, 
          selectedStyleId, 
          aspectRatio, 
          seed, 
          creativity, 
          uploadedImage,
          lightSourceId,
          lightDirectionId
      );

      const newImage: GeneratedImage = {
        id: crypto.randomUUID(),
        url: base64Image,
        prompt: currentPrompt || 'Image Variation',
        styleId: selectedStyleId,
        aspectRatio: aspectRatio,
        seed: seed,
        creativity: creativity,
        referenceImage: uploadedImage,
        lightSourceId: lightSourceId,
        lightDirectionId: lightDirectionId,
        timestamp: Date.now()
      };

      setCurrentImage(newImage);
      setHistory(prev => [newImage, ...prev].slice(0, 10));
      setStatus('success');
    } catch (error) {
      console.error(error);
      setStatus('error');
      setErrorMsg("Failed to generate. Please try again.");
    }
  };

  const handleDownload = () => {
    if (!currentImage) return;
    const link = document.createElement('a');
    link.href = currentImage.url;
    link.download = `${APP_NAME.toLowerCase()}-${currentImage.id.slice(0, 8)}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const loadFromHistory = (img: GeneratedImage) => {
    setCurrentImage(img);
    setPrompt(img.prompt);
    setPromptHistory(prev => [...prev.slice(0, historyIndex + 1), img.prompt]);
    setHistoryIndex(prev => prev + 1);
    setSelectedStyleId(img.styleId);
    setAspectRatio(img.aspectRatio || '1:1');
    setSeed(img.seed);
    setCreativity(img.creativity ?? 50);
    setUploadedImage(img.referenceImage || null);
    setLightSourceId(img.lightSourceId || 'auto');
    setLightDirectionId(img.lightDirectionId || 'auto');
    setStatus('success');
    setIsEditing(false);
    if (window.innerWidth < 768) previewRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleSaveEdit = (newImageSrc: string) => {
     if (!currentImage) return;
     const newImage: GeneratedImage = {
        ...currentImage,
        id: crypto.randomUUID(),
        url: newImageSrc,
        timestamp: Date.now()
     };
     setCurrentImage(newImage);
     setHistory(prev => [newImage, ...prev].slice(0, 10));
     setIsEditing(false);
  };

  const filteredPresets = presets.filter(p => 
    p.name.toLowerCase().includes(presetSearch.toLowerCase()) ||
    p.prompt.toLowerCase().includes(presetSearch.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-nano-50 text-white selection:bg-white selection:text-nano-50 flex flex-col font-sans">

      <header className="bg-nano-100/80 backdrop-blur-xl sticky top-0 z-50 border-b border-white/10 shadow-lg">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 bg-white rounded-xl flex items-center justify-center text-nano-50 shadow-xl shadow-white/5">
              <Camera size={20} />
            </div>
            <h1 className="text-xl font-extrabold tracking-tight text-white">{APP_NAME}</h1>
            <Badge text={MODEL_NAME_DISPLAY} />
          </div>
          <div className="flex items-center gap-6">
             <button onClick={resetWorkspace} className="text-xs font-bold text-white/50 hover:text-red-400 flex items-center gap-1.5 transition-all">
               <Eraser size={14} /> Clear Engine
             </button>
             <div className="hidden sm:block w-px h-6 bg-white/10"></div>
             <div className="hidden sm:flex text-sm text-white/40 font-bold uppercase tracking-[0.2em]">Studio PRO</div>
          </div>
        </div>
      </header>

      <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full flex flex-col lg:flex-row gap-8 lg:gap-12">

        {/* Left Column: Laboratory Controls */}
        <aside className="w-full lg:w-1/3 flex flex-col gap-8 order-2 lg:order-1">

          {/* --- MY PRESETS SECTION --- */}
          <section className="bg-nano-100 rounded-3xl border border-white/10 overflow-hidden shadow-2xl flex flex-col">
            <div className="p-5 border-b border-white/5 flex items-center justify-between bg-white/5">
              <button 
                onClick={() => setShowPresets(!showPresets)}
                className="flex items-center gap-2.5 text-sm font-black text-white focus:outline-none"
              >
                <Bookmark size={18} className={presets.length > 0 ? "text-emerald-400 fill-emerald-400" : "text-white/20"} />
                <span className="uppercase tracking-widest">My Presets</span>
                {presets.length > 0 && (
                  <span className="bg-white/10 text-white text-[10px] px-2 py-0.5 rounded-full font-black">
                    {presets.length}
                  </span>
                )}
                {showPresets ? <ChevronUp size={14} className="text-white/40" /> : <ChevronDown size={14} className="text-white/40" />}
              </button>

              <div className="flex items-center gap-1">
                  {!isSavingPreset && (
                    <button 
                      onClick={() => setIsSavingPreset(true)}
                      className="p-2 rounded-xl text-white/40 hover:text-white hover:bg-white/10 transition-all flex items-center gap-1.5"
                      title="Save current state"
                    >
                      <Plus size={18} />
                      <span className="text-[10px] font-black uppercase tracking-widest hidden sm:inline">Add</span>
                    </button>
                  )}
              </div>
            </div>

            {isSavingPreset && (
              <div className="p-5 bg-white/5 border-b border-white/5 animate-in slide-in-from-top-2">
                <div className="space-y-4">
                  <div className="flex justify-between items-center">
                    <span className="text-[10px] font-black uppercase tracking-widest text-emerald-400">New Configuration</span>
                    <button onClick={() => setIsSavingPreset(false)}><X size={14} className="text-white/20" /></button>
                  </div>
                  <input 
                    autoFocus
                    type="text"
                    placeholder="E.g., Cinematic Portrait v1"
                    value={newPresetName}
                    onChange={(e) => setNewPresetName(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleSavePreset()}
                    className="w-full p-3 text-sm rounded-xl border border-white/10 bg-nano-50 text-white placeholder:text-white/20 focus:outline-none focus:ring-1 focus:ring-emerald-400 transition-all"
                  />
                  <Button onClick={handleSavePreset} className="w-full !py-2.5 !text-[10px]" icon={<Save size={14} />}>Save Current Setup</Button>
                </div>
              </div>
            )}

            {showPresets && (
              <div className="flex flex-col h-[400px]">
                {/* Search Bar */}
                {presets.length > 0 && (
                    <div className="px-4 py-3 border-b border-white/5 bg-black/10">
                        <div className="relative">
                            <Search size={12} className="absolute left-3 top-1/2 -translate-y-1/2 text-white/20" />
                            <input 
                            type="text" 
                            placeholder="Filter presets..." 
                            value={presetSearch}
                            onChange={(e) => setPresetSearch(e.target.value)}
                            className="w-full pl-9 pr-4 py-2 bg-transparent border border-white/5 rounded-xl text-[10px] font-bold tracking-wider placeholder:text-white/10 focus:outline-none focus:border-white/20 transition-all uppercase"
                            />
                        </div>
                    </div>
                )}

                <div className="flex-grow p-3 space-y-2 overflow-y-auto hide-scrollbar">
                    {filteredPresets.length === 0 ? (
                    <div className="h-full flex flex-col items-center justify-center opacity-30 px-8 text-center">
                        <Bookmark size={32} className="mb-4" />
                        <p className="text-[10px] font-black text-white uppercase tracking-[0.3em] leading-relaxed">
                            {presets.length === 0 
                                ? "No saved presets. Use the '+' icon above to store your favorite engine configurations." 
                                : "No presets match your search."}
                        </p>
                    </div>
                    ) : (
                    filteredPresets.map((p) => (
                        <div
                        key={p.id}
                        onClick={() => loadPreset(p)}
                        className={`group relative flex flex-col p-4 rounded-2xl border transition-all cursor-pointer ${lastLoadedPresetId === p.id ? 'border-emerald-500 bg-emerald-500/10' : 'border-white/5 hover:bg-white/10 bg-white/2'}`}
                        >
                        <div className="flex justify-between items-start gap-2">
                            <div className="min-w-0 flex-grow">
                                {editingPresetId === p.id ? (
                                    <div className="flex items-center gap-2" onClick={e => e.stopPropagation()}>
                                        <input 
                                            autoFocus
                                            type="text"
                                            value={editNameValue}
                                            onChange={(e) => setEditNameValue(e.target.value)}
                                            onKeyDown={(e) => e.key === 'Enter' && handleUpdatePresetName(p.id)}
                                            onBlur={() => handleUpdatePresetName(p.id)}
                                            className="bg-nano-100 border border-white/20 rounded px-2 py-0.5 text-xs text-white focus:outline-none"
                                        />
                                        <button onClick={() => handleUpdatePresetName(p.id)} className="text-emerald-400"><Check size={14} /></button>
                                    </div>
                                ) : (
                                    <p className="text-xs font-black text-white truncate group-hover:text-emerald-400 transition-colors uppercase tracking-wider">{p.name}</p>
                                )}
                                <div className="flex items-center gap-2 mt-2">
                                    <Badge text={ART_STYLES.find(s => s.id === p.styleId)?.name || 'Custom'} />
                                    {p.referenceImage && (
                                        <div className="flex items-center gap-1 text-[8px] font-black text-emerald-400/60 uppercase tracking-widest border border-emerald-400/20 px-1.5 py-0.5 rounded">
                                            <ImageIcon size={8} /> Ref
                                        </div>
                                    )}
                                </div>
                            </div>

                            <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-all shrink-0">
                                <button 
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        setEditingPresetId(p.id);
                                        setEditNameValue(p.name);
                                    }} 
                                    className="p-1.5 text-white/20 hover:text-white"
                                    title="Rename"
                                >
                                    <Edit2 size={13} />
                                </button>
                                <button onClick={(e) => deletePreset(p.id, e)} className="p-1.5 text-white/20 hover:text-red-400" title="Delete">
                                    <Trash2 size={13} />
                                </button>
                            </div>
                        </div>

                        {lastLoadedPresetId === p.id && (
                            <div className="absolute top-2 right-2 animate-in zoom-in duration-300">
                                <CheckCircle2 size={14} className="text-emerald-500" />
                            </div>
                        )}
                        </div>
                    ))
                    )}
                </div>
              </div>
            )}
          </section>

          {/* --- PROMPT INPUT --- */}
          <section className="space-y-4">
            <div className="flex justify-between items-end">
              <div className="space-y-1">
                <label className="block text-xs font-black text-white uppercase tracking-[0.2em]">1. Visual Prompt</label>
                <p className="text-[10px] text-white/40 font-bold">Describe your desired masterpiece</p>
              </div>
              <div className="flex gap-1">
                <button onClick={handleUndo} disabled={historyIndex === 0} className="p-2 text-white/30 hover:text-white disabled:opacity-10 transition-all"><Undo size={14} /></button>
                <button onClick={handleRedo} disabled={historyIndex >= promptHistory.length - 1} className="p-2 text-white/30 hover:text-white disabled:opacity-10 transition-all"><Redo size={14} /></button>
              </div>
            </div>
            <textarea
              id="prompt"
              value={prompt}
              onChange={handlePromptChange}
              placeholder="A futuristic cyber-city with neon reflections..."
              className="w-full p-5 rounded-3xl border border-white/10 bg-nano-100 shadow-inner text-white placeholder:text-white/20 focus:outline-none focus:ring-2 focus:ring-white h-40 transition-all resize-none text-sm font-medium leading-relaxed"
            />
          </section>

          {/* --- STYLE PRESETS --- */}
          <section className="space-y-4">
            <label className="block text-xs font-black text-white uppercase tracking-[0.2em]">2. Visual Aesthetic</label>
            <div className="grid grid-cols-2 gap-3">
              {ART_STYLES.map((style) => (
                <StyleCard 
                  key={style.id} 
                  style={style} 
                  isSelected={selectedStyleId === style.id} 
                  isAutoSelected={lastAutoSelectedStyleId === style.id}
                  onClick={() => setSelectedStyleId(style.id)} 
                />
              ))}
            </div>
          </section>

          {/* --- VISUAL REFERENCE --- */}
