import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Button } from './UI';
import { 
  Check, 
  X, 
  Crop, 
  Wand2, 
  ZoomIn, 
  RotateCcw, 
  Loader2, 
  Sliders, 
  Sun, 
  Contrast, 
  Lock, 
  Unlock,
  Palette,
  Droplets,
  Eye,
  Sparkles,
  Zap,
  Undo,
  Redo,
  BrainCircuit,
  Settings2
} from 'lucide-react';
import { IMAGE_FILTERS, ASPECT_RATIOS } from '../constants';
import { generateImageWithNano } from '../services/geminiService';

interface ImageEditorProps {
  imageSrc: string;
  prompt: string;
  styleId: string;
  initialCreativity: number;
  lightSourceId?: string;
  lightDirectionId?: string;
  onSave: (newImageSrc: string) => void;
  onCancel: () => void;
}

// Define the shape of our history state
type EditorState = {
  imageSrc: string;
  filterId: string;
  adjustments: {
    brightness: number;
    contrast: number;
    saturation: number;
    hueRotate: number;
    creativity: number;
  };
  transform: {
    zoom: number;
    cropRatio: string;
    pan: { x: number; y: number };
    isRatioLocked: boolean;
  };
};

export const ImageEditor: React.FC<ImageEditorProps> = ({ 
  imageSrc: initialImageSrc, 
  prompt, 
  styleId, 
  initialCreativity,
  lightSourceId = 'auto',
  lightDirectionId = 'auto',
  onSave, 
  onCancel 
}) => {
  const [activeTab, setActiveTab] = useState<'filter' | 'adjust' | 'crop'>('filter');
  const [selectedFilterId, setSelectedFilterId] = useState('none');
  const [hoveredFilterId, setHoveredFilterId] = useState<string | null>(null);
  const [imageLoaded, setImageLoaded] = useState(false);
  const [currentImageSrc, setCurrentImageSrc] = useState(initialImageSrc);
  const [isRefining, setIsRefining] = useState(false);

  // Adjustment state
  const [brightness, setBrightness] = useState(100); 
  const [contrast, setContrast] = useState(100);   
  const [saturation, setSaturation] = useState(100); 
  const [hueRotate, setHueRotate] = useState(0);    
  const [creativity, setCreativity] = useState(initialCreativity);

  // Crop state
  const [zoom, setZoom] = useState(1);
  const [cropRatio, setCropRatio] = useState<string>('1:1');
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [isRatioLocked, setIsRatioLocked] = useState(true);

  // Interaction state
  const [isDragging, setIsDragging] = useState(false);
  const [isResetting, setIsResetting] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  // History state
  const [history, setHistory] = useState<EditorState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  const imageRef = useRef<HTMLImageElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // --- History Helpers ---

  // Construct the current state object from active variables
  const getCurrentState = useCallback((overrides: Partial<EditorState> = {}): EditorState => ({
    imageSrc: currentImageSrc,
    filterId: selectedFilterId,
    adjustments: { brightness, contrast, saturation, hueRotate, creativity },
    transform: { zoom, cropRatio, pan, isRatioLocked },
    ...overrides
  }), [currentImageSrc, selectedFilterId, brightness, contrast, saturation, hueRotate, creativity, zoom, cropRatio, pan, isRatioLocked]);

  // Initialize history on mount
  useEffect(() => {
    if (history.length === 0) {
      const initialState = getCurrentState();
      setHistory([initialState]);
      setHistoryIndex(0);
    }
  }, []); // Run once on mount

  const pushToHistory = (newState: EditorState) => {
    if (historyIndex >= 0) {
      const currentState = history[historyIndex];
      if (JSON.stringify(currentState) === JSON.stringify(newState)) return;
    }

    const newHistory = history.slice(0, historyIndex + 1);
    newHistory.push(newState);
    setHistory(newHistory);
    setHistoryIndex(newHistory.length - 1);
  };

  const handleUndo = () => {
    if (historyIndex > 0) {
      const newIndex = historyIndex - 1;
      setHistoryIndex(newIndex);
      restoreState(history[newIndex]);
    }
  };

  const handleRedo = () => {
    if (historyIndex < history.length - 1) {
      const newIndex = historyIndex + 1;
      setHistoryIndex(newIndex);
      restoreState(history[newIndex]);
    }
  };

  const restoreState = (state: EditorState) => {
    setCurrentImageSrc(state.imageSrc);
    setSelectedFilterId(state.filterId);
    setBrightness(state.adjustments.brightness);
    setContrast(state.adjustments.contrast);
    setSaturation(state.adjustments.saturation);
    setHueRotate(state.adjustments.hueRotate);
    setCreativity(state.adjustments.creativity);
    setZoom(state.transform.zoom);
    setCropRatio(state.transform.cropRatio);
    setPan(state.transform.pan);
    setIsRatioLocked(state.transform.isRatioLocked);
  };

  // --- Logic ---

  const getMinZoom = useCallback(() => {
    if (!imageRef.current || !containerRef.current) return 1;
    const img = imageRef.current;
    const container = containerRef.current;

    const containerAspect = container.clientWidth / container.clientHeight;
    const imgAspect = img.naturalWidth / img.naturalHeight;

    if (imgAspect > containerAspect) {
      return 1; 
    } else {
      return containerAspect / imgAspect;
    }
  }, []);

  const constrainPan = useCallback((currentPan: { x: number; y: number }, currentZoom: number) => {
    if (isResetting || !isRatioLocked || !imageRef.current || !containerRef.current) return currentPan;

    const img = imageRef.current;
    const container = containerRef.current;

    const imgAspect = img.naturalWidth / img.naturalHeight;
    const containerAspect = container.clientWidth / container.clientHeight;

    let displayWidth, displayHeight;
    if (imgAspect > containerAspect) {
      displayHeight = container.clientHeight;
      displayWidth = container.clientHeight * imgAspect;
    } else {
      displayWidth = container.clientWidth;
      displayHeight = container.clientWidth / imgAspect;
    }

    const scaledWidth = displayWidth * currentZoom;
    const scaledHeight = displayHeight * currentZoom;

    const maxX = Math.max(0, (scaledWidth - container.clientWidth) / 2) / currentZoom;
    const maxY = Math.max(0, (scaledHeight - container.clientHeight) / 2) / currentZoom;

    return {
      x: Math.min(Math.max(currentPan.x, -maxX), maxX),
      y: Math.min(Math.max(currentPan.y, -maxY), maxY)
    };
  }, [isRatioLocked, isResetting]);

  useEffect(() => {
    if (isRatioLocked && imageLoaded && !isResetting) {
      const minZoom = getMinZoom();
      if (zoom < minZoom) {
        setZoom(minZoom);
      }
      setPan(prev => constrainPan(prev, Math.max(zoom, minZoom)));
    }
  }, [isRatioLocked, cropRatio, imageLoaded, zoom, constrainPan, getMinZoom, isResetting]);

  const effectiveFilterId = hoveredFilterId || selectedFilterId;
  const activeFilterObject = IMAGE_FILTERS.find(f => f.id === effectiveFilterId);
  const baseFilter = activeFilterObject?.filter || 'none';
  const currentFilter = `${baseFilter === 'none' ? '' : baseFilter} brightness(${brightness}%) contrast(${contrast}%) saturate(${saturation}%) hue-rotate(${hueRotate}deg)`;

  const handlePointerDown = (e: React.PointerEvent) => {
    if (isResetting) return;
    setIsDragging(true);
    setDragStart({ x: e.clientX - pan.x * zoom, y: e.clientY - pan.y * zoom });
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (isDragging) {
      const newPan = {
        x: (e.clientX - dragStart.x) / zoom,
        y: (e.clientY - dragStart.y) / zoom
      };
      setPan(constrainPan(newPan, zoom));
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (isDragging) {
      pushToHistory(getCurrentState());
    }
    setIsDragging(false);
    (e.target as HTMLElement).releasePointerCapture(e.pointerId);
  };

  const handleResetTransform = () => {
    if (isResetting) return;
    setIsResetting(true);
    const targetZoom = isRatioLocked ? getMinZoom() : 1;
    const targetPan = { x: 0, y: 0 };
    setZoom(targetZoom);
    setPan(targetPan);

    pushToHistory({
        ...getCurrentState(),
        transform: {
            zoom: targetZoom,
            pan: targetPan,
            cropRatio,
            isRatioLocked
        }
    });

    setTimeout(() => setIsResetting(false), 600);
  };

  const handleResetAdjustments = () => {
    setBrightness(100);
    setContrast(100);
    setSaturation(100);
    setHueRotate(0);
    setCreativity(initialCreativity);
    setSelectedFilterId('none');

    pushToHistory({
        ...getCurrentState(),
        filterId: 'none',
        adjustments: { brightness: 100, contrast: 100, saturation: 100, hueRotate: 0, creativity: initialCreativity }
    });
  };

  const getCanvasData = () => {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    const img = imageRef.current;

    if (!ctx || !img) return null;

    const outputSize = 1024;
    let width = outputSize;
    let height = outputSize;

    const [wRatio, hRatio] = cropRatio.split(':').map(Number);
    if (wRatio && hRatio) {
        if (wRatio > hRatio) {
            height = outputSize * (hRatio / wRatio);
        } else {
            width = outputSize * (wRatio / hRatio);
        }
    }

    canvas.width = width;
    canvas.height = height;
    ctx.fillStyle = '#000000';
    ctx.fillRect(0, 0, width, height);

    const container = containerRef.current;
    if (!container) return null;

    const scaleFactor = width / container.clientWidth;

    ctx.save();
    const saveBaseFilter = IMAGE_FILTERS.find(f => f.id === selectedFilterId)?.filter || 'none';
    ctx.filter = `${saveBaseFilter === 'none' ? '' : saveBaseFilter} brightness(${brightness}%) contrast(${contrast}%) saturate(${saturation}%) hue-rotate(${hueRotate}deg)`;

    ctx.translate(width / 2, height / 2);
    ctx.scale(zoom, zoom);
    ctx.translate(pan.x * scaleFactor, pan.y * scaleFactor);

    const imgAspect = img.naturalWidth / img.naturalHeight;
    const containerAspect = container.clientWidth / container.clientHeight;

    let drawWidth, drawHeight;
    if (imgAspect > containerAspect) {
        drawHeight = height / zoom;
        drawWidth = drawHeight * imgAspect;
    } else {
        drawWidth = width / zoom;
        drawHeight = drawWidth / imgAspect;
    }

    ctx.drawImage(img, -drawWidth / 2, -drawHeight / 2, drawWidth, drawHeight);
    ctx.restore();

    return canvas.toDataURL('image/png', 0.95);
  };

  const handleSave = () => {
    const dataUrl = getCanvasData();
    if (dataUrl) onSave(dataUrl);
  };

  const handleAIRefine = async () => {
    const referenceData = getCanvasData();
    if (!referenceData) return;

    setIsRefining(true);
    setImageLoaded(false);

    try {
      const newImage = await generateImageWithNano(
        prompt,
        styleId,
        cropRatio,
        undefined, // random seed
        creativity,
        referenceData,
        lightSourceId,
        lightDirectionId
      );

      setCurrentImageSrc(newImage);

      // Reset canvas filters because the new image already has the look
      setBrightness(100);
      setContrast(100);
      setSaturation(100);
      setHueRotate(0);
      setSelectedFilterId('none');
      setZoom(isRatioLocked ? getMinZoom() : 1);
      setPan({ x: 0, y: 0 });

      const newState: EditorState = {
         imageSrc: newImage,
         filterId: 'none',
         adjustments: { brightness: 100, contrast: 100, saturation: 100, hueRotate: 0, creativity: creativity },
         transform: { 
             zoom: isRatioLocked ? getMinZoom() : 1, 
             cropRatio, 
             pan: { x: 0, y: 0 }, 
             isRatioLocked 
         }
      };

      setHistory(prev => {
         const newHistory = prev.slice(0, historyIndex + 1);
         return [...newHistory, newState];
      });
      setHistoryIndex(prev => prev + 1);

    } catch (error) {
      console.error("AI Refine failed:", error);
      setImageLoaded(true);
    } finally {
      setIsRefining(false);
    }
  };

  const handleFilterSelect = (id: string) => {
    setSelectedFilterId(id);
    pushToHistory({ ...getCurrentState(), filterId: id });
  };

  const handleRatioSelect = (ratio: string) => {
    setCropRatio(ratio);
    pushToHistory({ ...getCurrentState(), transform: { ...getCurrentState().transform, cropRatio: ratio } });
  };

  const handleLockToggle = () => {
    const newLock = !isRatioLocked;
    setIsRatioLocked(newLock);
    pushToHistory({ ...getCurrentState(), transform: { ...getCurrentState().transform, isRatioLocked: newLock } });
  };

  return (
    <div className="fixed inset-0 z-[100] bg-nano-50/90 backdrop-blur-md flex flex-col h-full animate-in fade-in duration-300">
      <div className="h-16 border-b border-white/10 flex items-center justify-between px-6 bg-nano-100 shrink-0 shadow-xl">
        <div className="flex items-center gap-3">
            <button onClick={onCancel} className="p-2 text-white/40 hover:text-white hover:bg-white/5 rounded-xl transition-all active:scale-95 focus:outline-none">
                <X size={20} />
            </button>
            <div className="h-6 w-px bg-white/10 mx-1 hidden sm:block"></div>
            <div className="flex items-center gap-1">
                <button onClick={handleUndo} disabled={historyIndex <= 0} className="p-2 text-white/40 hover:text-white hover:bg-white/5 rounded-xl transition-all disabled:opacity-20 disabled:hover:bg-transparent" title="Undo Edit">
                   <Undo size={18} />
                </button>
                <button onClick={handleRedo} disabled={historyIndex >= history.length - 1} className="p-2 text-white/40 hover:text-white hover:bg-white/5 rounded-xl transition-all disabled:opacity-20 disabled:hover:bg-transparent" title="Redo Edit">
                   <Redo size={18} />
                </button>
            </div>
        </div>

        <div className="flex flex-col items-center">
            <span className="font-black text-[10px] uppercase tracking-[0.4em] text-white/30 mb-0.5">Retouch Station</span>
            <div className="flex items-center gap-1.5">
                <div className="w-1 h-1 bg-emerald-400 rounded-full animate-pulse"></div>
                <span className="text-[11px] font-black uppercase tracking-widest text-white">Capture v2.1</span>
            </div>
        </div>

        <div className="flex items-center gap-3">
            <button 
                onClick={handleAIRefine} 
                disabled={!imageLoaded || isRefining} 
                className={`
                    flex items-center gap-2 px-4 py-2 rounded-2xl transition-all font-black text-[10px] uppercase tracking-widest 
                    ${isRefining ? 'bg-emerald-500 text-white animate-pulse' : 'bg-emerald-500/10 text-emerald-400 hover:bg-emerald-500 hover:text-white shadow-[0_0_20px_rgba(16,185,129,0.2)]'}
                    disabled:opacity-30 disabled:pointer-events-none active:scale-95
                `}
                title="Use current view as basis for a new AI generation"
            >
                <Zap size={16} fill={isRefining ? "currentColor" : "none"} />
                <span className="hidden sm:block">Magic Refine</span>
            </button>
            <div className="h-6 w-px bg-white/10 mx-1"></div>
            <button 
                onClick={handleSave} 
                disabled={!imageLoaded || isRefining} 
                className="p-3 bg-white text-nano-50 hover:bg-white/90 rounded-2xl transition-all font-bold disabled:opacity-30 active:scale-95 shadow-xl"
                title="Save Edits and Return"
            >
                <Check size={20} strokeWidth={3} />
            </button>
        </div>
      </div>

      <div className="flex-grow overflow-hidden relative flex items-center justify-center p-8 sm:p-12 lg:p-16 select-none bg-nano-50">
        {hoveredFilterId && (
          <div className="absolute top-8 left-1/2 -translate-x-1/2 z-20 flex items-center gap-2.5 px-5 py-2.5 bg-white text-nano-50 rounded-full shadow-2xl animate-in slide-in-from-top-4 border border-white/20">
            <Eye size={14} className="animate-pulse text-emerald-500" />
            <span className="text-[10px] font-black uppercase tracking-widest">Previewing: {activeFilterObject?.name}</span>
          </div>
        )}

        {(!imageLoaded || isRefining) && (
          <div className="absolute inset-0 z-30 flex flex-col items-center justify-center bg-nano-50/80 backdrop-blur-xl">
             <div className="relative mb-8">
                <div className="absolute inset-0 bg-emerald-400/20 blur-2xl rounded-full animate-pulse"></div>
                <BrainCircuit className="w-12 h-12 text-white animate-bounce relative z-10" />
             </div>
             {isRefining ? (
                 <div className="flex flex-col items-center gap-3">
                    <span className="text-[11px] font-black uppercase tracking-[0.6em] text-white animate-pulse">Synthesizing Vision</span>
                    <p className="text-[9px] font-bold text-white/30 uppercase tracking-widest">Iterating on your current canvas...</p>
                 </div>
             ) : (
                 <Loader2 className="w-8 h-8 text-white/20 animate-spin" />
             )}
          </div>
        )}

        <div 
          ref={containerRef}
          className="relative bg-black overflow-hidden shadow-[0_40px_100px_rgba(0,0,0,0.8)] ring-1 ring-white/10 rounded-sm"
          style={{
             aspectRatio: cropRatio.replace(':', '/'),
             width: '100%',
             maxWidth: '100%',
             maxHeight: '100%',
             cursor: isDragging ? 'grabbing' : 'grab',
             touchAction: 'none'
          }}
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={handlePointerUp}
          onPointerLeave={handlePointerUp}
        >
           <img 
             ref={imageRef}
             src={currentImageSrc} 
             alt="Editing"
             loading="lazy"
             decoding="async"
             onLoad={() => setImageLoaded(true)}
             className={`absolute max-w-none max-h-none origin-center pointer-events-none transition-opacity duration-500 ${imageLoaded ? 'opacity-100' : 'opacity-0'}`}
             style={{
                top: '50%',
                left: '50%',
                transform: `translate(-50%, -50%) scale(${zoom}) translate(${pan.x}px, ${pan.y}px)`,
                filter: currentFilter,
                minWidth: '100%',
                minHeight: '100%',
                transition: isResetting 
                  ? 'transform 0.6s cubic-bezier(0.25, 1, 0.5, 1), filter 0.3s ease' 
                  : (isDragging ? 'none' : 'transform 0.1s ease-out, filter 0.25s ease-out')
             }}
             draggable={false}
           />

           {/* Crop Guides */}
           {activeTab === 'crop' && (
             <div className="absolute inset-0 pointer-events-none border border-white/20 ring-[2000px] ring-black/40">
                <div className="absolute top-1/3 left-0 right-0 h-px bg-white/20"></div>
                <div className="absolute top-2/3 left-0 right-0 h-px bg-white/20"></div>
                <div className="absolute left-1/3 top-0 bottom-0 w-px bg-white/20"></div>
                <div className="absolute left-2/3 top-0 bottom-0 w-px bg-white/20"></div>
             </div>
           )}
        </div>
      </div>

      <div className="bg-nano-100 border-t border-white/10 shrink-0 pb-safe shadow-[0_-10px_60px_rgba(0,0,0,0.7)] z-10">
        <div className="flex border-b border-white/5">
           <button onClick={() => setActiveTab('filter')} className={`flex-1 py-4 text-[10px] uppercase font-bold tracking-[0.3em] flex items-center justify-center gap-2.5 focus:outline-none transition-all ${activeTab === 'filter' ? 'text-white bg-white/5 border-b-2 border-white' : 'text-white/30 hover:text-white/60'}`}>
             <Wand2 size={16} /> Filters
           </button>
           <button onClick={() => setActiveTab('adjust')} className={`flex-1 py-4 text-[10px] uppercase font-bold tracking-[0.3em] flex items-center justify-center gap-2.5 focus:outline-none transition-all ${activeTab === 'adjust' ? 'text-white bg-white/5 border-b-2 border-white' : 'text-white/30 hover:text-white/60'}`}>
             <Sliders size={16} /> Adjustments
           </button>
           <button onClick={() => setActiveTab('crop')} className={`flex-1 py-4 text-[10px] uppercase font-bold tracking-[0.3em] flex items-center justify-center gap-2.5 focus:outline-none transition-all ${activeTab === 'crop' ? 'text-white bg-white/5 border-b-2 border-white' : 'text-white/30 hover:text-white/60'}`}>
             <Crop size={16} /> Composition
           </button>
        </div>

        <div className="h-56 p-6 overflow-y-auto hide-scrollbar bg-black/20">
           {activeTab === 'filter' && (
             <div className="flex gap-5 overflow-x-auto pb-4 hide-scrollbar h-full items-center">
                {IMAGE_FILTERS.map((f) => (
                   <button 
                     key={f.id}
                     onClick={() => handleFilterSelect(f.id)}
                     onMouseEnter={() => setHoveredFilterId(f.id)}
                     onMouseLeave={() => setHoveredFilterId(null)}
                     className="flex flex-col items-center gap-3 shrink-0 group focus:outline-none"
                   >
                      <div className={`w-16 h-16 rounded-2xl overflow-hidden border-2 transition-all duration-300 ${selectedFilterId === f.id ? 'border-white ring-4 ring-white/10 scale-105' : 'border-white/5 group-hover:border-white/30 group-hover:scale-110'}`}>
                         <img src={currentImageSrc} alt={f.name} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-125" style={{ filter: f.filter }} />
                      </div>
                      <span className={`text-[10px] font-black uppercase tracking-widest transition-colors ${selectedFilterId === f.id || hoveredFilterId === f.id ? 'text-white' : 'text-white/20'}`}>{f.name}</span>
                   </button>
                ))}
             </div>
           )}

           {activeTab === 'adjust' && (
             <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-4 max-w-4xl mx-auto h-full">
                <div className="space-y-4">
                    <div className="flex items-center gap-4 group">
                    <div className="flex items-center gap-2.5 w-32 shrink-0">
                        <Sun size={14} className="text-white group-hover:text-amber-400 transition-colors" />
                        <span className="text-[10px] font-black uppercase tracking-widest text-white/60">Brightness</span>
                    </div>
                    <input 
                        type="range" min="0" max="200" step="1" 
                        value={brightness} 
                        onChange={(e) => setBrightness(parseInt(e.target.value))} 
                        onPointerUp={() => pushToHistory(getCurrentState())}
                        className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-white" 
                    />
                    <span className="text-[10px] font-mono w-10 text-right text-white/30">{brightness}%</span>
                    </div>

                    <div className="flex items-center gap-4 group">
                    <div className="flex items-center gap-2.5 w-32 shrink-0">
                        <Contrast size={14} className="text-white group-hover:text-blue-400 transition-colors" />
                        <span className="text-[10px] font-black uppercase tracking-widest text-white/60">Contrast</span>
                    </div>
                    <input 
                        type="range" min="0" max="200" step="1" 
                        value={contrast} 
                        onChange={(e) => setContrast(parseInt(e.target.value))} 
                        onPointerUp={() => pushToHistory(getCurrentState())}
                        className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-white" 
                    />
                    <span className="text-[10px] font-mono w-10 text-right text-white/30">{contrast}%</span>
                    </div>

                    <div className="flex items-center gap-4 group">
                    <div className="flex items-center gap-2.5 w-32 shrink-0">
                        <Droplets size={14} className="text-white group-hover:text-sky-400 transition-colors" />
                        <span className="text-[10px] font-black uppercase tracking-widest text-white/60">Saturation</span>
                    </div>
                    <input 
                        type="range" min="0" max="200" step="1" 
                        value={saturation} 
                        onChange={(e) => setSaturation(parseInt(e.target.value))} 
                        onPointerUp={() => pushToHistory(getCurrentState())}
                        className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-white" 
                    />
                    <span className="text-[10px] font-mono w-10 text-right text-white/30">{saturation}%</span>
                    </div>
                </div>

                <div className="space-y-4">
                    <div className="flex items-center gap-4 group">
                        <div className="flex items-center gap-2.5 w-32 shrink-0">
                            <Palette size={14} className="text-white group-hover:text-purple-400 transition-colors" />
                            <span className="text-[10px] font-black uppercase tracking-widest text-white/60">Hue Shift</span>
                        </div>
                        <input 
                            type="range" min="-180" max="180" step="1" 
                            value={hueRotate} 
                            onChange={(e) => setHueRotate(parseInt(e.target.value))} 
                            onPointerUp={() => pushToHistory(getCurrentState())}
                            className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-white" 
                        />
                        <span className="text-[10px] font-mono w-10 text-right text-white/30">{hueRotate}°</span>
                    </div>

                    <div className="p-4 rounded-2xl bg-emerald-500/5 border border-emerald-500/10 space-y-3">
                        <div className="flex items-center justify-between mb-1">
                            <div className="flex items-center gap-2.5">
                                <BrainCircuit size={14} className="text-emerald-400" />
                                <span className="text-[10px] font-black uppercase tracking-widest text-emerald-400">Refine Influence</span>
                            </div>
                            <span className="text-[10px] font-black text-emerald-400 bg-emerald-400/10 px-2 py-0.5 rounded-full">{creativity}%</span>
                        </div>
                        <input 
                            type="range" min="0" max="100" step="1" 
                            value={creativity} 
                            onChange={(e) => setCreativity(parseInt(e.target.value))} 
                            onPointerUp={() => pushToHistory(getCurrentState())}
                            className="w-full h-1 bg-emerald-500/10 rounded-full appearance-none cursor-pointer accent-emerald-400" 
                        />
                        <p className="text-[8px] font-bold text-emerald-400/50 uppercase tracking-widest">Controls how much the AI re-imagines the reference image during refinement.</p>
                    </div>

                    <div className="flex justify-end">
                       <button onClick={handleResetAdjustments} className="flex items-center gap-2 text-[9px] font-black uppercase tracking-[0.2em] text-white/20 hover:text-white transition-all">
                           <RotateCcw size={10} /> Reset All
                       </button>
                    </div>
                </div>
             </div>
           )}

           {activeTab === 'crop' && (
             <div className="flex flex-col gap-6 h-full justify-center max-w-2xl mx-auto">
                <div className="flex items-center gap-5 px-2">
                   <div className="p-2.5 bg-white/5 rounded-xl text-white">
                      <ZoomIn size={18} />
                   </div>
                   <input 
                     type="range" 
                     min={isRatioLocked ? getMinZoom() : 0.5} 
                     max="4" 
                     step="0.01"
                     value={zoom}
                     onChange={(e) => {
                       const val = parseFloat(e.target.value);
                       setZoom(val);
                       setPan(prev => constrainPan(prev, val));
                     }}
                     onPointerUp={() => pushToHistory(getCurrentState())}
                     className="w-full h-1.5 bg-white/10 rounded-full appearance-none cursor-pointer accent-white"
                   />
                   <div className="flex gap-2">
                     <button 
                        onClick={handleLockToggle} 
                        className={`p-3 rounded-2xl transition-all active:scale-90 border ${isRatioLocked ? 'bg-white text-nano-50 border-white' : 'text-white/40 border-white/5 hover:bg-white/5'}`} 
                        title={isRatioLocked ? "Unlock Viewport" : "Lock Viewport"}
                     >
                       {isRatioLocked ? <Lock size={16} /> : <Unlock size={16} />}
                     </button>
                     <button 
                        onClick={handleResetTransform} 
                        className="p-3 text-white/40 hover:text-white hover:bg-white/5 border border-white/5 rounded-2xl transition-all active:scale-90"
                        title="Reset Zoom/Pan"
                     >
                       <RotateCcw size={16} />
                     </button>
                   </div>
                </div>

                <div className="flex gap-3 overflow-x-auto pb-1 hide-scrollbar justify-center">
                   {['1:1', '16:9', '9:16', '4:3', '3:4'].map(r => (
                     <button 
                        key={r} 
                        onClick={() => handleRatioSelect(r)} 
                        className={`
                            px-6 py-2 rounded-2xl border text-[10px] font-black uppercase tracking-widest whitespace-nowrap transition-all
                            ${cropRatio === r ? 'bg-white text-nano-50 border-white shadow-lg' : 'border-white/10 text-white/40 hover:border-white/30 hover:text-white'}
                        `}
                     >
                        {r === '1:1' ? 'Square' : r}
                     </button>
                   ))}
                </div>
             </div>
           )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Button } from './UI';
import { 
  Check, 
  X, 
  Crop, 
  Wand2, 
  ZoomIn, 
  RotateCcw, 
  Loader2, 
  Sliders, 
  Sun, 
  Contrast, 
  Lock, 
  Unlock,
  Palette,
  Droplets,
  Eye,
  Sparkles,
  Zap,
  Undo,
  Redo,
  BrainCircuit,
  Settings2
} from 'lucide-react';
import { IMAGE_FILTERS, ASPECT_RATIOS } from '../constants';
import { generateImageWithNano } from '../services/geminiService';

interface ImageEditorProps {
  imageSrc: string;
  prompt: string;
  styleId: string;
  initialCreativity: number;
  lightSourceId?: string;
  lightDirectionId?: string;
  onSave: (newImageSrc: string) => void;
  onCancel: () => void;
}

// Define the shape of our history state
type EditorState = {
  imageSrc: string;
  filterId: string;
  adjustments: {
    brightness: number;
    contrast: number;
    saturation: number;
    hueRotate: number;
    creativity: number;
  };
  transform: {
    zoom: number;
    cropRatio: string;
    pan: { x: number; y: number };
    isRatioLocked: boolean;
  };
};

export const ImageEditor: React.FC<ImageEditorProps> = ({ 
  imageSrc: initialImageSrc, 
  prompt, 
  styleId, 
  initialCreativity,
  lightSourceId = 'auto',
  lightDirectionId = 'auto',
  onSave, 
  onCancel 
}) => {
  const [activeTab, setActiveTab] = useState<'filter' | 'adjust' | 'crop'>('filter');
  const [selectedFilterId, setSelectedFilterId] = useState('none');
  const [hoveredFilterId, setHoveredFilterId] = useState<string | null>(null);
  const [imageLoaded, setImageLoaded] = useState(false);
  const [currentImageSrc, setCurrentImageSrc] = useState(initialImageSrc);
  const [isRefining, setIsRefining] = useState(false);

  // Adjustment state
  const [brightness, setBrightness] = useState(100); 
  const [contrast, setContrast] = useState(100);   
  const [saturation, setSaturation] = useState(100); 
  const [hueRotate, setHueRotate] = useState(0);    
  const [creativity, setCreativity] = useState(initialCreativity);

  // Crop state
  const [zoom, setZoom] = useState(1);
  const [cropRatio, setCropRatio] = useState<string>('1:1');
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [isRatioLocked, setIsRatioLocked] = useState(true);

  // Interaction state
  const [isDragging, setIsDragging] = useState(false);
  const [isResetting, setIsResetting] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  // History state
  const [history, setHistory] = useState<EditorState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  const imageRef = useRef<HTMLImageElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // --- History Helpers ---

  // Construct the current state object from active variables
  const getCurrentState = useCallback((overrides: Partial<EditorState> = {}): EditorState => ({
    imageSrc: currentImageSrc,
    filterId: selectedFilterId,
    adjustments: { brightness, contrast, saturation, hueRotate, creativity },
    transform: { zoom, cropRatio, pan, isRatioLocked },
    ...overrides
  }), [currentImageSrc, selectedFilterId, brightness, contrast, saturation, hueRotate, creativity, zoom, cropRatio, pan, isRatioLocked]);

  // Initialize history on mount
  useEffect(() => {
    if (history.length === 0) {
      const initialState = getCurrentState();
      setHistory([initialState]);
      setHistoryIndex(0);
    }
  }, []); // Run once on mount

  const pushToHistory = (newState: EditorState) => {
    if (historyIndex >= 0) {
      const currentState = history[historyIndex];
      if (JSON.stringify(currentState) === JSON.stringify(newState)) return;
    }

    const newHistory = history.slice(0, historyIndex + 1);
    newHistory.push(newState);
    setHistory(newHistory);
    setHistoryIndex(newHistory.length - 1);
  };

  const handleUndo = () => {
    if (historyIndex > 0) {
      const newIndex = historyIndex - 1;
      setHistoryIndex(newIndex);
      restoreState(history[newIndex]);
    }
  };

  const handleRedo = () => {
    if (historyIndex < history.length - 1) {
      const newIndex = historyIndex + 1;
      setHistoryIndex(newIndex);
      restoreState(history[newIndex]);
    }
  };

  const restoreState = (state: EditorState) => {
    setCurrentImageSrc(state.imageSrc);
    setSelectedFilterId(state.filterId);
    setBrightness(state.adjustments.brightness);
    setContrast(state.adjustments.contrast);
    setSaturation(state.adjustments.saturation);
    setHueRotate(state.adjustments.hueRotate);
    setCreativity(state.adjustments.creativity);
    setZoom(state.transform.zoom);
    setCropRatio(state.transform.cropRatio);
    setPan(state.transform.pan);
    setIsRatioLocked(state.transform.isRatioLocked);
  };

  // --- Logic ---

  const getMinZoom = useCallback(() => {
    if (!imageRef.current || !containerRef.current) return 1;
    const img = imageRef.current;
    const container = containerRef.current;

    const containerAspect = container.clientWidth / container.clientHeight;
    const imgAspect = img.naturalWidth / img.naturalHeight;

    if (imgAspect > containerAspect) {
      return 1; 
    } else {
      return containerAspect / imgAspect;
    }
  }, []);

  const constrainPan = useCallback((currentPan: { x: number; y: number }, currentZoom: number) => {
    if (isResetting || !isRatioLocked || !imageRef.current || !containerRef.current) return currentPan;

    const img = imageRef.current;
    const container = containerRef.current;

    const imgAspect = img.naturalWidth / img.naturalHeight;
    const containerAspect = container.clientWidth / container.clientHeight;

    let displayWidth, displayHeight;
    if (imgAspect > containerAspect) {
      displayHeight = container.clientHeight;
      displayWidth = container.clientHeight * imgAspect;
    } else {
      displayWidth = container.clientWidth;
      displayHeight = container.clientWidth / imgAspect;
    }

    const scaledWidth = displayWidth * currentZoom;
    const scaledHeight = displayHeight * currentZoom;

    const maxX = Math.max(0, (scaledWidth - container.clientWidth) / 2) / currentZoom;
    const maxY = Math.max(0, (scaledHeight - container.clientHeight) / 2) / currentZoom;

    return {
      x: Math.min(Math.max(currentPan.x, -maxX), maxX),
      y: Math.min(Math.max(currentPan.y, -maxY), maxY)
    };
  }, [isRatioLocked, isResetting]);

  useEffect(() => {
    if (isRatioLocked && imageLoaded && !isResetting) {
      const minZoom = getMinZoom();
      if (zoom < minZoom) {
        setZoom(minZoom);
      }
      setPan(prev => constrainPan(prev, Math.max(zoom, minZoom)));
    }
  }, [isRatioLocked, cropRatio, imageLoaded, zoom, constrainPan, getMinZoom, isResetting]);

  const effectiveFilterId = hoveredFilterId || selectedFilterId;
  const activeFilterObject = IMAGE_FILTERS.find(f => f.id === effectiveFilterId);
  const baseFilter = activeFilterObject?.filter || 'none';
  const currentFilter = `${baseFilter === 'none' ? '' : baseFilter} brightness(${brightness}%) contrast(${contrast}%) saturate(${saturation}%) hue-rotate(${hueRotate}deg)`;

  const handlePointerDown = (e: React.PointerEvent) => {
    if (isResetting) return;
    setIsDragging(true);
    setDragStart({ x: e.clientX - pan.x * zoom, y: e.clientY - pan.y * zoom });
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (isDragging) {
      const newPan = {
        x: (e.clientX - dragStart.x) / zoom,
        y: (e.clientY - dragStart.y) / zoom
      };
      setPan(constrainPan(newPan, zoom));
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (isDragging) {
      pushToHistory(getCurrentState());
    }
    setIsDragging(false);
    (e.target as HTMLElement).releasePointerCapture(e.pointerId);
  };

  const handleResetTransform = () => {
    if (isResetting) return;
    setIsResetting(true);
    const targetZoom = isRatioLocked ? getMinZoom() : 1;
    const targetPan = { x: 0, y: 0 };
    setZoom(targetZoom);
    setPan(targetPan);

    pushToHistory({
        ...getCurrentState(),
        transform: {
            zoom: targetZoom,
            pan: targetPan,
            cropRatio,
            isRatioLocked
        }
    });

    setTimeout(() => setIsResetting(false), 600);
  };

  const handleResetAdjustments = () => {
    setBrightness(100);
    setContrast(100);
    setSaturation(100);
    setHueRotate(0);
    setCreativity(initialCreativity);
    setSelectedFilterId('none');

    pushToHistory({
        ...getCurrentState(),
        filterId: 'none',
        adjustments: { brightness: 100, contrast: 100, saturation: 100, hueRotate: 0, creativity: initialCreativity }
    });
  };

  const getCanvasData = () => {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    const img = imageRef.current;

    if (!ctx || !img) return null;

    const outputSize = 1024;
    let width = outputSize;
    let height = outputSize;

    const [wRatio, hRatio] = cropRatio.split(':').map(Number);
    if (wRatio && hRatio) {
        if (wRatio > hRatio) {
            height = outputSize * (hRatio / wRatio);
        } else {
            width = outputSize * (wRatio / hRatio);
        }
    }

    canvas.width = width;
    canvas.height = height;
    ctx.fillStyle = '#000000';
    ctx.fillRect(0, 0, width, height);

    const container = containerRef.current;
    if (!container) return null;

    const scaleFactor = width / container.clientWidth;

    ctx.save();
    const saveBaseFilter = IMAGE_FILTERS.find(f => f.id === selectedFilterId)?.filter || 'none';
    ctx.filter = `${saveBaseFilter === 'none' ? '' : saveBaseFilter} brightness(${brightness}%) contrast(${contrast}%) saturate(${saturation}%) hue-rotate(${hueRotate}deg)`;

    ctx.translate(width / 2, height / 2);
    ctx.scale(zoom, zoom);
    ctx.translate(pan.x * scaleFactor, pan.y * scaleFactor);

    const imgAspect = img.naturalWidth / img.naturalHeight;
    const containerAspect = container.clientWidth / container.clientHeight;

    let drawWidth, drawHeight;
    if (imgAspect > containerAspect) {
        drawHeight = height / zoom;
        drawWidth = drawHeight * imgAspect;
    } else {
        drawWidth = width / zoom;
        drawHeight = drawWidth / imgAspect;
    }

    ctx.drawImage(img, -drawWidth / 2, -drawHeight / 2, drawWidth, drawHeight);
    ctx.restore();

    // Apply Vignette if active
    if (effectiveFilterId === 'vignette') {
      const gradient = ctx.createRadialGradient(
        width / 2, height / 2, 0,
        width / 2, height / 2, Math.sqrt((width/2)**2 + (height/2)**2)
      );
      gradient.addColorStop(0, 'rgba(0,0,0,0)');
      gradient.addColorStop(0.5, 'rgba(0,0,0,0)');
      gradient.addColorStop(1, 'rgba(0,0,0,0.6)');
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, width, height);
    }

    return canvas.toDataURL('image/png', 0.95);
  };

  const handleSave = () => {
    const dataUrl = getCanvasData();
    if (dataUrl) onSave(dataUrl);
  };

  const handleAIRefine = async () => {
    const referenceData = getCanvasData();
    if (!referenceData) return;

    setIsRefining(true);
    setImageLoaded(false);

    try {
      const newImage = await generateImageWithNano(
        prompt,
        styleId,
        cropRatio,
        undefined, // random seed
        creativity,
        referenceData,
        lightSourceId,
        lightDirectionId
      );

      setCurrentImageSrc(newImage);

      // Reset canvas filters because the new image already has the look
      setBrightness(100);
      setContrast(100);
      setSaturation(100);
      setHueRotate(0);
      setSelectedFilterId('none');
      setZoom(isRatioLocked ? getMinZoom() : 1);
      setPan({ x: 0, y: 0 });

      const newState: EditorState = {
         imageSrc: newImage,
         filterId: 'none',
         adjustments: { brightness: 100, contrast: 100, saturation: 100, hueRotate: 0, creativity: creativity },
         transform: { 
             zoom: isRatioLocked ? getMinZoom() : 1, 
             cropRatio, 
             pan: { x: 0, y: 0 }, 
             isRatioLocked 
         }
      };

      setHistory(prev => {
         const newHistory = prev.slice(0, historyIndex + 1);
         return [...newHistory, newState];
      });
      setHistoryIndex(prev => prev + 1);

    } catch (error) {
      console.error("AI Refine failed:", error);
      setImageLoaded(true);
    } finally {
      setIsRefining(false);
    }
  };

  const handleFilterSelect = (id: string) => {
    setSelectedFilterId(id);
    pushToHistory(getCurrentState({ filterId: id }));
  };

  const handleRatioSelect = (ratio: string) => {
    setCropRatio(ratio);
    pushToHistory(getCurrentState({ transform: { ...getCurrentState().transform, cropRatio: ratio } }));
  };

  const handleLockToggle = () => {
    const newLock = !isRatioLocked;
    setIsRatioLocked(newLock);
    pushToHistory(getCurrentState({ transform: { ...getCurrentState().transform, isRatioLocked: newLock } }));
  };

  return (
    <div className="fixed inset-0 z-[100] bg-nano-50/90 backdrop-blur-md flex flex-col h-full animate-in fade-in duration-300">
      <div className="h-16 border-b border-white/10 flex items-center justify-between px-6 bg-nano-100 shrink-0 shadow-xl">
        <div className="flex items-center gap-3">
            <button onClick={onCancel} className="p-2 text-white/40 hover:text-white hover:bg-white/5 rounded-xl transition-all active:scale-95 focus:outline-none">
                <X size={20} />
            </button>
            <div className="h-6 w-px bg-white/10 mx-1 hidden sm:block"></div>
            <div className="flex items-center gap-1">
                <button onClick={handleUndo} disabled={historyIndex <= 0} className="p-2 text-white/40 hover:text-white hover:bg-white/5 rounded-xl transition-all disabled:opacity-20 disabled:hover:bg-transparent" title="Undo Edit">
                   <Undo size={18} />
                </button>
                <button onClick={handleRedo} disabled={historyIndex >= history.length - 1} className="p-2 text-white/40 hover:text-white hover:bg-white/5 rounded-xl transition-all disabled:opacity-20 disabled:hover:bg-transparent" title="Redo Edit">
                   <Redo size={18} />
                </button>
            </div>
        </div>

        <div className="flex flex-col items-center">
            <span className="font-black text-[10px] uppercase tracking-[0.4em] text-white/30 mb-0.5">Retouch Station</span>
            <div className="flex items-center gap-1.5">
                <div className="w-1 h-1 bg-emerald-400 rounded-full animate-pulse"></div>
                <span className="text-[11px] font-black uppercase tracking-widest text-white">Capture v2.1</span>
            </div>
        </div>

        <div className="flex items-center gap-3">
            <button 
                onClick={handleAIRefine} 
                disabled={!imageLoaded || isRefining} 
                className={`
                    flex items-center gap-2 px-4 py-2 rounded-2xl transition-all font-black text-[10px] uppercase tracking-widest 
                    ${isRefining ? 'bg-emerald-500 text-white animate-pulse' : 'bg-emerald-500/10 text-emerald-400 hover:bg-emerald-500 hover:text-white shadow-[0_0_20px_rgba(16,185,129,0.2)]'}
                    disabled:opacity-30 disabled:pointer-events-none active:scale-95
                `}
                title="Use current view as basis for a new AI generation"
            >
                <Zap size={16} fill={isRefining ? "currentColor" : "none"} />
                <span className="hidden sm:block">Magic Refine</span>
            </button>
            <div className="h-6 w-px bg-white/10 mx-1"></div>
            <button 
                onClick={handleSave} 
                disabled={!imageLoaded || isRefining} 
                className="p-3 bg-white text-nano-50 hover:bg-white/90 rounded-2xl transition-all font-bold disabled:opacity-30 active:scale-95 shadow-xl"
                title="Save Edits and Return"
            >
                <Check size={20} strokeWidth={3} />
            </button>
        </div>
      </div>

      <div className="flex-grow overflow-hidden relative flex items-center justify-center p-8 sm:p-12 lg:p-16 select-none bg-nano-50">
        {hoveredFilterId && (
          <div className="absolute top-8 left-1/2 -translate-x-1/2 z-20 flex items-center gap-2.5 px-5 py-2.5 bg-white text-nano-50 rounded-full shadow-2xl animate-in slide-in-from-top-4 border border-white/20">
            <Eye size={14} className="animate-pulse text-emerald-500" />
            <span className="text-[10px] font-black uppercase tracking-widest">Previewing: {activeFilterObject?.name}</span>
          </div>
        )}

        {(!imageLoaded || isRefining) && (
          <div className="absolute inset-0 z-30 flex flex-col items-center justify-center bg-nano-50/80 backdrop-blur-xl">
             <div className="relative mb-8">
                <div className="absolute inset-0 bg-emerald-400/20 blur-2xl rounded-full animate-pulse"></div>
                <BrainCircuit className="w-12 h-12 text-white animate-bounce relative z-10" />
             </div>
             {isRefining ? (
                 <div className="flex flex-col items-center gap-3">
                    <span className="text-[11px] font-black uppercase tracking-[0.6em] text-white animate-pulse">Synthesizing Vision</span>
                    <p className="text-[9px] font-bold text-white/30 uppercase tracking-widest">Iterating on your current canvas...</p>
                 </div>
             ) : (
                 <Loader2 className="w-8 h-8 text-white/20 animate-spin" />
             )}
          </div>
        )}

        <div 
          ref={containerRef}
          className="relative bg-black overflow-hidden shadow-[0_40px_100px_rgba(0,0,0,0.8)] ring-1 ring-white/10 rounded-sm"
          style={{
             aspectRatio: cropRatio.replace(':', '/'),
             width: '100%',
             maxWidth: '100%',
             maxHeight: '100%',
             cursor: isDragging ? 'grabbing' : 'grab',
             touchAction: 'none'
          }}
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={handlePointerUp}
          onPointerLeave={handlePointerUp}
        >
           <img 
             ref={imageRef}
             src={currentImageSrc} 
             alt="Editing"
             loading="lazy"
             decoding="async"
             onLoad={() => setImageLoaded(true)}
             className={`absolute max-w-none max-h-none origin-center pointer-events-none transition-opacity duration-500 ${imageLoaded ? 'opacity-100' : 'opacity-0'}`}
             style={{
                top: '50%',
                left: '50%',
                transform: `translate(-50%, -50%) scale(${zoom}) translate(${pan.x}px, ${pan.y}px)`,
                filter: currentFilter,
                minWidth: '100%',
                minHeight: '100%',
                transition: isResetting 
                  ? 'transform 0.6s cubic-bezier(0.25, 1, 0.5, 1), filter 0.3s ease' 
                  : (isDragging ? 'none' : 'transform 0.1s ease-out, filter 0.25s ease-out')
             }}
             draggable={false}
           />

           {/* Vignette Overlay (Preview) */}
           {effectiveFilterId === 'vignette' && (
             <div className="absolute inset-0 pointer-events-none bg-[radial-gradient(circle,transparent_50%,rgba(0,0,0,0.6)_100%)]"></div>
           )}

           {/* Crop Guides */}
           {activeTab === 'crop' && (
             <div className="absolute inset-0 pointer-events-none border border-white/20 ring-[2000px] ring-black/40">
                <div className="absolute top-1/3 left-0 right-0 h-px bg-white/20"></div>
                <div className="absolute top-2/3 left-0 right-0 h-px bg-white/20"></div>
                <div className="absolute left-1/3 top-0 bottom-0 w-px bg-white/20"></div>
                <div className="absolute left-2/3 top-0 bottom-0 w-px bg-white/20"></div>
             </div>
           )}
        </div>
      </div>

      <div className="bg-nano-100 border-t border-white/10 shrink-0 pb-safe shadow-[0_-10px_60px_rgba(0,0,0,0.7)] z-10">
        <div className="flex border-b border-white/5">
           <button onClick={() => setActiveTab('filter')} className={`flex-1 py-4 text-[10px] uppercase font-bold tracking-[0.3em] flex items-center justify-center gap-2.5 focus:outline-none transition-all ${activeTab === 'filter' ? 'text-white bg-white/5 border-b-2 border-white' : 'text-white/30 hover:text-white/60'}`}>
             <Wand2 size={16} /> Filters
           </button>
           <button onClick={() => setActiveTab('adjust')} className={`flex-1 py-4 text-[10px] uppercase font-bold tracking-[0.3em] flex items-center justify-center gap-2.5 focus:outline-none transition-all ${activeTab === 'adjust' ? 'text-white bg-white/5 border-b-2 border-white' : 'text-white/30 hover:text-white/60'}`}>
             <Sliders size={16} /> Adjustments
           </button>
           <button onClick={() => setActiveTab('crop')} className={`flex-1 py-4 text-[10px] uppercase font-bold tracking-[0.3em] flex items-center justify-center gap-2.5 focus:outline-none transition-all ${activeTab === 'crop' ? 'text-white bg-white/5 border-b-2 border-white' : 'text-white/30 hover:text-white/60'}`}>
             <Crop size={16} /> Composition
           </button>
        </div>

        <div className="h-56 p-6 overflow-y-auto hide-scrollbar bg-black/20">
           {activeTab === 'filter' && (
             <div className="flex gap-5 overflow-x-auto pb-4 hide-scrollbar h-full items-center">
                {IMAGE_FILTERS.map((f) => (
                   <button 
                     key={f.id}
                     onClick={() => handleFilterSelect(f.id)}
                     onMouseEnter={() => setHoveredFilterId(f.id)}
                     onMouseLeave={() => setHoveredFilterId(null)}
                     className="flex flex-col items-center gap-3 shrink-0 group focus:outline-none"
                   >
                      <div className={`relative w-16 h-16 rounded-2xl overflow-hidden border-2 transition-all duration-300 ${selectedFilterId === f.id ? 'border-white ring-4 ring-white/10 scale-105' : 'border-white/5 group-hover:border-white/30 group-hover:scale-110'}`}>
                         <img src={currentImageSrc} alt={f.name} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-125" style={{ filter: f.filter }} />
                         {f.id === 'vignette' && (
                           <div className="absolute inset-0 pointer-events-none bg-[radial-gradient(circle,transparent_50%,rgba(0,0,0,0.6)_100%)]"></div>
                         )}
                      </div>
                      <span className={`text-[10px] font-black uppercase tracking-widest transition-colors ${selectedFilterId === f.id || hoveredFilterId === f.id ? 'text-white' : 'text-white/20'}`}>{f.name}</span>
                   </button>
                ))}
             </div>
           )}

           {activeTab === 'adjust' && (
             <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-4 max-w-4xl mx-auto h-full">
                <div className="space-y-4">
                    <div className="flex items-center gap-4 group">
                    <div className="flex items-center gap-2.5 w-32 shrink-0">
                        <Sun size={14} className="text-white group-hover:text-amber-400 transition-colors" />
                        <span className="text-[10px] font-black uppercase tracking-widest text-white/60">Brightness</span>
                    </div>
                    <input 
                        type="range" min="0" max="200" step="1" 
                        value={brightness} 
                        onChange={(e) => setBrightness(parseInt(e.target.value))} 
                        onPointerUp={() => pushToHistory(getCurrentState())}
                        className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-white" 
                    />
                    <span className="text-[10px] font-mono w-10 text-right text-white/30">{brightness}%</span>
                    </div>

                    <div className="flex items-center gap-4 group">
                    <div className="flex items-center gap-2.5 w-32 shrink-0">
                        <Contrast size={14} className="text-white group-hover:text-blue-400 transition-colors" />
                        <span className="text-[10px] font-black uppercase tracking-widest text-white/60">Contrast</span>
                    </div>
                    <input 
                        type="range" min="0" max="200" step="1" 
                        value={contrast} 
                        onChange={(e) => setContrast(parseInt(e.target.value))} 
                        onPointerUp={() => pushToHistory(getCurrentState())}
                        className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-white" 
                    />
                    <span className="text-[10px] font-mono w-10 text-right text-white/30">{contrast}%</span>
                    </div>

                    <div className="flex items-center gap-4 group">
                    <div className="flex items-center gap-2.5 w-32 shrink-0">
                        <Droplets size={14} className="text-white group-hover:text-sky-400 transition-colors" />
                        <span className="text-[10px] font-black uppercase tracking-widest text-white/60">Saturation</span>
                    </div>
                    <input 
                        type="range" min="0" max="200" step="1" 
                        value={saturation} 
                        onChange={(e) => setSaturation(parseInt(e.target.value))} 
                        onPointerUp={() => pushToHistory(getCurrentState())}
                        className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-white" 
                    />
                    <span className="text-[10px] font-mono w-10 text-right text-white/30">{saturation}%</span>
                    </div>
                </div>

                <div className="space-y-4">
                    <div className="flex items-center gap-4 group">
                        <div className="flex items-center gap-2.5 w-32 shrink-0">
                            <Palette size={14} className="text-white group-hover:text-purple-400 transition-colors" />
                            <span className="text-[10px] font-black uppercase tracking-widest text-white/60">Hue Shift</span>
                        </div>
                        <input 
                            type="range" min="-180" max="180" step="1" 
                            value={hueRotate} 
                            onChange={(e) => setHueRotate(parseInt(e.target.value))} 
                            onPointerUp={() => pushToHistory(getCurrentState())}
                            className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-white" 
                        />
                        <span className="text-[10px] font-mono w-10 text-right text-white/30">{hueRotate}°</span>
                    </div>

                    <div className="p-4 rounded-2xl bg-emerald-500/5 border border-emerald-500/10 space-y-3">
                        <div className="flex items-center justify-between mb-1">
                            <div className="flex items-center gap-2.5">
                                <BrainCircuit size={14} className="text-emerald-400" />
                                <span className="text-[10px] font-black uppercase tracking-widest text-emerald-400">Refine Influence</span>
                            </div>
                            <span className="text-[10px] font-black text-emerald-400 bg-emerald-400/10 px-2 py-0.5 rounded-full">{creativity}%</span>
                        </div>
                        <input 
                            type="range" min="0" max="100" step="1" 
                            value={creativity} 
                            onChange={(e) => setCreativity(parseInt(e.target.value))} 
                            onPointerUp={() => pushToHistory(getCurrentState())}
                            className="w-full h-1 bg-emerald-500/10 rounded-full appearance-none cursor-pointer accent-emerald-400" 
                        />
                        <p className="text-[8px] font-bold text-emerald-400/50 uppercase tracking-widest">Controls how much the AI re-imagines the reference image during refinement.</p>
                    </div>

                    <div className="flex justify-end">
                       <button onClick={handleResetAdjustments} className="flex items-center gap-2 text-[9px] font-black uppercase tracking-[0.2em] text-white/20 hover:text-white transition-all">
                           <RotateCcw size={10} /> Reset All
                       </button>
                    </div>
                </div>
             </div>
           )}

           {activeTab === 'crop' && (
             <div className="flex flex-col gap-6 h-full justify-center max-w-2xl mx-auto">
                <div className="flex items-center gap-5 px-2">
                   <div className="p-2.5 bg-white/5 rounded-xl text-white">
                      <ZoomIn size={18} />
                   </div>
                   <input 
                     type="range" 
                     min={isRatioLocked ? getMinZoom() : 0.5} 
                     max="4" 
                     step="0.01"
                     value={zoom}
                     onChange={(e) => {
                       const val = parseFloat(e.target.value);
                       setZoom(val);
                       setPan(prev => constrainPan(prev, val));
                     }}
                     onPointerUp={() => pushToHistory(getCurrentState())}
                     className="w-full h-1.5 bg-white/10 rounded-full appearance-none cursor-pointer accent-white"
                   />
                   <div className="flex gap-2">
                     <button 
                        onClick={handleLockToggle} 
                        className={`p-3 rounded-2xl transition-all active:scale-90 border ${isRatioLocked ? 'bg-white text-nano-50 border-white' : 'text-white/40 border-white/5 hover:bg-white/5'}`} 
                        title={isRatioLocked ? "Unlock Viewport" : "Lock Viewport"}
                     >
                       {isRatioLocked ? <Lock size={16} /> : <Unlock size={16} />}
                     </button>
                     <button 
                        onClick={handleResetTransform} 
                        className="p-3 text-white/40 hover:text-white hover:bg-white/5 border border-white/5 rounded-2xl transition-all active:scale-90"
                        title="Reset Zoom/Pan"
                     >
                       <RotateCcw size={16} />
                     </button>
                   </div>
                </div>

                <div className="flex gap-3 overflow-x-auto pb-1 hide-scrollbar justify-center">
                   {['1:1', '16:9', '9:16', '4:3', '3:4'].map(r => (
                     <button 
                        key={r} 
                        onClick={() => handleRatioSelect(r)} 
                        className={`
                            px-6 py-2 rounded-2xl border text-[10px] font-black uppercase tracking-widest whitespace-nowrap transition-all
                            ${cropRatio === r ? 'bg-white text-nano-50 border-white shadow-lg' : 'border-white/10 text-white/40 hover:border-white/30 hover:text-white'}
                        `}
                     >
                        {r === '1:1' ? 'Square' : r}
                     </button>
                   ))}
                </div>
             </div>
           )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { 
  Sparkles, 
  Download, 
  RefreshCw, 
  Image as ImageIcon, 
  History, 
  Zap,
  Camera,
  Maximize,
  Sliders,
  ChevronDown,
  ChevronUp,
  Undo,
  Redo,
  Upload,
  X,
  Plus,
  Edit2,
  Dices,
  Trash2,
  Wand2,
  Bookmark,
  Save,
  Clock,
  CheckCircle2,
  Eraser,
  Search,
  Loader2,
  Sun,
  Cloud,
  BookOpen,
  User,
  Trees,
  Home,
  Building2,
  Coffee,
  Shapes,
  Bug,
  Waves,
  Check,
  Lightbulb,
  Copy,
  ExternalLink,
  MousePointer2
} from 'lucide-react';
import { ART_STYLES, APP_NAME, MODEL_NAME_DISPLAY, ASPECT_RATIOS, LIGHT_SOURCES, LIGHT_DIRECTIONS } from './constants';
import { ArtStyle, GeneratedImage, GenerationStatus, GenerationPreset } from './types';
import { generateImageWithNano, detectImageStyle } from './services/geminiService';
import { Button, StyleCard, Badge } from './components/UI';
import { ImageEditor } from './components/ImageEditor';
import { ZoomablePreview } from './components/ZoomablePreview';

const App: React.FC = () => {
  // --- Basic Generation State ---
  const [prompt, setPrompt] = useState<string>('');
  const [selectedStyleId, setSelectedStyleId] = useState<string>(ART_STYLES[0].id);
  const [aspectRatio, setAspectRatio] = useState<string>('1:1');

  // --- Lighting State ---
  const [lightSourceId, setLightSourceId] = useState<string>('auto');
  const [lightDirectionId, setLightDirectionId] = useState<string>('auto');

  // --- Advanced Parameters State ---
  const [seed, setSeed] = useState<number | undefined>(undefined);
  const [creativity, setCreativity] = useState<number>(50); // 0-100
  const [showAdvanced, setShowAdvanced] = useState<boolean>(false);

  // --- Presets State ---
  const [presets, setPresets] = useState<GenerationPreset[]>([]);
  const [isSavingPreset, setIsSavingPreset] = useState(false);
  const [newPresetName, setNewPresetName] = useState('');
  const [showPresets, setShowPresets] = useState(true);
  const [lastLoadedPresetId, setLastLoadedPresetId] = useState<string | null>(null);
  const [editingPresetId, setEditingPresetId] = useState<string | null>(null);
  const [editNameValue, setEditNameValue] = useState('');
  const [presetSearch, setPresetSearch] = useState('');
  const [copiedId, setCopiedId] = useState<string | null>(null);

  // --- Reference Image State ---
  const [uploadedImage, setUploadedImage] = useState<string | null>(null);
  const [isDetectingStyle, setIsDetectingStyle] = useState(false);
  const [lastAutoSelectedStyleId, setLastAutoSelectedStyleId] = useState<string | null>(null);

  // --- Generation & Gallery State ---
  const [status, setStatus] = useState<GenerationStatus>('idle');
  const [currentImage, setCurrentImage] = useState<GeneratedImage | null>(null);
  const [history, setHistory] = useState<GeneratedImage[]>([]);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  // --- UI/Editor State ---
  const [isEditing, setIsEditing] = useState(false);

  // --- Prompt History (Undo/Redo) ---
  const [promptHistory, setPromptHistory] = useState<string[]>(['']);
  const [historyIndex, setHistoryIndex] = useState(0);
  const debounceRef = useRef<any>(null);

  // --- Refs ---
  const previewRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- Persistence ---
  useEffect(() => {
    const saved = localStorage.getItem('nanoframe_presets_v6');
    if (saved) {
      try {
        setPresets(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse presets", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('nanoframe_presets_v6', JSON.stringify(presets));
  }, [presets]);

  // --- Handlers ---

  const handlePromptChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newVal = e.target.value;
    setPrompt(newVal);

    if (debounceRef.current) clearTimeout(debounceRef.current);

    debounceRef.current = setTimeout(() => {
      setPromptHistory(prev => {
        const newHistory = prev.slice(0, historyIndex + 1);
        newHistory.push(newVal);
        return newHistory;
      });
      setHistoryIndex(prev => prev + 1);
    }, 400);
  };

  const handleUndo = () => {
    if (historyIndex > 0) {
      const newIndex = historyIndex - 1;
      setHistoryIndex(newIndex);
      setPrompt(promptHistory[newIndex]);
    }
  };

  const handleRedo = () => {
    if (historyIndex < promptHistory.length - 1) {
      const newIndex = historyIndex + 1;
      setHistoryIndex(newIndex);
      setPrompt(promptHistory[newIndex]);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = async (event) => {
        if (event.target?.result) {
          const base64 = event.target.result as string;
          setUploadedImage(base64);
          setIsDetectingStyle(true);
          try {
            const detectedStyleId = await detectImageStyle(base64);
            if (detectedStyleId) {
                const cleanId = detectedStyleId.trim();
                const matchedStyle = ART_STYLES.find(s => cleanId.includes(s.id));
                if (matchedStyle) {
                    setSelectedStyleId(matchedStyle.id);
                    setLastAutoSelectedStyleId(matchedStyle.id);
                    setTimeout(() => setLastAutoSelectedStyleId(null), 3000);
                }
            }
          } catch (err) {
            console.warn("Style detection failed", err);
          } finally {
            setIsDetectingStyle(false);
          }
        }
      };
      reader.readAsDataURL(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const clearUploadedImage = () => setUploadedImage(null);

  const handleSavePreset = () => {
    if (!newPresetName.trim()) return;

    const newPreset: GenerationPreset = {
      id: crypto.randomUUID(),
      name: newPresetName.trim(),
      prompt: prompt,
      styleId: selectedStyleId,
      aspectRatio: aspectRatio,
      seed: seed,
      creativity: creativity,
      timestamp: Date.now(),
      referenceImage: uploadedImage,
      lightSourceId: lightSourceId,
      lightDirectionId: lightDirectionId
    };

    setPresets(prev => [newPreset, ...prev]);
    setLastLoadedPresetId(newPreset.id);
    setNewPresetName('');
    setIsSavingPreset(false);

    setTimeout(() => setLastLoadedPresetId(null), 2000);
  };

  const handleUpdatePresetName = (id: string) => {
    if (!editNameValue.trim()) {
      setEditingPresetId(null);
      return;
    }
    setPresets(prev => prev.map(p => p.id === id ? { ...p, name: editNameValue.trim() } : p));
    setEditingPresetId(null);
  };

  const loadPreset = (p: GenerationPreset) => {
    setPrompt(p.prompt);
    setSelectedStyleId(p.styleId);
    setAspectRatio(p.aspectRatio);
    setSeed(p.seed);
    setCreativity(p.creativity);
    setUploadedImage(p.referenceImage || null);
    setLightSourceId(p.lightSourceId || 'auto');
    setLightDirectionId(p.lightDirectionId || 'auto');
    setLastLoadedPresetId(p.id);

    setPromptHistory(prev => {
      const newHistory = prev.slice(0, historyIndex + 1);
      newHistory.push(p.prompt);
      return newHistory;
    });
    setHistoryIndex(prev => prev + 1);

    setTimeout(() => setLastLoadedPresetId(null), 1500);
  };

  const deletePreset = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm("Permanently remove this preset from your library?")) {
      setPresets(prev => prev.filter(p => p.id !== id));
      if (lastLoadedPresetId === id) setLastLoadedPresetId(null);
    }
  };

  const copyPromptFromPreset = (e: React.MouseEvent, id: string, text: string) => {
    e.stopPropagation();
    navigator.clipboard.writeText(text);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const resetWorkspace = () => {
    if (confirm("Reset engine to default states? This will clear current work.")) {
      setPrompt('');
      setSelectedStyleId(ART_STYLES[0].id);
      setAspectRatio('1:1');
      setSeed(undefined);
      setCreativity(50);
      setUploadedImage(null);
      setLightSourceId('auto');
      setLightDirectionId('auto');
      setPromptHistory(['']);
      setHistoryIndex(0);
      setStatus('idle');
      setCurrentImage(null);
    }
  };

  const handleQuickStart = (p: string, style?: string) => {
    setPrompt(p);
    if (style) setSelectedStyleId(style);
    setTimeout(() => {
        handleGenerate();
    }, 100);
  };

  const handleGenerate = async () => {
    const currentPrompt = prompt.trim();
    if (!currentPrompt && !uploadedImage) {
        setErrorMsg("Enter a visual prompt or upload a reference image to begin.");
        setStatus('error');
        return;
    }

    setStatus('generating');
    setErrorMsg(null);
    setCurrentImage(null);
    setIsEditing(false);

    if (window.innerWidth < 768) previewRef.current?.scrollIntoView({ behavior: 'smooth' });

    try {
      const base64Image = await generateImageWithNano(
          currentPrompt, 
          selectedStyleId, 
          aspectRatio, 
          seed, 
          creativity, 
          uploadedImage,
          lightSourceId,
          lightDirectionId
      );

      const newImage: GeneratedImage = {
        id: crypto.randomUUID(),
        url: base64Image,
        prompt: currentPrompt || 'Neural Variation',
        styleId: selectedStyleId,
        aspectRatio: aspectRatio,
        seed: seed,
        creativity: creativity,
        referenceImage: uploadedImage,
        lightSourceId: lightSourceId,
        lightDirectionId: lightDirectionId,
        timestamp: Date.now()
      };

      setCurrentImage(newImage);
      setHistory(prev => [newImage, ...prev].slice(0, 10));
      setStatus('success');
    } catch (error) {
      console.error(error);
      setStatus('error');
      setErrorMsg("Neural engine encountered an error. Please retry.");
    }
  };

  const handleDownload = () => {
    if (!currentImage) return;
    const link = document.createElement('a');
    link.href = currentImage.url;
    link.download = `${APP_NAME.toLowerCase()}-${currentImage.id.slice(0, 8)}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const loadFromHistory = (img: GeneratedImage) => {
    setCurrentImage(img);
    setPrompt(img.prompt);
    setPromptHistory(prev => [...prev.slice(0, historyIndex + 1), img.prompt]);
    setHistoryIndex(prev => prev + 1);
    setSelectedStyleId(img.styleId);
    setAspectRatio(img.aspectRatio || '1:1');
    setSeed(img.seed);
    setCreativity(img.creativity ?? 50);
    setUploadedImage(img.referenceImage || null);
    setLightSourceId(img.lightSourceId || 'auto');
    setLightDirectionId(img.lightDirectionId || 'auto');
    setStatus('success');
    setIsEditing(false);
    if (window.innerWidth < 768) previewRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleSaveEdit = (newImageSrc: string) => {
     if (!currentImage) return;
     const newImage: GeneratedImage = {
        ...currentImage,
        id: crypto.randomUUID(),
        url: newImageSrc,
        timestamp: Date.now()
     };
     setCurrentImage(newImage);
     setHistory(prev => [newImage, ...prev].slice(0, 10));
     setIsEditing(false);
  };

  const filteredPresets = presets.filter(p => 
    p.name.toLowerCase().includes(presetSearch.toLowerCase()) ||
    p.prompt.toLowerCase().includes(presetSearch.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-nano-50 text-white selection:bg-emerald-500 selection:text-white flex flex-col font-sans">

      <header className="bg-nano-100/80 backdrop-blur-xl sticky top-0 z-50 border-b border-white/10 shadow-lg">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-nano-50 shadow-2xl shadow-white/5 ring-1 ring-white/20">
              <Camera size={22} />
            </div>
            <div className="flex flex-col -gap-1">
                <h1 className="text-xl font-black tracking-tight text-white leading-none">{APP_NAME}</h1>
                <span className="text-[9px] font-bold text-white/30 tracking-[0.2em] uppercase">Visual Synthesis</span>
            </div>
            <div className="ml-2">
                <Badge text={MODEL_NAME_DISPLAY} />
            </div>
          </div>
          <div className="flex items-center gap-6">
             <button onClick={resetWorkspace} className="text-[10px] font-black text-white/40 hover:text-red-400 flex items-center gap-1.5 transition-all uppercase tracking-widest">
               <Eraser size={14} /> Reset Lab
             </button>
             <div className="hidden sm:block w-px h-6 bg-white/10"></div>
             <div className="hidden sm:flex items-center gap-2">
                <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full"></div>
                <div className="text-[10px] text-white/40 font-black uppercase tracking-[0.3em]">Studio Engine 2.5 Active</div>
             </div>
          </div>
        </div>
      </header>

      <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full flex flex-col lg:flex-row gap-8 lg:gap-12">

        {/* Left Column: Control Deck */}
        <aside className="w-full lg:w-1/3 flex flex-col gap-8 order-2 lg:order-1 pb-12">

          {/* --- PRESETS ENGINE --- */}
          <section className="bg-nano-100 rounded-[2rem] border border-white/10 overflow-hidden shadow-2xl flex flex-col ring-1 ring-white/5">
            <div className="p-6 border-b border-white/5 flex items-center justify-between bg-white/2">
              <button 
                onClick={() => setShowPresets(!showPresets)}
                className="flex items-center gap-3 text-[11px] font-black text-white focus:outline-none group"
              >
                <div className={`p-1.5 rounded-lg transition-colors ${presets.length > 0 ? 'bg-emerald-500/10 text-emerald-400' : 'bg-white/5 text-white/20'}`}>
                    <Bookmark size={16} fill={presets.length > 0 ? "currentColor" : "none"} />
                </div>
                <span className="uppercase tracking-[0.2em]">Storage & Presets</span>
                {presets.length > 0 && (
                  <span className="bg-white/10 text-white/60 text-[9px] px-2 py-0.5 rounded-full font-bold">
                    {presets.length}
                  </span>
                )}
                {showPresets ? <ChevronUp size={14} className="text-white/20" /> : <ChevronDown size={14} className="text-white/20" />}
              </button>

              <button 
                onClick={() => setIsSavingPreset(true)}
                className="flex items-center gap-2 px-3 py-1.5 rounded-xl bg-white/5 border border-white/10 text-white/40 hover:text-white hover:bg-white/10 hover:border-white/20 transition-all group"
                title="Create New Preset"
              >
                <Plus size={14} />
                <span className="text-[10px] font-black uppercase tracking-widest hidden sm:inline">Add</span>
              </button>
            </div>

            {isSavingPreset && (
              <div className="p-6 bg-emerald-500/5 border-b border-white/5 animate-in slide-in-from-top-4">
                <div className="space-y-4">
                  <div className="flex justify-between items-center">
                    <span className="text-[10px] font-black uppercase tracking-[0.2em] text-emerald-400">Cache Current Matrix</span>
                    <button onClick={() => setIsSavingPreset(false)} className="text-white/20 hover:text-white"><X size={14} /></button>
                  </div>
                  <div className="relative">
                    <input 
                        autoFocus
                        type="text"
                        placeholder="Preset Identifier..."
                        value={newPresetName}
                        onChange={(e) => setNewPresetName(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && handleSavePreset()}
                        className="w-full p-4 text-xs font-bold rounded-2xl border border-white/10 bg-nano-50 text-white placeholder:text-white/10 focus:outline-none focus:ring-1 focus:ring-emerald-400 transition-all uppercase tracking-widest"
                    />
                    <Sparkles size={14} className="absolute right-4 top-1/2 -translate-y-1/2 text-white/10" />
                  </div>
                  <Button onClick={handleSavePreset} className="w-full !rounded-2xl !py-3 !text-[10px] !bg-emerald-500 !text-white" icon={<Save size={14} />}>COMMIT TO STORAGE</Button>
                </div>
              </div>
            )}

            {showPresets && (
              <div className="flex flex-col h-[450px]">
                {/* Preset Search */}
                {presets.length > 0 && (
                    <div className="px-5 py-3 border-b border-white/5 bg-black/20">
                        <div className="relative">
                            <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-white/10" />
                            <input 
                                type="text" 
                                placeholder="Search presets library..." 
                                value={presetSearch}
                                onChange={(e) => setPresetSearch(e.target.value)}
                                className="w-full pl-10 pr-4 py-2 bg-transparent border-none text-[10px] font-bold tracking-[0.2em] placeholder:text-white/5 focus:outline-none transition-all uppercase"
                            />
                        </div>
                    </div>
                )}

                <div className="flex-grow p-4 space-y-3 overflow-y-auto hide-scrollbar">
                    {filteredPresets.length === 0 ? (
                    <div className="h-full flex flex-col items-center justify-center opacity-30 px-10 text-center">
                        <div className="w-16 h-16 rounded-[2rem] bg-white/5 flex items-center justify-center mb-6 border border-white/10">
                            <Bookmark size={32} />
                        </div>
                        <p className="text-[10px] font-black text-white uppercase tracking-[0.4em] leading-relaxed">
                            {presets.length === 0 
                                ? "No stored matrices found. Capture your current setup as a new preset." 
                                : "No identifiers match your filter."}
                        </p>
                    </div>
                    ) : (
                    filteredPresets.map((p) => {
                        const styleObj = ART_STYLES.find(s => s.id === p.styleId);
                        return (
                            <div
                                key={p.id}
                                onClick={() => loadPreset(p)}
                                className={`group relative flex flex-col p-4 rounded-2xl border transition-all cursor-pointer overflow-hidden ${lastLoadedPresetId === p.id ? 'border-emerald-500 bg-emerald-500/10 shadow-[0_0_30px_rgba(16,185,129,0.15)]' : 'border-white/5 hover:bg-white/5 bg-white/2 hover:border-white/20'}`}
                            >
                                <div className="flex gap-4">
                                    {/* Thumbnail Preview */}
                                    <div className={`w-12 h-12 rounded-xl border border-white/10 flex-shrink-0 relative overflow-hidden bg-gradient-to-br ${styleObj?.gradient}`}>
                                        {p.referenceImage ? (
                                            <img src={p.referenceImage} className="w-full h-full object-cover" alt="" />
                                        ) : (
                                            <div className="w-full h-full flex items-center justify-center opacity-40">
                                                <ImageIcon size={14} />
                                            </div>
                                        )}
                                        <div className="absolute inset-0 bg-black/10"></div>
                                    </div>

                                    <div className="min-w-0 flex-grow">
                                        <div className="flex items-center justify-between">
                                            {editingPresetId === p.id ? (
                                                <div className="flex items-center gap-2" onClick={e => e.stopPropagation()}>
                                                    <input 
                                                        autoFocus
                                                        type="text"
                                                        value={editNameValue}
                                                        onChange={(e) => setEditNameValue(e.target.value)}
                                                        onKeyDown={(e) => e.key === 'Enter' && handleUpdatePresetName(p.id)}
                                                        onBlur={() => handleUpdatePresetName(p.id)}
                                                        className="bg-nano-100 border border-white/20 rounded-lg px-2 py-0.5 text-[10px] font-black uppercase text-white focus:outline-none ring-1 ring-emerald-500/50"
                                                    />
                                                </div>
                                            ) : (
                                                <p className={`text-[11px] font-black truncate transition-colors uppercase tracking-wider ${lastLoadedPresetId === p.id ? 'text-emerald-400' : 'text-white'}`}>{p.name}</p>
                                            )}
                                        </div>
                                        <div className="flex items-center gap-2 mt-2">
                                            <span className="text-[8px] font-black text-white/30 uppercase tracking-[0.2em]">{styleObj?.name || 'Manual'}</span>
                                            <div className="w-1 h-1 bg-white/10 rounded-full"></div>
                                            <span className="text-[8px] font-black text-white/30 uppercase tracking-[0.2em]">{p.aspectRatio}</span>
                                            {p.referenceImage && (
                                                <>
                                                    <div className="w-1 h-1 bg-white/10 rounded-full"></div>
                                                    <span className="text-[8px] font-black text-emerald-500/60 uppercase tracking-[0.2em]">Ref</span>
                                                </>
                                            )}
                                        </div>
                                    </div>

                                    <div className="flex items-center gap-1 shrink-0 opacity-0 group-hover:opacity-100 transition-all">
                                        <button 
                                            onClick={(e) => copyPromptFromPreset(e, p.id, p.prompt)} 
                                            className={`p-2 rounded-lg transition-all ${copiedId === p.id ? 'bg-emerald-500 text-white' : 'text-white/20 hover:text-white hover:bg-white/10'}`}
                                            title="Copy Prompt"
                                        >
                                            {copiedId === p.id ? <Check size={12} /> : <Copy size={12} />}
                                        </button>
                                        <button 
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                setEditingPresetId(p.id);
                                                setEditNameValue(p.name);
                                            }} 
                                            className="p-2 rounded-lg text-white/20 hover:text-white hover:bg-white/10 transition-all"
                                            title="Rename"
                                        >
                                            <Edit2 size={12} />
                                        </button>
                                        <button 
                                            onClick={(e) => deletePreset(p.id, e)} 
                                            className="p-2 rounded-lg text-white/20 hover:text-red-400 hover:bg-red-500/10 transition-all"
                                            title="Delete"
                                        >
                                            <Trash2 size={12} />
                                        </button>
                                    </div>
                                </div>
                                {lastLoadedPresetId === p.id && (
                                    <div className="absolute top-0 right-0 p-2 animate-in zoom-in">
                                        <div className="bg-emerald-500 rounded-full p-0.5"><Check size={8} className="text-white" /></div>
                                    </div>
                                )}
                            </div>
                        );
                    })
                    )}
                </div>
              </div>
            )}
          </section>

          {/* --- MAIN INPUTS --- */}
          <section className="space-y-4">
            <div className="flex justify-between items-end px-1">
              <div className="space-y-1">
                <label className="block text-xs font-black text-white uppercase tracking-[0.3em]">1. Neural Prompt</label>
                <p className="text-[10px] text-white/30 font-bold uppercase tracking-widest">Visual definition string</p>
              </div>
              <div className="flex gap-1.5 bg-white/5 p-1 rounded-xl">
                <button onClick={handleUndo} disabled={historyIndex === 0} className="p-2 text-white/20 hover:text-white disabled:opacity-5 transition-all"><Undo size={14} /></button>
