            <button onClick={onCancel} className="p-2 text-white/40 hover:text-white hover:bg-white/5 rounded-xl transition-all active:scale-95 focus:outline-none">
                <X size={20} />
            </button>
            <div className="h-6 w-px bg-white/10 mx-1 hidden sm:block"></div>
            <div className="flex items-center gap-1">
                <button onClick={handleUndo} disabled={historyIndex <= 0} className="p-2 text-white/40 hover:text-white hover:bg-white/5 rounded-xl transition-all disabled:opacity-20 disabled:hover:bg-transparent" title="Deshacer Edición">
                   <Undo size={18} />
                </button>
                <button onClick={handleRedo} disabled={historyIndex >= history.length - 1} className="p-2 text-white/40 hover:text-white hover:bg-white/5 rounded-xl transition-all disabled:opacity-20 disabled:hover:bg-transparent" title="Rehacer Edición">
                   <Redo size={18} />
                </button>
            </div>
        </div>

        <div className="flex flex-col items-center">
            <span className="font-black text-[10px] uppercase tracking-[0.4em] text-white/30 mb-0.5">Laboratorio Iterativo</span>
            <div className="flex items-center gap-1.5">
                <div className="w-1.5 h-1.5 bg-emerald-400 rounded-full animate-pulse"></div>
                <span className="text-[11px] font-black uppercase tracking-widest text-white">Sesión de Retoque</span>
            </div>
        </div>

        <div className="flex items-center gap-3">
            <button 
                onClick={handleAIRefine} 
                disabled={!imageLoaded || isRefining} 
                className={`
                    flex items-center gap-2 px-4 py-2 rounded-2xl transition-all font-black text-[10px] uppercase tracking-widest 
                    ${isRefining ? 'bg-emerald-500 text-white animate-pulse' : 'bg-emerald-500/10 text-emerald-400 hover:bg-emerald-500 hover:text-white shadow-[0_0_20px_rgba(16,185,129,0.2)]'}
