            </Button>
            <button onClick={() => setIsSavingPreset(true)} className="w-full py-3.5 text-[10px] font-black uppercase tracking-[0.3em] text-white/20 hover:text-emerald-400 flex items-center justify-center gap-3 border border-white/5 rounded-2xl transition-all">
