                                        </div>
                                    </div>

                                    <div className="flex items-center gap-1 shrink-0 opacity-0 group-hover:opacity-100 transition-all">
                                        <button onClick={(e) => copyPrompt(e, p.id, p.prompt)} className={`p-2 rounded-lg transition-all ${copiedId === p.id ? 'text-emerald-400' : 'text-white/20 hover:text-white'}`}>
                                            {copiedId === p.id ? <Check size={12} /> : <Copy size={12} />}
                                        </button>
                                        <button onClick={(e) => { e.stopPropagation(); setEditingPresetId(p.id); setEditNameValue(p.name); }} className="p-2 text-white/20 hover:text-white">
                                            <Edit2 size={12} />
                                        </button>
                                        <button onClick={(e) => deletePreset(p.id, e)} className="p-2 text-white/20 hover:text-red-400">
                                            <Trash2 size={12} />
                                        </button>
                                    </div>
                                </div>
                            </div>
                        );
                    })
                    )}
                </div>
              </div>
