                   <input type="range" min={isRatioLocked ? getMinZoom() : 0.5} max="4" step="0.01" value={zoom} onChange={(e) => { const val = parseFloat(e.target.value); setZoom(val); setPan(prev => constrainPan(prev, val)); }} onPointerUp={() => pushToHistory(getCurrentState())} className="w-full h-1.5 bg-white/10 rounded-full appearance-none cursor-pointer accent-white" />
                   <div className="flex gap-3">
                     <button onClick={handleLockToggle} className={`p-4 rounded-2xl transition-all active:scale-90 border ${isRatioLocked ? 'bg-white text-nano-50 border-white shadow-xl' : 'text-white/40 border-white/10 hover:bg-white/5'}`} title={isRatioLocked ? "Desbloquear Aspecto" : "Bloquear Aspecto"}>
                       {isRatioLocked ? <Lock size={18} /> : <Unlock size={18} />}
                     </button>
                     <button onClick={handleResetTransform} className="p-4 text-white/40 hover:text-white hover:bg-white/5 border border-white/10 rounded-2xl transition-all active:scale-90" title="Reiniciar Encuadre">
                       <RotateCcw size={18} />
