                                   </button>
                                   <button onClick={() => handleQuickStart("Magical forest with bioluminescent mushrooms", "moody-cinematic")} className="flex flex-col items-center gap-3 p-4 rounded-3xl bg-white/2 border border-white/5 text-white/40 hover:text-white transition-all group">
                                      <div className="p-3 rounded-2xl bg-white/5 group-hover:bg-lime-400/20 group-hover:text-lime-300 transition-all"><Ghost size={18} /></div>
