      <footer className="py-12 border-t border-white/5 bg-black/20 text-center">
            <p className="text-[10px] font-black text-white/10 uppercase tracking-[0.5em] mb-4">Motor Studio {MODEL_NAME_DISPLAY} v2.5</p>
