  Eraser,
  Building2,
  Coffee,
  Cloud,
  MousePointer2,
  Trees,
  User,
  Utensils,
  Glasses,
  Rocket,
  Car,
  Shapes,
  MapPin,
  Shield,
  Home,
  Music,
  Ghost,
  Palette,
  Flame
} from 'lucide-react';
import { ART_STYLES, APP_NAME, MODEL_NAME_DISPLAY, ASPECT_RATIOS, LIGHT_SOURCES, LIGHT_DIRECTIONS } from './constants';
import { GeneratedImage, GenerationStatus, GenerationPreset } from './types';
import { generateImageWithNano, detectImageStyle } from './services/geminiService';
import { Button, StyleCard, Badge } from './components/UI';
import { ImageEditor } from './components/ImageEditor';
import { ZoomablePreview } from './components/ZoomablePreview';

const App: React.FC = () => {
  // --- Estados de Generación ---
  const [prompt, setPrompt] = useState<string>('');
  const [selectedStyleId, setSelectedStyleId] = useState<string>(ART_STYLES[0].id);
  const [aspectRatio, setAspectRatio] = useState<string>('1:1');
  const [lightSourceId, setLightSourceId] = useState<string>('auto');
  const [lightDirectionId, setLightDirectionId] = useState<string>('auto');
  const [seed, setSeed] = useState<number | undefined>(undefined);
  const [creativity, setCreativity] = useState<number>(50);
  const [uploadedImage, setUploadedImage] = useState<string | null>(null);

  // --- Estados de Gestión de Presets ---
  const [presets, setPresets] = useState<GenerationPreset[]>([]);
  const [isSavingPreset, setIsSavingPreset] = useState(false);
  const [newPresetName, setNewPresetName] = useState('');
  const [showPresets, setShowPresets] = useState(true);
  const [presetSearch, setPresetSearch] = useState('');
  const [editingPresetId, setEditingPresetId] = useState<string | null>(null);
  const [editNameValue, setEditNameValue] = useState('');
  const [lastLoadedPresetId, setLastLoadedPresetId] = useState<string | null>(null);
  const [copiedId, setCopiedId] = useState<string | null>(null);

  // --- Estados de Interfaz y Resultados ---
  const [status, setStatus] = useState<GenerationStatus>('idle');
  const [currentImage, setCurrentImage] = useState<GeneratedImage | null>(null);
  const [history, setHistory] = useState<GeneratedImage[]>([]);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [showAdvanced, setShowAdvanced] = useState<boolean>(false);
  const [isEditing, setIsEditing] = useState(false);
  const [isDetectingStyle, setIsDetectingStyle] = useState(false);
  const [lastAutoSelectedStyleId, setLastAutoSelectedStyleId] = useState<string | null>(null);

  // --- Historial de Prompt (Undo/Redo) ---
  const [promptHistory, setPromptHistory] = useState<string[]>(['']);
  const [historyIndex, setHistoryIndex] = useState(0);
  const debounceRef = useRef<any>(null);

  const previewRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- Persistencia de Presets ---
  useEffect(() => {
    const saved = localStorage.getItem('nanoframe_presets_v8');
    if (saved) {
      try {
        setPresets(JSON.parse(saved));
      } catch (e) {
        console.error("Error al cargar presets", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('nanoframe_presets_v8', JSON.stringify(presets));
  }, [presets]);

  // --- Handlers de Usuario ---

  const handlePromptChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newVal = e.target.value;
    setPrompt(newVal);
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => {
      setPromptHistory(prev => {
        const newHistory = prev.slice(0, historyIndex + 1);
        newHistory.push(newVal);
        return newHistory;
      });
      setHistoryIndex(prev => prev + 1);
    }, 400);
  };

  const handleUndo = () => {
    if (historyIndex > 0) {
      const newIndex = historyIndex - 1;
      setHistoryIndex(newIndex);
      setPrompt(promptHistory[newIndex]);
    }
  };

  const handleRedo = () => {
    if (historyIndex < promptHistory.length - 1) {
      const newIndex = historyIndex + 1;
      setHistoryIndex(newIndex);
      setPrompt(promptHistory[newIndex]);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = async (event) => {
        if (event.target?.result) {
          const base64 = event.target.result as string;
          setUploadedImage(base64);
          setIsDetectingStyle(true);
          try {
            const detectedStyleId = await detectImageStyle(base64);
            if (detectedStyleId) {
                const matchedStyle = ART_STYLES.find(s => detectedStyleId.includes(s.id));
                if (matchedStyle) {
                    setSelectedStyleId(matchedStyle.id);
                    setLastAutoSelectedStyleId(matchedStyle.id);
                    setTimeout(() => setLastAutoSelectedStyleId(null), 3000);
                }
            }
          } catch (err) {
            console.warn("Detección de estilo fallida", err);
          } finally {
            setIsDetectingStyle(false);
          }
        }
      };
      reader.readAsDataURL(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  // --- Gestión de Presets ---

  const handleSavePreset = () => {
    if (!newPresetName.trim()) {
      setIsSavingPreset(false);
      return;
    }

    const newPreset: GenerationPreset = {
      id: crypto.randomUUID(),
      name: newPresetName.trim(),
      prompt: prompt,
      styleId: selectedStyleId,
      aspectRatio: aspectRatio,
      seed: seed,
      creativity: creativity,
      timestamp: Date.now(),
      referenceImage: uploadedImage,
      lightSourceId: lightSourceId,
      lightDirectionId: lightDirectionId
    };

    setPresets(prev => [newPreset, ...prev]);
    setLastLoadedPresetId(newPreset.id);
    setNewPresetName('');
    setIsSavingPreset(false);
    setTimeout(() => setLastLoadedPresetId(null), 2000);
  };

  const loadPreset = (p: GenerationPreset) => {
    setPrompt(p.prompt);
    setSelectedStyleId(p.styleId);
    setAspectRatio(p.aspectRatio);
    setSeed(p.seed);
    setCreativity(p.creativity);
    setUploadedImage(p.referenceImage || null);
    setLightSourceId(p.lightSourceId || 'auto');
    setLightDirectionId(p.lightDirectionId || 'auto');
    setLastLoadedPresetId(p.id);

    // Al cargar un preset, actualizamos el historial de prompt
    setPromptHistory(prev => [...prev.slice(0, historyIndex + 1), p.prompt]);
    setHistoryIndex(prev => prev + 1);

    setTimeout(() => setLastLoadedPresetId(null), 1500);
  };

  const deletePreset = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm("¿Eliminar este preset permanentemente?")) {
      setPresets(prev => prev.filter(p => p.id !== id));
    }
  };

  const handleUpdatePresetName = (id: string) => {
    if (!editNameValue.trim()) {
      setEditingPresetId(null);
      return;
    }
    setPresets(prev => prev.map(p => p.id === id ? { ...p, name: editNameValue.trim() } : p));
    setEditingPresetId(null);
  };

  const copyPromptToClipboard = (e: React.MouseEvent, id: string, text: string) => {
    e.stopPropagation();
    navigator.clipboard.writeText(text);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const handleGenerate = async () => {
    const currentPrompt = prompt.trim();
    if (!currentPrompt && !uploadedImage) {
        setErrorMsg("Introduce un prompt o sube una imagen de referencia.");
        setStatus('error');
        return;
    }

    setStatus('generating');
    setErrorMsg(null);
    setCurrentImage(null);
    setIsEditing(false);

    if (window.innerWidth < 768) previewRef.current?.scrollIntoView({ behavior: 'smooth' });

    try {
      const base64Image = await generateImageWithNano(
          currentPrompt, 
          selectedStyleId, 
          aspectRatio, 
          seed, 
          creativity, 
          uploadedImage,
          lightSourceId,
          lightDirectionId
      );

      const newImage: GeneratedImage = {
        id: crypto.randomUUID(),
        url: base64Image,
        prompt: currentPrompt || 'Sintetizado',
        styleId: selectedStyleId,
        aspectRatio: aspectRatio,
        seed: seed,
        creativity: creativity,
        referenceImage: uploadedImage,
        lightSourceId: lightSourceId,
        lightDirectionId: lightDirectionId,
        timestamp: Date.now()
      };

      setCurrentImage(newImage);
      setHistory(prev => [newImage, ...prev].slice(0, 10));
      setStatus('success');
    } catch (error) {
      console.error(error);
      setStatus('error');
      setErrorMsg("Error en el motor neuronal. Intenta de nuevo.");
    }
  };

  const handleSaveEdit = (newImageSrc: string) => {
    if (!currentImage) return;

    const updatedImage: GeneratedImage = {
      ...currentImage,
      id: crypto.randomUUID(),
      url: newImageSrc,
      timestamp: Date.now()
    };

    setCurrentImage(updatedImage);
    setHistory(prev => [updatedImage, ...prev].slice(0, 10));
    setIsEditing(false);
    setStatus('success');
  };

  const handleQuickStart = (p: string, style?: string) => {
    setPrompt(p);
    if (style) setSelectedStyleId(style);
    setTimeout(() => handleGenerate(), 100);
  };

  const resetWorkspace = () => {
    if (confirm("¿Reiniciar laboratorio? Se perderá el trabajo no guardado.")) {
      setPrompt('');
      setSelectedStyleId(ART_STYLES[0].id);
      setAspectRatio('1:1');
      setSeed(undefined);
      setCreativity(50);
      setUploadedImage(null);
      setLightSourceId('auto');
      setLightDirectionId('auto');
      setStatus('idle');
      setCurrentImage(null);
    }
  };

  const filteredPresets = presets.filter(p => 
    p.name.toLowerCase().includes(presetSearch.toLowerCase()) ||
    p.prompt.toLowerCase().includes(presetSearch.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-nano-50 text-white selection:bg-emerald-500 selection:text-white flex flex-col font-sans">

      <header className="bg-nano-100/80 backdrop-blur-xl sticky top-0 z-50 border-b border-white/10 shadow-lg">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-nano-50 shadow-2xl ring-1 ring-white/20">
              <Camera size={22} />
            </div>
            <div className="flex flex-col">
                <h1 className="text-xl font-black tracking-tight leading-none">{APP_NAME}</h1>
                <span className="text-[9px] font-bold text-white/30 tracking-widest uppercase">Síntesis Visual</span>
            </div>
            <Badge text={MODEL_NAME_DISPLAY} />
          </div>
          <div className="flex items-center gap-6">
             <button onClick={resetWorkspace} className="text-[10px] font-black text-white/40 hover:text-red-400 flex items-center gap-1.5 transition-all uppercase tracking-[0.2em]">
               <Eraser size={14} /> Reiniciar
             </button>
             <div className="hidden sm:flex items-center gap-2">
                <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse"></div>
                <div className="text-[10px] text-white/40 font-black uppercase tracking-widest">Estudio Activo</div>
             </div>
          </div>
        </div>
      </header>

      <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full flex flex-col lg:flex-row gap-8 lg:gap-12">

        {/* Columna Izquierda: Deck de Control */}
        <aside className="w-full lg:w-1/3 flex flex-col gap-8 order-2 lg:order-1 pb-12">

          {/* --- SECCIÓN MIS PRESETS --- */}
          <section className="bg-nano-100 rounded-[2rem] border border-white/10 overflow-hidden shadow-2xl flex flex-col">
            <div className="p-6 border-b border-white/5 flex items-center justify-between bg-white/2">
              <button 
                onClick={() => setShowPresets(!showPresets)}
                className="flex items-center gap-3 text-[11px] font-black uppercase tracking-[0.2em]"
              >
                <Bookmark size={16} className={presets.length > 0 ? 'text-emerald-400' : 'text-white/20'} fill={presets.length > 0 ? 'currentColor' : 'none'} />
                Mis Presets
                {presets.length > 0 && <span className="bg-white/10 text-white/60 text-[9px] px-2 py-0.5 rounded-full font-mono">{presets.length}</span>}
                {showPresets ? <ChevronUp size={14} className="opacity-20" /> : <ChevronDown size={14} className="opacity-20" />}
              </button>

              <button 
                onClick={() => setIsSavingPreset(true)}
                className="flex items-center gap-2 px-3 py-1.5 rounded-xl bg-white/5 border border-white/10 text-white/40 hover:text-white transition-all group"
                title="Guardar configuración actual"
              >
                <Plus size={14} className="group-hover:scale-125 transition-transform" />
                <span className="text-[10px] font-black uppercase tracking-widest">Nuevo</span>
              </button>
            </div>

            {isSavingPreset && (
              <div className="p-6 bg-emerald-500/5 border-b border-white/5 animate-in slide-in-from-top-4">
                <div className="space-y-4">
                  <div className="flex justify-between items-center">
                    <div className="flex items-center gap-2">
                      <Save size={12} className="text-emerald-400" />
                      <span className="text-[10px] font-black uppercase tracking-[0.2em] text-emerald-400">Capturar Estado</span>
                    </div>
                    <button onClick={() => setIsSavingPreset(false)} className="text-white/20 hover:text-white"><X size={14} /></button>
                  </div>
                  <input 
                      autoFocus
                      type="text"
                      placeholder="Nombre del preset..."
                      value={newPresetName}
                      onChange={(e) => setNewPresetName(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && handleSavePreset()}
                      className="w-full p-4 text-xs font-bold rounded-2xl border border-white/10 bg-nano-50 text-white focus:outline-none focus:ring-1 focus:ring-emerald-400 uppercase tracking-widest placeholder:text-white/5"
                  />
                  <Button onClick={handleSavePreset} className="w-full !rounded-2xl !py-3 !text-[10px] !bg-emerald-500" icon={<Save size={14} />}>GUARDAR PRESET</Button>
                </div>
              </div>
            )}

            {showPresets && (
              <div className="flex flex-col h-[400px]">
                {presets.length > 0 ? (
                    <>
                        <div className="px-5 py-3 border-b border-white/5 bg-black/20">
                            <div className="relative">
                                <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-white/10" />
                                <input 
                                    type="text" 
                                    placeholder="BUSCAR EN BIBLIOTECA..." 
                                    value={presetSearch}
                                    onChange={(e) => setPresetSearch(e.target.value)}
                                    className="w-full pl-10 pr-4 py-2 bg-transparent border-none text-[10px] font-black tracking-widest focus:outline-none uppercase"
                                />
                            </div>
                        </div>

                        <div className="flex-grow p-4 space-y-3 overflow-y-auto hide-scrollbar">
                            {filteredPresets.length === 0 ? (
                                <div className="h-full flex flex-col items-center justify-center opacity-20 px-10 text-center">
                                    <Search size={40} className="mb-4" />
                                    <p className="text-[10px] font-black uppercase tracking-[0.3em]">Sin coincidencias</p>
                                </div>
                            ) : (
                                filteredPresets.map((p) => {
                                    const styleObj = ART_STYLES.find(s => s.id === p.styleId);
                                    return (
                                        <div
                                            key={p.id}
                                            onClick={() => loadPreset(p)}
                                            className={`group relative flex flex-col p-4 rounded-3xl border transition-all cursor-pointer overflow-hidden ${lastLoadedPresetId === p.id ? 'border-emerald-500 bg-emerald-500/10' : 'border-white/5 hover:bg-white/5 bg-white/2'}`}
                                        >
                                            <div className="flex gap-4">
                                                <div className={`w-12 h-12 rounded-2xl border border-white/10 flex-shrink-0 relative overflow-hidden bg-gradient-to-br ${styleObj?.gradient || 'from-gray-500 to-gray-700'}`}>
                                                    {p.referenceImage ? (
                                                        <img src={p.referenceImage} className="w-full h-full object-cover" alt="" />
                                                    ) : (
                                                        <div className="w-full h-full flex items-center justify-center text-white/20">
                                                            <Sparkles size={16} />
                                                        </div>
                                                    )}
                                                    <div className="absolute inset-0 bg-black/10"></div>
                                                </div>

                                                <div className="min-w-0 flex-grow">
                                                    {editingPresetId === p.id ? (
                                                        <input 
                                                            autoFocus
                                                            value={editNameValue}
                                                            onClick={e => e.stopPropagation()}
                                                            onChange={e => setEditNameValue(e.target.value)}
                                                            onBlur={() => handleUpdatePresetName(p.id)}
                                                            onKeyDown={e => e.key === 'Enter' && handleUpdatePresetName(p.id)}
                                                            className="bg-nano-100 border border-white/20 rounded-lg px-2 py-0.5 text-[10px] font-black uppercase text-white w-full"
                                                        />
                                                    ) : (
                                                        <p className={`text-[11px] font-black truncate transition-colors uppercase tracking-wider ${lastLoadedPresetId === p.id ? 'text-emerald-400' : 'text-white'}`}>{p.name}</p>
                                                    )}
                                                    <div className="flex items-center gap-2 mt-1">
                                                        <span className="text-[8px] font-black text-white/30 uppercase tracking-widest">{styleObj?.name || 'Libre'}</span>
                                                        <div className="w-1 h-1 bg-white/10 rounded-full"></div>
                                                        <span className="text-[8px] font-black text-white/30 uppercase tracking-widest">{p.aspectRatio}</span>
                                                    </div>
                                                </div>

                                                <div className="flex items-center gap-1 shrink-0 opacity-0 group-hover:opacity-100 transition-all">
                                                    <button onClick={(e) => copyPromptToClipboard(e, p.id, p.prompt)} className={`p-2 rounded-lg transition-all ${copiedId === p.id ? 'text-emerald-400' : 'text-white/20 hover:text-white'}`} title="Copiar Prompt">
                                                        {copiedId === p.id ? <Check size={12} /> : <Copy size={12} />}
                                                    </button>
                                                    <button onClick={(e) => { e.stopPropagation(); setEditingPresetId(p.id); setEditNameValue(p.name); }} className="p-2 text-white/20 hover:text-white" title="Renombrar">
                                                        <Edit2 size={12} />
                                                    </button>
                                                    <button onClick={(e) => deletePreset(p.id, e)} className="p-2 text-white/20 hover:text-red-400" title="Eliminar">
                                                        <Trash2 size={12} />
                                                    </button>
                                                </div>
                                            </div>
                                        </div>
                                    );
                                })
                            )}
                        </div>
                    </>
                ) : (
                    <div className="h-full flex flex-col items-center justify-center opacity-20 px-10 text-center py-12">
                        <Bookmark size={48} className="mb-4 text-white" strokeWidth={1} />
                        <h4 className="text-[10px] font-black uppercase tracking-[0.3em] mb-2">Tu biblioteca está vacía</h4>
                        <p className="text-[8px] font-bold uppercase tracking-widest leading-relaxed">Guarda tus configuraciones favoritas para usarlas en cualquier momento.</p>
                        <button onClick={() => setIsSavingPreset(true)} className="mt-6 px-4 py-2 border border-white/20 rounded-full text-[9px] font-black hover:bg-white/5 transition-all">EMPEZAR AHORA</button>
                    </div>
                )}
              </div>
            )}
          </section>

          {/* --- INPUTS PRINCIPALES --- */}
          <section className="space-y-4">
            <div className="flex justify-between items-end px-1">
              <label className="text-xs font-black uppercase tracking-[0.3em]">1. Prompt Neuronal</label>
              <div className="flex gap-1.5 bg-white/5 p-1 rounded-xl">
                <button onClick={handleUndo} disabled={historyIndex === 0} className="p-2 text-white/20 hover:text-white disabled:opacity-5 transition-all"><Undo size={14} /></button>
                <button onClick={handleRedo} disabled={historyIndex >= promptHistory.length - 1} className="p-2 text-white/20 hover:text-white disabled:opacity-5 transition-all"><Redo size={14} /></button>
              </div>
            </div>
            <textarea
                value={prompt}
                onChange={handlePromptChange}
                placeholder="Describe tu visión con todo lujo de detalles..."
                className="w-full p-6 rounded-[2rem] border border-white/10 bg-nano-100 shadow-2xl text-white placeholder:text-white/5 focus:ring-1 focus:ring-emerald-500 h-44 transition-all resize-none text-[13px] font-medium leading-relaxed"
            />
          </section>

          {/* --- MATRIZ DE ESTILO --- */}
          <section className="space-y-4">
            <label className="block text-xs font-black uppercase tracking-[0.3em] px-1">2. Matriz Estética</label>
            <div className="grid grid-cols-2 gap-4">
              {ART_STYLES.map((style) => (
                <StyleCard 
                  key={style.id} 
                  style={style} 
                  isSelected={selectedStyleId === style.id} 
                  isAutoSelected={lastAutoSelectedStyleId === style.id}
                  onClick={() => setSelectedStyleId(style.id)} 
                />
              ))}
            </div>
          </section>

          {/* --- REFERENCIA Y CONFIGURACIÓN --- */}
          <section className="space-y-6">
            <div className="space-y-4">
                <label className="block text-xs font-black uppercase tracking-[0.3em] px-1">3. Guía Visual</label>
                <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept="image/*" className="hidden" />
                {!uploadedImage ? (
                    <button onClick={() => fileInputRef.current?.click()} className="w-full py-10 border-2 border-dashed border-white/10 rounded-[2.5rem] flex flex-col items-center justify-center gap-3 bg-white/2 hover:bg-emerald-500/5 transition-all group">
                        <Upload size={24} className="text-white/20 group-hover:text-emerald-400 transition-colors" />
                        <span className="text-[10px] font-black uppercase tracking-widest text-white/20 group-hover:text-white/40">Sube una imagen de referencia</span>
                    </button>
                ) : (
                    <div className="relative rounded-[2.5rem] overflow-hidden aspect-video border border-white/20 shadow-2xl group">
                        <img src={uploadedImage} alt="Referencia" className="w-full h-full object-cover" />
                        <div className="absolute inset-0 bg-nano-50/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-6 backdrop-blur-sm">
                            <button onClick={() => fileInputRef.current?.click()} className="p-4 bg-white text-nano-50 rounded-2xl hover:scale-110 transition-all"><RefreshCw size={24} /></button>
                            <button onClick={() => setUploadedImage(null)} className="p-4 bg-red-500 text-white rounded-2xl hover:scale-110 transition-all"><Trash2 size={24} /></button>
                        </div>
                        {isDetectingStyle && <div className="absolute inset-0 bg-nano-50/80 flex items-center justify-center"><span className="text-[9px] font-black uppercase tracking-[0.4em] animate-pulse">Analizando...</span></div>}
                    </div>
                )}
            </div>

            <div className="space-y-4">
                <label className="block text-xs font-black uppercase tracking-[0.3em] px-1">4. Formato</label>
                <div className="grid grid-cols-4 sm:grid-cols-5 lg:grid-cols-4 xl:grid-cols-5 gap-3">
                    {ASPECT_RATIOS.map((ratio) => (
                        <button
                            key={ratio.id}
                            onClick={() => setAspectRatio(ratio.id)}
                            className={`flex flex-col items-center justify-center py-4 rounded-2xl border transition-all ${aspectRatio === ratio.id ? 'bg-white text-nano-50 border-white shadow-lg' : 'bg-nano-100 text-white/20 border-white/5 hover:text-white/40'}`}
                        >
                            <div className={`border-2 rounded-sm mb-2 ${ratio.shapeClass} ${aspectRatio === ratio.id ? 'border-nano-50 bg-nano-50' : 'border-white/10'}`}></div>
                            <span className="text-[9px] font-black uppercase tracking-widest">{ratio.label}</span>
                        </button>
                    ))}
                </div>
            </div>

            <button 
                onClick={() => setShowAdvanced(!showAdvanced)} 
                className={`flex items-center justify-between w-full p-5 rounded-2xl border transition-all ${showAdvanced ? 'bg-white/5 border-emerald-500/30' : 'bg-white/2 border-white/10'}`}
            >
                <div className="flex items-center gap-4">
                    <Sliders size={18} className={showAdvanced ? 'text-emerald-400' : 'text-white/40'} />
                    <span className={`text-[11px] font-black uppercase tracking-[0.2em] ${showAdvanced ? 'text-white' : 'text-white/40'}`}>Ajustes de Estudio</span>
                </div>
                {showAdvanced ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
            </button>

            {showAdvanced && (
                <div className="p-6 bg-nano-100 rounded-[2rem] border border-white/10 space-y-8 animate-in slide-in-from-top-4">
                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <label className="text-[9px] font-bold text-white/20 uppercase tracking-widest">Fuente de Luz</label>
                            <select value={lightSourceId} onChange={(e) => setLightSourceId(e.target.value)} className="w-full bg-nano-50 border border-white/10 text-white text-[10px] font-black uppercase rounded-xl px-4 py-3 focus:outline-none focus:ring-1 focus:ring-emerald-400">
                                {LIGHT_SOURCES.map(l => <option key={l.id} value={l.id}>{l.label}</option>)}
                            </select>
                        </div>
                        <div className="space-y-2">
                            <label className="text-[9px] font-bold text-white/20 uppercase tracking-widest">Dirección</label>
                            <select value={lightDirectionId} onChange={(e) => setLightDirectionId(e.target.value)} className="w-full bg-nano-50 border border-white/10 text-white text-[10px] font-black uppercase rounded-xl px-4 py-3 focus:outline-none focus:ring-1 focus:ring-emerald-400">
                                {LIGHT_DIRECTIONS.map(l => <option key={l.id} value={l.id}>{l.label}</option>)}
                            </select>
                        </div>
                    </div>
                    <div className="space-y-4">
                        <div className="flex justify-between items-center">
                            <label className="text-[10px] font-black uppercase tracking-widest text-white/40">Creatividad de IA</label>
                            <span className="text-emerald-400 text-[10px] font-black">{creativity}%</span>
                        </div>
                        <input type="range" min="0" max="100" value={creativity} onChange={(e) => setCreativity(parseInt(e.target.value))} className="w-full h-1.5 bg-white/5 rounded-full appearance-none accent-emerald-500" />
                    </div>
                </div>
            )}
          </section>

          {/* --- BOTONES DE ACCIÓN --- */}
          <div className="pt-4 flex flex-col gap-3">
            <Button 
                onClick={handleGenerate} 
                isLoading={status === 'generating'} 
                className="w-full !rounded-[2rem] !h-20 shadow-[0_20px_50px_rgba(0,0,0,0.5)] border-t border-white/20 active:scale-95" 
                icon={<Zap size={24} className="fill-nano-50" />}
            >
               {status === 'generating' ? 'SINTETIZANDO...' : 'EJECUTAR GENERACIÓN'}
            </Button>

            <button 
              onClick={() => setIsSavingPreset(true)} 
              className="w-full py-3.5 text-[10px] font-black uppercase tracking-[0.3em] text-white/20 hover:text-emerald-400 flex items-center justify-center gap-3 border border-white/5 rounded-2xl transition-all bg-white/2 hover:bg-white/5"
            >
              <Save size={14} /> Guardar configuración actual
            </button>

            {errorMsg && <p className="text-red-400 text-[10px] font-black text-center mt-2 uppercase tracking-widest animate-pulse">{errorMsg}</p>}
          </div>
        </aside>

        {/* Columna Derecha: Output Creativo */}
        <section className="w-full lg:w-2/3 flex flex-col gap-8 order-1 lg:order-2">

          <div ref={previewRef} className="w-full bg-nano-100 rounded-[3rem] shadow-2xl border border-white/10 overflow-hidden relative flex flex-col min-h-[650px] lg:min-h-[850px]">

            {isEditing && currentImage ? (
                <ImageEditor 
                  imageSrc={currentImage.url} 
                  prompt={prompt} 
                  styleId={selectedStyleId}
                  initialCreativity={creativity}
                  lightSourceId={lightSourceId}
                  lightDirectionId={lightDirectionId}
                  onSave={handleSaveEdit} 
                  onCancel={() => setIsEditing(false)} 
                />
            ) : (
                <>
                    <header className="h-24 border-b border-white/5 flex items-center justify-between px-10 bg-nano-100/40 backdrop-blur-2xl z-10 shrink-0">
                      <div className="flex items-center gap-4">
                        <div className="w-3 h-3 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_15px_#10b981]"></div>
                        <div className="flex flex-col">
                            <span className="text-[12px] font-black uppercase tracking-[0.4em] text-white">Stream de Síntesis</span>
                            <span className="text-[8px] font-bold text-white/20 uppercase tracking-widest">{status === 'success' ? 'Carga completada' : 'Listo para procesar'}</span>
                        </div>
                      </div>

                      {status === 'success' && currentImage && (
                        <div className="flex gap-3 items-center">
                          <button onClick={() => setIsEditing(true)} className="p-4 bg-white/5 hover:bg-white/10 border border-white/5 rounded-2xl text-white transition-all" title="Retoque Manual"><Edit2 size={20} /></button>
