  Sun, 
  Contrast, 
  Lock, 
  Unlock,
  Palette,
  Droplets,
  Eye,
  EyeOff,
  Sparkles,
  Zap,
  Undo,
  Redo,
  BrainCircuit,
  MessageSquareText,
  MousePointer2,
  ChevronRight
} from 'lucide-react';
import { IMAGE_FILTERS, ASPECT_RATIOS, REFINEMENT_PRESETS } from '../constants';
import { generateImageWithNano } from '../services/geminiService';

interface ImageEditorProps {
  imageSrc: string;
  prompt: string;
  styleId: string;
  initialCreativity: number;
  lightSourceId?: string;
  lightDirectionId?: string;
  onSave: (newImageSrc: string) => void;
  onCancel: () => void;
}

// Define the shape of our history state
type EditorState = {
  imageSrc: string;
  filterId: string;
  adjustments: {
    brightness: number;
    contrast: number;
    saturation: number;
    hueRotate: number;
    creativity: number;
  };
  transform: {
    zoom: number;
    cropRatio: string;
    pan: { x: number; y: number };
    isRatioLocked: boolean;
  };
};

export const ImageEditor: React.FC<ImageEditorProps> = ({ 
  imageSrc: initialImageSrc, 
  prompt: initialPrompt, 
  styleId, 
  initialCreativity,
  lightSourceId = 'auto',
  lightDirectionId = 'auto',
  onSave, 
  onCancel 
}) => {
  const [activeTab, setActiveTab] = useState<'filter' | 'adjust' | 'crop' | 'refine'>('filter');
  const [selectedFilterId, setSelectedFilterId] = useState('none');
  const [hoveredFilterId, setHoveredFilterId] = useState<string | null>(null);
  const [imageLoaded, setImageLoaded] = useState(false);
  const [currentImageSrc, setCurrentImageSrc] = useState(initialImageSrc);
  const [isRefining, setIsRefining] = useState(false);
  const [localPrompt, setLocalPrompt] = useState(initialPrompt);
  const [showBefore, setShowBefore] = useState(false);

  // Adjustment state
  const [brightness, setBrightness] = useState(100); 
  const [contrast, setContrast] = useState(100);   
  const [saturation, setSaturation] = useState(100); 
  const [hueRotate, setHueRotate] = useState(0);    
  const [creativity, setCreativity] = useState(initialCreativity);

  // Crop state
  const [zoom, setZoom] = useState(1);
  const [cropRatio, setCropRatio] = useState<string>('1:1');
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [isRatioLocked, setIsRatioLocked] = useState(true);

  // Interaction state
  const [isDragging, setIsDragging] = useState(false);
  const [isResetting, setIsResetting] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  // History state
  const [history, setHistory] = useState<EditorState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  const imageRef = useRef<HTMLImageElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // --- History Helpers ---

  const getCurrentState = useCallback((overrides: Partial<EditorState> = {}): EditorState => ({
    imageSrc: currentImageSrc,
    filterId: selectedFilterId,
    adjustments: { brightness, contrast, saturation, hueRotate, creativity },
    transform: { zoom, cropRatio, pan, isRatioLocked },
    ...overrides
  }), [currentImageSrc, selectedFilterId, brightness, contrast, saturation, hueRotate, creativity, zoom, cropRatio, pan, isRatioLocked]);

  useEffect(() => {
    if (history.length === 0) {
      const initialState = getCurrentState();
      setHistory([initialState]);
      setHistoryIndex(0);
    }
  }, []);

  const pushToHistory = (newState: EditorState) => {
    if (historyIndex >= 0) {
      const currentState = history[historyIndex];
      if (JSON.stringify(currentState) === JSON.stringify(newState)) return;
    }
    const newHistory = history.slice(0, historyIndex + 1);
    newHistory.push(newState);
    setHistory(newHistory);
    setHistoryIndex(newHistory.length - 1);
  };

  const handleUndo = () => {
    if (historyIndex > 0) {
      const newIndex = historyIndex - 1;
      setHistoryIndex(newIndex);
      restoreState(history[newIndex]);
    }
  };

  const handleRedo = () => {
    if (historyIndex < history.length - 1) {
      const newIndex = historyIndex + 1;
      setHistoryIndex(newIndex);
      restoreState(history[newIndex]);
    }
  };

  const restoreState = (state: EditorState) => {
    setCurrentImageSrc(state.imageSrc);
    setSelectedFilterId(state.filterId);
    setBrightness(state.adjustments.brightness);
    setContrast(state.adjustments.contrast);
    setSaturation(state.adjustments.saturation);
    setHueRotate(state.adjustments.hueRotate);
    setCreativity(state.adjustments.creativity);
    setZoom(state.transform.zoom);
    setCropRatio(state.transform.cropRatio);
    setPan(state.transform.pan);
    setIsRatioLocked(state.transform.isRatioLocked);
  };

  // --- Logic ---

  const getMinZoom = useCallback(() => {
    if (!imageRef.current || !containerRef.current) return 1;
    const img = imageRef.current;
    const container = containerRef.current;
    const containerAspect = container.clientWidth / container.clientHeight;
    const imgAspect = img.naturalWidth / img.naturalHeight;
    return imgAspect > containerAspect ? 1 : containerAspect / imgAspect;
  }, []);

  const constrainPan = useCallback((currentPan: { x: number; y: number }, currentZoom: number) => {
    if (isResetting || !isRatioLocked || !imageRef.current || !containerRef.current) return currentPan;
    const img = imageRef.current;
    const container = containerRef.current;
    const imgAspect = img.naturalWidth / img.naturalHeight;
    const containerAspect = container.clientWidth / container.clientHeight;
    let displayWidth, displayHeight;
    if (imgAspect > containerAspect) {
      displayHeight = container.clientHeight;
      displayWidth = container.clientHeight * imgAspect;
    } else {
      displayWidth = container.clientWidth;
      displayHeight = container.clientWidth / imgAspect;
    }
    const scaledWidth = displayWidth * currentZoom;
    const scaledHeight = displayHeight * currentZoom;
    const maxX = Math.max(0, (scaledWidth - container.clientWidth) / 2) / currentZoom;
    const maxY = Math.max(0, (scaledHeight - container.clientHeight) / 2) / currentZoom;
    return {
      x: Math.min(Math.max(currentPan.x, -maxX), maxX),
      y: Math.min(Math.max(currentPan.y, -maxY), maxY)
    };
  }, [isRatioLocked, isResetting]);

  useEffect(() => {
    if (isRatioLocked && imageLoaded && !isResetting) {
      const minZoom = getMinZoom();
      if (zoom < minZoom) setZoom(minZoom);
      setPan(prev => constrainPan(prev, Math.max(zoom, minZoom)));
    }
  }, [isRatioLocked, cropRatio, imageLoaded, zoom, constrainPan, getMinZoom, isResetting]);

  const effectiveFilterId = hoveredFilterId || selectedFilterId;
  const activeFilterObject = IMAGE_FILTERS.find(f => f.id === effectiveFilterId);
  const baseFilter = activeFilterObject?.filter || 'none';
  const currentFilter = `${baseFilter === 'none' ? '' : baseFilter} brightness(${brightness}%) contrast(${contrast}%) saturate(${saturation}%) hue-rotate(${hueRotate}deg)`;

  const handlePointerDown = (e: React.PointerEvent) => {
    if (isResetting) return;
    setIsDragging(true);
    setDragStart({ x: e.clientX - pan.x * zoom, y: e.clientY - pan.y * zoom });
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (isDragging) {
      const newPan = {
        x: (e.clientX - dragStart.x) / zoom,
        y: (e.clientY - dragStart.y) / zoom
      };
      setPan(constrainPan(newPan, zoom));
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (isDragging) pushToHistory(getCurrentState());
    setIsDragging(false);
    (e.target as HTMLElement).releasePointerCapture(e.pointerId);
  };

  const handleResetTransform = () => {
    if (isResetting) return;
    setIsResetting(true);
    const targetZoom = isRatioLocked ? getMinZoom() : 1;
    const targetPan = { x: 0, y: 0 };
    setZoom(targetZoom);
    setPan(targetPan);
    pushToHistory({
        ...getCurrentState(),
        transform: { zoom: targetZoom, pan: targetPan, cropRatio, isRatioLocked }
    });
    setTimeout(() => setIsResetting(false), 600);
  };

  const handleResetAdjustments = () => {
    setBrightness(100);
    setContrast(100);
    setSaturation(100);
    setHueRotate(0);
    setCreativity(initialCreativity);
    setSelectedFilterId('none');
    pushToHistory({
        ...getCurrentState(),
        filterId: 'none',
        adjustments: { brightness: 100, contrast: 100, saturation: 100, hueRotate: 0, creativity: initialCreativity }
    });
  };

  const handleFilterSelect = (id: string) => {
    setSelectedFilterId(id);
    pushToHistory(getCurrentState({ filterId: id }));
  };

  const handleRatioSelect = (r: string) => {
    setCropRatio(r);
    pushToHistory(getCurrentState({ transform: { zoom, cropRatio: r, pan, isRatioLocked } }));
  };

  const handleLockToggle = () => {
    const nextLocked = !isRatioLocked;
    setIsRatioLocked(nextLocked);
    pushToHistory(getCurrentState({ transform: { zoom, cropRatio, pan, isRatioLocked: nextLocked } }));
  };

  const getCanvasData = () => {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    const img = imageRef.current;
    if (!ctx || !img) return null;
    const outputSize = 1024;
    let width = outputSize;
    let height = outputSize;
    const [wRatio, hRatio] = cropRatio.split(':').map(Number);
    if (wRatio && hRatio) {
        if (wRatio && hRatio) {
            if (wRatio > hRatio) height = outputSize * (hRatio / wRatio);
            else width = outputSize * (wRatio / hRatio);
        }
    }
    canvas.width = width;
    canvas.height = height;
    ctx.fillStyle = '#000000';
    ctx.fillRect(0, 0, width, height);
    const container = containerRef.current;
    if (!container) return null;
    const scaleFactor = width / container.clientWidth;
    ctx.save();
    const saveBaseFilter = IMAGE_FILTERS.find(f => f.id === selectedFilterId)?.filter || 'none';
    ctx.filter = `${saveBaseFilter === 'none' ? '' : saveBaseFilter} brightness(${brightness}%) contrast(${contrast}%) saturate(${saturation}%) hue-rotate(${hueRotate}deg)`;
    ctx.translate(width / 2, height / 2);
    ctx.scale(zoom, zoom);
    ctx.translate(pan.x * scaleFactor, pan.y * scaleFactor);
    const imgAspect = img.naturalWidth / img.naturalHeight;
    const containerAspect = container.clientWidth / container.clientHeight;
    let drawWidth, drawHeight;
    if (imgAspect > containerAspect) {
        drawHeight = height / zoom;
        drawWidth = drawHeight * imgAspect;
    } else {
        drawWidth = width / zoom;
        drawHeight = drawWidth / imgAspect;
    }
    ctx.drawImage(img, -drawWidth / 2, -drawHeight / 2, drawWidth, drawHeight);
    ctx.restore();
    if (selectedFilterId === 'vignette') {
      const gradient = ctx.createRadialGradient(
        width / 2, height / 2, 0,
        width / 2, height / 2, Math.sqrt((width/2)**2 + (height/2)**2)
      );
      gradient.addColorStop(0, 'rgba(0,0,0,0)');
      gradient.addColorStop(0.5, 'rgba(0,0,0,0)');
      gradient.addColorStop(1, 'rgba(0,0,0,0.6)');
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, width, height);
    }
    return canvas.toDataURL('image/png', 0.95);
  };

  const handleSave = () => {
    const dataUrl = getCanvasData();
    if (dataUrl) onSave(dataUrl);
  };

  const handleAIRefine = async () => {
    const referenceData = getCanvasData();
    if (!referenceData) return;
    setIsRefining(true);
    setImageLoaded(false);
    try {
      const newImage = await generateImageWithNano(
        localPrompt,
        styleId,
        cropRatio,
        undefined, 
        creativity,
        referenceData,
        lightSourceId,
        lightDirectionId
      );
      setCurrentImageSrc(newImage);
      setBrightness(100);
      setContrast(100);
      setSaturation(100);
      setHueRotate(0);
      setSelectedFilterId('none');
      setZoom(isRatioLocked ? getMinZoom() : 1);
      setPan({ x: 0, y: 0 });
      const newState: EditorState = {
         imageSrc: newImage,
         filterId: 'none',
         adjustments: { brightness: 100, contrast: 100, saturation: 100, hueRotate: 0, creativity: creativity },
         transform: { zoom: isRatioLocked ? getMinZoom() : 1, cropRatio, pan: { x: 0, y: 0 }, isRatioLocked }
      };
      setHistory(prev => [...prev.slice(0, historyIndex + 1), newState]);
      setHistoryIndex(prev => prev + 1);
    } catch (error) {
      console.error("Fallo en Refinar por IA:", error);
      setImageLoaded(true);
    } finally {
      setIsRefining(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] bg-nano-50/95 backdrop-blur-2xl flex flex-col h-full animate-in fade-in duration-500">
      <div className="h-16 border-b border-white/10 flex items-center justify-between px-6 bg-nano-100 shrink-0 shadow-xl z-20">
        <div className="flex items-center gap-3">
            <button onClick={onCancel} className="p-2 text-white/40 hover:text-white hover:bg-white/5 rounded-xl transition-all active:scale-95 focus:outline-none">
                <X size={20} />
            </button>
            <div className="h-6 w-px bg-white/10 mx-1 hidden sm:block"></div>
            <div className="flex items-center gap-1">
                <button onClick={handleUndo} disabled={historyIndex <= 0} className="p-2 text-white/40 hover:text-white hover:bg-white/5 rounded-xl transition-all disabled:opacity-20 disabled:hover:bg-transparent" title="Deshacer Edición">
                   <Undo size={18} />
                </button>
                <button onClick={handleRedo} disabled={historyIndex >= history.length - 1} className="p-2 text-white/40 hover:text-white hover:bg-white/5 rounded-xl transition-all disabled:opacity-20 disabled:hover:bg-transparent" title="Rehacer Edición">
                   <Redo size={18} />
                </button>
            </div>
        </div>

        <div className="flex flex-col items-center">
            <span className="font-black text-[10px] uppercase tracking-[0.4em] text-white/30 mb-0.5">Laboratorio Iterativo</span>
            <div className="flex items-center gap-1.5">
                <div className="w-1.5 h-1.5 bg-emerald-400 rounded-full animate-pulse"></div>
                <span className="text-[11px] font-black uppercase tracking-widest text-white">Sesión de Retoque</span>
            </div>
        </div>

        <div className="flex items-center gap-3">
            <button 
                onClick={handleAIRefine} 
                disabled={!imageLoaded || isRefining} 
                className={`
                    flex items-center gap-2 px-4 py-2 rounded-2xl transition-all font-black text-[10px] uppercase tracking-widest 
                    ${isRefining ? 'bg-emerald-500 text-white animate-pulse' : 'bg-emerald-500/10 text-emerald-400 hover:bg-emerald-500 hover:text-white shadow-[0_0_20px_rgba(16,185,129,0.2)]'}
                    disabled:opacity-30 disabled:pointer-events-none active:scale-95
                `}
                title="Refinar por IA al instante"
            >
                <Zap size={16} fill={isRefining ? "currentColor" : "none"} />
                <span className="hidden sm:block">Refinar</span>
            </button>
            <div className="h-6 w-px bg-white/10 mx-1"></div>
            <button 
                onClick={handleSave} 
                disabled={!imageLoaded || isRefining} 
                className="p-3 bg-white text-nano-50 hover:bg-white/90 rounded-2xl transition-all font-bold disabled:opacity-30 active:scale-95 shadow-xl"
                title="Guardar Cambios"
            >
                <Check size={20} strokeWidth={3} />
            </button>
        </div>
      </div>

      <div className="flex-grow overflow-hidden relative flex items-center justify-center p-8 sm:p-12 lg:p-16 select-none bg-nano-50">
        {(hoveredFilterId || showBefore) && (
          <div className="absolute top-8 left-1/2 -translate-x-1/2 z-20 flex items-center gap-2.5 px-5 py-2.5 bg-white text-nano-50 rounded-full shadow-2xl animate-in slide-in-from-top-4 border border-white/20">
            <Eye size={14} className="animate-pulse text-emerald-500" />
            <span className="text-[10px] font-black uppercase tracking-widest">
              {showBefore ? 'Viendo Original' : `Previsualizando: ${activeFilterObject?.name}`}
            </span>
          </div>
        )}

        {isRefining && (
          <div className="absolute inset-0 z-50 flex flex-col items-center justify-center bg-nano-50/80 backdrop-blur-3xl animate-in fade-in duration-300">
             <div className="relative mb-10">
                <div className="absolute inset-0 bg-emerald-400/30 blur-3xl rounded-full animate-pulse"></div>
                <BrainCircuit className="w-16 h-16 text-white animate-[bounce_2s_infinite] relative z-10" />
             </div>
             <div className="flex flex-col items-center gap-4">
                <span className="text-[14px] font-black uppercase tracking-[0.8em] text-white animate-pulse">Sintetizando Visión</span>
                <p className="text-[10px] font-bold text-white/30 uppercase tracking-[0.4em]">Procesando Variaciones de Matriz...</p>
             </div>
          </div>
        )}

        <div 
          ref={containerRef}
          className="relative bg-black overflow-hidden shadow-[0_50px_120px_rgba(0,0,0,0.9)] ring-1 ring-white/10 rounded-sm"
          style={{
             aspectRatio: cropRatio.replace(':', '/'),
             width: '100%',
             maxWidth: '100%',
             maxHeight: '100%',
             cursor: isDragging ? 'grabbing' : 'grab',
             touchAction: 'none'
          }}
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={handlePointerUp}
          onPointerLeave={handlePointerUp}
        >
           <img 
             ref={imageRef}
             src={currentImageSrc} 
             alt="Editando"
             loading="lazy"
             decoding="async"
             onLoad={() => setImageLoaded(true)}
             className={`absolute max-w-none max-h-none origin-center pointer-events-none transition-opacity duration-700 ${imageLoaded ? 'opacity-100' : 'opacity-0'}`}
             style={{
                top: '50%',
                left: '50%',
                transform: `translate(-50%, -50%) scale(${zoom}) translate(${pan.x}px, ${pan.y}px)`,
                filter: showBefore ? 'none' : currentFilter,
                minWidth: '100%',
                minHeight: '100%',
                transition: isResetting 
                  ? 'transform 0.6s cubic-bezier(0.25, 1, 0.5, 1), filter 0.3s ease' 
                  : (isDragging ? 'none' : 'transform 0.1s ease-out, filter 0.25s ease-out')
             }}
             draggable={false}
           />
           {effectiveFilterId === 'vignette' && !showBefore && (
             <div className="absolute inset-0 pointer-events-none bg-[radial-gradient(circle,transparent_50%,rgba(0,0,0,0.6)_100%)]"></div>
           )}
           {activeTab === 'crop' && (
             <div className="absolute inset-0 pointer-events-none border border-white/20 ring-[2000px] ring-black/40">
                <div className="absolute top-1/3 left-0 right-0 h-px bg-white/20"></div>
                <div className="absolute top-2/3 left-0 right-0 h-px bg-white/20"></div>
                <div className="absolute left-1/3 top-0 bottom-0 w-px bg-white/20"></div>
                <div className="absolute left-2/3 top-0 bottom-0 w-px bg-white/20"></div>
             </div>
           )}
        </div>
      </div>

      <div className="bg-nano-100 border-t border-white/10 shrink-0 pb-safe shadow-[0_-15px_80px_rgba(0,0,0,0.8)] z-10">
        <div className="flex border-b border-white/5">
           {[
             { id: 'filter', icon: Wand2, label: 'Filtros' },
             { id: 'adjust', icon: Sliders, label: 'Ajustes' },
             { id: 'crop', icon: Crop, label: 'Composición' },
             { id: 'refine', icon: Sparkles, label: 'Refinar (IA)' }
           ].map((tab) => (
             <button 
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)} 
                className={`flex-1 py-5 text-[10px] uppercase font-bold tracking-[0.3em] flex items-center justify-center gap-2.5 focus:outline-none transition-all ${activeTab === tab.id ? 'text-white bg-white/5 border-b-2 border-white' : 'text-white/30 hover:text-white/60'}`}
             >
               <tab.icon size={16} className={activeTab === tab.id ? 'text-emerald-400' : ''} /> 
               <span className="hidden sm:inline">{tab.label}</span>
             </button>
           ))}
        </div>

        <div className="h-64 p-8 overflow-y-auto hide-scrollbar bg-black/30">
           {activeTab === 'filter' && (
             <div className="flex gap-6 overflow-x-auto pb-4 hide-scrollbar h-full items-center px-4">
                {IMAGE_FILTERS.map((f) => (
                   <button 
                     key={f.id}
                     onClick={() => handleFilterSelect(f.id)}
                     onMouseEnter={() => setHoveredFilterId(f.id)}
                     onMouseLeave={() => setHoveredFilterId(null)}
                     className="flex flex-col items-center gap-4 shrink-0 group focus:outline-none"
                   >
                      <div className={`relative w-20 h-20 rounded-3xl overflow-hidden border-2 transition-all duration-300 ${selectedFilterId === f.id ? 'border-white ring-8 ring-white/10 scale-105' : 'border-white/5 group-hover:border-white/40 group-hover:scale-110'}`}>
                         <img src={currentImageSrc} alt={f.name} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-125" style={{ filter: f.filter }} />
                         {f.id === 'vignette' && <div className="absolute inset-0 pointer-events-none bg-[radial-gradient(circle,transparent_50%,rgba(0,0,0,0.6)_100%)]"></div>}
                         {selectedFilterId === f.id && (
                           <div className="absolute inset-0 bg-white/20 flex items-center justify-center backdrop-blur-sm">
                             <Check className="text-white drop-shadow-lg" size={28} strokeWidth={4} />
                           </div>
                         )}
                      </div>
                      <span className={`text-[10px] font-black uppercase tracking-widest transition-colors ${selectedFilterId === f.id || hoveredFilterId === f.id ? 'text-white' : 'text-white/20'}`}>{f.name}</span>
                   </button>
                ))}
             </div>
           )}

           {activeTab === 'adjust' && (
             <div className="grid grid-cols-1 md:grid-cols-2 gap-x-16 gap-y-6 max-w-5xl mx-auto h-full">
                <div className="space-y-6">
                    <div className="space-y-2">
                        <div className="flex justify-between items-center mb-1">
                            <div className="flex items-center gap-3">
                                <Sun size={14} className="text-amber-400" />
                                <span className="text-[10px] font-black uppercase tracking-widest text-white/60">Brillo</span>
                            </div>
                            <span className="text-[10px] font-mono text-white/30">{brightness}%</span>
                        </div>
                        <input type="range" min="0" max="200" step="1" value={brightness} onChange={(e) => setBrightness(parseInt(e.target.value))} onPointerUp={() => pushToHistory(getCurrentState())} className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-white" />
                    </div>
                    <div className="space-y-2">
                        <div className="flex justify-between items-center mb-1">
                            <div className="flex items-center gap-3">
                                <Contrast size={14} className="text-blue-400" />
                                <span className="text-[10px] font-black uppercase tracking-widest text-white/60">Contraste</span>
                            </div>
                            <span className="text-[10px] font-mono text-white/30">{contrast}%</span>
                        </div>
                        <input type="range" min="0" max="200" step="1" value={contrast} onChange={(e) => setContrast(parseInt(e.target.value))} onPointerUp={() => pushToHistory(getCurrentState())} className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-white" />
                    </div>
                </div>
                <div className="space-y-6">
                    <div className="space-y-2">
                        <div className="flex justify-between items-center mb-1">
                            <div className="flex items-center gap-3">
                                <Droplets size={14} className="text-sky-400" />
                                <span className="text-[10px] font-black uppercase tracking-widest text-white/60">Saturación</span>
                            </div>
                            <span className="text-[10px] font-mono text-white/30">{saturation}%</span>
                        </div>
                        <input type="range" min="0" max="200" step="1" value={saturation} onChange={(e) => setSaturation(parseInt(e.target.value))} onPointerUp={() => pushToHistory(getCurrentState())} className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-white" />
                    </div>
                    <div className="flex justify-between items-center pt-4">
                        <button 
                          onClick={() => setShowBefore(!showBefore)} 
                          className={`flex items-center gap-2 text-[10px] font-black uppercase tracking-[0.2em] transition-all ${showBefore ? 'text-emerald-400' : 'text-white/20 hover:text-white'}`}
                        >
                           {showBefore ? <EyeOff size={12} /> : <Eye size={12} />} 
                           {showBefore ? 'Mostrar Editado' : 'Comparar Antes'}
                        </button>
                        <button onClick={handleResetAdjustments} className="flex items-center gap-2 text-[10px] font-black uppercase tracking-[0.2em] text-white/20 hover:text-white transition-all">
                           <RotateCcw size={12} /> Restablecer Parámetros
                        </button>
                    </div>
                </div>
             </div>
           )}

           {activeTab === 'crop' && (
             <div className="flex flex-col gap-8 h-full justify-center max-w-3xl mx-auto">
                <div className="flex items-center gap-6">
                   <ZoomIn size={18} className="text-white/40" />
                   <input type="range" min={isRatioLocked ? getMinZoom() : 0.5} max="4" step="0.01" value={zoom} onChange={(e) => { const val = parseFloat(e.target.value); setZoom(val); setPan(prev => constrainPan(prev, val)); }} onPointerUp={() => pushToHistory(getCurrentState())} className="w-full h-1.5 bg-white/10 rounded-full appearance-none cursor-pointer accent-white" />
                   <div className="flex gap-3">
                     <button onClick={handleLockToggle} className={`p-4 rounded-2xl transition-all active:scale-90 border ${isRatioLocked ? 'bg-white text-nano-50 border-white shadow-xl' : 'text-white/40 border-white/10 hover:bg-white/5'}`} title={isRatioLocked ? "Desbloquear Aspecto" : "Bloquear Aspecto"}>
                       {isRatioLocked ? <Lock size={18} /> : <Unlock size={18} />}
                     </button>
                     <button onClick={handleResetTransform} className="p-4 text-white/40 hover:text-white hover:bg-white/5 border border-white/10 rounded-2xl transition-all active:scale-90" title="Reiniciar Encuadre">
                       <RotateCcw size={18} />
                     </button>
                   </div>
                </div>
                <div className="flex gap-4 overflow-x-auto pb-1 hide-scrollbar justify-center px-4">
                   {ASPECT_RATIOS.map(r => (
                     <button key={r.id} onClick={() => handleRatioSelect(r.id)} className={`px-8 py-3 rounded-2xl border text-[11px] font-black uppercase tracking-widest transition-all ${cropRatio === r.id ? 'bg-white text-nano-50 border-white shadow-2xl' : 'border-white/10 text-white/40 hover:border-white/30 hover:text-white'}`}>{r.label}</button>
                   ))}
                </div>
             </div>
           )}

           {activeTab === 'refine' && (
             <div className="grid grid-cols-1 lg:grid-cols-12 gap-10 max-w-6xl mx-auto h-full">
                <div className="lg:col-span-7 flex flex-col gap-4">
                   <div className="flex items-center justify-between px-1">
                      <div className="flex items-center gap-3">
                        <MessageSquareText size={16} className="text-emerald-400" />
                        <span className="text-[10px] font-black uppercase tracking-[0.4em] text-white">Prompt de Iteración Neuronal</span>
                      </div>
                      <span className="text-[8px] font-bold text-white/20 uppercase tracking-widest">Modificado para la siguiente ejecución</span>
                   </div>

                   {/* Refinement Presets */}
                   <div className="flex gap-2 overflow-x-auto pb-3 hide-scrollbar -mx-2 px-2">
                      {REFINEMENT_PRESETS.map((preset) => (
                        <button
                          key={preset.id}
                          onClick={() => setLocalPrompt(preset.prompt)}
                          className="flex flex-col gap-1 px-4 py-2.5 rounded-xl bg-white/5 hover:bg-white/10 border border-white/5 hover:border-emerald-500/30 transition-all shrink-0 group text-left max-w-[140px]"
                        >
                          <span className="text-[9px] font-black uppercase tracking-widest text-white/70 group-hover:text-emerald-400 truncate w-full">{preset.label}</span>
                          <span className="text-[8px] text-white/30 truncate w-full">{preset.description}</span>
                        </button>
                      ))}
                   </div>

                   <div className="relative group flex-grow">
                      <textarea 
                        value={localPrompt}
                        onChange={(e) => setLocalPrompt(e.target.value)}
                        placeholder="Refina la descripción visual o selecciona un preset..."
                        className="w-full h-full min-h-[100px] p-5 bg-white/5 border border-white/10 rounded-3xl text-[12px] font-medium text-white resize-none focus:outline-none focus:ring-1 focus:ring-emerald-500 transition-all placeholder:text-white/10"
                      />
                      <div className="absolute bottom-4 right-4 text-white/5">
                        <MousePointer2 size={16} />
                      </div>
                   </div>
                </div>
                <div className="lg:col-span-5 flex flex-col justify-between py-1">
                   <div className="space-y-6 bg-white/2 p-6 rounded-[2.5rem] border border-white/5">
                      <div className="space-y-4">
                         <div className="flex justify-between items-center">
                            <span className="text-[10px] font-black uppercase tracking-widest text-white/60">Influencia de Variación</span>
                            <span className="text-[11px] font-black text-emerald-400">{creativity}%</span>
                         </div>
                         <input type="range" min="0" max="100" value={creativity} onChange={(e) => setCreativity(parseInt(e.target.value))} onPointerUp={() => pushToHistory(getCurrentState())} className="w-full h-1 bg-emerald-500/10 rounded-full appearance-none cursor-pointer accent-emerald-500" />
                         <p className="text-[8px] font-bold text-white/10 uppercase tracking-widest leading-relaxed">Determina cuánto se desvía la IA del lienzo actual.</p>
                      </div>
                      <Button onClick={handleAIRefine} isLoading={isRefining} className="w-full !rounded-2xl !py-4 !bg-emerald-500 !text-white shadow-[0_15px_30px_rgba(16,185,129,0.2)]" icon={<Zap size={18} fill="white" />}>EJECUTAR REFINAMIENTO</Button>
                   </div>
                   <p className="text-center text-[8px] font-black text-white/10 uppercase tracking-[0.4em] mt-2">El refinamiento utiliza el estado actual del lienzo como referencia</p>
                </div>
             </div>
           )}
        </div>
      </div>
    </div>
  );
};

