  Dices,
  Trash2,
  Bookmark,
  Save,
  Check,
  Lightbulb,
  Copy,
  Search,
  Eraser,
  Building2,
  Coffee,
  Cloud,
  MousePointer2,
  Trees,
  User,
  Utensils,
  Glasses,
