                    ${isRefining 
                        ? 'bg-emerald-500 text-white cursor-wait' 
                        : 'bg-emerald-500/10 text-emerald-400 hover:bg-emerald-500 hover:text-white shadow-[0_0_20px_rgba(16,185,129,0.2)] active:scale-95'
                    }
                    ${(!imageLoaded) ? 'opacity-30 cursor-not-allowed' : ''}
                `}
                title={activeTab === 'eraser' ? "Eliminar objetos seleccionados" : "Refinar por IA al instante"}
            >
                {isRefining ? (
                    <>
                        <Loader2 size={16} className="animate-spin" />
