        <div 
          ref={containerRef}
          className="relative bg-black overflow-hidden shadow-[0_50px_120px_rgba(0,0,0,0.9)] ring-1 ring-white/10 rounded-sm"
          style={{
             aspectRatio: cropRatio.replace(':', '/'),
             width: '100%',
             maxWidth: '100%',
             maxHeight: '100%',
             cursor: activeTab === 'eraser' ? 'none' : (isDragging ? 'grabbing' : 'grab'),
             touchAction: 'none'
          }}
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={handlePointerUp}
          onPointerLeave={handlePointerUp}
        >
           {/* Custom Cursor for Eraser */}
           {activeTab === 'eraser' && !isDragging && (
             <div 
               className="pointer-events-none fixed z-50 rounded-full border border-white/80 bg-red-500/20 shadow-[0_0_10px_rgba(255,0,0,0.5)]"
