                 width: brushSize * (canvasRef.current ? canvasRef.current.width / (canvasRef.current.getBoundingClientRect().width || 1) * zoom : 1) + 'px', 
                 height: brushSize * (canvasRef.current ? canvasRef.current.height / (canvasRef.current.getBoundingClientRect().height || 1) * zoom : 1) + 'px',
                 // Note: Since pointer events are none, we can't easily track mouse exact pos without state, 
                 // but the native cursor: none hides the arrow. 
                 // For a true custom cursor we'd need mouse tracking state. 
                 // For now, let's stick to the browser crosshair or rely on the red stroke visibility.
               }}
             />
