                        <input type="range" min="0" max="200" step="1" value={brightness} onChange={(e) => setBrightness(parseInt(e.target.value))} onPointerUp={() => pushToHistory(getCurrentState())} className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-white" />
                    </div>
                    <div className="space-y-2">
