                        />
                        <div className="w-8 h-8 rounded-full bg-white/20 flex items-center justify-center border border-white/10"></div>
                    </div>
                </div>

                <div className="flex gap-4 items-center bg-white/5 p-4 rounded-2xl border border-white/5">
                   <div className="p-2 bg-emerald-500/20 rounded-lg text-emerald-400">
                      <BrainCircuit size={20} />
                   </div>
                   <div className="space-y-1">
                        <p className="text-[9px] text-white/80 font-bold uppercase tracking-wide">Modo Inteligente</p>
                        <p className="text-[9px] text-white/40 leading-relaxed">
                            Sin texto: Elimina objeto y reconstruye fondo. <br/>
                            Con texto: Reemplaza objeto (ej: "un gato").
                        </p>
