  prompt: initialPrompt, 
  styleId, 
  initialCreativity,
  lightSourceId: initialLightSourceId = 'auto',
  lightDirectionId: initialLightDirectionId = 'auto',
  onSave, 
  onCancel 
}) => {
  const [activeTab, setActiveTab] = useState<'filter' | 'adjust' | 'lighting' | 'crop' | 'refine' | 'eraser'>('filter');
  const [selectedFilterId, setSelectedFilterId] = useState('none');
