import { ART_STYLES, APP_NAME, MODEL_NAME_DISPLAY, ASPECT_RATIOS, LIGHT_SOURCES, LIGHT_DIRECTIONS, IMAGE_FILTERS } from './constants';
import { GeneratedImage, GenerationStatus, GenerationPreset } from './types';
import { generateImageWithNano, detectImageStyle } from './services/geminiService';
import { Button, StyleCard, Badge } from './components/UI';
import { ImageEditor } from './components/ImageEditor';
import { ZoomablePreview } from './components/ZoomablePreview';

const App: React.FC = () => {
  // --- Estados de Generación ---
  const [prompt, setPrompt] = useState<string>('');
  const [selectedStyleId, setSelectedStyleId] = useState<string>(ART_STYLES[0].id);
  const [selectedCategory, setSelectedCategory] = useState<string>('Todos');
  const [aspectRatio, setAspectRatio] = useState<string>('1:1');
  const [lightSourceId, setLightSourceId] = useState<string>('auto');
  const [lightDirectionId, setLightDirectionId] = useState<string>('auto');
  const [selectedFilterId, setSelectedFilterId] = useState<string>('none');
  const [seed, setSeed] = useState<number | undefined>(undefined);
  const [creativity, setCreativity] = useState<number>(50);
  const [uploadedImage, setUploadedImage] = useState<string | null>(null);

  // --- Estados de Interfaz ---
  const [activeSidebarSection, setActiveSidebarSection] = useState<'creative' | 'technical'>('creative');
  const [isPromptFocused, setIsPromptFocused] = useState(false);
  const [status, setStatus] = useState<GenerationStatus>('idle');
  const [currentImage, setCurrentImage] = useState<GeneratedImage | null>(null);
  const [history, setHistory] = useState<GeneratedImage[]>([]);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [isDetectingStyle, setIsDetectingStyle] = useState(false);
  const [lastAutoSelectedStyleId, setLastAutoSelectedStyleId] = useState<string | null>(null);

  // --- Historial y Presets ---
  const [presets, setPresets] = useState<GenerationPreset[]>([]);
  const [showPresets, setShowPresets] = useState(false);
  const [promptHistory, setPromptHistory] = useState<string[]>(['']);
  const [historyIndex, setHistoryIndex] = useState(0);

  const previewRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- Filtrado de Estilos ---
  const categories = useMemo(() => ['Todos', ...new Set(ART_STYLES.map(s => (s as any).category))], []);
  const filteredStyles = useMemo(() => {
    if (selectedCategory === 'Todos') return ART_STYLES;
    return ART_STYLES.filter(s => (s as any).category === selectedCategory);
  }, [selectedCategory]);

  useEffect(() => {
    const saved = localStorage.getItem('nanoframe_presets_v9');
    if (saved) setPresets(JSON.parse(saved));
  }, []);

  useEffect(() => {
    localStorage.setItem('nanoframe_presets_v9', JSON.stringify(presets));
  }, [presets]);

  const handlePromptChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setPrompt(e.target.value);
    if (e.target.value.trim() === '') setStatus('idle');
  };

  const handleGenerate = async () => {
    if (!prompt.trim() && !uploadedImage) {
      setErrorMsg("Define tu visión para comenzar.");
      return;
    }
    setStatus('generating');
    setErrorMsg(null);
    try {
      const base64Image = await generateImageWithNano(prompt, selectedStyleId, aspectRatio, seed, creativity, uploadedImage, lightSourceId, lightDirectionId, selectedFilterId);
      const newImage: GeneratedImage = {
        id: crypto.randomUUID(),
        url: base64Image,
        prompt: prompt || 'Sintetizado',
        styleId: selectedStyleId,
        aspectRatio,
        seed,
        creativity,
        referenceImage: uploadedImage,
        lightSourceId,
        lightDirectionId,
        timestamp: Date.now()
      };
      setCurrentImage(newImage);
      setHistory(prev => [newImage, ...prev].slice(0, 10));
      setStatus('success');
    } catch (error) {
      setStatus('error');
      setErrorMsg("El motor neuronal ha encontrado una interferencia.");
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = async (event) => {
        if (event.target?.result) {
          const base64 = event.target.result as string;
          setUploadedImage(base64);
          setIsDetectingStyle(true);
          const detected = await detectImageStyle(base64);
          if (detected) {
            const matched = ART_STYLES.find(s => detected.includes(s.id));
            if (matched) setSelectedStyleId(matched.id);
          }
          setIsDetectingStyle(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="min-h-screen bg-nano-50 text-white selection:bg-emerald-500 flex flex-col font-sans">

      {/* Header Minimalista */}
      <header className="h-20 bg-nano-100/40 backdrop-blur-2xl sticky top-0 z-50 border-b border-white/5 px-6 flex items-center justify-between">
