                ) : (
                  currentImage && (
                    <div className="w-full h-full animate-in zoom-in-95 duration-700 relative group">
                      <ZoomablePreview src={currentImage.url} alt={currentImage.prompt} className="rounded-[3rem] shadow-[0_50px_100px_rgba(0,0,0,0.8)] border border-white/10" isVisible={true} />

                      {/* Floating Actions */}
                      <div className="absolute top-8 right-8 flex flex-col gap-3 opacity-0 group-hover:opacity-100 transition-all translate-x-4 group-hover:translate-x-0">
                         <button onClick={() => setIsEditing(true)} className="p-4 bg-white text-nano-50 rounded-2xl shadow-2xl hover:scale-110 transition-all"><Edit2 size={20} /></button>
                         <button onClick={handleGenerate} className="p-4 bg-white/10 backdrop-blur-md text-white border border-white/10 rounded-2xl shadow-2xl hover:scale-110 transition-all"><RefreshCw size={20} /></button>
