                      </div>
                    </div>
                  )
                )}
              </div>
            )}
          </div>

          {/* Historial Horizontal Inferior */}
          {history.length > 0 && !isEditing && (
            <div className="h-40 border-t border-white/5 bg-nano-100/40 backdrop-blur-3xl px-10 flex items-center gap-6 overflow-x-auto hide-scrollbar shrink-0">
              <div className="flex items-center gap-3 shrink-0">
                 <History size={16} className="text-white/20" />
                 <span className="text-[9px] font-black uppercase tracking-[0.3em] text-white/20">Historial</span>
              </div>
              <div className="flex gap-4">
                {history.map(img => (
                  <button 
                    key={img.id}
                    onClick={() => setCurrentImage(img)}
                    className={`w-24 h-24 rounded-2xl overflow-hidden border-2 transition-all flex-shrink-0 relative group ${currentImage?.id === img.id ? 'border-emerald-500 scale-105 shadow-xl' : 'border-transparent opacity-40 hover:opacity-100'}`}
                  >
                    <img src={img.url} className="w-full h-full object-cover transition-transform group-hover:scale-110" alt="" />
                    <div className="absolute inset-0 bg-black/20 group-hover:opacity-0 transition-opacity"></div>
                  </button>
                ))}
              </div>
            </div>
          )}
        </section>
      </main>

      <footer className="h-10 bg-black border-t border-white/5 flex items-center justify-center">
        <p className="text-[8px] font-black text-white/10 uppercase tracking-[0.5em]">Motor Neural NanoFrame v3.0 / Laboratorio Premium</p>
      </footer>
    </div>
  );
};

