import React from 'react';
import { ArtStyle } from '../types';
import { Check, Sparkles, Loader2 } from 'lucide-react';

// --- Button Component ---
interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'ghost';
  isLoading?: boolean;
  icon?: React.ReactNode;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  isLoading, 
  className = '', 
  icon,
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center gap-3 px-8 py-4 rounded-[2rem] font-black transition-all duration-300 focus:outline-none disabled:opacity-50 disabled:cursor-not-allowed active:scale-[0.96] relative overflow-hidden group";

  const variants = {
    primary: "bg-white text-nano-50 hover:bg-emerald-500 hover:text-white shadow-xl shadow-black/20 uppercase tracking-[0.2em] text-[12px]",
    secondary: "bg-nano-100/50 backdrop-blur-md text-white border border-white/10 hover:border-white/30 shadow-sm uppercase tracking-widest text-[10px]",
    ghost: "bg-transparent text-white/40 hover:bg-white/5 hover:text-white"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${className}`} 
      disabled={isLoading || props.disabled}
      {...props}
    >
      {isLoading ? (
        <div className="flex items-center gap-3">
          <Loader2 className="animate-spin h-5 w-5" />
          <span className="tracking-[0.4em]">SINTETIZANDO</span>
        </div>
      ) : (
        <>
          {icon && <span className="relative z-10">{icon}</span>}
          <span className="relative z-10">{children}</span>
          <div className="absolute inset-0 bg-white/10 translate-y-full group-hover:translate-y-0 transition-transform duration-500"></div>
        </>
      )}
    </button>
  );
};

// --- Style Card Component ---
interface StyleCardProps {
  style: ArtStyle;
  isSelected: boolean;
  onClick: () => void;
}

export const StyleCard: React.FC<StyleCardProps> = ({ style, isSelected, onClick }) => {
  const isDark = style.id.includes('night') || style.id.includes('moody') || style.id.includes('noir');

  return (
    <button 
      type="button"
      onClick={onClick}
      className={`
        text-left w-full relative overflow-hidden cursor-pointer group rounded-3xl p-5 h-36 flex flex-col justify-end transition-all duration-700
        focus:outline-none bg-gradient-to-br ${style.gradient}
        ${isSelected ? 'ring-2 ring-white ring-offset-4 ring-offset-nano-50 scale-[1.05] shadow-[0_20px_40px_rgba(0,0,0,0.4)] z-10' : 'hover:scale-[1.02] border border-white/5'}
      `}
    >
      <div className={`absolute inset-0 transition-opacity ${isDark ? 'bg-black/10' : 'bg-black/5'} opacity-40 group-hover:opacity-0`}></div>
      <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-10 mix-blend-overlay"></div>

      <div className="relative z-10">
        <h3 className={`font-black text-[12px] uppercase tracking-[0.2em] mb-1 ${isDark ? 'text-white' : 'text-nano-50'}`}>
          {style.name}
        </h3>
        <p className={`text-[9px] font-bold leading-tight opacity-60 ${isDark ? 'text-white' : 'text-nano-50'}`}>
          {style.description}
        </p>
      </div>

      {isSelected && (
        <div className="absolute top-4 right-4 w-8 h-8 rounded-full bg-white flex items-center justify-center shadow-2xl animate-in zoom-in">
           <Check size={16} className="text-nano-50" strokeWidth={4} />
        </div>
      )}
    </button>
  );
