} from 'lucide-react';
import { ART_STYLES, APP_NAME, MODEL_NAME_DISPLAY, ASPECT_RATIOS, LIGHT_SOURCES, LIGHT_DIRECTIONS, IMAGE_FILTERS } from './constants';
import { GeneratedImage, GenerationStatus, GenerationPreset } from './types';
import { generateImageWithNano, detectImageStyle } from './services/geminiService';
import { Button, StyleCard, Badge } from './components/UI';
import { ImageEditor } from './components/ImageEditor';
import { ZoomablePreview } from './components/ZoomablePreview';

const App: React.FC = () => {
  // --- Estados de Generación ---
  const [prompt, setPrompt] = useState<string>('');
  const [selectedStyleId, setSelectedStyleId] = useState<string>(ART_STYLES[0].id);
  const [selectedCategory, setSelectedCategory] = useState<string>('Todos');
  const [aspectRatio, setAspectRatio] = useState<string>('1:1');
  const [lightSourceId, setLightSourceId] = useState<string>('auto');
  const [lightDirectionId, setLightDirectionId] = useState<string>('auto');
  const [selectedFilterId, setSelectedFilterId] = useState<string>('none');
  const [seed, setSeed] = useState<number | undefined>(undefined);
  const [creativity, setCreativity] = useState<number>(50);
  const [uploadedImage, setUploadedImage] = useState<string | null>(null);

  // --- Estados de Interfaz ---
  const [activeSidebarSection, setActiveSidebarSection] = useState<'creative' | 'technical'>('creative');
  const [isPromptFocused, setIsPromptFocused] = useState(false);
  const [status, setStatus] = useState<GenerationStatus>('idle');
  const [currentImage, setCurrentImage] = useState<GeneratedImage | null>(null);
  const [history, setHistory] = useState<GeneratedImage[]>([]);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [isDetectingStyle, setIsDetectingStyle] = useState(false);

  // --- Historial y Presets ---
  const [presets, setPresets] = useState<GenerationPreset[]>([]);
  const [showPresets, setShowPresets] = useState(false);

  const previewRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- Filtrado de Estilos ---
  const categories = useMemo(() => ['Todos', ...new Set(ART_STYLES.map(s => (s as any).category))], []);
  const filteredStyles = useMemo(() => {
    if (selectedCategory === 'Todos') return ART_STYLES;
    return ART_STYLES.filter(s => (s as any).category === selectedCategory);
  }, [selectedCategory]);

  useEffect(() => {
    const saved = localStorage.getItem('nanoframe_presets_v10');
    if (saved) setPresets(JSON.parse(saved));
  }, []);

  useEffect(() => {
    localStorage.setItem('nanoframe_presets_v10', JSON.stringify(presets));
  }, [presets]);

  const handlePromptChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setPrompt(e.target.value);
    if (e.target.value.trim() === '') setStatus('idle');
  };

  const handleGenerate = async () => {
    if (!prompt.trim() && !uploadedImage) {
      setErrorMsg("Define tu visión para comenzar.");
      return;
    }
    setStatus('generating');
    setErrorMsg(null);
    if (window.innerWidth < 1024) {
      previewRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
    try {
      const base64Image = await generateImageWithNano(prompt, selectedStyleId, aspectRatio, seed, creativity, uploadedImage, lightSourceId, lightDirectionId, selectedFilterId);
      const newImage: GeneratedImage = {
        id: crypto.randomUUID(),
        url: base64Image,
        prompt: prompt || 'Sintetizado',
        styleId: selectedStyleId,
        aspectRatio,
        seed,
        creativity,
        referenceImage: uploadedImage,
        lightSourceId,
        lightDirectionId,
        timestamp: Date.now()
      };
      setCurrentImage(newImage);
      setHistory(prev => [newImage, ...prev].slice(0, 10));
      setStatus('success');
    } catch (error) {
      setStatus('error');
      setErrorMsg("El motor neuronal ha encontrado una interferencia.");
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = async (event) => {
        if (event.target?.result) {
          const base64 = event.target.result as string;
          setUploadedImage(base64);
          setIsDetectingStyle(true);
          const detected = await detectImageStyle(base64);
          if (detected) {
            const matched = ART_STYLES.find(s => detected.includes(s.id));
            if (matched) setSelectedStyleId(matched.id);
          }
          setIsDetectingStyle(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="min-h-screen bg-nano-50 text-white selection:bg-emerald-500 flex flex-col font-sans">

      {/* Header Fijo */}
      <header className="h-20 bg-nano-100/60 backdrop-blur-2xl sticky top-0 z-[60] border-b border-white/5 px-6 flex items-center justify-between">
        <div className="flex items-center gap-4">
          <div className="w-11 h-11 bg-white rounded-2xl flex items-center justify-center text-nano-50 shadow-[0_10px_30px_rgba(255,255,255,0.1)]">
            <Camera size={24} />
          </div>
          <div>
            <h1 className="text-lg font-black tracking-tight leading-none uppercase">{APP_NAME}</h1>
            <p className="text-[9px] font-bold text-white/40 tracking-[0.3em] uppercase mt-1">AI Engine v3.1</p>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <button onClick={() => setShowPresets(!showPresets)} className={`p-3 rounded-2xl transition-all ${showPresets ? 'bg-emerald-500 text-white' : 'bg-white/5 text-white/40 hover:text-white'}`}>
            <Bookmark size={20} />
          </button>
          <div className="hidden sm:block h-8 w-px bg-white/10 mx-2"></div>
          <Badge text={MODEL_NAME_DISPLAY} />
        </div>
      </header>

      {/* Grid Principal con Scroll Controlado */}
      <main className="flex-grow max-w-[1600px] mx-auto w-full grid grid-cols-1 lg:grid-cols-[450px_1fr] lg:h-[calc(100vh-80px)]">

        {/* Panel Lateral de Control - SCROLL INTERNO EN ESCRITORIO */}
        <aside className="lg:h-full lg:overflow-y-auto border-r border-white/5 bg-nano-100/20 flex flex-col scroll-smooth">

          {/* Navegación de Pestañas */}
          <div className="flex p-4 gap-2 sticky top-0 bg-nano-50 z-20 border-b border-white/5">
            <button 
              onClick={() => setActiveSidebarSection('creative')}
              className={`flex-1 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-3 transition-all ${activeSidebarSection === 'creative' ? 'bg-white text-nano-50 shadow-xl' : 'text-white/40 hover:bg-white/5'}`}
            >
              <Palette size={16} /> Creatividad
            </button>
            <button 
              onClick={() => setActiveSidebarSection('technical')}
              className={`flex-1 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-3 transition-all ${activeSidebarSection === 'technical' ? 'bg-white text-nano-50 shadow-xl' : 'text-white/40 hover:bg-white/5'}`}
            >
              <Settings2 size={16} /> Laboratorio
            </button>
          </div>

          <div className="p-6 space-y-10 pb-32">
            {activeSidebarSection === 'creative' ? (
              <div className="space-y-10 animate-in fade-in slide-in-from-left-4 duration-300">
                {/* 1. Prompt Area */}
                <div className="space-y-4">
                  <label className="text-[10px] font-black uppercase tracking-[0.4em] text-white/40 px-1">Concepto Visual</label>
                  <div className={`relative transition-all duration-500 ${isPromptFocused ? 'scale-[1.01]' : ''}`}>
                    <textarea
                      value={prompt}
                      onChange={handlePromptChange}
                      onFocus={() => setIsPromptFocused(true)}
                      onBlur={() => setIsPromptFocused(false)}
                      placeholder="Describe tu visión con todo lujo de detalles..."
                      className="w-full p-6 rounded-[2.5rem] border border-white/10 bg-nano-100/50 backdrop-blur-md text-white placeholder:text-white/10 focus:ring-1 focus:ring-emerald-500 h-48 transition-all resize-none text-[14px] font-medium leading-relaxed shadow-xl"
                    />
                    <div className="absolute bottom-6 right-6">
                      <div className="px-3 py-1 bg-black/40 rounded-full text-[9px] font-black text-white/30 uppercase tracking-widest border border-white/5">
                        {prompt.length} Caracteres
                      </div>
                    </div>
                  </div>
                </div>

                {/* 2. Style Matrix */}
                <div className="space-y-6">
                  <label className="text-[10px] font-black uppercase tracking-[0.4em] text-white/40 px-1">Matriz Estética</label>

                  <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-thin">
                    {categories.map(cat => (
                      <button
                        key={cat}
                        onClick={() => setSelectedCategory(cat)}
                        className={`px-4 py-2 rounded-full text-[9px] font-black uppercase tracking-widest whitespace-nowrap border transition-all ${selectedCategory === cat ? 'bg-emerald-500 border-emerald-400 text-white shadow-[0_5px_15px_rgba(16,185,129,0.3)]' : 'bg-white/5 border-white/5 text-white/40 hover:border-white/20'}`}
                      >
                        {cat}
                      </button>
                    ))}
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    {filteredStyles.map((style) => (
                      <StyleCard 
                        key={style.id} 
                        style={style} 
                        isSelected={selectedStyleId === style.id} 
                        onClick={() => setSelectedStyleId(style.id)} 
                      />
                    ))}
                  </div>
                </div>
              </div>
            ) : (
              <div className="space-y-10 animate-in fade-in slide-in-from-right-4 duration-300">
                {/* 1. Referencia Visual */}
                <div className="space-y-4">
                  <label className="text-[10px] font-black uppercase tracking-[0.4em] text-white/40 px-1">Referencia Visual</label>
                  <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept="image/*" className="hidden" />
                  {!uploadedImage ? (
                    <button onClick={() => fileInputRef.current?.click()} className="w-full py-12 border-2 border-dashed border-white/5 rounded-[2.5rem] flex flex-col items-center justify-center gap-3 bg-white/2 hover:bg-emerald-500/5 transition-all group">
                      <div className="p-4 bg-white/5 rounded-2xl group-hover:bg-emerald-500/20 transition-all">
                        <Upload size={24} className="text-white/20 group-hover:text-emerald-400" />
                      </div>
                      <span className="text-[10px] font-black uppercase tracking-widest text-white/20">Cargar Imagen Maestra</span>
                    </button>
                  ) : (
                    <div className="relative rounded-[2.5rem] overflow-hidden group border border-white/10 shadow-2xl aspect-video bg-black">
                      <img src={uploadedImage} alt="Referencia" className="w-full h-full object-contain" />
                      <div className="absolute inset-0 bg-nano-50/80 opacity-0 group-hover:opacity-100 transition-all flex items-center justify-center gap-4 backdrop-blur-md">
                        <button onClick={() => fileInputRef.current?.click()} className="p-4 bg-white text-nano-50 rounded-2xl hover:scale-110 transition-all"><RefreshCw size={20} /></button>
                        <button onClick={() => setUploadedImage(null)} className="p-4 bg-red-500 text-white rounded-2xl hover:scale-110 transition-all"><Trash2 size={20} /></button>
                      </div>
                    </div>
                  )}
                </div>

                {/* 2. Formato del Lienzo (Iconos Visuales) */}
                <div className="space-y-4">
                    <label className="text-[10px] font-black uppercase tracking-[0.4em] text-white/40 px-1">Formato de Salida</label>
                    <div className="grid grid-cols-4 gap-3">
                        {ASPECT_RATIOS.map((ratio) => (
                            <button
                                key={ratio.id}
                                onClick={() => setAspectRatio(ratio.id)}
                                className={`flex flex-col items-center justify-center py-4 rounded-2xl border transition-all ${aspectRatio === ratio.id ? 'bg-white text-nano-50 border-white shadow-lg' : 'bg-white/2 text-white/20 border-white/5 hover:text-white/40'}`}
                            >
                                <div className={`border-2 rounded-sm mb-2 ${ratio.shapeClass} ${aspectRatio === ratio.id ? 'border-nano-50 bg-nano-50' : 'border-white/10'}`}></div>
                                <span className="text-[9px] font-black uppercase tracking-widest">{ratio.label}</span>
                            </button>
                        ))}
                    </div>
                </div>

                {/* 3. Iluminación Detallada */}
                <div className="space-y-6">
                    <div className="flex items-center gap-3">
                        <Sun size={16} className="text-amber-400" />
                        <label className="text-[10px] font-black uppercase tracking-[0.4em] text-white/40">Esquema de Luz</label>
                    </div>
                    <div className="grid grid-cols-2 gap-3">
                        {LIGHT_SOURCES.slice(0, 8).map(l => (
                            <button 
                                key={l.id} 
                                onClick={() => setLightSourceId(l.id)}
                                className={`p-4 rounded-2xl border text-[10px] font-black uppercase tracking-widest transition-all text-left ${lightSourceId === l.id ? 'bg-emerald-500 text-white border-emerald-400' : 'bg-white/5 border-white/5 text-white/30 hover:border-white/20'}`}
                            >
                                {l.label}
                            </button>
                        ))}
                    </div>
                </div>

                {/* 4. Configuración IA */}
                <div className="space-y-6 bg-white/5 p-8 rounded-[2.5rem] border border-white/5 shadow-inner">
                    <div className="flex justify-between items-center mb-2">
                      <label className="text-[10px] font-black uppercase tracking-widest text-white/60">Creatividad de Síntesis</label>
                      <span className="text-emerald-400 text-[11px] font-black">{creativity}%</span>
                    </div>
                    <input 
                      type="range" min="0" max="100" value={creativity} 
                      onChange={(e) => setCreativity(parseInt(e.target.value))} 
                      className="w-full h-1.5 bg-white/10 rounded-full appearance-none accent-emerald-500 cursor-pointer" 
                    />

                    <div className="flex items-center gap-4 pt-6 mt-6 border-t border-white/5">
                        <div className="flex-1 space-y-2">
                             <label className="text-[9px] font-bold text-white/30 uppercase tracking-widest">Gradación</label>
                             <select value={selectedFilterId} onChange={(e) => setSelectedFilterId(e.target.value)} className="w-full bg-nano-50 border border-white/10 text-white text-[10px] font-black uppercase rounded-xl p-4 focus:outline-none focus:ring-1 focus:ring-emerald-500">
                                {IMAGE_FILTERS.map(f => <option key={f.id} value={f.id}>{f.name}</option>)}
                             </select>
                        </div>
                    </div>
                </div>
              </div>
            )}
          </div>

          {/* Botón de Generación Sticky */}
          <div className="sticky bottom-0 p-6 bg-gradient-to-t from-nano-50 via-nano-50 to-transparent pt-12 z-30">
            <button 
              onClick={handleGenerate} 
              disabled={status === 'generating'}
              className="w-full h-20 bg-emerald-500 hover:bg-emerald-400 disabled:bg-white/5 text-white rounded-[2.5rem] flex items-center justify-center gap-4 shadow-[0_20px_50px_rgba(16,185,129,0.3)] transition-all active:scale-95 group relative overflow-hidden"
            >
              {status === 'generating' ? (
                <div className="flex items-center gap-3">
                  <RefreshCw className="animate-spin" size={24} />
                  <span className="text-[14px] font-black uppercase tracking-[0.4em]">Sintetizando...</span>
                </div>
              ) : (
                <>
                  <Zap size={24} className="group-hover:scale-125 transition-transform" fill="white" />
                  <span className="text-[14px] font-black uppercase tracking-[0.4em]">Ejecutar Motor</span>
                  <div className="absolute inset-0 bg-white/20 translate-y-full group-hover:translate-y-0 transition-transform duration-500"></div>
                </>
              )}
            </button>
            {errorMsg && <p className="text-red-400 text-[10px] font-black text-center mt-4 uppercase tracking-widest animate-pulse">{errorMsg}</p>}
          </div>
        </aside>

        {/* Lienzo de Visualización (Canvas) */}
        <section ref={previewRef} className="relative flex flex-col min-h-[600px] lg:h-full bg-nano-50">

          <div className="flex-grow flex items-center justify-center p-6 lg:p-12 relative overflow-hidden">

            {/* Atmósfera de Fondo */}
            <div className="absolute inset-0 z-0 pointer-events-none">
               <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-emerald-500/10 blur-[150px] rounded-full animate-pulse"></div>
               <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-blue-500/10 blur-[150px] rounded-full animate-pulse" style={{ animationDelay: '1.5s' }}></div>
            </div>

            {isEditing && currentImage ? (
              <ImageEditor 
                imageSrc={currentImage.url} prompt={prompt} styleId={selectedStyleId} initialCreativity={creativity}
                onSave={(src) => { 
                  const updated = { ...currentImage, url: src, id: crypto.randomUUID() };
                  setCurrentImage(updated);
                  setHistory(prev => [updated, ...prev]);
                  setIsEditing(false);
                }} 
                onCancel={() => setIsEditing(false)} 
              />
            ) : (
              <div className="w-full max-w-5xl aspect-square relative z-10 flex items-center justify-center">
                {status === 'idle' ? (
                  <div className="w-full h-full border border-white/5 rounded-[4rem] bg-white/2 backdrop-blur-sm flex flex-col items-center justify-center p-12 text-center group transition-all duration-700">
                    <div className="w-40 h-40 bg-white/5 rounded-[3.5rem] flex items-center justify-center mb-10 group-hover:scale-110 group-hover:bg-emerald-500/10 transition-all duration-700 border border-white/5">
                      <Telescope size={64} className="text-white/10 group-hover:text-emerald-400 transition-colors" />
                    </div>
                    <h3 className="text-[12px] font-black uppercase tracking-[0.6em] text-white/20 mb-4">Laboratorio Listo</h3>
                    <p className="text-[10px] font-bold text-white/10 uppercase tracking-widest max-w-sm leading-relaxed">Ajusta los parámetros laterales y define tu concepto para iniciar la captura neuronal.</p>
                  </div>
                ) : status === 'generating' ? (
                  <div className="w-full h-full flex flex-col items-center justify-center gap-10">
                    <div className="relative">
                      <div className="w-32 h-32 border-2 border-white/5 rounded-full animate-[spin_3s_linear_infinite]"></div>
                      <div className="absolute inset-0 flex items-center justify-center">
                        <Sparkles className="text-emerald-400 animate-pulse" size={40} />
                      </div>
                    </div>
                    <div className="space-y-3 text-center">
                      <p className="text-[14px] font-black uppercase tracking-[0.8em] text-white animate-pulse">Procesando Tensores</p>
                      <p className="text-[8px] font-bold text-white/30 uppercase tracking-[0.4em]">Sincronizando coherencia visual...</p>
                    </div>
                  </div>
                ) : (
                  currentImage && (
                    <div className="w-full h-full animate-in zoom-in-95 duration-700 relative group flex items-center justify-center">
                      <ZoomablePreview src={currentImage.url} alt={currentImage.prompt} className="rounded-[3rem] shadow-[0_50px_100px_rgba(0,0,0,0.8)] border border-white/10" isVisible={true} />

                      {/* Acciones Flotantes */}
                      <div className="absolute top-8 right-8 flex flex-col gap-4 opacity-0 group-hover:opacity-100 transition-all translate-x-4 group-hover:translate-x-0 z-40">
                         <button onClick={() => setIsEditing(true)} className="p-4 bg-white text-nano-50 rounded-2xl shadow-2xl hover:scale-110 active:scale-95 transition-all"><Edit2 size={20} /></button>
                         <button onClick={handleGenerate} className="p-4 bg-white/10 backdrop-blur-md text-white border border-white/10 rounded-2xl shadow-2xl hover:scale-110 active:scale-95 transition-all"><RefreshCw size={20} /></button>
                         <button onClick={() => { const link = document.createElement('a'); link.href = currentImage.url; link.download = 'captura-ia.png'; link.click(); }} className="p-4 bg-emerald-500 text-white rounded-2xl shadow-2xl hover:scale-110 active:scale-95 transition-all"><Download size={20} /></button>
                      </div>
                    </div>
                  )
                )}
              </div>
            )}
          </div>

          {/* Historial Inferior */}
          {history.length > 0 && !isEditing && (
            <div className="h-44 border-t border-white/5 bg-nano-100/60 backdrop-blur-3xl px-10 flex items-center gap-8 overflow-x-auto shrink-0 scrollbar-thin">
              <div className="flex items-center gap-3 shrink-0">
                 <History size={18} className="text-white/20" />
                 <span className="text-[9px] font-black uppercase tracking-[0.3em] text-white/20">Secuencia</span>
              </div>
              <div className="flex gap-5 py-4">
                {history.map(img => (
                  <button 
                    key={img.id}
                    onClick={() => setCurrentImage(img)}
                    className={`w-24 h-24 rounded-2xl overflow-hidden border-2 transition-all flex-shrink-0 relative group ${currentImage?.id === img.id ? 'border-emerald-500 scale-105 shadow-[0_0_20px_rgba(16,185,129,0.4)]' : 'border-transparent opacity-40 hover:opacity-100'}`}
                  >
                    <img src={img.url} className="w-full h-full object-cover transition-transform group-hover:scale-110" alt="" />
                    <div className="absolute inset-0 bg-black/20 group-hover:opacity-0 transition-opacity"></div>
                  </button>
                ))}
              </div>
            </div>
          )}
        </section>
      </main>

      <footer className="h-10 bg-black border-t border-white/5 flex items-center justify-center shrink-0">
        <p className="text-[8px] font-black text-white/10 uppercase tracking-[0.5em]">Motor Fotográfico NanoFrame 3.1 / Powered by Gemini</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  Sparkles, 
  Download, 
  RefreshCw, 
  History, 
  Zap, 
  Camera, 
  Maximize, 
  ChevronDown, 
  ChevronUp, 
  Undo, 
  Redo, 
  Upload, 
  X, 
  Plus, 
  Edit2, 
  Dices, 
  Trash2, 
  Bookmark, 
  Save, 
  Check, 
  Lightbulb, 
  Copy, 
  Search, 
  Eraser, 
  Building2, 
  Coffee, 
  Cloud, 
  User, 
  Utensils, 
  Glasses, 
  Rocket, 
  Car, 
  Shapes, 
  MapPin, 
  Shield, 
  Home, 
  Music, 
  Ghost, 
  Palette, 
  Flame, 
  Droplets,
  Settings2,
  Telescope,
  Sun,
  Layout,
  Focus
} from 'lucide-react';
import { ART_STYLES, APP_NAME, MODEL_NAME_DISPLAY, ASPECT_RATIOS, LIGHT_SOURCES, LIGHT_DIRECTIONS, IMAGE_FILTERS } from './constants';
import { GeneratedImage, GenerationStatus, GenerationPreset } from './types';
import { generateImageWithNano, detectImageStyle } from './services/geminiService';
import { Button, StyleCard, Badge } from './components/UI';
import { ImageEditor } from './components/ImageEditor';
import { ZoomablePreview } from './components/ZoomablePreview';

const INSPIRATION_CHIPS = [
  { label: 'Cyberpunk', icon: Zap, prompt: 'Ciudad futurista con neones y lluvia, estilo cyberpunk 2077', style: 'cyberpunk' },
  { label: 'Minimalista', icon: Home, prompt: 'Interior zen minimalista, luz natural suave, materiales orgánicos', style: 'minimal-studio' },
  { label: 'Gourmet', icon: Utensils, prompt: 'Plato de alta cocina, macro fotografía, iluminación de estudio, bokeh profundo', style: 'minimal-studio' },
  { label: 'Retrato', icon: User, prompt: 'Retrato cinematográfico de una persona, iluminación lateral dramática, detalle extremo de piel', style: 'natural-portrait' },
  { label: 'Vintage', icon: Camera, prompt: 'Coche clásico en la costa italiana, estilo película analógica años 60', style: 'analog-film' },
  { label: 'Espacial', icon: Rocket, prompt: 'Nebulosa cósmica vibrante, estrellas distantes, polvo estelar brillante', style: 'night-exterior' },
  { label: 'Arquitectura', icon: Building2, prompt: 'Rascacielos moderno de cristal reflejando el atardecer, ángulo contrapicado', style: 'daytime-exterior' },
  { label: 'Abstracto', icon: Shapes, prompt: 'Formas geométricas 3D flotando en un vacío infinito, texturas de cristal y cromo', style: '3d-surreal' },
];

const App: React.FC = () => {
  const [prompt, setPrompt] = useState<string>('');
  const [selectedStyleId, setSelectedStyleId] = useState<string>(ART_STYLES[0].id);
  const [selectedCategory, setSelectedCategory] = useState<string>('Todos');
  const [aspectRatio, setAspectRatio] = useState<string>('1:1');
  const [lightSourceId, setLightSourceId] = useState<string>('auto');
  const [lightDirectionId, setLightDirectionId] = useState<string>('auto');
  const [selectedFilterId, setSelectedFilterId] = useState<string>('none');
  const [creativity, setCreativity] = useState<number>(50);
  const [uploadedImage, setUploadedImage] = useState<string | null>(null);

  const [activeSidebarSection, setActiveSidebarSection] = useState<'creative' | 'technical'>('creative');
  const [status, setStatus] = useState<GenerationStatus>('idle');
  const [currentImage, setCurrentImage] = useState<GeneratedImage | null>(null);
  const [history, setHistory] = useState<GeneratedImage[]>([]);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [isDetectingStyle, setIsDetectingStyle] = useState(false);

  const previewRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const categories = useMemo(() => ['Todos', ...new Set(ART_STYLES.map(s => (s as any).category))], []);
  const filteredStyles = useMemo(() => {
    if (selectedCategory === 'Todos') return ART_STYLES;
    return ART_STYLES.filter(s => (s as any).category === selectedCategory);
  }, [selectedCategory]);

  const handleInspirationClick = (item: typeof INSPIRATION_CHIPS[0]) => {
    setPrompt(item.prompt);
    setSelectedStyleId(item.style);
    // Visual feedback
    setStatus('idle');
  };

  const handleGenerate = async () => {
    if (!prompt.trim() && !uploadedImage) {
      setErrorMsg("Define tu visión antes de ejecutar el motor.");
      return;
    }
    setStatus('generating');
    setErrorMsg(null);
    if (window.innerWidth < 1024) previewRef.current?.scrollIntoView({ behavior: 'smooth' });
    try {
      const base64Image = await generateImageWithNano(prompt, selectedStyleId, aspectRatio, undefined, creativity, uploadedImage, lightSourceId, lightDirectionId, selectedFilterId);
      const newImage: GeneratedImage = {
        id: crypto.randomUUID(),
        url: base64Image,
        prompt: prompt || 'Sintetizado',
        styleId: selectedStyleId,
        aspectRatio,
        timestamp: Date.now()
      };
      setCurrentImage(newImage);
      setHistory(prev => [newImage, ...prev].slice(0, 10));
      setStatus('success');
    } catch (error) {
      setStatus('error');
      setErrorMsg("El motor neuronal ha encontrado una interferencia. Intenta de nuevo.");
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = async (event) => {
        if (event.target?.result) {
          const base64 = event.target.result as string;
          setUploadedImage(base64);
          setIsDetectingStyle(true);
          const detected = await detectImageStyle(base64);
          if (detected) {
            const matched = ART_STYLES.find(s => detected.includes(s.id));
            if (matched) setSelectedStyleId(matched.id);
          }
          setIsDetectingStyle(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="min-h-screen bg-nano-50 text-white flex flex-col overflow-x-hidden">
