      return;
    }
    setStatus('generating');
    setErrorMsg(null);
    if (window.innerWidth < 1024) previewRef.current?.scrollIntoView({ behavior: 'smooth' });
    try {
      const base64Image = await generateImageWithNano(prompt, selectedStyleId, aspectRatio, undefined, creativity, uploadedImage, lightSourceId, lightDirectionId, selectedFilterId);
      const newImage: GeneratedImage = {
        id: crypto.randomUUID(),
        url: base64Image,
        prompt: prompt || 'Sintetizado',
        styleId: selectedStyleId,
        aspectRatio,
        timestamp: Date.now()
      };
      setCurrentImage(newImage);
      setHistory(prev => [newImage, ...prev].slice(0, 10));
      setStatus('success');
    } catch (error) {
      setStatus('error');
      setErrorMsg("Interferencia en el motor neuronal. Reintentando...");
