import { GoogleGenAI } from "@google/genai";
import { ART_STYLES, LIGHT_SOURCES, LIGHT_DIRECTIONS, IMAGE_FILTERS } from "../constants";

// Inicialización diferida para evitar errores de entorno
const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateImageWithNano = async (
  prompt: string, 
  styleId: string, 
  aspectRatio: string = "1:1",
  seed?: number,
  creativity: number = 50,
  referenceImage?: string | null,
  maskImage?: string | null,
  lightSourceId: string = 'auto',
  lightDirectionId: string = 'auto',
  filterId: string = 'none'
): Promise<string> => {
  const ai = getAI();
  const selectedStyle = ART_STYLES.find(s => s.id === styleId);
  const styleModifier = selectedStyle ? selectedStyle.promptModifier : '';
  const sourceModifier = LIGHT_SOURCES.find(l => l.id === lightSourceId)?.promptModifier || '';
  const directionModifier = LIGHT_DIRECTIONS.find(l => l.id === lightDirectionId)?.promptModifier || '';
  const filterModifier = IMAGE_FILTERS.find(f => f.id === filterId)?.prompt || '';

  const lightingPrompt = [sourceModifier, directionModifier].filter(Boolean).join(', ');

  let fullPrompt = '';
  if (maskImage && referenceImage) {
    fullPrompt = prompt && prompt.trim() !== "" 
      ? `Edit the image using the mask. Replace the white area with: "${prompt}". Blend perfectly.`
      : `Remove the object in the masked area and reconstruct the background flawlessly.`;
  } else if (!prompt && referenceImage) {
    fullPrompt = `High quality variation of this image, keeping composition but enhancing details.`;
  } else {
    fullPrompt = `Professional photography of: ${prompt || 'an artistic masterpiece'}.`;
  }

  if (!maskImage) {
    fullPrompt += ` \nStyle: ${styleModifier}. Lighting: ${lightingPrompt}. Finish: ${filterModifier}. 8k resolution.`;
  } else {
    fullPrompt += ` \nStrictly maintain original lighting, grain, and color palette.`;
  }

  const temperature = 0.2 + (creativity / 100) * 1.6;

  try {
    const parts: any[] = [];
    if (referenceImage) {
      const match = referenceImage.match(/^data:(image\/[a-z]+);base64,(.+)$/);
      if (match) parts.push({ inlineData: { mimeType: match[1], data: match[2] } });
    }
    if (maskImage) {
      const match = maskImage.match(/^data:(image\/[a-z]+);base64,(.+)$/);
      if (match) parts.push({ inlineData: { mimeType: match[1], data: match[2] } });
    }
    parts.push({ text: fullPrompt });

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts },
      config: { imageConfig: { aspectRatio }, temperature, seed }
    });

    const part = response.candidates[0].content.parts.find(p => p.inlineData);
    if (part) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    throw new Error("No image data");
  } catch (error) {
    console.error("Gemini Error:", error);
    throw error;
  }
};

export const detectImageStyle = async (imageBase64: string): Promise<string | null> => {
  try {
    const ai = getAI();
    const match = imageBase64.match(/^data:(image\/[a-z]+);base64,(.+)$/);
    if (!match) return null;

    const styleList = ART_STYLES.map(s => `ID: "${s.id}" - ${s.name}`).join('\n');
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { mimeType: match[1], data: match[2] } },
          { text: `Analyze this image and match its style to one ID from this list: ${styleList}. Return ONLY the ID.` }
        ]
      }
    });
    return response.text?.trim().replace(/['"]/g, '') || null;
  } catch (error) {
    return null;
  }
};

