  onSave: (newImageSrc: string) => void;
  onCancel: () => void;
}

export const ImageEditor: React.FC<ImageEditorProps> = ({ 
  imageSrc: initialImageSrc, prompt: initialPrompt, styleId, initialCreativity, onSave, onCancel 
}) => {
  const [activeTab, setActiveTab] = useState<'filter' | 'adjust' | 'lighting' | 'crop' | 'eraser'>('adjust');
  const [brightness, setBrightness] = useState(100);
  const [contrast, setContrast] = useState(100);
  const [saturation, setSaturation] = useState(100);
  const [currentImageSrc, setCurrentImageSrc] = useState(initialImageSrc);
  const [isRefining, setIsRefining] = useState(false);
  const [brushSize, setBrushSize] = useState(40);
  const [isDrawing, setIsDrawing] = useState(false);
  const [localPrompt, setLocalPrompt] = useState(initialPrompt);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const imageRef = useRef<HTMLImageElement>(null);

  const clearMask = () => {
    const ctx = canvasRef.current?.getContext('2d');
    if (ctx) ctx.clearRect(0, 0, canvasRef.current!.width, canvasRef.current!.height);
  };

  const handlePointerDown = (e: React.PointerEvent) => {
    if (activeTab !== 'eraser') return;
    setIsDrawing(true);
    const canvas = canvasRef.current!;
    const rect = canvas.getBoundingClientRect();
    const ctx = canvas.getContext('2d')!;
    const scale = canvas.width / rect.width;
    ctx.beginPath();
    ctx.moveTo((e.clientX - rect.left) * scale, (e.clientY - rect.top) * scale);
    ctx.lineWidth = brushSize * scale;
    ctx.lineCap = 'round';
    ctx.strokeStyle = 'rgba(255, 0, 0, 0.5)';
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!isDrawing || activeTab !== 'eraser') return;
    const canvas = canvasRef.current!;
    const rect = canvas.getBoundingClientRect();
    const ctx = canvas.getContext('2d')!;
    const scale = canvas.width / rect.width;
    ctx.lineTo((e.clientX - rect.left) * scale, (e.clientY - rect.top) * scale);
    ctx.stroke();
  };

  const getMaskData = () => {
    const canvas = canvasRef.current!;
    const maskCanvas = document.createElement('canvas');
    maskCanvas.width = canvas.width;
    maskCanvas.height = canvas.height;
    const mCtx = maskCanvas.getContext('2d')!;
    mCtx.fillStyle = '#000000';
    mCtx.fillRect(0, 0, maskCanvas.width, maskCanvas.height);
    mCtx.drawImage(canvas, 0, 0);
    const data = mCtx.getImageData(0, 0, maskCanvas.width, maskCanvas.height);
    for (let i = 0; i < data.data.length; i += 4) {
      const isRed = data.data[i] > 100;
      const color = isRed ? 255 : 0;
      data.data[i] = data.data[i+1] = data.data[i+2] = color;
      data.data[i+3] = 255;
    }
    mCtx.putImageData(data, 0, 0);
    return maskCanvas.toDataURL('image/png');
  };

  const handleAIRefine = async () => {
    setIsRefining(true);
    try {
      const mask = activeTab === 'eraser' ? getMaskData() : null;
      const newImg = await generateImageWithNano(localPrompt, styleId, "1:1", undefined, initialCreativity, currentImageSrc, mask);
      setCurrentImageSrc(newImg);
      clearMask();
      if (activeTab === 'eraser') setActiveTab('adjust');
    } catch (e) {
      console.error(e);
    } finally {
      setIsRefining(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] bg-nano-50 flex flex-col animate-in fade-in">
      <div className="h-16 border-b border-white/10 flex items-center justify-between px-6 bg-nano-100">
        <button onClick={onCancel} className="p-2 text-white/40"><X size={20} /></button>
        <div className="flex gap-4">
          <button onClick={handleAIRefine} disabled={isRefining} className="flex items-center gap-2 px-4 py-2 bg-emerald-500/10 text-emerald-400 rounded-xl font-black text-[10px] uppercase tracking-widest">
            {isRefining ? <Loader2 size={16} className="animate-spin" /> : <Zap size={16} />}
            {activeTab === 'eraser' ? 'Borrar Selección' : 'Refinar'}
          </button>
          <button onClick={() => onSave(currentImageSrc)} className="p-2 bg-white text-nano-50 rounded-xl"><Check size={20} /></button>
        </div>
      </div>

      <div className="flex-grow relative flex items-center justify-center p-12 overflow-hidden bg-black/20">
        <div className="relative max-w-full max-h-full aspect-square shadow-2xl rounded-3xl overflow-hidden border border-white/5">
          <img ref={imageRef} src={currentImageSrc} className="w-full h-full object-contain" style={{ filter: `brightness(${brightness}%) contrast(${contrast}%) saturate(${saturation}%)` }} />
          <canvas 
            ref={canvasRef} 
            width={1024} height={1024}
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerUp={() => setIsDrawing(false)}
            className={`absolute inset-0 w-full h-full cursor-crosshair ${activeTab === 'eraser' ? 'opacity-100' : 'pointer-events-none opacity-0'}`}
          />
        </div>
      </div>

      <div className="h-64 bg-nano-100 border-t border-white/10 flex flex-col shrink-0">
        <div className="flex border-b border-white/5">
          {[
            { id: 'adjust', icon: Sliders, label: 'Ajustes' },
            { id: 'eraser', icon: Eraser, label: 'Magic Eraser' },
            { id: 'filter', icon: Wand2, label: 'Filtros' }
          ].map(t => (
            <button key={t.id} onClick={() => setActiveTab(t.id as any)} className={`flex-1 py-4 flex items-center justify-center gap-2 text-[10px] uppercase font-black tracking-widest ${activeTab === t.id ? 'bg-white/5 border-b-2 border-white' : 'text-white/30'}`}>
              <t.icon size={16} /> {t.label}
            </button>
          ))}
        </div>
        <div className="p-8 h-full flex items-center justify-center">
          {activeTab === 'adjust' && (
            <div className="w-full max-w-2xl grid grid-cols-2 gap-8">
              <div className="space-y-4">
                <div className="flex justify-between text-[10px] font-black uppercase tracking-widest text-white/40"><span>Brillo</span><span>{brightness}%</span></div>
                <input type="range" min="50" max="150" value={brightness} onChange={e => setBrightness(parseInt(e.target.value))} className="w-full" />
              </div>
              <div className="space-y-4">
                <div className="flex justify-between text-[10px] font-black uppercase tracking-widest text-white/40"><span>Contraste</span><span>{contrast}%</span></div>
                <input type="range" min="50" max="150" value={contrast} onChange={e => setContrast(parseInt(e.target.value))} className="w-full" />
              </div>
            </div>
          )}
          {activeTab === 'eraser' && (
            <div className="flex flex-col items-center gap-4">
              <p className="text-[10px] text-white/40 uppercase font-black tracking-widest">Pinta para eliminar objetos de la foto</p>
              <div className="flex items-center gap-6">
                <input type="range" min="10" max="100" value={brushSize} onChange={e => setBrushSize(parseInt(e.target.value))} className="w-48" />
                <button onClick={clearMask} className="px-4 py-2 border border-white/10 rounded-xl text-[9px] font-black uppercase tracking-widest">Limpiar</button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

